INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1752','Audio-object instantiation','Audio-object instantiation is the act of creating a concrete, addressable audio object at render time from its stored definition and metadata, so the renderer can place and play it. In object-based audio the object combines an audio stream with time-varying metadata such as position, gain, and size that the renderer resolves for the target loudspeaker layout.','This is when a stored audio object becomes a live, playable object. The renderer reads its sound and its metadata. It then places the object for the actual speakers. Position, level, and size come from the metadata.','It turns an abstract object definition into an active element the renderer can position and reproduce on whatever playback layout is present.','When an ADM program is rendered, each audioObject is instantiated with its block-format position data and mapped onto the room''s speakers.','Object-Based Audio',ARRAY['Audio object','Audio-object relationship','Renderer','Channel-based audio','Audio-embedded metadata']::text[],ARRAY['Confusing the stored object definition with the instantiated, playing object.','Assuming an object always maps to one speaker rather than being rendered across many.','Forgetting that instantiation depends on the target layout.']::text[],ARRAY['Rendering an ADM master to a specific immersive room.','Mapping objects to a binaural renderer for headphones.','Debugging why an object plays at the wrong position on playback.']::text[],'advanced',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio-object instantiation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1752','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1752') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1752');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1753','Audio-object integrity','Audio-object integrity is the property that an audio object''s essence and its associated metadata remain complete, consistent, and unaltered as they move through production, coding, and delivery. It covers both bit-level correctness of the audio and the validity of position, gain, and grouping metadata that the renderer relies on.','This means an audio object stays whole and correct. Its sound and its metadata are not damaged or changed. Position and level data still match the audio. The renderer can trust what it receives.','It ensures that what the creator authored is what the renderer receives, so objects are placed and mixed exactly as intended without corruption.','A technician validates an ADM file so each object''s essence and metadata references resolve correctly and nothing was dropped in transcoding.','Object-Based Audio',ARRAY['Audio object','Audio-object provenance','Audio-embedded metadata','Audio-object relationship','Coded representation']::text[],ARRAY['Assuming audio integrity alone is enough; metadata can be corrupted independently.','Treating a file that plays as automatically intact when metadata references may be broken.','Confusing integrity (unaltered) with provenance (documented origin).']::text[],ARRAY['Validating an ADM master before archival.','Confirming objects survived a codec round-trip.','Checking that metadata references still resolve after editing.']::text[],'advanced',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio-object integrity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1753','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1753') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1753');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1754','Audio-object provenance','Audio-object provenance is documented, verifiable information about an audio object''s origin and processing history — who created it, with what tools, and how it was edited. It supports authenticity and trust, and can be recorded using content-provenance frameworks that bind cryptographically signed history to the media.','This is the recorded history of an audio object. It shows where it came from and how it changed. It can name the tools and edits used. This helps prove the audio is authentic.','It lets downstream users verify an object''s source and editing chain, supporting authenticity, rights tracking, and trust in the content.','A facility attaches signed provenance assertions to delivered assets so a broadcaster can confirm the origin and edit history before airing.','Object-Based Audio',ARRAY['Audio-object integrity','Audio-embedded metadata','Audio object','Coded representation','Audio-sample metadata embedding']::text[],ARRAY['Confusing provenance (origin history) with integrity (unaltered state).','Assuming provenance data cannot itself be forged without cryptographic signing.','Treating a filename or a comment field as trustworthy provenance.']::text[],ARRAY['Attaching signed history to news audio to prove authenticity.','Tracking rights and sources across a production chain.','Verifying an asset''s origin before broadcast.']::text[],'advanced',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio-object provenance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1754','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1754') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1754');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1755','Audio-object relationship','An audio-object relationship is a defined association between audio objects that governs how they are grouped, ordered, or made mutually exclusive during rendering and interaction. Examples include grouping objects into a content item, or making alternative language objects exclusive so only one plays at a time.','This is a defined link between audio objects. It says how objects group or depend on each other. Some objects belong together, like a bed. Others exclude each other, like two languages.','It lets authors control how objects combine, so interactive choices and renderers keep valid, intended combinations of elements.','An engineer marks two language commentary objects as mutually exclusive within a preselection so a viewer hears only one at a time.','Object-Based Audio',ARRAY['Audio object','Audio-object instantiation','Audio-object integrity','Audio-embedded metadata','Channel-based audio']::text[],ARRAY['Ignoring exclusivity so two mutually exclusive objects play together.','Confusing grouping relationships with the objects'' physical positions.','Assuming relationships are optional when interactivity depends on them.']::text[],ARRAY['Grouping dialogue, music, and effects into content items.','Defining mutually exclusive language options.','Building an interactive preselection menu.']::text[],'advanced',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio-object relationship');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1755','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1755') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1755');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1756','Audio-sample metadata embedding','Audio-sample metadata embedding is the technique of carrying metadata within or alongside the audio sample stream, either in dedicated file chunks, in reserved bits, or as a watermark hidden in the signal itself. It keeps descriptive or control data synchronized with the audio at sample granularity.','This puts metadata right with the audio samples. It may live in file chunks or hidden in the signal. It stays lined up with the sound sample by sample. That keeps the data and audio in sync.','It binds metadata tightly to the audio timeline so control or identification data cannot drift out of sync with the samples.','A technician embeds timecode or identification data into a BWF chunk, or uses an inaudible watermark to carry an identifier through analog stages.','Metadata',ARRAY['Audio-embedded metadata','Audio-embedded loudness metadata','Coded representation','Audio object','Audio-object provenance']::text[],ARRAY['Assuming watermark data is lossless; heavy processing can destroy it.','Confusing chunk-based metadata with signal-domain watermarking.','Forgetting that some transcoders discard reserved or ancillary data.']::text[],ARRAY['Embedding timecode in a Broadcast Wave file.','Watermarking a broadcast for audience measurement.','Carrying identifiers that survive analog transfer.']::text[],'intermediate',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio-sample metadata embedding');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1756','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1756') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1756');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1757','Audio-visual coherence','Audio-visual coherence is the degree to which sound and picture agree in time and space, so that what is heard matches what is seen. It spans temporal synchronization (lip-sync) and spatial agreement between a sound''s apparent position and the on-screen source.','This is how well sound matches picture. The timing should line up, like lips and speech. The position should match too, like a voice from the right person. When both agree, the scene feels natural.','It preserves believable, immersive presentation by keeping audio aligned with the visual events that produce it, both in timing and location.','A technician checks that dialogue timing stays within the recommended lip-sync window and that panned effects track the on-screen action.','Audio-Visual Alignment',ARRAY['Audio-visual spatial alignment','Audio-visual position mismatch','Audio-visual object association','Lip-sync','Channel-based audio']::text[],ARRAY['Reducing coherence to timing only, ignoring spatial agreement.','Assuming small sync errors are always unnoticeable.','Confusing coherence with overall audio quality.']::text[],ARRAY['Quality-checking a finished program for sync and placement.','Aligning immersive effects to on-screen motion.','Diagnosing viewer complaints about mismatched sound.']::text[],'intermediate',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio-visual coherence');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1757','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1757') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1757');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1758','Audio-visual object association','Audio-visual object association is the linking of an audio object to the visual object or region that produces or corresponds to its sound. It underpins object-based workflows and audio-visual machine learning, where a model or author binds a sound source to its on-screen counterpart.','This links a sound to the thing you see making it. A voice ties to the speaker on screen. A car sound ties to the visible car. Software or an author sets the link.','It connects sound sources to their visual origins so audio can be placed, tracked, or manipulated in step with the picture.','In a spatial mix, an engineer associates a dialogue object with an actor''s on-screen position so the object pans as the actor moves.','Audio-Visual Alignment',ARRAY['Audio-visual spatial alignment','Audio-visual coherence','Audio-visual position mismatch','Audio object','Audio-object relationship']::text[],ARRAY['Assuming association is automatic; it usually requires authoring or detection.','Confusing association (which source) with alignment (how well positioned).','Expecting robust association when sources overlap or leave the frame.']::text[],ARRAY['Panning dialogue objects to follow actors on screen.','Training an audio-visual model to localize sound sources.','Authoring an immersive mix bound to visual motion.']::text[],'advanced',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio-visual object association');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1758','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1758') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1758');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1759','Audio-visual position mismatch','An audio-visual position mismatch is a discrepancy between a sound''s apparent spatial location and the position of its on-screen source. It degrades immersion and can cause the ventriloquism effect, where the listener''s perceived sound location is pulled toward the visual object.','This is when a sound seems to come from the wrong place. The picture shows the source in one spot. The sound appears from another. The eyes often win, dragging the sound toward the picture.','Naming this error lets technicians identify and correct spatial misplacement so sound and picture agree in location.','A technician notices dialogue anchored center while the actor is far left, then repans the object to match the on-screen position.','Audio-Visual Alignment',ARRAY['Audio-visual spatial alignment','Audio-visual coherence','Audio-visual object association','Ventriloquism effect','Channel-based audio']::text[],ARRAY['Assuming listeners cannot detect spatial mismatch because vision dominates.','Confusing position mismatch (spatial) with lip-sync error (temporal).','Fixing timing but leaving placement wrong.']::text[],ARRAY['Correcting a mispanned dialogue object.','Evaluating immersive playback where objects drift off-screen sources.','Reviewing a mix for placement errors before delivery.']::text[],'intermediate',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio-visual position mismatch');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1759','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1759') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1759');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1760','Audio-visual spatial alignment','Audio-visual spatial alignment is the process of positioning audio so that each sound''s rendered location coincides with its on-screen or in-scene source. In immersive and object-based production it maps object positions to the reproduction layout so the perceived direction matches the picture.','This lines up where sounds are with where things appear. A voice should seem to come from the speaker. Effects should match the action on screen. The mix maps sound positions to the speakers.','It creates convincing immersion by making the heard direction of each sound agree with the seen position of its source.','An engineer sets object azimuth and elevation to match on-screen positions, verifying alignment across the target speaker layout.','Audio-Visual Alignment',ARRAY['Audio-visual position mismatch','Audio-visual coherence','Audio-visual object association','Binaural rendering','Channel-based audio']::text[],ARRAY['Aligning for one seat and ignoring other listening positions.','Assuming channel-based panning matches picture as precisely as object placement.','Confusing spatial alignment with temporal sync.']::text[],ARRAY['Placing objects to match on-screen action in an immersive mix.','Checking alignment across a cinema speaker layout.','Rendering to headphones while keeping sources tied to picture.']::text[],'advanced',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio-visual spatial alignment');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1760','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1760') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1760');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1761','Augmented-reality listener space','An augmented-reality listener space is the acoustic environment in which virtual audio objects are rendered to blend with the real room the listener occupies, so synthetic sounds appear to share the physical space. It requires matching reverberation, occlusion, and head-tracked spatialization to the listener''s actual surroundings.','This is the real space where AR sound is placed. Virtual sounds must fit the room you are in. They should match its echo and blocking. Head tracking keeps them steady as you move.','It makes virtual audio believable in augmented reality by rendering it to match the listener''s real acoustic environment and viewpoint.','A developer uses room acoustic data and head tracking so a virtual talker seems to speak from a real chair, with reverberation matching the room.','Immersive Audio',ARRAY['Binaural rendering','Audio-visual spatial alignment','Audio object','Head-related transfer function','Six degrees of freedom']::text[],ARRAY['Using generic reverb that does not match the real room, breaking the illusion.','Ignoring head tracking, so virtual sources move with the head.','Neglecting occlusion by real objects between listener and source.']::text[],ARRAY['Rendering AR audio that matches the user''s living room.','Head-tracked virtual talkers in a shared physical space.','Blending virtual and real sound in a museum AR guide.']::text[],'advanced',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Augmented-reality listener space');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1761','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1761') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1761');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1762','Beamforming weight vector','A beamforming weight vector is the set of complex gains applied to each microphone (or loudspeaker) in an array, one weight per element, that together steer and shape the array''s directional response. Choosing the weights sets the look direction and controls sidelobes and nulls.','This is a list of gains, one per microphone in an array. Applying them aims the array in a chosen direction. It can boost a target and suppress noise from other angles. The weights set the beam shape.','It defines how array signals are combined so the array listens toward a wanted direction while rejecting sound from others.','For a delay-and-sum beam the output is y[n] = wᴴx[n]; with M = 4 mics and equal weights wᵢ = 1/4, the array averages the aligned signals for a 6 dB noise reduction on uncorrelated noise.','Array Processing',ARRAY['Delay-and-sum beamformer','Beamforming','Steering vector','Microphone array','Spatial filtering']::text[],ARRAY['Assuming more elements always narrow the beam without regard to spacing and aliasing.','Forgetting weights are complex, carrying both gain and phase.','Confusing the weight vector with the steering vector it is designed against.']::text[],ARRAY['Designing a mic-array beam for conferencing.','Steering a null toward a noise source.','Comparing fixed versus adaptive weight designs.']::text[],'advanced','y[n] = w^H x[n],   w = [w_1, ..., w_M]^T','The array output is the conjugate transpose of the weight vector multiplied by the vector of array-element signals.','5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Beamforming weight vector');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1762','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1762') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1762');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1763','Beat Histogram','A beat histogram is a music-information-retrieval feature that tallies the strength of rhythmic periodicities across a range of tempi for a piece of audio. Peaks indicate dominant beat and tempo candidates, and the overall shape summarizes a track''s rhythmic content for tasks such as genre classification.','This is a chart of how strong each tempo is in a track. Tall bars mark the main beat rates. Its shape captures the rhythm feel. Software uses it to sort music by style.','It compactly represents a recording''s rhythmic structure so classifiers and search tools can compare tempo and beat content across tracks.','A developer computes a beat histogram from an autocorrelated onset envelope, then feeds its peak positions and heights to a genre classifier.','Music Information Retrieval',ARRAY['Beat Spectrum','Music information retrieval','Onset detection','Tempo estimation','Autocorrelation']::text[],ARRAY['Confusing a beat histogram with a plain tempo estimate; it shows the whole distribution.','Assuming the tallest peak is always the perceived tempo (octave errors).','Mixing it up with the beat spectrum, which is a lag-domain curve.']::text[],ARRAY['Extracting rhythm features for genre classification.','Comparing rhythmic similarity between tracks.','Detecting tempo octave ambiguities.']::text[],'intermediate',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Beat Histogram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1763','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1763') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1763');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1764','Beat Spectrum','A beat spectrum is a music-information-retrieval representation that measures rhythmic self-similarity as a function of time lag, computed by summing a self-similarity matrix of audio features along its diagonals. Peaks at particular lags reveal repetition periods such as the beat and bar.','This shows how the music repeats over different time gaps. It is built from a grid comparing every moment to every other. Adding up along the diagonals gives the curve. Peaks mark strong repeat times.','It exposes rhythmic periodicity and structure directly from audio similarity, without first detecting individual beats.','A developer builds a feature self-similarity matrix, sums along each diagonal to get B(l), and reads the strongest lag as the beat period.','Music Information Retrieval',ARRAY['Beat Histogram','Self-similarity matrix','Music information retrieval','Autocorrelation','Tempo estimation']::text[],ARRAY['Confusing the lag-domain beat spectrum with the tempo-axis beat histogram.','Assuming the first peak is the beat when it may be a sub-beat.','Ignoring the choice of feature, which strongly affects results.']::text[],ARRAY['Analyzing rhythmic structure of a recording.','Estimating beat period from self-similarity.','Comparing rhythm across sections of a piece.']::text[],'advanced','B(l) = sum_k S(k, k + l)','The beat spectrum at a lag is the sum of the self-similarity matrix entries along the diagonal offset by that lag.','5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Beat Spectrum');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1764','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1764') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1764');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1765','Binaural rendering','Binaural rendering is the synthesis of a two-channel signal for headphones that recreates the spatial cues of sources at defined directions by filtering each source with head-related transfer functions for the left and right ears. The result gives the listener a sense of direction and distance over headphones.','This makes headphone sound seem to come from around you. Each sound is filtered for the left and right ear. The filters copy how your head and ears change sound by direction. Your brain then hears a direction.','It reproduces three-dimensional spatial audio over ordinary headphones by encoding the direction cues the ears normally receive.','For each object, y_L = Σ sₒ ∗ h_{L,o} and y_R = Σ sₒ ∗ h_{R,o}; an engineer convolves a source with a measured HRIR pair to place it, adding head tracking to keep it stable.','Immersive Audio',ARRAY['Head-related transfer function','Augmented-reality listener space','Channel-based audio','Audio-visual spatial alignment','Audio object']::text[],ARRAY['Expecting good results from a generic HRTF for every listener.','Omitting head tracking, which weakens externalization and front-back cues.','Confusing binaural rendering with ordinary stereo panning.']::text[],ARRAY['Rendering an immersive mix to headphones.','Adding head-tracked spatial audio to a VR app.','Auditioning an object mix binaurally before speaker playback.']::text[],'advanced','y_L[n] = sum_o ( s_o[n] * h_{L,o}[n] );   y_R[n] = sum_o ( s_o[n] * h_{R,o}[n] )','Each ear signal is the sum over sources of that source convolved with the head-related impulse response for that ear and direction.','5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Binaural rendering');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1765','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1765') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1765');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1766','Categorical Loudness Scaling','Categorical loudness scaling is a psychoacoustic method in which listeners rate the loudness of presented sounds using named categories, such as ''soft'', ''medium'', and ''loud'', typically mapped to categorical units. It yields an individual loudness growth function used in hearing research and hearing-aid fitting.','This measures loudness by asking listeners to pick a label. Choices run from very soft to too loud. The ratings build a loudness growth curve for that person. It is used in hearing tests and hearing-aid fitting.','It maps how loudness grows with level for an individual, revealing reduced dynamic range such as loudness recruitment in impaired ears.','A clinician plays narrowband stimuli at several levels; the listener rates each in categories, and the fitted function guides hearing-aid gain settings.','Psychoacoustics',ARRAY['Loudness','Common intelligibility scale','Dichotic Pitch','Equal-loudness contour','Loudness range']::text[],ARRAY['Confusing categorical loudness (perception) with metered loudness in LUFS.','Assuming one universal curve; the function is listener-specific.','Treating the category labels as an absolute physical scale.']::text[],ARRAY['Fitting hearing aids to a patient''s loudness growth.','Studying loudness recruitment in hearing loss.','Comparing perceived loudness across listeners.']::text[],'advanced',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Categorical Loudness Scaling');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1766','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1766') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1766');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1767','Channel-based audio','Channel-based audio is a representation in which each signal is assigned to a specific loudspeaker or channel position, such as left, right, or center, and reproduction assumes a defined layout. It contrasts with object-based audio, where sounds carry positional metadata rendered to whatever layout is present.','This ties each sound to a fixed speaker. Left goes left, right goes right, and so on. It assumes a known speaker layout. If the speakers differ, the mix must be folded down or up.','It delivers a mix designed for a specific speaker arrangement, giving predictable playback when the target layout matches the authored one.','An engineer mixes a 5.1 program as fixed channels, then supplies downmix metadata so stereo devices fold it down correctly.','Audio Representation',ARRAY['Object-based audio','Audio object','Audio-embedded downmix metadata','Binaural rendering','Coded representation']::text[],ARRAY['Assuming a channel mix plays identically on any speaker layout.','Confusing channels with objects that carry position metadata.','Forgetting downmix rules when fewer speakers are present.']::text[],ARRAY['Mixing a fixed 5.1 or 7.1 program.','Delivering stereo and surround from one channel master.','Comparing channel-based and object-based deliverables.']::text[],'intermediate',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Channel-based audio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1767','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1767') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1767');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1768','Codebook index','A codebook index is the integer that identifies the entry chosen from a codebook in vector quantization, so a decoder can look up the corresponding stored vector. Transmitting the index instead of the full vector is what compresses the data in codec quantization stages.','This is a number that points to an entry in a lookup table. Instead of sending a whole block of values, the coder sends the number. The decoder reads the table to get the values back. This saves data.','It enables efficient coding by replacing a data vector with a short index into a shared codebook of representative vectors.','An encoder picks i* = argminᵢ ‖x − cᵢ‖² for input x and sends i*; a 1024-entry codebook needs only 10 bits per vector regardless of vector length.','Coding',ARRAY['Coded representation','Vector quantization','Huffman codebook','Codebook','Bit rate']::text[],ARRAY['Confusing the index with the codeword it points to.','Assuming quantization is lossless; the nearest entry only approximates the input.','Forgetting encoder and decoder must share the identical codebook.']::text[],ARRAY['Quantizing spectral parameters in a codec.','Compressing feature vectors with vector quantization.','Debugging a decoder using the wrong codebook version.']::text[],'advanced','i* = argmin_i || x - c_i ||^2 ;   x_hat = c_{i*}','The index is the codebook entry that minimizes the squared distance to the input; the decoder outputs that entry as the reconstruction.','5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Codebook index');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1768','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1768') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1768');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1769','Coded representation','A coded representation is the structured, compressed form in which audio is encoded for storage or transmission, defined by a coding standard so that any compliant decoder can reconstruct the signal. It specifies the bitstream syntax, parameters, and semantics rather than raw samples.','This is the packed form of audio made by a codec. It follows a standard so any matching decoder can read it. It stores parameters and rules, not raw samples. This keeps files small and interchangeable.','It defines a standardized, efficient bitstream so encoded audio can be stored, transmitted, and decoded interoperably across devices.','A technician delivers audio in a standardized coded representation so any conformant decoder reconstructs it identically.','Coding',ARRAY['Codebook index','Channel-based audio','Audio-embedded metadata','Bit rate','Audio object']::text[],ARRAY['Confusing the coded bitstream with the decoded audio samples.','Assuming any decoder reads any bitstream regardless of the standard.','Treating container format and coded representation as the same thing.']::text[],ARRAY['Choosing a coding standard for delivery.','Ensuring decoder conformance to a bitstream syntax.','Distinguishing essence from container in a workflow.']::text[],'intermediate',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Coded representation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1769','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1769') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1769');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1770','Common intelligibility scale','The common intelligibility scale (CIS) is a reference scale for reporting speech intelligibility, defined by a fixed mathematical relation to the speech transmission index (STI). It rescales STI so that different intelligibility measures can be compared on one common axis.','This is a shared scale for speech clarity scores. It is worked out directly from the speech transmission index. It lets different clarity measures be compared fairly. Higher values mean clearer speech.','It provides a single common axis so intelligibility results from different methods can be expressed and compared consistently.','With a measured STI of 0.6, CIS = 1 + log10(0.6) = 0.78; a technician reports both to compare against a venue''s intelligibility target.','Speech Intelligibility',ARRAY['Speech transmission index','RASTI','Categorical Loudness Scaling','Speech intelligibility','Articulation index']::text[],ARRAY['Confusing CIS with STI; they use different numeric ranges.','Applying natural log instead of base-ten in the formula.','Assuming CIS is a separate measurement rather than a rescaling of STI.']::text[],ARRAY['Reporting intelligibility of a public-address system.','Comparing STI-based results on a common scale.','Documenting a venue''s speech clarity against a target.']::text[],'intermediate','CIS = 1 + log10( STI )','The common intelligibility scale equals one plus the base-ten logarithm of the speech transmission index.','5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Common intelligibility scale');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1770','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1770') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1770');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1771','Deep clustering','Deep clustering is a machine-learning method for source separation that trains a neural network to map each time-frequency bin to an embedding vector, so bins from the same source cluster together. Clustering the embeddings at inference assigns bins to sources, producing separation masks.','This uses a neural network to separate mixed sounds. It gives each tiny time-frequency piece a position in a space. Pieces from the same source land close together. Grouping them splits the mixture into sources.','It separates overlapping sources, such as competing speakers, without fixing the number or identity of sources in advance.','A developer trains embeddings with the affinity loss ‖VVᵀ − YYᵀ‖²_F, then applies k-means to the embeddings to build a mask per speaker.','Machine Learning Audio',ARRAY['Time-frequency masking','Source separation','Beamforming weight vector','Codebook index','Machine learning']::text[],ARRAY['Confusing deep clustering with fixed-output mask regression.','Assuming it needs the source count in advance; clustering can be flexible.','Ignoring that embeddings must be clustered at inference, not just trained.']::text[],ARRAY['Separating two overlapping talkers.','Preprocessing noisy speech before recognition.','Comparing clustering-based and mask-based separation.']::text[],'advanced','L = || V V^T - Y Y^T ||_F^2','Training minimizes the squared Frobenius difference between the embedding affinity matrix and the ideal label affinity matrix.','5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Deep clustering');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1771','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1771') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1771');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1772','Delay-and-sum beamformer','A delay-and-sum beamformer is the simplest array processor: it delays each microphone signal to time-align a wave arriving from the look direction, then sums (and averages) the aligned signals. Sound from the target direction adds coherently while off-axis and uncorrelated noise partly cancel.','This lines up mic signals for one direction, then adds them. Sound from that direction reinforces itself. Noise from other directions does not line up and shrinks. It is the most basic way to aim an array.','It provides basic spatial filtering, boosting sound from a chosen direction and reducing noise, using only delays and a sum.','Output is y[n] = (1/M) Σ xₘ[n − τₘ]; with M = 4 mics aligned on the talker, uncorrelated noise drops about 10·log10(4) = 6 dB.','Array Processing',ARRAY['Beamforming weight vector','Beamforming','Microphone array','Spatial filtering','Steering vector']::text[],ARRAY['Expecting sharp directivity at low frequencies, where the beam is wide.','Ignoring spatial aliasing when element spacing is too large.','Assuming it suppresses correlated interference as well as an adaptive beamformer.']::text[],ARRAY['Building a simple conferencing mic array.','Teaching the baseline before adaptive beamforming.','Steering a fixed beam toward a talker.']::text[],'intermediate','y[n] = (1/M) sum_{m=1}^{M} x_m[n - tau_m]','The output is the average of the microphone signals after each is delayed by its steering delay to align on the target direction.','5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Delay-and-sum beamformer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1772','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1772') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1772');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1773','Dialogue enhancement','Dialogue enhancement is a receiver-side feature that lets a listener raise the level or clarity of speech relative to the rest of a program, improving intelligibility. In object- and next-generation-audio systems it adjusts a dedicated dialogue element or applies guided processing, controlled by metadata.','This lets a viewer make speech easier to hear. It raises the dialogue above music and effects. Modern systems keep dialogue as its own element to boost. It helps in noisy rooms or for hard-of-hearing listeners.','It improves speech intelligibility for the listener by allowing dialogue to be boosted relative to background sound at playback.','An engineer authors dialogue as a separate object with enhancement metadata, so the receiver can raise it several decibels above the bed on request.','Accessibility Delivery',ARRAY['Dialogue normalization','Audio-description presentation','Audio object','Channel-based audio','Audio-embedded metadata']::text[],ARRAY['Confusing dialogue enhancement (clarity boost) with dialogue normalization (level reference).','Assuming it works well when dialogue is baked into a full mix.','Expecting large boosts without artifacts from separation-based processing.']::text[],ARRAY['Authoring speech as a separately controllable object.','Helping hard-of-hearing viewers raise dialogue.','Improving intelligibility in a noisy living room.']::text[],'intermediate',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dialogue enhancement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1773','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1773') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1773');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1774','Dialogue normalization','Dialogue normalization (dialnorm) is a metadata value in AC-3 and related systems that states a program''s dialogue loudness so a decoder can attenuate output to a fixed reference level, keeping perceived loudness consistent across programs. The value ranges from −1 to −31 in LKFS units, referenced to −31 LKFS.','This is a stored number for how loud a show''s speech is. The player uses it to set a steady volume. Quiet and loud shows then match at a reference level. It stops jarring jumps between programs and ads.','It equalizes perceived loudness across programs by telling the decoder how much to attenuate so dialogue reaches a common reference level.','Applied gain is G = −31 − dialnorm; for a program tagged −24 LKFS, G = −31 − (−24) = −7 dB, so the decoder lowers output by 7 dB.','Loudness Metadata',ARRAY['Audio-embedded loudness metadata','Audio-embedded true-peak metadata','Dialogue enhancement','Loudness range','Audio-embedded downmix metadata']::text[],ARRAY['Confusing dialnorm (a loudness reference) with dialogue enhancement (a clarity boost).','Leaving dialnorm at a default that misstates true loudness.','Assuming dialnorm changes the file''s audio rather than decoder output level.']::text[],ARRAY['Setting dialnorm correctly in an AC-3 encode.','Meeting ATSC A/85 loudness requirements for broadcast.','Diagnosing loudness jumps caused by wrong dialnorm.']::text[],'advanced','G = -31 - dialnorm   [dB],   dialnorm in LKFS (-1 to -31)','The applied gain in decibels equals minus 31 minus the coded dialogue-loudness value, bringing dialogue to the −31 LKFS reference.','5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dialogue normalization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1774','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1774') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1774');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1775','Dichotic Pitch','Dichotic pitch is a pitch sensation produced only when different signals are presented to the two ears, so it cannot be heard by either ear alone. The classic example, Huggins pitch, uses noise with a narrow frequency-dependent interaural phase shift, revealing binaural processing in the auditory system.','This is a pitch you hear only with both ears together. Each ear alone hears just noise. A small phase difference between the ears creates the tone. It shows the brain compares the two ears to find pitch.','It demonstrates and probes binaural processing, showing that the auditory system extracts pitch from interaural differences the ears cannot detect separately.','A researcher presents identical noise to both ears but with a narrow-band interaural phase shift; listeners report a faint tone, confirming binaural pitch extraction.','Psychoacoustics',ARRAY['Binaural rendering','Categorical Loudness Scaling','Interaural phase difference','Binaural hearing','Pitch perception']::text[],ARRAY['Assuming the pitch exists in either ear''s signal alone; it does not.','Confusing dichotic pitch with binaural beats.','Expecting a strong tone; the percept is typically faint.']::text[],ARRAY['Demonstrating binaural processing in a hearing lab.','Testing central auditory function.','Illustrating why two ears aid pitch and localization.']::text[],'advanced',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dichotic Pitch');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1775','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1775') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1775');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1776','Directional loudness','Directional loudness is the way the perceived loudness of a sound depends on the direction from which it reaches the listener, even when the level at the eardrum-equivalent point is held constant. The effect arises from direction-dependent filtering by the head and outer ears, so a sound of fixed physical level can seem louder from some angles than others.','A sound can seem louder from some directions than others. This happens even when its measured level stays the same. Your head and ears shape sound based on where it comes from. Engineers study this when checking loudness in surround and immersive audio.','It explains why loudness judgements shift with source angle, which matters when balancing sounds placed all around a listener in immersive mixes.','When balancing a surround mix, a technician may nudge a rear channel slightly higher because sounds behind the listener are often judged quieter than the same level in front.','Loudness perception',ARRAY['Partial loudness','Integrated loudness','Localization blur','In-head localization']::text[],ARRAY['Assuming a fixed sound-pressure level always gives the same loudness regardless of direction.','Confusing directional loudness with localization, which is about where a sound seems to be, not how loud.','Believing loudness meters fully capture direction-dependent loudness differences.']::text[],ARRAY['Balancing front and rear levels in a 5.1 or immersive mix.','Investigating why an overhead object seems too quiet at a fixed meter reading.','Designing listening tests for spatial audio loudness.']::text[],'advanced',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Directional loudness');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1776','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1776') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1776');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1777','Downmix coefficient','A downmix coefficient is a fixed gain factor applied to a source channel when a multichannel programme is folded down to fewer output channels, such as 5.1 to two-channel stereo. Standard decoders sum the source channels through these coefficients to build compatible stereo (Lo/Ro) or matrix surround (Lt/Rt) outputs.','A downmix coefficient is a volume factor used when folding many channels into fewer. For example, it sets how much of the centre and surround channels goes into a stereo mix. Decoders use these factors so surround content still plays on stereo systems. The values are chosen to keep a good balance and avoid overload.','It lets a single multichannel programme play back correctly on systems with fewer speakers, keeping dialogue and effects at sensible relative levels.','Using L'' = L + 0.707*C + 0.707*Ls, a front-left of 0.3, centre 0.2 and left-surround 0.1 give a stereo left of 0.3 + 0.141 + 0.071 = 0.512.','Channel downmix',ARRAY['Rendering matrix','Object priority','Immersive audio bitstream','Normalized loudness']::text[],ARRAY['Forgetting that summing channels through coefficients can overload and clip the downmix.','Assuming every decoder uses the same coefficient values instead of the metadata-signalled ones.','Ignoring that the centre and surround levels are attenuated, not passed at unity.']::text[],ARRAY['Checking that a 5.1 broadcast folds down cleanly to stereo.','Setting metadata mix levels in an encoder.','Diagnosing a dialogue level that changes between surround and stereo playback.']::text[],'intermediate','Lo = L + clev*C + slev*Ls ; Ro = R + clev*C + slev*Rs','The stereo left output equals the front-left channel plus the centre channel scaled by the centre mix level plus the left-surround channel scaled by the surround mix level; the right output is formed the same way from the right-side channels.','5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Downmix coefficient');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1777','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1777') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1777');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1778','Fine-structure cue','A fine-structure cue is information the auditory system extracts from the rapid, carrier-rate oscillations of a sound waveform, known as temporal fine structure, as distinct from its slower amplitude envelope. At low frequencies these cues carry interaural time differences and support pitch and speech perception in noise.','Every sound wave wiggles quickly inside a slower loudness shape. The fast wiggles are called temporal fine structure. Your ears use them for low pitches and to tell tiny timing differences between the two ears. These cues help you find a sound source and follow speech in noise.','It underlies low-frequency sound localization and the ability to separate voices in noisy scenes, so it matters for binaural and immersive rendering.','A technician preserving fine-structure cues avoids heavy low-frequency phase distortion in binaural processing, so interaural timing at low frequencies stays intact and images remain stable.','Binaural cue',ARRAY['In-head localization','Localization blur','Pitch salience','Onset asynchrony']::text[],ARRAY['Confusing temporal fine structure with the slower amplitude envelope of the sound.','Assuming fine-structure timing cues matter equally at all frequencies rather than mainly low ones.','Believing envelope cues alone are enough for accurate low-frequency localization.']::text[],ARRAY['Evaluating a binaural renderer for stable low-frequency imaging.','Studying speech intelligibility in noisy immersive scenes.','Explaining why interaural time differences dominate low-frequency localization.']::text[],'advanced',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Fine-structure cue');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1778','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1778') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1778');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1779','Gated loudness','Gated loudness is a loudness measurement in which short blocks of the programme falling below defined thresholds are excluded before averaging, so silences and very quiet passages do not lower the result. The controlling method applies an absolute gate at -70 LKFS and a relative gate 10 LU below the mean loudness of the blocks that pass the absolute gate, per ITU-R BS.1770.','Gated loudness ignores the quiet gaps in a programme. It drops blocks below a set level before working out the average. This stops long silences from pulling the loudness number down. It gives a value that matches how loud the active content really seems.','Gating makes the integrated loudness reflect the parts a listener actually hears, so quiet gaps do not distort the measured level.','A technician measuring a film with long silent scenes trusts the gated reading, because the absolute -70 LKFS gate removes the silences that would otherwise understate loudness.','Loudness measurement',ARRAY['Integrated loudness','K-weighting','Loudness range','Normalized loudness']::text[],ARRAY['Thinking gating raises or lowers loudness artificially rather than excluding non-representative blocks.','Confusing the absolute -70 LKFS gate with the relative -10 LU gate.','Assuming momentary or short-term loudness use the same two-stage gating as the integrated value.']::text[],ARRAY['Measuring a movie with long quiet passages for delivery.','Explaining why a meter''s integrated value ignores silence.','Comparing gated and ungated loudness on sparse content.']::text[],'intermediate',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Gated loudness');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1779','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1779') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1779');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1780','Harmonic-percussive source separation','Harmonic-percussive source separation is a signal-processing technique that splits an audio spectrogram into a harmonic part, made of steady tonal energy that spreads horizontally in time, and a percussive part, made of transient energy that spreads vertically across frequency. A common method applies median filtering along time and along frequency to build masks for the two components.','This method splits music into two layers. One layer holds steady tones like sustained notes. The other holds sharp hits like drums. It looks at a picture of the sound over time and frequency. Then it separates the smooth lines from the sudden spikes.','It isolates rhythmic and tonal content so tasks like beat tracking, remixing, or transcription can focus on the relevant layer.','A technician preparing a track for beat detection first runs harmonic-percussive separation, then feeds the percussive layer to the beat tracker for cleaner onset picking.','Source separation',ARRAY['Non-negative matrix factorization','Onset detection function','Primary-ambient decomposition','Pitch salience']::text[],ARRAY['Expecting perfect separation, when sustained noisy sounds land in both layers.','Assuming the harmonic layer contains only pitched instruments and no reverberant tails.','Treating the technique as a single fixed algorithm rather than a family of methods.']::text[],ARRAY['Pre-processing audio for beat and tempo estimation.','Building a drum-only stem for remixing.','Cleaning tonal content before music transcription.']::text[],'advanced',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Harmonic-percussive source separation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1780','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1780') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1780');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1781','High-order ambisonics','High-order ambisonics is a sound-field representation that encodes spatial audio using spherical harmonic functions beyond first order, so more components describe the field with finer angular detail. Higher order raises spatial resolution and the size of the accurate listening area at the cost of more channels.','Ambisonics stores a full sphere of sound as a set of channels. First order uses only four channels and is fairly blurry. High order adds many more channels for sharper direction. This gives a bigger sweet spot and more precise placement.','It captures and reproduces a full three-dimensional sound field with adjustable spatial accuracy, independent of any fixed speaker layout.','A technician recording with a higher-order microphone array can later decode the same signals to headphones or to a dome of speakers, choosing order to trade channel count against sharpness.','Ambisonics',ARRAY['Higher-order ambisonic coefficient','Order of an ambisonic system','Plane-wave decomposition','Rendering matrix']::text[],ARRAY['Thinking more order always sounds better, ignoring microphone and decoder limits.','Confusing the number of ambisonic channels with the number of speakers.','Assuming a first-order recording can be upgraded to high order after capture.']::text[],ARRAY['Recording an immersive scene with a spherical microphone array.','Decoding a scene to a speaker dome or to binaural headphones.','Choosing an ambisonic order for a virtual-reality soundtrack.']::text[],'advanced',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='High-order ambisonics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1781','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1781') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1781');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1782','Higher-order ambisonic coefficient','A higher-order ambisonic coefficient is the weight assigned to one spherical harmonic function in an ambisonic encoding of a sound field. For a single plane wave from a given direction, each coefficient is the source signal multiplied by that spherical harmonic evaluated at the source''s azimuth and elevation.','Ambisonics describes sound using a set of shapes on a sphere. Each shape gets its own weight, called a coefficient. Together the weighted shapes rebuild the sound field. For one direction, each weight is the signal times that shape''s value at that angle.','The coefficients hold the directional information of the sound field, letting a decoder later steer the energy to the correct output directions.','To encode a source at the front, the technician sets each coefficient to the signal times its spherical harmonic value there, so the zeroth-order component carries the full omnidirectional signal.','Ambisonics',ARRAY['High-order ambisonics','Order of an ambisonic system','Plane-wave decomposition','Rendering matrix']::text[],ARRAY['Mixing up different normalization conventions such as SN3D and N3D.','Assuming channel ordering is fixed, when ACN and other orderings differ.','Treating coefficients as speaker feeds rather than sound-field descriptors.']::text[],ARRAY['Encoding an object into an ambisonic bed.','Converting between SN3D and N3D normalizations.','Debugging a rotation applied to an ambisonic scene.']::text[],'advanced','B_nm = s * Y_n^m(theta, phi)','The ambisonic coefficient of degree n and index m equals the source signal multiplied by the spherical harmonic of degree n and index m evaluated at the source direction, given by its azimuth and elevation.','5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Higher-order ambisonic coefficient');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1782','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1782') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1782');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1783','Immersive audio bitstream','The Immersive Audio Bitstream is a standardized container format that carries object-based immersive audio, combining audio essence with positional and descriptive metadata, defined in SMPTE ST 2098-2 for digital cinema. It represents each sound as an object with time-varying position data so a renderer can place it in a room of any speaker layout.','This is a file format for cinema immersive sound. It stores each sound plus its position over time. A renderer in the cinema reads it and sends sounds to the right speakers. It works no matter how many speakers the room has. The format is set by a SMPTE standard.','It lets one immersive mix play correctly across cinemas with different speaker counts, because positions are stored as metadata rather than fixed channels.','A technician packaging a theatrical immersive mix delivers it as an Immersive Audio Bitstream, so each auditorium''s renderer maps the objects onto its own speaker array.','Immersive format',ARRAY['Object priority','Rendering matrix','Presentation timestamp','Downmix coefficient']::text[],ARRAY['Confusing the object-based bitstream with fixed channel-based surround formats.','Assuming the bitstream contains speaker feeds rather than objects plus metadata.','Treating the SMPTE format as identical to any one brand''s cinema system.']::text[],ARRAY['Mastering an immersive theatrical mix for distribution.','Verifying object metadata survives packaging.','Rendering the same programme in auditoriums with different speaker counts.']::text[],'advanced',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Immersive audio bitstream');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1783','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1783') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1783');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1784','In-head localization','In-head localization is the perception that a sound image lies inside the head, on a line between the ears, rather than out in external space. It commonly occurs with headphone listening when the signals lack the natural direction-dependent cues and room reflections that support externalization.','Sometimes a sound seems to sit inside your head. This happens most often with headphones. The sound lacks the natural cues that place it out in the room. So the brain locates it between your ears instead of outside. Good binaural processing reduces this effect.','Understanding it guides binaural design toward externalized, out-of-head images that feel like real spatial sources.','A technician adds head-related filtering and a little simulated room reflection to a headphone mix, pushing the image out of the head so it seems to come from around the listener.','Spatial perception',ARRAY['Fine-structure cue','Localization blur','Directional loudness','Rendering matrix']::text[],ARRAY['Blaming in-head localization on headphone quality rather than missing spatial cues.','Assuming stereo panning alone can externalize a headphone image.','Thinking the effect never happens with loudspeakers.']::text[],ARRAY['Diagnosing why a binaural mix sounds stuck inside the head.','Adding room cues to externalize a headphone rendering.','Evaluating virtual-reality audio for out-of-head imaging.']::text[],'intermediate',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='In-head localization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1784','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1784') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1784');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1785','Integrated loudness','Integrated loudness is a single loudness value for a whole programme, measured with K-weighting and two-stage gating and expressed in LUFS (equivalently LKFS). It is computed from the mean of the K-weighted, gated channel powers, summed with defined channel weights, per ITU-R BS.1770.','Integrated loudness is one number for a whole programme. It sums up how loud everything is over time. It uses a special weighting that matches hearing. Quiet gaps are removed before averaging. The result is given in units called LUFS.','It gives broadcasters and streaming services a consistent overall loudness figure so different programmes can be matched to a target.','Summing the gated weighted powers to 0.01 gives L = -0.691 + 10*log10(0.01) = -20.7 LKFS, which the technician then trims to hit a -23 LUFS delivery target.','Loudness measurement',ARRAY['Gated loudness','K-weighting','Loudness range','Normalized loudness']::text[],ARRAY['Treating LUFS and dBFS as the same, when LUFS reflects perceived loudness.','Confusing integrated loudness with short-term or momentary loudness.','Forgetting that the -0.691 offset and channel weights are part of the defined algorithm.']::text[],ARRAY['Measuring a mix against a broadcast loudness target.','Comparing loudness across episodes of a series.','Preparing a master for streaming loudness normalization.']::text[],'intermediate','L_K = -0.691 + 10*log10( sum_i G_i * z_i )','The K-weighted loudness in LKFS equals minus 0.691 plus ten times the base-ten logarithm of the sum, over channels, of each channel weight times that channel''s mean-square K-weighted power.','5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Integrated loudness');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1785','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1785') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1785');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1786','K-weighting','K-weighting is the frequency weighting used in loudness measurement, formed by two filter stages: a high-frequency shelving pre-filter that models the head''s acoustic effect, followed by a high-pass filter that de-emphasizes low frequencies. It is applied to each channel before power averaging in ITU-R BS.1770, and gives the K in LKFS.','K-weighting is a filter used before measuring loudness. It has two stages. The first lifts high frequencies to mimic the head. The second cuts very low frequencies. Together they make the measurement track how loud sound seems to us.','It shapes the signal so a simple power measurement lines up better with human loudness perception across the audio band.','A technician trusts that a K-weighted meter counts a bright vocal and a deep bass fairly, because the shelf and high-pass stages weight each band toward perceived loudness.','Loudness measurement',ARRAY['Integrated loudness','Gated loudness','Loudness range','Normalized loudness']::text[],ARRAY['Confusing K-weighting with the older A-weighting used for noise measurement.','Assuming K-weighting includes gating, which is a separate later step.','Thinking K-weighting changes the audio you hear rather than only the measurement.']::text[],ARRAY['Explaining why loudness meters read differently from peak meters.','Verifying a meter conforms to the BS.1770 filter response.','Teaching the origin of the LKFS unit.']::text[],'intermediate',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='K-weighting');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1786','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1786') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1786');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1787','Key profile','A key profile is a twelve-value vector that gives the relative prominence expected for each pitch class within a musical key. In key detection it is correlated with a piece''s measured pitch-class distribution to estimate the most likely key.','A key profile is a set of twelve numbers, one per note name. Each number says how important that note is in a key. To guess a song''s key, a program compares its note counts to these profiles. The best match names the key.','It provides a template of tonal expectation so software can automatically estimate the key of a recording.','A technician tagging a music library runs a key detector that correlates each track''s pitch-class histogram with major and minor key profiles, then labels the best-matching key.','Music information retrieval',ARRAY['Pitch salience','Pitch strength','Onset detection function','Non-negative matrix factorization']::text[],ARRAY['Assuming key profiles work equally well on atonal or heavily modulating music.','Confusing the key profile template with the actual pitch content of one song.','Believing a single profile fits all musical styles.']::text[],ARRAY['Automatically tagging keys in a DJ or production library.','Building a key-detection algorithm.','Analyzing tonal structure of a corpus.']::text[],'intermediate',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Key profile');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1787','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1787') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1787');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1788','Localization blur','Localization blur is the smallest change in a sound source''s direction that a listener can just reliably detect, marking the angular resolution of auditory localization. It is smallest for broadband sources directly ahead, where it can be around one degree, and grows toward the sides and rear.','Localization blur is how finely you can tell a sound''s direction. It is the smallest angle change you can notice. Straight ahead you can hear tiny shifts. To the sides and behind, the blur is larger. So direction is fuzzier there.','It sets a practical limit on how precisely spatial audio needs to place sources, since finer detail than the blur is not perceived.','Knowing frontal blur is near one degree, a technician spends more panning precision on front images and less on rear objects, where larger placement errors go unnoticed.','Spatial perception',ARRAY['In-head localization','Fine-structure cue','Directional loudness','Rendering matrix']::text[],ARRAY['Assuming localization is equally sharp in all directions.','Confusing localization blur with the size or width of a source image.','Thinking blur values from the front apply to the sides and rear.']::text[],ARRAY['Deciding panning resolution for an immersive renderer.','Setting speaker spacing in a sound-field system.','Interpreting listening-test placement errors.']::text[],'intermediate',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Localization blur');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1788','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1788') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1788');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1789','Loudness range','Loudness range, abbreviated LRA, is a statistical measure of how much the loudness of a programme varies over its duration, expressed in loudness units (LU). It is computed from the distribution of gated short-term loudness values as the difference between the 95th and 10th percentiles, per EBU Tech 3342.','Loudness range says how much a programme''s loudness moves up and down. A small range means fairly steady loudness. A large range means big swings between quiet and loud. It is measured from the spread of short-term loudness values. The unit is the loudness unit, or LU.','It tells engineers whether a programme has wide dynamics or a compressed, consistent level, guiding decisions about processing for a given platform.','If the 95th-percentile short-term loudness is -14 LUFS and the 10th percentile is -23 LUFS, the loudness range is 9 LU, warning of wide swings that may need control for mobile listening.','Loudness measurement',ARRAY['Integrated loudness','Gated loudness','K-weighting','Normalized loudness']::text[],ARRAY['Confusing loudness range with dynamic range measured on peak meters.','Assuming a low loudness range always means over-compression.','Mixing up the LRA gating with the integrated-loudness gating thresholds.']::text[],ARRAY['Checking whether a mix suits quiet mobile listening.','Comparing dynamics across programmes for a platform spec.','Reporting loudness metrics alongside integrated loudness.']::text[],'intermediate','LRA = P95 - P10','The loudness range equals the ninety-fifth percentile of the gated short-term loudness distribution minus its tenth percentile, in loudness units.','5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Loudness range');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1789','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1789') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1789');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1790','Loudness recruitment','Loudness recruitment is an abnormally rapid growth of perceived loudness with increasing sound level, characteristic of ears with cochlear (sensorineural) hearing loss. Because faint sounds are inaudible but loud sounds seem nearly as loud as in a normal ear, the usable range between threshold and discomfort is compressed.','Loudness recruitment is a hearing effect from inner-ear damage. Quiet sounds cannot be heard at all. But as the level rises, loudness grows very fast. Soon loud sounds seem about as loud as they would to a normal ear. This squeezes the comfortable range.','It explains why simply turning up a level for a hearing-impaired listener can jump from inaudible to uncomfortably loud, shaping how hearing aids compress sound.','A technician fitting assistive audio uses gentle amplification for soft sounds and less gain for loud ones, respecting the narrowed range that recruitment leaves between audible and uncomfortable.','Loudness perception',ARRAY['Partial loudness','Directional loudness','Integrated loudness','Loudness range']::text[],ARRAY['UNSAFE: Boosting overall level for a hearing-impaired listener, which recruitment can push to painful, hearing-damaging loudness.','Confusing recruitment with simple deafness that needs only more volume.','Assuming linear amplification suits an ear with recruitment.']::text[],ARRAY['Setting compression in a hearing-aid or assistive-listening system.','Explaining why a listener finds loud passages uncomfortable but soft ones inaudible.','Designing accessible loudness options for a broadcast.']::text[],'advanced',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Loudness recruitment');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1790','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1790') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1790');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1791','Non-negative matrix factorization','Non-negative matrix factorization is a technique that approximates a non-negative matrix as the product of two smaller non-negative matrices, so that a spectrogram is expressed as spectral templates times their time-varying activations. The non-negativity constraint yields parts-based, additive components well suited to audio.','This method breaks a sound picture into building blocks. It finds a small set of spectral shapes. It also finds when each shape is active over time. Multiplying the shapes by their activity rebuilds the sound. All the numbers stay positive, which suits audio energy.','It provides an unsupervised way to decompose mixtures into interpretable components for source separation and transcription.','A technician factoring a piano recording sets around ten components, so the algorithm learns per-note spectral templates and their activations, then reconstructs individual notes.','Machine learning',ARRAY['Harmonic-percussive source separation','Primary-ambient decomposition','Key profile','Onset detection function']::text[],ARRAY['Expecting components to always map cleanly onto single instruments.','Ignoring that the result depends on the chosen number of components.','Confusing the additive parts-based model with methods that allow negative values.']::text[],ARRAY['Separating instruments from a mixture spectrogram.','Learning note templates for automatic transcription.','Reducing a spectrogram to a few interpretable components.']::text[],'advanced','V ~= W * H, with W >= 0 and H >= 0','The non-negative data matrix is approximated by the product of a non-negative basis matrix and a non-negative activation matrix, where every entry of both factor matrices is zero or positive.','5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Non-negative matrix factorization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1791','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1791') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1791');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1792','Normalized loudness','Normalized loudness is the state of a programme whose measured integrated loudness has been adjusted to a defined target, so that different items play back at a consistent level. The adjustment is a single gain equal to the target loudness minus the measured loudness, applied without changing the internal dynamics.','Normalized loudness means a programme is set to an agreed loudness target. Its overall loudness is measured first. Then one volume change moves it to the target. This lets different tracks or shows play at matched levels. Broadcast and streaming platforms each set their own target.','It removes jarring level jumps between programmes or tracks by aligning each to a shared loudness reference such as -23 LUFS for European broadcast.','A file measuring -18 LUFS against a -23 LUFS target gets a gain of -23 minus -18, or -5 LU, so the technician attenuates by 5 dB to normalize it.','Loudness measurement',ARRAY['Integrated loudness','Loudness range','K-weighting','Gated loudness']::text[],ARRAY['Confusing loudness normalization with peak normalization to 0 dBFS.','Assuming one target fits all platforms, when broadcast and streaming differ.','Expecting normalization to change dynamics rather than only overall gain.']::text[],ARRAY['Aligning a series to a broadcast loudness target.','Preparing a master for a streaming service''s normalization.','Batch-normalizing an archive to a common level.']::text[],'beginner','G = L_target - L_measured','The normalization gain in loudness units equals the target integrated loudness minus the measured integrated loudness of the programme.','5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Normalized loudness');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1792','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1792') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1792');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1793','Object priority','Object priority, also called importance, is metadata attached to an audio object that ranks how essential it is relative to other objects in an immersive scene. A renderer facing limited channels, speakers, or processing can use it to decide which objects to keep, cull, or cluster.','In immersive audio each sound can be a separate object. Object priority marks how important each one is. If the player runs low on resources, it keeps the top objects. Less important objects may be merged or dropped. This keeps key sounds like dialogue intact.','It lets a renderer degrade gracefully under limits by preserving the most important objects, such as dialogue, before less critical effects.','A technician tags dialogue objects with high priority, so a device that can render only a few objects at once keeps the voices and clusters the ambience.','Object metadata',ARRAY['Immersive audio bitstream','Rendering matrix','Downmix coefficient','Presentation timestamp']::text[],ARRAY['Assuming priority controls loudness rather than rendering importance.','Leaving all objects at equal priority, giving the renderer no guidance.','Confusing object priority with playback order or timing.']::text[],ARRAY['Authoring metadata for a scene with many effects objects.','Ensuring dialogue survives on resource-limited devices.','Clustering low-priority objects to fit a channel budget.']::text[],'intermediate',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Object priority');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1793','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1793') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1793');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1794','Onset asynchrony','Onset asynchrony is a grouping cue in auditory scene analysis in which frequency components that start at different times tend to be heard as belonging to separate sources. Even a small difference in onset time can pull a component out of a complex tone into its own perceived object.','Onset asynchrony is about when sounds begin. Parts that start together seem to belong to one source. Parts that start at slightly different times seem to split apart. The brain uses this timing to separate overlapping sounds. Even a short delay can matter.','It helps the auditory system separate simultaneous sounds, which informs how mixes and separation algorithms handle overlapping onsets.','A technician layering two synth notes staggers their onsets slightly so listeners hear two distinct sounds, exploiting onset asynchrony to keep them from fusing.','Auditory scene analysis',ARRAY['Onset detection function','Fine-structure cue','Pitch salience','Harmonic-percussive source separation']::text[],ARRAY['Confusing onset asynchrony, a grouping cue, with onset detection, an analysis step.','Assuming only large timing gaps cause perceptual separation.','Ignoring that harmonic relationships also affect whether components fuse.']::text[],ARRAY['Layering sounds so they read as separate voices.','Explaining why a mistuned or late harmonic pops out of a chord.','Designing stimuli for auditory grouping experiments.']::text[],'advanced',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Onset asynchrony');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1794','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1794') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1794');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1795','Onset detection function','An onset detection function is a one-dimensional signal derived from audio that rises sharply at note or event onsets, so that peaks in it mark likely onset times. A common form is spectral flux, which sums the positive frame-to-frame increases in magnitude across frequency bins.','An onset detection function is a curve made from audio. It jumps up whenever a new note or hit begins. Software then looks for peaks in this curve. Each peak marks a likely onset time. One common version adds up rises in energy across frequencies.','It converts raw audio into a signal whose peaks are easy to pick, enabling onset detection, beat tracking, and segmentation.','Using spectral flux, if a bin''s magnitude rises from 2 to 5 between frames it adds 3 to the function, and only such increases are summed to flag an onset.','Music information retrieval',ARRAY['Onset asynchrony','Harmonic-percussive source separation','Pitch salience','Key profile']::text[],ARRAY['Confusing the detection function with the final list of detected onsets.','Summing both increases and decreases instead of only positive changes.','Assuming one detection function suits every instrument type.']::text[],ARRAY['Feeding a beat tracker with detected onsets.','Segmenting a recording into notes or events.','Tuning peak-picking thresholds for onset detection.']::text[],'advanced','ODF(n) = sum_k H( |X(n,k)| - |X(n-1,k)| )','The onset detection function at frame n equals the sum over frequency bins of the half-wave-rectified difference between the magnitude in the current frame and the magnitude in the previous frame, so only increases are counted.','5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Onset detection function');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1795','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1795') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1795');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1796','Order of an ambisonic system','The order of an ambisonic system is the highest spherical harmonic degree used to represent the sound field, setting its spatial resolution. For a full three-dimensional (periphonic) system the number of channels equals the order plus one, squared.','Ambisonic order tells how detailed the sound sphere is. A higher order means sharper direction and more channels. First order uses four channels. Each step up adds more channels and finer placement. The order fixes the channel count.','It quantifies the trade-off between spatial accuracy and channel count, guiding format and bandwidth choices.','For a third-order full-sphere system the channel count is (3 + 1) squared, or 16, which the technician budgets for when choosing storage and transport.','Ambisonics',ARRAY['High-order ambisonics','Higher-order ambisonic coefficient','Plane-wave decomposition','Rendering matrix']::text[],ARRAY['Using the two-dimensional channel count where a full-sphere system needs the squared formula.','Confusing ambisonic order with the number of playback speakers.','Assuming order can be increased after a lower-order capture.']::text[],ARRAY['Budgeting channels for an ambisonic delivery.','Choosing capture order for a spherical microphone.','Explaining why first order has four channels.']::text[],'intermediate','N = (M + 1)^2','For a full three-dimensional ambisonic system the number of channels equals the order plus one, all squared.','5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Order of an ambisonic system');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1796','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1796') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1796');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1797','Partial loudness','Partial loudness is the loudness of a sound that is partly masked by another sound present at the same time, as opposed to its loudness in quiet. In loudness models it is computed from the portion of the signal''s excitation that exceeds the masking noise, so partial loudness falls as the masker grows.','Partial loudness is how loud a sound seems when another sound partly hides it. In quiet it would seem louder. With a masker present, only the part that stands out counts. As the masker gets stronger, the partial loudness drops. Loudness models calculate this.','It predicts how audible and how loud a component remains within a mixture, useful for mixing and for perceptual coding.','A technician judging whether a synth pad survives under a loud drum loop reasons in terms of partial loudness, raising the pad only until it clears the masking.','Loudness perception',ARRAY['Loudness recruitment','Directional loudness','Integrated loudness','Pitch salience']::text[],ARRAY['Confusing partial loudness with the total loudness of the whole mixture.','Assuming a component keeps its unmasked loudness inside a mix.','Ignoring that partial loudness depends on the masker''s spectrum and level.']::text[],ARRAY['Judging whether an element stays audible in a dense mix.','Reasoning about masking in perceptual audio coding.','Setting relative levels so a part is just audible.']::text[],'advanced',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Partial loudness');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1797','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1797') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1797');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1798','Perceptual linear prediction','Perceptual linear prediction is a speech-analysis method that transforms the short-term spectrum using psychoacoustic steps: a critical-band warping, an equal-loudness pre-emphasis, and an intensity-to-loudness power law, before fitting an all-pole model. The result is a compact feature set that emphasizes perceptually relevant spectral detail.','Perceptual linear prediction turns speech into a small set of numbers. First it reshapes the spectrum to match hearing. It groups frequencies into critical bands. It weights them by how loud we hear them. Then it fits a simple model to get features for recognition.','It produces speech features that suppress detail the ear ignores, improving robustness in automatic speech recognition.','A technician building a speech recognizer chooses perceptual linear prediction features so the front end downplays fine spectral detail listeners do not use, aiding recognition in noise.','Speech processing',ARRAY['Non-negative matrix factorization','Key profile','Pitch salience','Onset detection function']::text[],ARRAY['Confusing perceptual linear prediction with plain linear predictive coding, which skips the psychoacoustic steps.','Assuming it is a coding method rather than a feature-extraction method.','Overlooking that its steps model hearing, not the vocal tract alone.']::text[],ARRAY['Designing a front end for speech recognition.','Comparing speech features under noisy conditions.','Explaining psychoacoustically motivated speech analysis.']::text[],'advanced',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Perceptual linear prediction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1798','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1798') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1798');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1799','Pitch salience','Pitch salience is the perceptual prominence with which a particular pitch stands out in a sound, especially in complex or polyphonic material. In music analysis a salience function assigns, across frequency and time, a value indicating how strongly each candidate pitch is present.','Pitch salience is how much a pitch stands out to the ear. In a busy mix, some pitches are easy to hear and some are faint. A salience function scores each possible pitch over time. High scores mark the pitches a listener notices most. It helps track melodies.','It supports melody extraction and multi-pitch estimation by highlighting which pitches are perceptually dominant at each moment.','A technician extracting a lead melody runs a salience function, then follows the highest-salience pitch track through the recording to isolate the tune.','Music information retrieval',ARRAY['Pitch strength','Key profile','Onset detection function','Harmonic-percussive source separation']::text[],ARRAY['Confusing pitch salience with loudness, though the two are related.','Assuming the most salient pitch is always the intended melody.','Treating salience as a single number rather than a time-frequency function.']::text[],ARRAY['Extracting the main melody from a polyphonic recording.','Estimating multiple simultaneous pitches.','Ranking pitch candidates for transcription.']::text[],'advanced',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pitch salience');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1799','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1799') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1799');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1800','Pitch strength','Pitch strength is the degree to which a sound evokes a clear, definite pitch sensation, ranging from a strong tonal pitch to a weak, noise-like one. It is a perceptual attribute separate from pitch height, so two sounds at the same pitch can differ in how strongly that pitch is heard.','Pitch strength is how clearly a sound has a pitch. A pure tone has a strong, definite pitch. Filtered noise has a weak, vague pitch. Two sounds can share the same pitch yet differ in strength. It measures the clarity, not the height, of the pitch.','It captures how tonal versus noisy a sound is, informing sound design, synthesis, and psychoacoustic description.','A technician shaping a bell tone widens or narrows its spectral peaks to raise or lower pitch strength, making the pitch feel either firm or vague.','Psychoacoustics',ARRAY['Pitch salience','Fine-structure cue','Key profile','Partial loudness']::text[],ARRAY['Confusing pitch strength (clarity) with pitch height (how high or low).','Assuming louder sounds automatically have stronger pitch.','Treating noisy sounds as having no pitch rather than a weak one.']::text[],ARRAY['Designing tonal versus noisy sound-effect timbres.','Describing why some sounds have a vague pitch.','Comparing tonal clarity across synthesized sounds.']::text[],'intermediate',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pitch strength');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1800','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1800') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1800');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1801','Plane-wave decomposition','Plane-wave decomposition represents a sound field as a weighted superposition of plane waves arriving from many directions, giving a directional map of the field. In ambisonics it is obtained from the spherical-harmonic coefficients and underlies beamforming and decoding to loudspeakers.','A sound field can be seen as many flat waves from all directions. Plane-wave decomposition finds how much comes from each direction. This makes a map of where sound arrives from. Ambisonic systems use it to steer sound to speakers. It also supports beamforming.','It turns a captured sound field into directional components, enabling analysis, beamforming, and decoding to any speaker layout.','A technician analyzing an ambisonic recording performs a plane-wave decomposition to see which directions carry the most energy before choosing a decoder.','Ambisonics',ARRAY['High-order ambisonics','Higher-order ambisonic coefficient','Order of an ambisonic system','Rendering matrix']::text[],ARRAY['Assuming a plane wave is a real point source rather than an idealized direction.','Confusing the directional decomposition with the final speaker feeds.','Ignoring that resolution is limited by the ambisonic order.']::text[],ARRAY['Mapping directional energy in an ambisonic recording.','Designing a beamformer from sound-field data.','Preparing signals for ambisonic decoding.']::text[],'advanced',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Plane-wave decomposition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1801','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1801') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1801');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1802','Presentation timestamp','A presentation timestamp, abbreviated PTS, is a field in a program or transport stream that specifies the intended presentation time of an access unit such as an audio or video frame, referenced to the stream''s system clock. Defined in ISO/IEC 13818-1, it is carried at a 90 kHz clock resolution and lets a decoder present audio and video in sync.','A presentation timestamp says when a frame should be played. It is a time value stored in the stream. The decoder reads it to show audio and video together. It is measured against the stream''s own clock. This keeps sound and picture in sync.','It provides the timing reference that keeps audio and video aligned during playback of a multiplexed stream.','A technician diagnosing lip-sync error inspects the audio and video presentation timestamps, since a fixed offset between them shifts sound relative to picture.','Stream timing',ARRAY['Immersive audio bitstream','Object priority','Rendering matrix','Downmix coefficient']::text[],ARRAY['Confusing the presentation timestamp with the decoding timestamp, which can differ.','Assuming the 90 kHz clock is the audio sample rate.','Ignoring that a constant PTS offset causes a fixed lip-sync error.']::text[],ARRAY['Diagnosing lip-sync in a broadcast stream.','Multiplexing audio and video into a transport stream.','Verifying timing after re-encoding.']::text[],'intermediate',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Presentation timestamp');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1802','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1802') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1802');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1803','Primary-ambient decomposition','Primary-ambient decomposition splits an audio signal, often stereo, into a primary component made of directional, correlated content and an ambient component made of diffuse, decorrelated content. Separating the two lets a processor treat direct sounds and reverberation differently, for example when upmixing to more channels.','This method splits a signal into two parts. The primary part is the direct, pointed sound. The ambient part is the diffuse background and reverberation. Keeping them apart lets a system place each correctly. It is often used to upmix stereo to surround.','It enables spatial upmixing and enhancement by routing directional content and diffuse content to appropriate output positions.','A technician upmixing stereo to surround extracts the ambient component and steers it to the rear speakers while keeping the primary component up front.','Source separation',ARRAY['Harmonic-percussive source separation','Non-negative matrix factorization','Rendering matrix','Plane-wave decomposition']::text[],ARRAY['Assuming the primary component contains only one source.','Confusing the ambient component with simple stereo difference (side) signal.','Expecting perfect separation of direct sound from reverberation.']::text[],ARRAY['Upmixing a stereo recording to surround.','Enhancing spatial impression of a two-channel mix.','Separating reverberation for re-processing.']::text[],'advanced',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Primary-ambient decomposition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1803','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1803') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1803');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1804','Quadrature mirror filter','A quadrature mirror filter is one of a pair of filters that split a signal into two frequency subbands whose responses are mirror images about the quarter-sampling frequency. When the two subbands are later recombined, the pair is designed so that aliasing introduced by downsampling cancels, allowing near-perfect reconstruction.','A quadrature mirror filter splits sound into a low band and a high band. The two filters are mirror images of each other. Splitting lets each band be processed on its own. When the bands are rejoined, the errors from splitting cancel out. This is used in audio compression.','It provides the subband split used in filter banks for perceptual audio coding, so each band can be quantized according to its perceptual importance.','A technician tracing a codec''s filter bank sees a quadrature mirror pair split the band in two, with the high-pass built as the low-pass mirrored about the quarter-rate frequency.','Filter banks',ARRAY['Non-negative matrix factorization','Immersive audio bitstream','Downmix coefficient','Rendering matrix']::text[],ARRAY['Assuming a single filter is a quadrature mirror filter, when it is a designed pair.','Believing each subband alone is alias-free before reconstruction.','Confusing the mirror relationship with simple crossover filters.']::text[],ARRAY['Tracing the filter bank inside a perceptual audio codec.','Explaining subband coding to a student.','Analyzing aliasing cancellation in a two-band split.']::text[],'advanced','H1(z) = H0(-z)','The high-pass filter of the pair is obtained from the low-pass filter by replacing the frequency variable z with its negative, which mirrors the response about the quarter-sampling frequency.','5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Quadrature mirror filter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1804','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1804') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1804');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1805','Rendering matrix','A rendering matrix is a set of gain coefficients that maps input audio signals, such as ambisonic components or audio objects, onto a specific set of output signals, usually loudspeaker or headphone feeds. Multiplying the input signal vector by the matrix produces the output feeds for a given playback layout.','A rendering matrix is a grid of gains. It turns input audio into speaker signals. Each output speaker gets a weighted mix of the inputs. Changing the matrix adapts the same content to a new speaker layout. It is the core of an audio renderer.','It formalizes how a scene or ambisonic signal is decoded to a particular reproduction system, so one mix can serve many layouts.','With output = matrix times input, a technician swaps in a new rendering matrix to move a mix from a 7.1 room to a headphone binaural setup without re-editing the objects.','Rendering',ARRAY['Downmix coefficient','Higher-order ambisonic coefficient','Object priority','Immersive audio bitstream']::text[],ARRAY['Confusing the rendering matrix with a downmix, which is one special case.','Assuming a fixed matrix suits every speaker layout.','Treating the matrix rows and columns loosely and swapping inputs with outputs.']::text[],ARRAY['Decoding an ambisonic scene to a speaker array.','Adapting an object mix to headphones.','Configuring a renderer for a non-standard layout.']::text[],'advanced','y = R * x','The output signal vector equals the rendering matrix multiplied by the input signal vector, so each output feed is a weighted sum of the input signals.','5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rendering matrix');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1805','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1805') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1805');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1806','Signal-to-mask ratio','In perceptual audio coding, the signal-to-mask ratio (SMR) is the ratio, in decibels, of the signal energy in a frequency subband to the masking threshold in that band, as estimated by a psychoacoustic model. Encoders use each subband''s SMR to allocate quantization bits so that quantization noise stays below the masking threshold and remains inaudible.','The signal-to-mask ratio compares a sound''s strength to the level where it hides other sounds. Audio coders work it out for each frequency band. A high ratio means that band needs more bits. This keeps coding noise from being heard.','It tells a codec how audible a band is, so bits are spent where the ear will notice errors and saved where masking hides them.','In an MP3-style encoder the psychoacoustic model reports, say, an SMR of 30 dB in a band; the bit allocator then assigns enough bits to push the noise-to-mask ratio to 0 dB or below in that band.','Perceptual coding',ARRAY['Masking threshold','Critical band','Noise-to-mask ratio','Bit allocation','Perceptual audio coding']::text[],ARRAY['Confusing signal-to-mask ratio with signal-to-noise ratio; SMR is measured against the masking threshold, not the noise floor.','Assuming a fixed SMR; it changes with the signal and the psychoacoustic model.','Thinking a larger SMR means better quality; it means the band is more audible and needs more bits.']::text[],ARRAY['Tuning bit allocation in an MPEG-1 Layer 3 encoder.','Explaining why quiet passages code differently from loud ones.','Comparing psychoacoustic models in a codec evaluation.']::text[],'advanced','SMR_dB = L_signal - L_mask = 10 log10( P_signal / P_mask )','The signal-to-mask ratio in decibels is the subband signal level minus the masking-threshold level, which equals ten times the base-ten logarithm of their power ratio.','5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Signal-to-mask ratio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1806','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1806') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1806');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1807','Spatial aliasing frequency','The spatial aliasing frequency is the frequency above which a discrete array of transducers can no longer sample or reproduce a sound field unambiguously, because the acoustic wavelength becomes shorter than twice the element spacing. Above it, spatial sampling produces aliased directions or artifacts, analogous to temporal aliasing above the Nyquist frequency.','A speaker or microphone array has gaps between its elements. Above a certain frequency the sound waves are shorter than those gaps. Then the array cannot capture or steer them correctly. This limit is the spatial aliasing frequency.','It sets the usable upper frequency of an array, guiding how closely elements must be spaced for clean beamforming or sound-field synthesis.','For a line array with 2 cm spacing in air at 343 m/s, the spatial aliasing frequency is c/(2d) = 343/(2 x 0.02) = about 8.6 kHz, so aliasing lobes appear above roughly 8.6 kHz.','Array processing',ARRAY['Wave field synthesis','Superdirective beamforming','Vector-base amplitude panning','Nyquist frequency','Grating lobe']::text[],ARRAY['Confusing spatial aliasing with temporal aliasing; one comes from element spacing, the other from sample rate.','Assuming closer spacing is always free; it raises cost and mutual coupling.','Ignoring source angle, which lowers the effective aliasing frequency for off-axis sources.']::text[],ARRAY['Choosing driver spacing for a beam-steering column loudspeaker.','Designing a microphone array for a conferencing system.','Predicting the high-frequency limit of a wave field synthesis rig.']::text[],'advanced','f_alias = c / (2 d)','The spatial aliasing frequency equals the speed of sound divided by twice the spacing between adjacent array elements.','5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spatial aliasing frequency');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1807','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1807') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1807');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1808','Spatial audio object coding','Spatial Audio Object Coding (SAOC) is an MPEG parametric method that transmits several audio objects as one or a few downmix channels plus compact side information, letting the decoder re-render and re-balance the individual objects at playback. It is standardized as MPEG-D SAOC in ISO/IEC 23003-2.','SAOC sends many sound objects mixed into just a few channels. It adds small extra data describing each object. The player can then rebuild and re-balance those objects. This saves data while keeping listener control.','It lets interactive and low-bitrate services carry many separable sources, so listeners can move, mute, or re-level objects such as voices at the receiver.','A technician running an interactive dialogue service uses an SAOC decoder to boost a commentator object relative to crowd noise, guided by the object metadata sent alongside the downmix.','Object-based coding',ARRAY['MPEG Surround','Object-based audio','Downmix','Parametric spatial audio','Metadata']::text[],ARRAY['Confusing SAOC with channel-based surround coding; SAOC keeps objects separable, not fixed to channels.','Assuming SAOC stores each object as a full audio track; it sends a downmix plus parameters.','Mixing up SAOC with MPEG Surround, which parametrically codes channels, not objects.']::text[],ARRAY['Interactive sports audio with adjustable commentary.','Teleconferencing with independently controllable talkers.','Low-bitrate immersive services needing listener remixing.']::text[],'advanced',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spatial audio object coding');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1808','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1808') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1808');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1809','Spatial impression','Spatial impression is the perceived sense of space a room adds to sound, commonly divided into apparent source width (the broadening of the source) and listener envelopment (the sense of being surrounded by sound). It is driven largely by early and late lateral reflections and is quantified in room acoustics by measures such as the early lateral energy fraction.','Spatial impression is how spacious a room makes sound feel. One part is how wide a source seems. Another part is the feeling of being surrounded. Side reflections from the walls create both effects.','It captures why a concert hall feels enveloping, helping acousticians link measurable lateral reflections to a valued listening quality.','To improve spatial impression a technician measures the early lateral energy fraction and adds side reflections; a value near 0.2 or higher is typical of well-regarded halls.','Room acoustics',ARRAY['Lateral energy fraction','Interaural cross-correlation','Listener envelopment','Apparent source width','Reverberation']::text[],ARRAY['Thinking more reverberation alone gives spatial impression; lateral (side) energy matters most.','Treating apparent source width and envelopment as the same thing.','Assuming frontal reflections widen the source as much as side reflections do.']::text[],ARRAY['Assessing a concert hall''s acoustic quality.','Designing reflector panels to widen an ensemble.','Comparing seats for envelopment in a performance space.']::text[],'intermediate','LF = ( integral_{5ms}^{80ms} p_L^2(t) dt ) / ( integral_{0}^{80ms} p^2(t) dt )','The early lateral energy fraction is the sound energy arriving from the sides between 5 and 80 milliseconds divided by the total early energy in the first 80 milliseconds.','5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spatial impression');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1809','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1809') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1809');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1810','Speech intelligibility index','The Speech Intelligibility Index (SII) is a standardized value between 0 and 1 that predicts the proportion of speech information available to a listener, computed as a weighted sum of the effective signal-to-noise ratio across frequency bands. It is defined by ANSI/ASA S3.5 and weights each band by a band-importance function for speech.','The Speech Intelligibility Index predicts how much speech a listener can follow. It runs from 0, meaning none, to 1, meaning all. It adds up the signal-to-noise ratio in each frequency band. Bands that matter more for speech count more.','It gives a repeatable score for how well a system or environment supports understanding speech, replacing guesswork with a standardized metric.','To rate a paging zone a technician measures band signal-to-noise ratios, clips each band''s audibility to the 0-to-1 range, weights by the band-importance values, and sums them; an SII of 0.75 predicts good intelligibility.','Speech metric',ARRAY['Speech transmission index','Articulation index','Critical band','Signal-to-noise ratio','Band-importance function']::text[],ARRAY['Confusing SII with the Speech Transmission Index; STI uses modulation, SII uses band signal-to-noise ratios.','Reading SII as a percentage of words correct rather than an index of available information.','Forgetting to clip each band''s audibility to the 0-to-1 range before weighting.']::text[],ARRAY['Evaluating a hearing-aid fitting.','Specifying a public-address system for announcements.','Comparing noisy classrooms for speech access.']::text[],'advanced','SII = sum_{i=1}^{n} I_i * A_i','The Speech Intelligibility Index is the sum over frequency bands of each band''s importance weight times that band''s audibility, where the importance weights add up to one.','5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Speech intelligibility index');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1810','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1810') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1810');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1811','Streaming loudness compliance','Streaming loudness compliance is the practice of delivering programme audio at the integrated loudness target and true-peak ceiling specified by a streaming platform, measured with the ITU-R BS.1770 loudness algorithm. Because platforms normalize playback to their own targets (commonly around -14 LUFS for music services), compliant masters avoid unwanted gain changes and clipping.','Streaming services play everything at a set loudness. They turn tracks up or down to hit that target. Compliance means delivering audio at the platform''s loudness and peak limits. This keeps your mix sounding as intended.','It ensures a release survives platform loudness normalization without being turned down or distorted, giving consistent, artifact-free playback across services.','A mastering engineer measures integrated loudness with a BS.1770 meter, targets about -14 LUFS with true peaks at or below -1 dBTP for a music service, then re-checks before upload.','Loudness practice',ARRAY['True peak level','Loudness units relative to full scale','ITU-R BS.1770','EBU R128','Loudness range']::text[],ARRAY['Assuming one loudness target fits every platform; music, broadcast, and podcast targets differ.','Mastering hot above the target expecting more loudness; the service just turns it down.','Checking sample peak instead of true peak, so inter-sample overs slip through.']::text[],ARRAY['Delivering a single to a music streaming service.','Preparing a podcast to a spoken-word loudness target.','Setting export presets in a mastering session.']::text[],'intermediate',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Streaming loudness compliance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1811','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1811') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1811');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1812','Superdirective beamforming','Superdirective beamforming is an array technique that achieves higher directivity than conventional delay-and-sum processing for a given aperture, especially at low frequencies, by optimizing element weights to exploit small phase differences between closely spaced sensors. The gain comes at the cost of high sensitivity to sensor noise and mismatch, quantified by a low white-noise gain.','A superdirective array can focus tightly even when small. It weights closely spaced microphones with care. This cuts noise picked up from other directions. The cost is being very sensitive to sensor noise.','It squeezes more directional gain from a compact microphone array, useful where a large array is impractical, such as in hearing aids or laptops.','A technician building a two-microphone endfire array with millimetre spacing can approach the superdirective limit near a directivity factor of N^2 = 4 (about 6 dB), but must add robustness constraints to keep noise gain acceptable.','Array processing',ARRAY['Spatial aliasing frequency','Beamforming','Directivity index','White-noise gain','Endfire array']::text[],ARRAY['Expecting superdirective gain for free; real arrays trade it against severe noise sensitivity.','Assuming wider spacing improves it; superdirectivity relies on small spacing.','Ignoring calibration; small gain or phase errors destroy the theoretical directivity.']::text[],ARRAY['Designing a hearing-aid microphone array.','Improving voice pickup on a compact device.','Teaching the limits of small-aperture arrays.']::text[],'advanced','D_max = N^2   (endfire array, isotropic elements, spacing -> 0)','For an endfire array of N isotropic elements with vanishingly small spacing, the maximum achievable directivity factor approaches the square of the number of elements.','5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Superdirective beamforming');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1812','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1812') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1812');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1813','Temporal envelope cue','The temporal envelope is the relatively slow variation in the amplitude of a sound, or of a band-limited channel, over time, and its cues (roughly 2-50 Hz modulations) carry much of the information for identifying speech and rhythm. It is often extracted as the magnitude of the analytic signal within a frequency band.','The temporal envelope is how a sound''s loudness rises and falls over time. These slow changes carry speech rhythm and syllables. The ear uses them to recognize words. They are the outline of the waveform, not its fast wiggles.','It explains how listeners understand speech from slow amplitude changes, and it underlies vocoder and cochlear-implant processing that transmit mainly envelope information.','A cochlear-implant or channel-vocoder designer splits sound into bands, extracts each band''s envelope, and uses those envelopes to modulate carriers, keeping speech intelligible even when fine detail is discarded.','Auditory cue',ARRAY['Temporal fine structure','Temporal weighting function','Critical band','Amplitude modulation','Vocoder']::text[],ARRAY['Confusing the envelope with the temporal fine structure; the envelope is the slow outline, the fine structure is the fast carrier.','Assuming envelope cues alone give good pitch or localization; those rely more on fine structure.','Thinking envelope means the whole waveform rather than its amplitude contour.']::text[],ARRAY['Designing cochlear-implant speech processors.','Explaining why vocoded speech stays intelligible.','Analyzing speech rhythm and modulation.']::text[],'intermediate','e(t) = | s(t) + j * s_hat(t) |','The temporal envelope is the magnitude of the analytic signal, formed from the band signal and its Hilbert transform.','5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Temporal envelope cue');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1813','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1813') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1813');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1814','Temporal fine structure','Temporal fine structure is the rapid oscillation of a band-limited sound near its center frequency, carried by the phase of the analytic signal, in contrast to the slow temporal envelope. It provides important cues for pitch perception, sound localization, and listening in noisy backgrounds.','Temporal fine structure is the fast wiggle of a sound inside a frequency band. It sits under the slower loudness outline. The ear uses it for pitch and direction. It also helps us hear speech in noise.','It explains how the auditory system extracts pitch and location from fast waveform detail, and why losing this information degrades hearing in noise.','A technician assessing why a hearing-impaired listener struggles in noise can attribute part of the deficit to poor use of temporal fine structure, which many coders and implants do not preserve.','Auditory cue',ARRAY['Temporal envelope cue','Temporal weighting function','Interaural time difference','Pitch perception','Critical band']::text[],ARRAY['Swapping fine structure and envelope; fine structure is the fast carrier, envelope is the slow outline.','Assuming standard vocoders keep fine structure; most discard it and keep only the envelope.','Believing fine structure only affects pitch; it also aids localization and speech-in-noise.']::text[],ARRAY['Explaining speech-in-noise difficulty with hearing loss.','Comparing pitch cues in coders.','Studying binaural localization from waveform timing.']::text[],'advanced','s(t) = e(t) * cos( phi(t) ) ,  TFS = cos( phi(t) )','A band signal can be written as its envelope times the cosine of an instantaneous phase; the temporal fine structure is that fast cosine carrier.','5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Temporal fine structure');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1814','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1814') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1814');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1815','Temporal weighting function','A temporal weighting function specifies how a meter or model weights sound energy over time when forming a running level or loudness value; in sound level meters it is an exponential time weighting with a standard time constant, such as Fast (0.125 s) or Slow (1 s). It causes recent sound to dominate the reading while earlier sound decays smoothly.','A temporal weighting function decides how a meter blends sound over time. Recent sound counts most and older sound fades out. Sound level meters use set time constants called Fast and Slow. This gives a smooth, standard reading.','It standardizes how quickly a meter responds to changing sound, so different instruments give comparable, repeatable level readings.','A technician selects Fast (tau = 0.125 s) time weighting to follow speech peaks, or Slow (tau = 1 s) to read steady background noise, knowing both apply an exponential decay to past energy.','Measurement weighting',ARRAY['Zwicker loudness model','Sound level meter','Time constant','Integration time','Frequency weighting']::text[],ARRAY['Confusing temporal (time) weighting with frequency weighting such as A or C.','Assuming Fast and Slow read the same on fluctuating sound; the time constant changes the result.','Treating the reading as an instantaneous value rather than an exponentially weighted average.']::text[],ARRAY['Choosing Fast or Slow on a sound level meter.','Metering fluctuating noise for a survey.','Explaining meter ballistics in loudness measurement.']::text[],'intermediate','p_tau^2(t) = (1/tau) * integral_{-inf}^{t} p^2(xi) * exp( -(t - xi)/tau ) d xi','The time-weighted mean-square sound pressure is a running average of past squared pressure, with each earlier instant weighted by an exponential that decays over the time constant.','5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Temporal weighting function');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1815','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1815') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1815');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1816','Transaural reproduction','Transaural reproduction delivers binaural (two-ear) signals over two or more loudspeakers by applying crosstalk cancellation, so each ear receives mainly its intended signal and little of the other channel. By inverting the loudspeaker-to-ear transfer matrix, it recreates over speakers the ear signals normally achieved with headphones.','Transaural reproduction plays binaural recordings through loudspeakers, not headphones. Normally each speaker leaks into the wrong ear. The method cancels that crosstalk with filters. Then each ear hears mostly its own channel.','It lets ear-specific binaural cues, and thus 3D spatial audio, work over loudspeakers, extending headphone-style spatialization to a listener in a sweet spot.','A technician sets up a transaural system by measuring or modeling the speaker-to-ear responses, building an inverse crosstalk-cancellation filter, and keeping the listener at the calibrated position for the effect to hold.','Spatial reproduction',ARRAY['Wave field synthesis','Vector-base amplitude panning','Binaural audio','Crosstalk cancellation','Head-related transfer function']::text[],ARRAY['Confusing transaural with plain stereo; transaural adds crosstalk cancellation and binaural cues.','Expecting a wide sweet spot; the cancellation holds only near the calibrated position.','Assuming it needs many speakers; two suffice, with more used to widen or stabilize it.']::text[],ARRAY['3D audio demos over a pair of desktop speakers.','Binaural playback without headphones.','Virtual surround from a soundbar.']::text[],'advanced','C = H^{-1} ,  y = C x   (2x2: H = [[H_LL, H_RL],[H_LR, H_RR]])','The crosstalk-cancellation filter is the inverse of the loudspeaker-to-ear transfer matrix; applying it to the desired ear signals yields the loudspeaker feeds.','5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Transaural reproduction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1816','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1816') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1816');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1817','True peak level','True peak level is the maximum level of the continuous waveform reconstructed from digital samples, expressed in decibels relative to full scale (dBTP), and it captures inter-sample peaks that lie between sample points. It is estimated by oversampling the signal at least four times before taking the maximum, as specified in ITU-R BS.1770.','Digital audio stores only sample points. The real wave between them can rise higher than any sample. True peak level measures that highest point of the rebuilt wave. It is written in dBTP, decibels relative to full scale.','It warns of clipping that a plain sample-peak meter misses, protecting downstream converters and lossy codecs from distortion caused by inter-sample overs.','A mastering engineer sets a true-peak ceiling of -1 dBTP (per EBU R128); an oversampled peak of 1.12 times full scale would read 20 log10(1.12) = about +1.0 dBTP, signaling likely clipping.','Loudness metering',ARRAY['Streaming loudness compliance','Loudness units relative to full scale','ITU-R BS.1770','Inter-sample peak','EBU R128']::text[],ARRAY['Confusing sample peak with true peak; true peak can exceed the highest stored sample.','Assuming a 0 dBFS sample peak is safe; inter-sample peaks can still clip after conversion.','Reading dBTP as the same as LUFS; one is peak level, the other is loudness.']::text[],ARRAY['Setting a limiter''s true-peak ceiling in mastering.','Checking a broadcast deliverable against a dBTP limit.','Diagnosing distortion after lossy encoding.']::text[],'intermediate','L_TP = 20 log10( max_n | x_os[n] | )   (x_os = signal oversampled >= 4x; full scale = 1.0)','True peak level in dBTP is twenty times the base-ten logarithm of the largest absolute sample of the signal after oversampling by at least four times, referenced to full scale.','5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='True peak level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1817','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1817') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1817');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1818','Vector-base amplitude panning','Vector-base amplitude panning (VBAP), introduced by Ville Pulkki, is an amplitude-panning method that positions a virtual source by driving the two (in 2D) or three (in 3D) nearest loudspeakers with gains found from a vector formulation of their directions. The gain vector is obtained by expressing the target direction in the basis of the chosen loudspeaker direction vectors and then normalizing for constant perceived loudness.','VBAP places a virtual sound between loudspeakers using volume differences. It picks the two or three speakers nearest the target direction. It sets their levels from the speakers'' direction vectors. The gains are scaled to keep loudness steady.','It gives a simple, flexible way to pan sources across arbitrary 2D or 3D loudspeaker layouts, widely used in object-based and immersive rendering.','An immersive-audio renderer uses VBAP to place an object between three speakers, computing the gain vector g = p^T L^{-1} from the speaker directions, then scaling g so the squared gains sum to one.','Panning',ARRAY['Wave field synthesis','Transaural reproduction','Spatial audio object coding','Ambisonics','Amplitude panning']::text[],ARRAY['Expecting VBAP to synthesize a real wavefront; it only creates a phantom image between speakers.','Forgetting to normalize the gains, which changes perceived loudness with position.','Assuming it works for any layout without choosing the correct enclosing speaker pair or triplet.']::text[],ARRAY['Rendering objects in an immersive mix.','Panning across a dome of loudspeakers.','Implementing a game-audio spatializer.']::text[],'advanced','g = p^T * L^{-1} ,  then g_norm = g / ||g||   (L columns = active speaker direction vectors)','The panning gains are found by expressing the target direction vector in the basis of the active loudspeaker direction vectors, then normalizing so the gain vector has unit length for constant loudness.','5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Vector-base amplitude panning');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1818','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1818') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1818');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1819','Wave field synthesis','Wave field synthesis is a spatial sound reproduction method that uses a dense array of loudspeakers to physically reconstruct a desired sound field within a listening area, based on the Huygens principle and the Kirchhoff-Helmholtz integral. Unlike phantom-image panning, it can recreate wavefronts so that source direction and distance stay consistent over a large area rather than a single sweet spot.','Wave field synthesis rebuilds a real sound field with many loudspeakers. Each speaker acts like a small wave source. Together they recreate the wavefront of a virtual source. The effect works across a large area, not one seat.','It provides a large listening area with correct source localization, addressing the narrow sweet spot of stereo and surround panning.','A technician installing a WFS system spaces loudspeakers a few centimetres apart along the room edge and computes each driver''s signal from the target source, accepting a spatial aliasing frequency near c/(2 x spacing).','Sound field synthesis',ARRAY['Vector-base amplitude panning','Spatial aliasing frequency','Transaural reproduction','Ambisonics','Huygens principle']::text[],ARRAY['Confusing WFS with panning; WFS reconstructs a wavefront, while panning creates a phantom between speakers.','Ignoring spatial aliasing; wide driver spacing corrupts high frequencies.','Assuming a few speakers suffice; WFS needs a dense, closely spaced array.']::text[],ARRAY['Immersive installations and theme parks.','Research listening rooms with large arrays.','Auditoria needing a wide listening area.']::text[],'advanced','f_alias ~= c / (2 * delta_x)   (WFS high-frequency limit set by driver spacing)','Above a spatial aliasing frequency set by the loudspeaker spacing, wave field synthesis can no longer reconstruct the field cleanly; the limit is roughly the speed of sound divided by twice the spacing.','5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wave field synthesis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1819','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1819') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1819');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1820','Zwicker loudness model','The Zwicker loudness model computes the perceived loudness of a sound by transforming its spectrum into specific loudness (loudness per critical band) across the critical-band-rate (Bark) scale and integrating it, yielding total loudness in sones. It accounts for spectral masking and the nonlinear growth of loudness, and it is standardized for stationary sounds in ISO 532-1.','The Zwicker model predicts how loud a sound seems to people. It splits the sound into critical bands on the Bark scale. It finds a loudness value in each band, allowing for masking. Adding these up gives total loudness in sones.','It links measured spectra to perceived loudness, letting engineers rate products and signals by how loud they actually seem, not just their sound pressure level.','To rate appliance noise a technician runs the Zwicker method to get specific loudness across Bark bands, integrates it to a sone value, and compares products on that perceptual scale.','Loudness model',ARRAY['Temporal weighting function','Signal-to-mask ratio','Critical band','Sone','Bark scale']::text[],ARRAY['Confusing loudness in sones with sound pressure level in decibels.','Assuming a flat frequency weighting; the model uses critical bands and masking.','Applying the stationary Zwicker method to strongly time-varying sound without the time-varying extension.']::text[],ARRAY['Product sound-quality testing.','Rating appliance or vehicle noise.','Comparing loudness of complex spectra.']::text[],'advanced','N = integral_{0}^{24 Bark} N''(z) dz','Total loudness is the integral of specific loudness over the critical-band-rate scale from 0 to 24 Bark.','5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Zwicker loudness model');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1820','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1820') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1820');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1821','Absolute Limen','The absolute limen (absolute threshold) is the smallest stimulus magnitude a listener can just detect, conventionally the level detected on a fixed percentage of trials (often 50 percent). In hearing, it is the lowest sound level at a given frequency that produces an auditory sensation under stated measurement conditions.','The absolute limen is the faintest sound a person can just hear. Below it, the sound is missed. Scientists set it where the listener detects the sound half the time. It changes with frequency and test conditions.','It marks the lower boundary of hearing, letting researchers and clinicians measure sensitivity and define reference levels.','An audiologist finds a listener''s absolute limen at 1 kHz near 0 dB HL, matching the audiometric reference zero.','Psychophysics',ARRAY['Difference limen','Absolute threshold of hearing','Audiometric reference zero','Hearing threshold','Sensation level']::text[],ARRAY['Treating the absolute limen as a fixed physical value rather than a statistical detection level.','Confusing the absolute limen (detecting a stimulus) with the difference limen (detecting a change).','Ignoring that the method and response criterion shift the measured threshold.']::text[],ARRAY['Measuring the quietest tone a subject can hear in a listening test.','Explaining audiometric zero to a trainee.','Comparing detection thresholds across frequencies.']::text[],'intermediate',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Absolute Limen');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1821','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1821') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1821');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1822','Across-Formant Grouping','Across-formant grouping is the auditory scene analysis process by which the auditory system binds simultaneous formants (spectral peaks) from a common source, such as one voice, into a single perceived sound. Cues including a shared fundamental frequency, onset synchrony, and common spatial location promote this grouping.','Speech has several energy peaks called formants. The ear must decide which peaks belong to one voice. Grouping them lets you hear a single talker. Shared pitch and timing help the ear join them.','It lets listeners fuse the parts of a complex sound into one object, which is essential for understanding speech among competing sounds.','A researcher gives one formant a different pitch or ear and finds it splits off, showing across-formant grouping breaking down.','Auditory scene analysis',ARRAY['Auditory scene analysis','Formant','Fundamental frequency','Onset synchrony','Auditory stream']::text[],ARRAY['Assuming formants are grouped by frequency alone; onset time and common pitch also matter.','Confusing across-formant (simultaneous) grouping with sequential streaming.','Thinking grouping is fixed rather than dependent on grouping cues.']::text[],ARRAY['Studying how listeners separate two simultaneous vowels.','Designing speech-in-noise experiments.','Explaining perceptual fusion in a psychoacoustics course.']::text[],'advanced',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Across-Formant Grouping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1822','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1822') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1822');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1823','Across-Modal Influence','Across-modal (cross-modal) influence is the effect of one sensory modality on perception in another, such as vision altering heard speech or perceived sound location. Classic examples include the McGurk effect, where seen articulation changes the heard phoneme, and the ventriloquism effect, where vision shifts a sound''s apparent position.','What we see can change what we hear. A person''s lip movements can change the speech sound you perceive. A picture can pull a sound''s apparent location. These are cross-modal effects.','It shows the brain combines the senses into one perception, improving reliability when a single sense is ambiguous.','A sound engineer notes viewers localize dialogue to the on-screen actor, not the side loudspeaker, due to the ventriloquism effect.','Multisensory perception',ARRAY['McGurk effect','Ventriloquism effect','Auditory localization','Multisensory integration','Speech perception']::text[],ARRAY['Assuming hearing works independently of vision.','Confusing the McGurk effect (speech) with the ventriloquism effect (location).','Thinking cross-modal effects require conscious attention.']::text[],ARRAY['Explaining why on-screen dialogue seems to come from the actor.','Studying audiovisual speech in noisy rooms.','Designing cinema sound to match picture.']::text[],'intermediate',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Across-Modal Influence');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1823','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1823') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1823');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1824','Additivity of Forward Masking','Additivity of forward masking describes how the masking produced by two temporally separated forward maskers combines. When the individual masking amounts are expressed in decibels, the combined masking usually exceeds their simple sum, an excess attributed to the compressive nonlinearity of the cochlea.','A sound can raise the threshold for a later sound. This is forward masking. With two earlier sounds, their effects combine. The total is often larger than a simple sum. Cochlear compression explains the extra.','It provides a way to probe the nonlinear, compressive processing of the cochlea by testing how masking amounts add.','A researcher measures masking from two brief maskers alone, then together, and finds excess masking that reveals basilar-membrane compression.','Temporal masking',ARRAY['Forward masking','Cochlear compression','Basilar-membrane motion','Masking','Nonlinearity']::text[],ARRAY['Expecting masking in decibels to add linearly.','Confusing forward masking with simultaneous masking.','Ignoring cochlear compression when interpreting the excess masking.']::text[],ARRAY['Estimating cochlear compression from masking data.','Modeling temporal masking in a codec.','Teaching cochlear nonlinearity.']::text[],'advanced',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Additivity of Forward Masking');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1824','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1824') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1824');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1825','Air-conduction audiometry','Air-conduction audiometry measures pure-tone hearing thresholds for sounds presented through earphones or a loudspeaker, so the stimulus travels the outer, middle, and inner ear. Thresholds are recorded in decibels hearing level (dB HL) relative to standardized reference levels, following the procedure of ISO 8253-1 with calibration per ISO 389 and ANSI/ASA S3.6.','This test measures the quietest tones you can hear through earphones. The sound goes through the whole ear. Results are plotted as an audiogram. It shows hearing loss at each pitch.','It quantifies overall hearing sensitivity by frequency, forming the basis of clinical and occupational hearing assessment.','A technician presents 1 kHz tones and records the lowest level heard as, say, 15 dB HL, plotting it on the audiogram.','Audiometry',ARRAY['Bone-conduction audiometry','Audiogram','Hearing level','Audiometric reference zero','Hearing threshold']::text[],ARRAY['UNSAFE: Presenting tones at high levels with an uncalibrated audiometer, risking over-exposure and invalid results.','Confusing air-conduction thresholds with bone-conduction thresholds.','Forgetting to mask the non-test ear when a cross-hearing risk exists.']::text[],ARRAY['Screening a new employee''s hearing.','Diagnosing hearing loss in a clinic.','Calibrating an audiometer before testing.']::text[],'intermediate',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Air-conduction audiometry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1825','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1825') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1825');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1826','Annoyance','In community and environmental acoustics, annoyance is a person''s adverse reaction of displeasure or disturbance caused by noise. It is assessed with standardized survey questions and rating scales (ISO/TS 15666) and related to noise-exposure metrics in standards such as ISO 1996.','Annoyance is how much noise bothers people. It is a feeling, not a sound level. Surveys measure it with set questions and scales. It links noise exposure to community reaction.','It captures the human impact of environmental noise, guiding limits and planning where sound level alone is not enough.','A consultant surveys residents with the ISO/TS 15666 scale and relates the percent highly annoyed to measured day-evening-night levels.','Environmental acoustics',ARRAY['Environmental noise','Day-evening-night level','Loudness','Noise metric','Sound exposure']::text[],ARRAY['Equating annoyance directly with sound pressure level.','Ignoring non-acoustic factors such as attitude and time of day.','Using non-standard survey wording, which harms comparability.']::text[],ARRAY['Assessing community response to an airport.','Setting local noise ordinances.','Reporting percent highly annoyed in an impact study.']::text[],'intermediate',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Annoyance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1826','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1826') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1826');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1827','Antiphasic Listening Condition','An antiphasic listening condition presents a signal or masker with a 180 degree interaural phase difference, so the waveform at one ear is inverted relative to the other. In binaural detection studies this is denoted S-pi (signal out of phase) and typically produces a large masking-level difference.','The two ears get the same sound but flipped in phase. One ear''s wave is upside down versus the other. The brain uses this difference. It makes a hidden tone much easier to hear.','It creates the interaural differences that drive binaural unmasking, used to probe how the brain compares the two ears.','In an NoS-pi setup a technician inverts the tone at one ear and measures a threshold drop of roughly 12 to 15 dB at low frequencies.','Binaural hearing',ARRAY['Binaural unmasking','Masking-level difference','Interaural phase difference','Binaural advantage','Bilateral masking-level difference']::text[],ARRAY['Confusing the antiphasic (S-pi) condition with the in-phase (So) condition.','Assuming phase inversion helps equally at all frequencies; the benefit is largest at low frequencies.','Overlooking that signal and noise phase are specified separately.']::text[],ARRAY['Running a masking-level-difference experiment.','Explaining binaural release from masking.','Testing interaural phase sensitivity.']::text[],'advanced',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Antiphasic Listening Condition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1827','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1827') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1827');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1828','Apical Excitation','Apical excitation is stimulation of the apex of the cochlea, the region of the basilar membrane tuned to low frequencies. Because of tonotopic (place) organization, low-frequency sounds produce their peak traveling-wave displacement near the apex, while high frequencies peak near the base.','The cochlea is a coiled tube. Its far end, the apex, responds to low pitches. Low sounds shake this region most. This place coding maps pitch to position.','It reflects the cochlea''s frequency-to-place mapping, central to how frequency and pitch are coded in the inner ear.','A researcher notes a 200 Hz tone drives mainly apical regions, informing where a cochlear-implant electrode should stimulate for low pitches.','Cochlear mechanics',ARRAY['Basilar-membrane motion','Tonotopy','Traveling wave','Characteristic frequency','Place coding']::text[],ARRAY['Reversing the map; the apex codes low, not high, frequencies.','Assuming a tone excites only one point rather than a spread of places.','Confusing the apex (low frequencies) with the base (high frequencies).']::text[],ARRAY['Explaining cochlear tonotopy.','Planning cochlear-implant frequency allocation.','Interpreting low-frequency hearing loss patterns.']::text[],'intermediate',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Apical Excitation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1828','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1828') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1828');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1829','Artificial mastoid','An artificial mastoid (mechanical coupler) is a calibrated device that presents a defined mechanical impedance to a bone-conduction vibrator so the vibratory force it delivers can be measured. Its mechanical properties are specified in IEC 60318-6, and it is used to calibrate bone-conduction audiometry to reference equivalent threshold force levels (RETFL) per ISO 389-3.','A bone vibrator sends sound through the skull. To test it, engineers press it on an artificial mastoid. This pad mimics the head''s mechanical response. It measures the force the vibrator produces.','It provides a standardized mechanical load for calibrating bone-conduction transducers so audiometers read correctly.','A calibration lab couples a B71 bone vibrator to an artificial mastoid and adjusts output to the RETFL reference force at each frequency.','Audiometric calibration',ARRAY['Bone-conduction audiometry','Reference equivalent threshold force level','Mechanical coupler','Audiometric reference zero','Ear simulator']::text[],ARRAY['Confusing the artificial mastoid (mechanical coupler) with an ear simulator (acoustic coupler).','Ignoring the specified static application force of the vibrator.','Assuming one coupler suits every vibrator type without verification.']::text[],ARRAY['Calibrating a clinical audiometer''s bone oscillator.','Verifying bone-conduction output during a check.','Certifying transducers to standard.']::text[],'advanced',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Artificial mastoid');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1829','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1829') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1829');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1831','Audiometric reference zero','The audiometric reference zero is the standardized baseline sound level, at each test frequency, corresponding to 0 dB hearing level (dB HL). It is defined by reference equivalent threshold sound pressure levels (RETSPLs) for specified earphones and couplers in the ISO 389 series, representing the median threshold of otologically normal young adults.','Zero on an audiogram is not silence. It is the average faint level a healthy young adult can just hear. Each earphone and pitch has its own reference. This baseline is the audiometric reference zero.','It anchors the dB HL scale so any listener''s thresholds can be compared with normal hearing on a common basis.','The ISO 389-1 RETSPL for a supra-aural earphone at 1 kHz is about 7.5 dB SPL; setting the audiometer to 0 dB HL delivers that level.','Audiometric calibration',ARRAY['Reference equivalent threshold sound pressure level','Hearing level','Air-conduction audiometry','Audiogram','Audiometrically normal listener']::text[],ARRAY['Thinking 0 dB HL means zero sound pressure.','Assuming one RETSPL applies to all earphone and coupler types.','Confusing dB HL directly with dB SPL.']::text[],ARRAY['Calibrating an audiometer to standard.','Explaining the audiogram''s zero line.','Converting dB HL to dB SPL.']::text[],'intermediate',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audiometric reference zero');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1831','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1831') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1831');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1832','Audiometrically Normal Listener','An audiometrically (otologically) normal listener is a person free of ear disease and excessive noise exposure whose hearing thresholds fall within the normal range, used as the reference for standardized hearing data. The ISO 389 and ISO 226 standards define such an otologically normal person, typically aged 18 to 25, to set reference thresholds and equal-loudness contours.','Some standards need people with typical, healthy hearing. This is the audiometrically normal listener. They have no ear disease and little noise exposure. Their thresholds set the reference for tests.','It defines a reference population so hearing standards and equal-loudness data represent healthy young ears.','A lab recruits otologically normal 18 to 25 year olds to measure thresholds for a new earphone''s RETSPL.','Audiometric reference',ARRAY['Audiometric reference zero','Equal-loudness contour','Hearing threshold','Reference equivalent threshold sound pressure level','Air-conduction audiometry']::text[],ARRAY['Assuming ''normal'' means perfect hearing or the average of everyone.','Ignoring the age and ear-health screening criteria.','Confusing normal hearing with the total absence of any threshold shift.']::text[],ARRAY['Selecting subjects for threshold standardization.','Defining reference data for equal-loudness contours.','Interpreting what 0 dB HL represents.']::text[],'intermediate',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audiometrically Normal Listener');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1832','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1832') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1832');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1833','Auditory Gap','An auditory gap is a brief silent interval within or between sounds; the shortest detectable gap (the gap-detection threshold) indexes the auditory system''s temporal resolution. For broadband stimuli at moderate levels, gap-detection thresholds are typically only a few milliseconds.','A gap is a short silence in a sound. The smallest gap you can notice shows how fast your hearing is. For loud, wideband sounds it is only a few milliseconds. This measures temporal resolution.','It gives a simple measure of how quickly the auditory system can follow changes over time.','A clinician runs a gap-detection test and finds a threshold near 3 ms, indicating normal temporal resolution.','Temporal resolution',ARRAY['Gap detection','Temporal resolution','Temporal integration','Masking','Auditory processing']::text[],ARRAY['Assuming the gap-detection threshold is fixed regardless of level or bandwidth.','Confusing gap detection with pitch or loudness tasks.','Ignoring that narrowband stimuli yield larger thresholds.']::text[],ARRAY['Assessing temporal processing in a listener.','Comparing normal and impaired temporal resolution.','Teaching temporal acuity.']::text[],'intermediate',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auditory Gap');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1833','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1833') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1833');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1834','Auditory Negative Afterimage','An auditory negative afterimage is a faint illusory tone heard after a masking noise containing a spectral gap is switched off, with the phantom pitch corresponding to the gap frequency. Known as the Zwicker tone, it is analogous to visual negative afterimages and is attributed to central adaptation.','Play a noise with a narrow gap in its spectrum, then stop it. You may hear a faint tone at the missing frequency. This ghost tone is the Zwicker tone. It fades after a moment.','It reveals adaptation and central processing in the auditory system, paralleling afterimages in vision.','A demonstrator plays notched white noise, switches it off, and listeners report a brief faint tone at the notch frequency.','Auditory illusion',ARRAY['Zwicker tone','Adaptation','Masking','Pitch perception','Auditory sensation area']::text[],ARRAY['Confusing the Zwicker tone with tinnitus.','Assuming the tone is physically present in the stimulus.','Expecting it after any noise rather than spectrally notched noise.']::text[],ARRAY['Demonstrating auditory adaptation.','Explaining phantom-pitch phenomena.','Distinguishing illusory tones from tinnitus.']::text[],'advanced',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auditory Negative Afterimage');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1834','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1834') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1834');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1835','Auditory Sensation Area','The auditory sensation area (auditory field) is the region on a sound-level-versus-frequency plot bounded below by the threshold of hearing and above by the threshold of pain or discomfort. It spans roughly 20 Hz to 20 kHz and up to about 120 to 130 dB SPL, enclosing all audible sounds, including speech and music.','Plot sound level against pitch. The lowest curve is the hearing threshold. The top is where sound hurts. The area between holds every sound we can hear. Speech and music sit inside it.','It maps the full range of audible sound, showing where hearing works and where damage risk begins.','An instructor overlays the speech and music ranges inside the auditory sensation area to show what a listener can perceive.','Psychoacoustics',ARRAY['Threshold of hearing','Threshold of pain','Equal-loudness contour','Dynamic range of hearing','Absolute limen']::text[],ARRAY['Thinking the area is rectangular; its borders vary with frequency.','Assuming the upper limit is safe to reach.','Confusing the whole sensation area with a single equal-loudness contour.']::text[],ARRAY['Teaching the range of human hearing.','Placing speech and music on the hearing map.','Explaining why sensitivity varies with frequency.']::text[],'intermediate',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auditory Sensation Area');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1835','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1835') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1835');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1836','Auditory Time Error','The auditory time error (time-order error) is a systematic bias in comparing two sounds presented in sequence, where the judged magnitude of the first depends on the inter-stimulus interval and presentation order. It reflects perceptual memory and weighting rather than any true difference between the stimuli.','When you compare two sounds one after another, order matters. The first sound''s remembered strength can drift. This bias is the time-order error. It comes from memory, not the sounds themselves.','It warns experimenters that presentation order can distort paired comparisons, so designs must control or balance it.','A researcher counterbalances which sound comes first in a loudness comparison to cancel the time-order error.','Psychophysics',ARRAY['Difference limen','Paired comparison','Auditory memory','Loudness comparison','Psychophysical method']::text[],ARRAY['Ignoring order effects in paired comparisons.','Attributing the bias to the stimuli rather than to memory.','Failing to counterbalance the presentation order.']::text[],ARRAY['Designing a two-interval loudness test.','Interpreting order effects in listening data.','Teaching psychophysical method pitfalls.']::text[],'advanced',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auditory Time Error');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1836','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1836') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1836');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1837','Auditory weighting function','An auditory weighting function is a frequency-dependent filter that shapes a sound''s spectrum to approximate a listener''s hearing sensitivity before a level or exposure metric is computed. Examples include A- and C-weighting for humans, defined in IEC 61672, and species-specific marine-mammal weighting functions used in noise-exposure criteria.','Ears are not equally sensitive at all pitches. A weighting function corrects for this. It boosts or cuts each frequency before adding up a level. A-weighting does this for human hearing.','It makes a measured level better reflect what a listener perceives or is affected by, rather than raw physical energy.','A meter applies A-weighting so a 100 Hz tone contributes less to the reading than a 1 kHz tone at the same SPL.','Frequency weighting',ARRAY['A-weighting','Equal-loudness contour','Sound level meter','Loudness','Auditory-field correction']::text[],ARRAY['Assuming one weighting fits all species or all purposes.','Confusing frequency weighting with a simple flat gain.','Treating the A-weighted level as true perceived loudness at high levels.']::text[],ARRAY['Measuring environmental noise in dB(A).','Setting marine-mammal noise-exposure limits.','Explaining why sound level meters use weighting.']::text[],'intermediate',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auditory weighting function');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1837','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1837') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1837');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1838','Auditory-Filter Asymmetry','Auditory-filter asymmetry refers to the unequal steepness of the two skirts of an auditory filter''s frequency response. At low levels the filter is nearly symmetric, but as level rises the low-frequency skirt becomes shallower, so lower-frequency maskers grow relatively more effective, producing the upward spread of masking.','Each auditory filter passes a band of frequencies. Its two edges are not equally steep. At high levels the lower edge flattens. So loud low sounds mask higher sounds more easily.','It explains level-dependent masking patterns, especially why intense low frequencies mask higher ones.','An engineer notes a loud 300 Hz note masks a 1 kHz detail, reflecting the shallow low-frequency skirt at high levels.','Auditory filtering',ARRAY['Auditory-filter bandwidth','Upward spread of masking','Critical band','Excitation pattern','Masking']::text[],ARRAY['Assuming the auditory filter is symmetric at all levels.','Confusing filter asymmetry with the asymmetry of forward and backward masking.','Ignoring level dependence when modeling masking.']::text[],ARRAY['Modeling masking in a perceptual codec.','Explaining the upward spread of masking.','Interpreting notched-noise masking data.']::text[],'advanced',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auditory-Filter Asymmetry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1838','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1838') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1838');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1839','Auditory-field correction','An auditory-field correction converts thresholds or sound levels between listening conditions, typically between pressure at the eardrum or in a coupler and equivalent free-field or diffuse-field sound pressure levels. Standards such as ISO 389-7 tabulate free-field and diffuse-field reference thresholds, and the corrections account for head, pinna, and ear-canal transfer effects.','Sound at the eardrum differs from sound out in the open air. Corrections bridge the two. They account for the head and ear canal. Standards list values for free-field and diffuse-field listening.','It lets thresholds measured under headphones be compared with sound-field listening, and the reverse.','A researcher applies the ISO 389-7 diffuse-field correction to compare headphone thresholds with a reverberant-room test.','Audiometric reference',ARRAY['Free-field threshold','Diffuse-field','Head-related transfer function','Reference equivalent threshold sound pressure level','Audiometric reference zero']::text[],ARRAY['Confusing free-field and diffuse-field corrections.','Ignoring ear-canal and pinna transfer when converting.','Assuming coupler SPL equals field SPL.']::text[],ARRAY['Comparing headphone and loudspeaker thresholds.','Calibrating for sound-field audiometry.','Deriving free-field reference levels.']::text[],'advanced',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auditory-field correction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1839','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1839') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1839');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1840','Auditory-filter bandwidth','The auditory-filter bandwidth is the effective width of the band-pass filter the ear applies around a given center frequency, commonly quantified as the equivalent rectangular bandwidth (ERB). Glasberg and Moore (1990) express the ERB of the normal auditory filter as a function of center frequency, with the bandwidth widening as frequency increases.','The ear splits sound into overlapping frequency bands. Each band has a width. Higher-frequency bands are wider. This width is the auditory-filter bandwidth, often given as the ERB.','It quantifies frequency selectivity, setting how finely the ear separates nearby frequencies and how masking spreads.','At a 1 kHz center frequency the ERB is 24.7 x (4.37 x 1 + 1) = about 132.6 Hz, so components within roughly that band interact strongly.','Auditory filtering',ARRAY['Equivalent rectangular bandwidth','Critical band','Bark scale','Auditory-filter asymmetry','Frequency selectivity']::text[],ARRAY['Confusing the ERB with the classic critical band; the two differ, especially below 500 Hz.','Using center frequency in hertz where the formula expects kilohertz.','Assuming the bandwidth is constant across frequency.']::text[],ARRAY['Building an auditory filterbank.','Predicting the spread of masking.','Comparing the ERB and Bark scales.']::text[],'advanced','ERB = 24.7 (4.37 F + 1)','The equivalent rectangular bandwidth in hertz equals 24.7 times the quantity 4.37 times the center frequency in kilohertz plus one.','4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auditory-filter bandwidth');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1840','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1840') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1840');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1841','Backward Masking','Backward masking occurs when a masker presented after a brief target sound raises the target''s threshold, even though the masker follows the target in time. The effect is usually small, decays within about 20 ms, and varies greatly with listener training.','A later sound can hide an earlier one. This is backward masking. The masker comes after the target. The effect is small and brief. Practice can reduce it.','It probes the temporal processing window of the auditory system, showing masking can act on preceding sounds.','A researcher places a noise burst 5 ms after a click and finds the click harder to detect.','Temporal masking',ARRAY['Forward masking','Simultaneous masking','Additivity of forward masking','Temporal resolution','Masking']::text[],ARRAY['Assuming masking can only act forward in time.','Confusing backward masking with forward masking.','Overstating its size; backward masking is usually small and highly variable.']::text[],ARRAY['Studying temporal masking windows.','Explaining very rapid masking effects.','Designing gap and masking experiments.']::text[],'advanced',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Backward Masking');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1841','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1841') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1841');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1842','Basilar-Membrane Motion','Basilar-membrane motion is the traveling-wave displacement of the cochlear partition in response to sound. Each place along the membrane is tuned to a characteristic frequency, and the active, nonlinear response of the outer hair cells sharpens and compresses this motion, underlying the ear''s frequency selectivity.','Sound makes a wave travel along the basilar membrane in the cochlea. Each spot responds best to one pitch. Outer hair cells boost and sharpen the motion. This gives the ear its fine tuning.','It is the mechanical basis of the ear''s frequency analysis and sensitivity, converting sound into place-specific vibration.','A researcher observes the peak membrane displacement move toward the base as tone frequency rises, mapping characteristic frequencies.','Cochlear mechanics',ARRAY['Traveling wave','Characteristic frequency','Outer hair cell','Apical excitation','Tonotopy']::text[],ARRAY['Thinking the membrane vibrates uniformly rather than as a traveling wave.','Ignoring the active, nonlinear amplification by outer hair cells.','Assuming the response is linear with level.']::text[],ARRAY['Explaining cochlear frequency analysis.','Relating hearing loss to hair-cell damage.','Teaching traveling-wave theory.']::text[],'advanced',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Basilar-Membrane Motion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1842','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1842') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1842');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1843','Between-Channel Masking','Between-channel masking involves interactions between different auditory frequency channels, in contrast to within-channel masking confined to a single filter. It underlies effects such as comodulation masking release, where correlated amplitude modulation across channels aids detection of a signal.','Masking can involve more than one frequency band. The ear compares across bands. Matching level changes in other bands can help you hear a target. This across-band effect is between-channel masking.','It shows the auditory system combines information across frequency channels, improving detection in fluctuating backgrounds.','Adding correlated noise in other bands lowers a tone''s threshold, demonstrating comodulation masking release.','Masking',ARRAY['Comodulation masking release','Auditory-filter bandwidth','Amplitude modulation','Binaural interference','Masking']::text[],ARRAY['Assuming all masking stays within a single auditory filter.','Confusing between-channel effects with simple energy summation.','Overlooking modulation correlation as the key cue.']::text[],ARRAY['Explaining comodulation masking release.','Modeling detection in modulated noise.','Studying across-frequency processing.']::text[],'advanced',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Between-Channel Masking');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1843','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1843') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1843');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1844','Bilateral Masking-Level Difference','The bilateral masking-level difference (MLD) — ''bilateral'' meaning the effect arises only under binaural (both-ears) presentation — is the improvement in detecting a signal in noise obtained when the interaural phase or level relationships of signal and masker differ between the two ears, compared with an identical (diotic) presentation. Expressed in decibels, the binaural MLD can reach about 12 to 15 dB at low frequencies for an antiphasic signal in identical noise.','Listening with two ears can pull a tone out of noise. If the tone or noise differs between the ears, detection improves. The size of that gain is the masking-level difference. It is largest for low pitches.','It measures the binaural system''s ability to use interaural differences to release a signal from masking.','A technician measures thresholds for NoSo and NoS-pi conditions and reports the difference, an MLD of about 13 dB at 500 Hz.','Binaural hearing',ARRAY['Binaural unmasking','Antiphasic listening condition','Interaural phase difference','Binaural advantage','Masking']::text[],ARRAY['Confusing the MLD with overall binaural loudness summation.','Expecting a large MLD at high frequencies.','Forgetting to specify the interaural conditions of both signal and noise.']::text[],ARRAY['Assessing binaural processing clinically.','Demonstrating release from masking.','Comparing NoSo and NoS-pi thresholds.']::text[],'advanced',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bilateral Masking-Level Difference');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1844','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1844') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1844');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1845','Binaural Advantage','Binaural advantage is the collective benefit of listening with two ears rather than one, including binaural summation, the head-shadow effect, and binaural squelch (release from masking). It improves detection, loudness, and speech understanding in noise compared with monaural listening.','Two ears beat one. They add loudness, use the head''s shadow, and separate speech from noise. Together these help you hear in noisy places. This overall benefit is the binaural advantage.','It explains why two-ear listening improves hearing in noise, guiding bilateral hearing-aid and cochlear-implant fitting.','An audiologist fits two hearing aids so a client gains head-shadow and squelch benefits in a noisy restaurant.','Binaural hearing',ARRAY['Binaural summation','Head-shadow effect','Binaural squelch','Binaural unmasking','Spatial release from masking']::text[],ARRAY['Assuming the advantage is only loudness summation.','Ignoring the head-shadow and squelch components.','Expecting equal benefit in quiet and in noise.']::text[],ARRAY['Justifying bilateral hearing-aid fitting.','Explaining hearing in noisy rooms.','Comparing one-ear and two-ear listening.']::text[],'intermediate',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Binaural Advantage');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1845','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1845') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1845');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1846','Binaural Interference','Binaural interference is the reduced ability to use interaural cues in a target frequency region when an off-frequency sound is also present, degrading tasks such as interaural time-difference discrimination. It shows that binaural processing can be disrupted by irrelevant across-frequency information.','The brain uses timing between the ears to place sounds. A different, off-pitch sound can get in the way. Then judging the target''s position gets worse. This is binaural interference.','It reveals across-frequency pooling and its limits in binaural processing, relevant to hearing in complex scenes.','A researcher adds a low-frequency distractor and finds that high-frequency interaural time-difference thresholds worsen.','Binaural hearing',ARRAY['Interaural time difference','Binaural sluggishness','Binaural advantage','Between-channel masking','Localization']::text[],ARRAY['Confusing binaural interference with simple energetic masking.','Assuming binaural cues are processed independently in each frequency region.','Overlooking that the interferer lies off the target frequency.']::text[],ARRAY['Studying the limits of localization.','Explaining difficulty locating sounds in clutter.','Designing interaural-difference experiments.']::text[],'advanced',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Binaural Interference');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1846','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1846') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1846');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1847','Binaural Sluggishness','Binaural sluggishness is the relatively slow temporal resolution of the binaural system: listeners cannot track rapid changes in interaural time or phase differences and instead respond to a time-averaged value. The effective binaural time constant is on the order of tens to a few hundred milliseconds.','The brain compares timing at the two ears. But it reacts slowly to fast changes. It averages the differences over time. This slowness is binaural sluggishness.','It sets a temporal limit on binaural processing, explaining why fast-moving or fluctuating spatial cues are smeared.','A researcher varies interaural phase quickly and finds listeners follow only slow changes, estimating a binaural time constant of tens of milliseconds.','Binaural hearing',ARRAY['Binaural unmasking','Interaural time difference','Binaural advantage','Temporal resolution','Localization']::text[],ARRAY['Assuming binaural processing is as fast as monaural temporal resolution.','Confusing sluggishness with overall reaction time.','Ignoring that only a time-averaged interaural cue is used.']::text[],ARRAY['Explaining smeared cues from a moving source.','Modeling dynamic binaural detection.','Studying fluctuating interaural differences.']::text[],'advanced',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Binaural Sluggishness');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1847','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1847') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1847');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1848','Binaural room impulse response','A binaural room impulse response (BRIR) is the pair of impulse responses measured from a sound source to the two ears of a listener or dummy head in a room, capturing both the room''s acoustics and the listener''s head-related filtering. Convolving anechoic audio with a BRIR reproduces the spatial and reverberant experience over headphones.','A BRIR records how a room''s sound reaches each ear. It includes echoes and the head''s filtering. Play dry audio through it and you hear the room over headphones. It captures space for both ears.','It enables realistic binaural reproduction and auralization of a specific room and seat over headphones.','An engineer measures a hall''s BRIR with a dummy head, then convolves a dry recording to audition seats over headphones.','Binaural technology',ARRAY['Head-related transfer function','Room impulse response','Auralization','Convolution reverb','Binaural recording']::text[],ARRAY['Confusing a BRIR (which includes the room) with an HRTF (anechoic).','Using a mismatched HRTF or BRIR, which harms externalization.','Ignoring head tracking, which BRIR playback often needs for realism.']::text[],ARRAY['Auralizing a hall for a design review.','Creating headphone virtual acoustics.','Comparing seats via measured responses.']::text[],'advanced',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Binaural room impulse response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1848','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1848') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1848');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1849','Binaural unmasking','Binaural unmasking is the improved detection of a signal in noise that occurs when interaural differences make the signal''s binaural cues differ from those of the masker. Quantified as the binaural masking-level difference, it can lower thresholds by up to about 15 dB at low frequencies.','Using two ears can uncover a sound buried in noise. If the sound and noise differ between the ears, the sound pops out. This release is binaural unmasking. It works best at low pitches.','It shows how interaural comparison releases signals from masking, aiding detection and speech understanding in noise.','Switching a 500 Hz tone to an antiphasic condition in identical noise lowers its threshold by about 13 dB.','Binaural hearing',ARRAY['Masking-level difference','Antiphasic listening condition','Binaural advantage','Spatial release from masking','Interaural phase difference']::text[],ARRAY['Confusing binaural unmasking with monaural release from masking.','Expecting large effects at high frequencies.','Assuming it requires a spatially separated source rather than interaural cue differences.']::text[],ARRAY['Explaining detection gains with two ears.','Assessing binaural function.','Demonstrating the masking-level difference.']::text[],'advanced',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Binaural unmasking');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1849','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1849') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1849');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1850','Blauert Band','Blauert bands (directional bands) are frequency regions whose spectral emphasis biases the perceived direction of a sound in the median plane, largely independent of the source''s true position. Blauert reported that boosting energy near about 300 to 600 Hz and 3 kHz tends to evoke ''front'', near 8 kHz ''above'', and near 1 kHz and 10 kHz ''behind''.','Where a sound seems to come from, up or behind, depends on its spectrum. Certain frequency bands push the perceived direction. Blauert mapped these bands. Boosting one band can make a sound seem above or behind you.','They explain median-plane localization from spectral cues and guide spatial-audio and virtual-height rendering.','A spatial-audio engineer boosts energy near 8 kHz to nudge a source''s perceived elevation upward.','Spatial hearing',ARRAY['Head-related transfer function','Median plane','Spectral cues','Localization','Binaural room impulse response']::text[],ARRAY['Assuming localization uses only interaural cues and not spectral shape.','Treating the band frequencies as exact rather than approximate.','Ignoring individual differences in pinna cues.']::text[],ARRAY['Designing height cues for immersive audio.','Explaining front-back and up-down confusions.','Studying median-plane localization.']::text[],'advanced',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Blauert Band');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1850','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1850') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1850');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1851','Bone-conduction threshold','The lowest bone-conducted vibration level, at a given frequency, that a listener can just detect, obtained by placing a calibrated bone vibrator on the mastoid or forehead. It is expressed relative to the reference equivalent threshold force levels standardized for bone vibrators, so a normal cochlea reads near 0 dB HL.','A small vibrator is placed on the skull, usually behind the ear. It shakes the bone and drives the inner ear directly. The quietest shaking a person can hear is the bone-conduction threshold. It helps tell inner-ear loss from middle-ear loss.','It probes the inner ear and nerve while bypassing the outer and middle ear, so clinicians can separate sensorineural loss from conductive loss.','A technician calibrates the bone vibrator to the standardized reference force levels, then a large air-bone gap (for example air threshold 45 dB HL but bone threshold 5 dB HL) points to a conductive problem.','Audiometry',ARRAY['Hearing level','Air-bone gap','Pure-tone audiometry','Audiometric zero','Masking']::text[],ARRAY['Reporting bone-conduction results without masking the non-test ear, which allows crossover to the better cochlea.','Assuming bone-conduction thresholds use the same 0 dB reference as air conduction; the reference is force, not sound pressure.','Confusing a conductive loss with a sensorineural loss by ignoring the air-bone gap.']::text[],ARRAY['Diagnosing whether a hearing loss is conductive or sensorineural.','Calibrating a clinical audiometer''s bone vibrator.','Testing a patient with impacted earwax or middle-ear fluid.']::text[],'intermediate',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bone-conduction threshold');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1851','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1851') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1851');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1852','Center-of-gravity effect','A phenomenon in vowel and timbre perception in which two spectral peaks (formants) lying close together in frequency are perceptually fused into a single peak located at their intensity-weighted mean frequency. The fusion holds when the peaks fall within roughly 3.5 Bark of each other.','The ear does not always resolve two nearby peaks in a sound''s spectrum. If two peaks are close in pitch, they blend into one. The heard peak sits at their weighted average. This shapes how we recognize vowels.','It describes how the auditory system integrates closely spaced spectral energy, which explains why some different formant patterns sound like the same vowel.','When two formants are within about 3.5 Bark, a technician can predict listeners will hear one blended peak, so shifting energy between the two peaks changes perceived vowel color without adding a new heard peak.','Speech perception',ARRAY['Critical Bandwidth','Excitation pattern','Formant Transition Cue','Bark scale','Timbre']::text[],ARRAY['Assuming the effect works at any frequency spacing rather than within about 3.5 Bark.','Treating the fused peak as the simple arithmetic mean instead of the intensity-weighted mean.','Confusing spectral center of gravity with fundamental frequency.']::text[],ARRAY['Explaining vowel identity in speech synthesis.','Predicting timbre changes when narrow spectral peaks are close together.','Analyzing perceived brightness in formant-rich sounds.']::text[],'advanced',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Center-of-gravity effect');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1852','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1852') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1852');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1853','Co-articulation cue','An acoustic cue for a speech sound that arises because the vocal tract shapes for neighboring phonemes overlap in time, so the spectrum of one sound carries information about the sounds around it. Listeners exploit these context-dependent cues to identify phonemes. Note that ''co-articulation cue'' and the sibling ''coarticulated cue'' name the same overlap phenomenon: this term stresses the acoustic evidence the listener uses, while ''coarticulated cue'' stresses the same information as a property of the produced sound.','When we talk, the mouth moves for the next sound before the last one ends. This overlap leaves traces in each speech sound. Those traces are co-articulation cues. Listeners use them to guess neighboring sounds.','It lets a single stretch of speech signal information about more than one phoneme, which speeds and stabilizes spoken-word recognition.','A technician editing speech should avoid splicing across coarticulated boundaries, because the formant traces of the neighboring phoneme carried in a segment can make the cut sound unnatural or change the perceived sound.','Speech perception',ARRAY['Coarticulated cue','Formant Transition Cue','Grouping cue','Cue integration','Speech intelligibility']::text[],ARRAY['Assuming each phoneme occupies a clean, separable slice of the signal.','Ignoring that a vowel''s onset carries cues to the preceding consonant.','Confusing coarticulation cues with simple background context or word knowledge.']::text[],ARRAY['Editing or concatenating recorded speech.','Designing concatenative speech synthesis units.','Explaining why isolated speech segments are hard to identify.']::text[],'intermediate',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Co-articulation cue');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1853','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1853') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1853');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1854','Coarticulated cue','A speech cue that is inherently shaped by adjacent phonemes rather than being fixed and context-free; its acoustic form depends on the surrounding sounds produced by overlapping articulatory gestures. It is the coarticulation-dependent counterpart to an invariant, context-independent cue.','Some speech cues stay the same in every word. A coarticulated cue does not. Its exact sound depends on the neighbors around it. The listener reads it together with its context.','It captures the fact that many phonetic cues are relative and context-bound, which is central to models of how listeners normalize speech across contexts.','A technician analyzing formant transitions treats them as coarticulated cues, reading a transition''s meaning relative to the following vowel rather than from one fixed frequency value.','Speech perception',ARRAY['Co-articulation cue','Formant Transition Cue','Cue integration','Confusion neighborhood','Speech intelligibility']::text[],ARRAY['Treating a coarticulated cue as having one fixed acoustic value across all contexts.','Assuming ''coarticulated cue'' and ''coarticulation cue'' name different mechanisms; they describe the same overlap phenomenon.','Overlooking that the same acoustic value can signal different phonemes in different contexts.']::text[],ARRAY['Modeling context normalization in speech perception.','Interpreting formant transitions in spectrograms.','Training automatic speech recognition on context-dependent units.']::text[],'intermediate',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Coarticulated cue');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1854','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1854') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1854');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1855','Comodulation Masking Release','The improvement in a listener''s ability to detect a tone in noise that occurs when the masking noise carries the same slow amplitude fluctuation (comodulation) across widely separated frequency bands. Adding correlated flanking masker bands lowers the tone''s masked threshold rather than raising it.','A tone can hide inside noise. If the noise wobbles in loudness the same way across the spectrum, the tone becomes easier to hear. This drop in the masking is comodulation masking release. The ear compares wobble across frequency bands.','It shows the auditory system compares information across frequency channels over time, helping listeners hear signals in real-world fluctuating noise.','A technician can expect a warning tone to be more detectable in an engine noise that fluctuates coherently across frequency than in flat steady noise of the same level, an effect worth several decibels.','Auditory masking',ARRAY['Masking','Critical Bandwidth','Grouping cue','Comodulation','Auditory scene analysis']::text[],ARRAY['Assuming masking always depends only on energy within one critical band.','Expecting the release with uncorrelated (independently fluctuating) flanking bands.','Confusing the release (easier detection) with an increase in masking.']::text[],ARRAY['Predicting detection of alarms in fluctuating machinery noise.','Explaining hearing-in-noise advantages for modulated maskers.','Designing psychoacoustic masking experiments with flanking bands.']::text[],'advanced',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Comodulation Masking Release');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1855','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1855') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1855');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1856','Conditioned Threshold','A behavioral hearing threshold measured using a conditioned response, in which the listener is trained to give a reliable, observable reaction (such as placing a toy or turning toward a reinforced signal) whenever a sound is detected. It is used mainly with young children and other listeners who cannot give a standard voluntary response.','Young children cannot always raise a hand for a test tone. Instead, they are taught to do a fun action when they hear a sound. The quietest sound that reliably triggers the action is the conditioned threshold. It lets clinicians test hard-to-test listeners.','It extends reliable behavioral audiometry to infants and difficult-to-test patients by replacing the standard button-press with a trained, reinforced response.','In conditioned play audiometry, a technician teaches a child to drop a block in a bucket each time a tone plays, then finds the softest level that still produces the play response as the threshold.','Audiometry',ARRAY['Hearing level','Pure-tone audiometry','Hearing threshold','Bone-conduction threshold','Visual reinforcement audiometry']::text[],ARRAY['Recording a threshold before the conditioned response is reliably established, giving falsely high values.','Reinforcing responses that were not actually triggered by the sound.','Assuming conditioned thresholds need no ear-specific masking.']::text[],ARRAY['Pediatric hearing screening with play audiometry.','Visual reinforcement audiometry with infants.','Testing patients who cannot follow standard instructions.']::text[],'intermediate',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Conditioned Threshold');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1856','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1856') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1856');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1857','Cone of Confusion','A conical surface, centered on the interaural axis, along which sound sources produce nearly identical interaural time and level differences, making them acoustically ambiguous. Sources anywhere on one cone yield the same binaural cues, so front-back and up-down errors arise unless other cues resolve them.','Your two ears compare timing and loudness to place a sound. Many directions give almost the same comparison. Those directions form a cone around the line through both ears. Sounds on that cone are easy to confuse, like front versus back.','It explains a fundamental limit of two-eared localization and why front-back and elevation confusions occur without spectral or head-movement cues.','A technician building a binaural or virtual-reality mix adds individualized spectral (pinna) filtering and head tracking so listeners can resolve directions that otherwise fall on the same cone of confusion.','Spatial hearing',ARRAY['Interaural time difference','Interaural level difference','Head-related impulse response','Pinna cues','Localization']::text[],ARRAY['Believing interaural time and level cues alone give a unique direction.','Ignoring the role of pinna spectral cues and head movement in resolving the ambiguity.','Assuming front-back confusions indicate a listener error rather than a physical cue limit.']::text[],ARRAY['Diagnosing front-back reversals in headphone virtualization.','Designing head-tracked binaural rendering.','Explaining elevation confusions in localization tests.']::text[],'intermediate',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cone of Confusion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1857','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1857') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1857');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1858','Confusion neighborhood','In spoken-word recognition, the set of words that are phonetically similar to a target word and therefore compete with it during recognition, typically defined as words differing by a single phoneme substitution, addition, or deletion. Words in dense neighborhoods are recognized more slowly and less accurately.','A spoken word sounds like several other words. Those similar-sounding words are its confusion neighborhood. When many similar words exist, the target is harder to pick out. This slows and weakens recognition.','It quantifies lexical competition, letting researchers predict how neighborhood density and word frequency affect the speed and accuracy of word recognition.','When choosing call signs or command words for a noisy interface, a technician favors words with sparse confusion neighborhoods so listeners are less likely to mishear them as similar words.','Speech perception',ARRAY['Speech intelligibility','Co-articulation cue','Cue integration','Neighborhood density','Lexical competition']::text[],ARRAY['Assuming only background noise, not similar-word competition, limits recognition.','Ignoring how word frequency interacts with neighborhood density.','Defining neighbors by spelling rather than by sound.']::text[],ARRAY['Selecting distinctive command words for voice interfaces.','Predicting word confusability in intelligibility testing.','Explaining recognition errors for words in dense neighborhoods.']::text[],'advanced',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Confusion neighborhood');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1858','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1858') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1858');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1859','Continuous rating scale','A subjective-response scale on which listeners mark a judgment at any point along an unbroken line or slider rather than choosing from a fixed set of discrete categories. It yields effectively continuous numeric data, as in the 0-to-100 quality scale used in standardized subjective audio-quality tests.','In a listening test, people rate what they hear. A continuous scale lets them mark anywhere on a line. They are not limited to a few fixed choices. This gives finer, number-like ratings.','It captures fine gradations in perceived quality and reduces the clustering seen with a few discrete categories, supporting more sensitive statistical analysis.','Running a MUSHRA-style codec test, a technician has listeners drag a slider from 0 to 100 for each excerpt, then averages the marked positions to compare processing conditions.','Listening tests',ARRAY['Subjective testing','MUSHRA','Mean opinion score','Continuous quality scale','Psychoacoustics']::text[],ARRAY['Treating the recorded pixel or slider position as an absolute physical unit rather than a relative rating.','Ignoring the anchor and reference labels that define the scale endpoints.','Assuming continuous-scale data are automatically interval-level without checking.']::text[],ARRAY['Codec and processing quality evaluation with MUSHRA.','Rating loudness or annoyance on a slider.','Collecting fine-grained preference data in listening panels.']::text[],'intermediate',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Continuous rating scale');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1859','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1859') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1859');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1860','Conversational level','The typical sound pressure level of everyday speech produced at normal vocal effort, commonly taken as about 60 to 65 dB SPL measured at one metre in front of the talker (overall, A-weighted or linear depending on convention). It serves as a reference speech level in intelligibility and hearing-aid work.','Normal talking is not shouting or whispering. Measured a metre away, it is around 60 to 65 decibels. This is the conversational level. It is a common reference for speech tests.','It provides a standard talker level for predicting speech intelligibility and for setting realistic input levels in hearing-aid and communication-system testing.','For a speech-in-noise test, a technician sets the speech to about 65 dB SPL at the listener and then adds noise to hit a target signal-to-noise ratio, reflecting real conversation.','Speech acoustics',ARRAY['Speech intelligibility','Sound pressure level','Speech Intelligibility Index','Vocal effort','Signal-to-noise ratio']::text[],ARRAY['Quoting a level without stating the measurement distance.','Confusing normal conversational level with raised or shouted speech, which are much higher.','Ignoring weighting (A-weighted versus linear) when comparing figures.']::text[],ARRAY['Setting speech level in a speech-in-noise test.','Specifying input levels for hearing-aid fitting.','Estimating intelligibility with the Speech Intelligibility Index.']::text[],'beginner','SNR_dB = L_speech - L_noise ; L_speech(conversational) ~ 60-65 dB SPL @ 1 m','Speech-to-noise ratio in decibels equals the speech level minus the noise level; conversational speech is about 60 to 65 dB SPL measured one metre from the talker.','4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Conversational level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1860','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1860') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1860');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1861','Critical Bandwidth','The frequency band, centered on a given tone, within which the auditory system integrates energy as if through a single band-pass filter, so that only noise falling inside this band contributes to masking that tone. Its width grows with center frequency and underlies the Bark frequency scale.','The ear acts like a bank of overlapping filters. Each filter passes a small band of frequencies. The critical bandwidth is the width of one such band. Only sound inside it strongly masks a tone at its center.','It captures the frequency resolution of hearing and underlies models of masking, loudness, and the Bark scale used in perceptual audio coding.','Using Zwicker''s formula, the critical bandwidth around a 1 kHz tone is about 160 Hz, so a technician expects only noise energy within roughly that band to mask the tone effectively.','Auditory filtering',ARRAY['Equivalent rectangular bandwidth','Critical ratio','Masking','Bark scale','Excitation pattern']::text[],ARRAY['Treating the critical bandwidth as constant across frequency.','Equating it numerically with the equivalent rectangular bandwidth, which is a related but different measure.','Assuming noise far outside the band contributes equally to masking.']::text[],ARRAY['Explaining why narrowband noise masks a nearby tone.','Setting band structure in perceptual audio codecs.','Modeling loudness summation across bands.']::text[],'advanced','CB(f) = 25 + 75*(1 + 1.4*f^2)^0.69,  f in kHz, CB in Hz','Zwicker''s approximation gives the critical bandwidth in hertz as twenty-five plus seventy-five times the quantity one plus one point four times frequency squared, raised to the power zero point six nine, with frequency in kilohertz.','4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Critical Bandwidth');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1861','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1861') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1861');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1862','Critical ratio','The ratio, expressed in decibels, of a tone''s power at its masked threshold to the spectrum level (power per hertz) of a broadband masking noise. Fletcher proposed it as an indirect estimate of the auditory filter''s width under the simplifying assumption that the tone is just detectable when its power equals the noise power within the critical band.','A tone is masked by wideband noise. Compare the tone level at threshold to the noise level in each hertz. That difference in decibels is the critical ratio. It gives a rough estimate of the ear''s filter width.','It offers a quick, indirect estimate of auditory frequency selectivity without directly measuring the filter shape.','If a 1 kHz tone is just detectable at 58 dB SPL in noise whose spectrum level is 40 dB, the critical ratio is 18 dB, implying an effective bandwidth near 10^(18/10) which is about 63 Hz.','Auditory filtering',ARRAY['Critical Bandwidth','Equivalent rectangular bandwidth','Masking','Spectrum level','Auditory filter']::text[],ARRAY['Treating the critical ratio (in Hz) as equal to the measured critical bandwidth; it is typically smaller.','Assuming detection occurs exactly at a 0 dB signal-to-noise ratio within the band.','Confusing masker spectrum level (per hertz) with overall masker level.']::text[],ARRAY['Estimating auditory bandwidth from a masking experiment.','Comparing frequency selectivity across listeners.','Teaching the power-spectrum model of masking.']::text[],'advanced','CR_dB = L_T - N0 ;  BW_Hz = 10^(CR_dB/10)','The critical ratio in decibels equals the tone level at masked threshold minus the noise spectrum level; the implied bandwidth in hertz is ten raised to one tenth of that ratio.','4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Critical ratio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1862','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1862') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1862');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1863','Cross-adaptive processing','A signal-processing approach in which the parameters applied to one audio channel are controlled by features extracted from one or more other channels, so tracks are processed in relation to each other. It generalizes side-chaining and underpins automatic-mixing tools that balance sources based on their mutual content.','Normal effects react only to their own track. Cross-adaptive effects also listen to other tracks. One track''s setting then depends on the others. This is the idea behind automatic mixing and ducking.','It lets a processor make decisions using the relationships between multiple signals, enabling automatic level balancing, ducking, and inter-channel dynamics.','A technician sets a cross-adaptive ducker so the music level is driven down whenever the announcer''s microphone shows speech energy, using the voice channel''s level to control the music channel''s gain.','Audio processing',ARRAY['Side-chain','Automatic mixing','Dynamic range compression','Feature extraction','Ducking']::text[],ARRAY['Confusing cross-adaptive processing with ordinary single-channel adaptive effects.','Assuming the control signal must be audible in the output; it only steers parameters.','Overlooking latency introduced by cross-channel feature analysis.']::text[],ARRAY['Automatic level balancing across many live microphones.','Music ducking under a voiceover.','Research prototypes for intelligent mixing systems.']::text[],'advanced',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cross-adaptive processing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1863','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1863') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1863');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1864','Cross-modal binding','The perceptual process by which information from different sensory modalities, such as hearing and vision, is combined into a single unified object or event when the inputs share features like timing and spatial location. It causes phenomena such as hearing a talker''s voice as coming from the seen lips.','Our senses often work on the same event. The brain ties sound and sight together into one thing. This joining is cross-modal binding. It is why a voice seems to come from moving lips.','It lets the brain treat matching sights and sounds as one event, improving perception of source location, identity, and timing.','In a cinema, a technician relies on cross-modal binding: viewers accept dialogue as coming from the on-screen actor even though the sound comes from side or rear speakers, as long as timing stays tight.','Multisensory perception',ARRAY['Cue integration','Ventriloquist effect','Precedence effect','Localization','McGurk effect']::text[],ARRAY['Assuming hearing and vision are processed in fully separate, non-interacting channels.','Believing binding tolerates large audio-video timing errors; it degrades with delay.','Confusing cross-modal binding with simple attention to one sense.']::text[],ARRAY['Managing lip-sync tolerance in film and broadcast.','Designing audiovisual virtual-reality experiences.','Explaining the ventriloquist and McGurk effects.']::text[],'intermediate',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cross-modal binding');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1864','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1864') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1864');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1865','Cue integration','The process by which the perceptual system combines multiple, independently noisy cues to a property into a single estimate, typically weighting each cue in proportion to its reliability. Near-optimal integration follows a maximum-likelihood rule, giving a combined estimate more precise than any single cue.','We often get several clues about the same thing. Each clue is a bit uncertain. The brain blends them, trusting the reliable clues more. The blended guess beats any single clue.','It explains how the brain achieves precise, robust percepts by pooling information across cues and modalities according to each cue''s trustworthiness.','When timing and level cues both point to a source direction, a technician expects listeners to weight the more reliable cue more heavily, so degrading one cue shifts localization toward the other.','Perceptual integration',ARRAY['Cross-modal binding','Detection theory','Localization','Co-articulation cue','Reliability weighting']::text[],ARRAY['Assuming the brain simply averages cues with equal weight.','Ignoring that unreliable cues receive lower weight in the combined estimate.','Expecting the combined estimate to be less precise than single cues.']::text[],ARRAY['Predicting localization when time and level cues conflict.','Modeling audiovisual perception of a common event.','Understanding robustness of speech perception across cues.']::text[],'advanced','S_hat = w1*S1 + w2*S2,  w_i = (1/var_i) / sum_j(1/var_j)','The combined estimate is a weighted sum of the individual cue estimates, where each weight is that cue''s reciprocal variance divided by the total of all reciprocal variances.','4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cue integration');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1865','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1865') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1865');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1866','Delayed masking','A form of non-simultaneous (temporal) masking in which the masker and the signal do not overlap in time but are separated by a delay, so the presence of the masker still raises the signal''s threshold. It encompasses forward masking, where the masker precedes the signal, and backward masking, where the masker follows it.','A loud sound can hide a nearby quiet sound even when they do not overlap. There is a short gap between them. This is delayed, or non-simultaneous, masking. The effect fades as the gap grows.','It shows that masking extends in time beyond the masker itself, which matters for perceiving brief sounds near louder ones and for temporal audio coding.','A technician relies on this in perceptual coding: quantization noise placed in a short window just after a loud transient can be masked, because the transient still masks quieter sounds for a few milliseconds afterward.','Auditory masking',ARRAY['Forward-backward masking','Masking','Gap detection threshold','Temporal resolution','Echo threshold']::text[],ARRAY['Assuming masking only happens when masker and signal overlap in time.','Confusing forward masking (masker first) with backward masking (masker second).','Expecting the effect to last as long on both sides; backward masking decays much faster than forward masking.']::text[],ARRAY['Placing coding noise around transients in perceptual codecs.','Explaining reduced audibility of a quiet sound after a loud one.','Measuring temporal masking curves in the lab.']::text[],'intermediate',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Delayed masking');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1866','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1866') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1866');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1867','Detection efficiency','In signal detection theory, a measure comparing a human observer''s detection performance with that of an ideal observer given the same stimulus information, expressed as the ratio of the signal energy the ideal observer would need to the energy the human needs to reach the same performance. Equivalently it is the square of the ratio of the human to the ideal sensitivity index.','An ideal detector uses all the information in a signal. A person uses less. Detection efficiency compares the two. A value near one means the person is almost ideal.','It provides an absolute benchmark for how well a listener uses the available information, separating internal noise and inefficiency from the task''s inherent difficulty.','If an ideal observer needs signal energy E_ideal and a listener needs 4 times that energy for the same score, the detection efficiency is E_ideal/E_human = 0.25, or 25 percent.','Detection theory',ARRAY['Detection theory','d-prime','Ideal observer','Signal-to-noise ratio','Psychometric function']::text[],ARRAY['Confusing efficiency (relative to an ideal observer) with raw percent-correct.','Ignoring that efficiency depends on the assumed ideal-observer model.','Treating efficiency above one as possible; the ideal observer is the ceiling.']::text[],ARRAY['Benchmarking listener performance against an ideal detector.','Comparing efficiency across tasks or observers.','Evaluating detection in noise experiments.']::text[],'advanced','eta = E_ideal / E_human = (d''_human / d''_ideal)^2','Detection efficiency equals the signal energy the ideal observer needs divided by the energy the human needs, which also equals the square of the ratio of the human sensitivity index to the ideal sensitivity index.','4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Detection efficiency');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1867','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1867') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1867');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1868','Detection theory','A mathematical framework, also called signal detection theory, that models a listener''s decisions about whether a signal is present in noise by separating two independent factors: sensitivity, the ability to tell signal-plus-noise from noise, and criterion, the listener''s bias toward responding present or absent. Sensitivity is summarized by the index d-prime.','Deciding if a faint sound is there mixes two things. One is how well the ears separate signal from noise. The other is how cautious the person is about saying yes. Detection theory keeps these apart. It measures each on its own.','It lets researchers measure true sensitivity independently of a listener''s willingness to say a signal is present, avoiding confusing perception with response bias.','From hit and false-alarm rates, a technician computes d-prime as the difference of their z-scores; hits 0.84 and false alarms 0.16 give z-scores of about +1 and -1, so d-prime is about 2.0.','Detection theory',ARRAY['Detection efficiency','d-prime','Receiver operating characteristic','Hearing threshold','Criterion']::text[],ARRAY['Reading percent-correct as pure sensitivity while ignoring response bias.','Assuming a conservative listener has poorer hearing rather than a stricter criterion.','Confusing the criterion with the sensitivity measure d-prime.']::text[],ARRAY['Analyzing yes/no detection experiments.','Separating sensitivity from bias in threshold testing.','Building receiver operating characteristic curves.']::text[],'advanced','d'' = z(H) - z(F)','The sensitivity index equals the z-score of the hit rate minus the z-score of the false-alarm rate.','4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Detection theory');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1868','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1868') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1868');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1869','Difference limen for frequency','The smallest change in the frequency of a tone that a listener can reliably detect, also called the frequency difference limen or frequency discrimination threshold. It is small at low and mid frequencies, on the order of a few hertz around 1 kHz, and grows in relative terms at high frequencies.','Play a tone, then change its pitch slightly. The smallest change a listener can hear is this limit. Around one kilohertz it is only a few hertz. The ear is very sensitive to pitch change.','It quantifies the ear''s frequency resolution over time and constrains models of pitch coding and hearing impairment.','Near 1 kHz a good listener may detect a change of about 2 to 3 Hz, so a technician tuning by ear can rely on very fine pitch discrimination at mid frequencies.','Frequency discrimination',ARRAY['Difference limen for intensity','Critical Bandwidth','Pitch perception','Just noticeable difference','Frequency selectivity']::text[],ARRAY['Confusing frequency discrimination (change over time) with frequency selectivity (resolving simultaneous tones).','Quoting a single value without stating the frequency and level.','Assuming the relative limen is constant across all frequencies.']::text[],ARRAY['Measuring pitch discrimination in the lab.','Assessing subtle hearing changes.','Explaining fine tuning by ear at mid frequencies.']::text[],'intermediate','DLF = delta_f_min ;  relative DLF = delta_f_min / f','The frequency difference limen is the smallest detectable change in frequency; the relative limen is that smallest change divided by the tone''s frequency.','4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Difference limen for frequency');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1869','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1869') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1869');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1870','Difference limen for intensity','The smallest change in the intensity (or level) of a sound that a listener can reliably detect, also called the intensity difference limen. For wideband sounds it is roughly a constant fraction of intensity (Weber''s law), corresponding to a level change of a fraction of a decibel, while for pure tones it shrinks slightly at high levels (the ''near miss'' to Weber''s law).','Make a sound a little louder. The smallest step in loudness a listener can hear is this limit. For most sounds it is under one decibel. The ear is quite sensitive to level change.','It quantifies loudness resolution and underlies limits on how finely level differences can be perceived in metering, mixing, and hearing tests.','Because the intensity limen for broadband sound is about 0.5 to 1 dB, a technician knows a fader move smaller than roughly half a decibel is usually inaudible to listeners.','Intensity discrimination',ARRAY['Difference limen for frequency','Just noticeable difference','Loudness','Weber''s law','Sound pressure level']::text[],ARRAY['Assuming the intensity limen is a fixed decibel value across all levels for pure tones.','Confusing intensity (energy) with sound pressure level when stating the limen.','Ignoring that the limen depends on bandwidth and duration.']::text[],ARRAY['Judging the smallest audible fader move.','Setting meter resolution for level matching.','Measuring loudness discrimination in the lab.']::text[],'intermediate','delta_L = 10*log10( (I + delta_I) / I ) ;  Weber fraction = delta_I / I','The just-detectable level change in decibels is ten times the base-ten logarithm of the ratio of the increased intensity to the original intensity; the Weber fraction is the smallest detectable intensity change divided by the intensity.','4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Difference limen for intensity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1870','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1870') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1870');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1871','Downward Spread of Masking','The masking of a signal at a frequency below that of the masker, that is, the spread of a masker''s effect toward lower frequencies. It is generally much weaker than the upward spread of masking, in which lower-frequency maskers strongly mask higher frequencies, and it grows somewhat at high masker levels.','A masking sound hides other sounds nearby in pitch. It hides higher pitches strongly. It hides lower pitches only weakly. That weaker downward reach is the downward spread of masking.','It describes the asymmetry of the auditory filter, explaining why maskers hide higher tones far more than lower ones and informing perceptual coding.','A technician expects a strong 1 kHz tone to mask a 1.5 kHz tone much more than a 700 Hz tone, so headroom for lower-frequency content near a strong masker is greater.','Auditory masking',ARRAY['Upward spread of masking','Masking','Critical Bandwidth','Excitation pattern','Auditory filter']::text[],ARRAY['Assuming masking spreads equally up and down in frequency.','Confusing downward spread (toward lower frequencies) with upward spread.','Ignoring that the asymmetry increases with masker level.']::text[],ARRAY['Predicting audibility of a low tone near a strong higher-frequency masker.','Setting masking thresholds in perceptual codecs.','Explaining asymmetric masking patterns.']::text[],'advanced',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Downward Spread of Masking');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1871','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1871') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1871');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1872','Echo threshold','The delay between a direct sound and a following reflection at which the reflection first becomes audible as a separate echo rather than being fused with the direct sound. Below this delay the precedence (Haas) effect fuses the two; the threshold ranges from a few milliseconds for clicks to tens of milliseconds for speech and music.','A sound and its reflection can arrive close together. If the gap is short, we hear one sound. As the gap grows, the reflection splits off as an echo. The gap where that split happens is the echo threshold.','It marks the limit of the precedence effect, defining when a reflection stops fusing with the direct sound and becomes a distinct, potentially disturbing echo.','In a sound-reinforcement delay design, a technician keeps a rear loudspeaker''s arrival within the echo threshold (roughly under 30 to 40 ms behind the source for speech) so listeners perceive one source, not an echo.','Spatial hearing',ARRAY['Precedence effect','Haas effect','Cross-modal binding','Delayed masking','Reflection']::text[],ARRAY['Assuming a single fixed threshold; it depends strongly on the signal (clicks versus speech).','Confusing the echo threshold with the summing-localization region at very short delays.','Ignoring level: a much louder reflection lowers the delay at which it is heard as an echo.']::text[],ARRAY['Setting delay times for distributed loudspeakers.','Judging acceptable reflection delays in room design.','Explaining when a reflection is heard as a separate echo.']::text[],'intermediate',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Echo threshold');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1872','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1872') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1872');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1873','Equivalent rectangular bandwidth','The bandwidth of an ideal rectangular filter that has the same peak transmission and passes the same total power (for a flat-spectrum input) as a given auditory filter. It is a standard measure of auditory frequency selectivity; a widely used formula gives it as a function of center frequency from notched-noise data.','Real ear filters have smooth, rounded shapes. Replace one with a plain rectangle of the same height and area. The width of that rectangle is the equivalent rectangular bandwidth. It is a simple number for the ear''s filter width.','It provides a single, comparable width for the rounded auditory filter, underpinning the ERB frequency scale used in loudness and speech models.','Using the Glasberg and Moore formula, the equivalent rectangular bandwidth at 1 kHz is about 133 Hz, which a technician can use as the effective analysis bandwidth of hearing at that frequency.','Auditory filtering',ARRAY['Critical Bandwidth','Critical ratio','Excitation pattern','Auditory filter','ERB scale']::text[],ARRAY['Treating the equivalent rectangular bandwidth as identical to the classic critical bandwidth; the values differ.','Forgetting it is frequency-dependent and using one value everywhere.','Confusing the ERB value with the ERB-number frequency scale derived from it.']::text[],ARRAY['Setting filter bandwidths in loudness models.','Comparing frequency selectivity across listeners.','Building auditory filterbanks for hearing models.']::text[],'advanced','ERB(F) = 24.7*(4.37*F + 1),  F in kHz, ERB in Hz','The equivalent rectangular bandwidth in hertz equals twenty-four point seven times the quantity four point three seven times the center frequency in kilohertz plus one.','4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Equivalent rectangular bandwidth');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1873','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1873') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1873');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1874','Excitation pattern','A representation of the distribution of neural excitation, or auditory-filter output level, as a function of characteristic frequency produced by a given sound. It is computed by passing the sound through a bank of auditory filters and plotting each filter''s output against its center frequency, and it forms the basis of loudness and masking models.','A sound stirs up activity along the inner ear. Some places react strongly, others weakly. Plot that activity against place, or frequency, and you get the excitation pattern. It shows how the ear spreads a sound out.','It links a sound''s spectrum to the internal auditory representation, letting models predict loudness, masking, and the audibility of spectral detail.','A technician using a loudness model reads a tone''s excitation pattern to see how far its excitation spreads, predicting which nearby quieter components will fall below the pattern and be masked.','Auditory filtering',ARRAY['Critical Bandwidth','Equivalent rectangular bandwidth','Masking','Loudness','Auditory filter']::text[],ARRAY['Confusing the excitation pattern (internal representation) with the sound''s physical spectrum.','Assuming the pattern is symmetric; it spreads more toward high frequencies at high levels.','Ignoring that the pattern changes shape with level.']::text[],ARRAY['Predicting masking with a loudness model.','Explaining upward spread of masking.','Modeling loudness of complex sounds.']::text[],'advanced',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Excitation pattern');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1874','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1874') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1874');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1875','Formant Transition Cue','The rapid change in the frequency of the vocal-tract resonances (formants), especially the second formant, at the junction between a consonant and an adjoining vowel, which signals the consonant''s place of articulation. Listeners use the direction and extent of these transitions to distinguish sounds such as /b/, /d/, and /g/.','Vowels have resonant peaks called formants. Near a consonant, these peaks slide quickly in frequency. That slide tells the listener which consonant it is. It is a key clue for sounds like b, d, and g.','It provides a dynamic acoustic cue that identifies consonant place of articulation, which is often not carried by any single steady spectrum.','A technician editing dialogue avoids trimming the short formant transition at a consonant-vowel boundary, because removing that glide can turn a heard /d/ into a different consonant.','Speech perception',ARRAY['Co-articulation cue','Coarticulated cue','Center-of-gravity effect','Cue integration','Speech intelligibility']::text[],ARRAY['Assuming consonant identity lives only in the consonant''s own noise burst, not the following transition.','Ignoring that the same burst can be heard as different consonants depending on the transition.','Confusing the steady-state formant with the brief transition.']::text[],ARRAY['Editing and splicing recorded speech.','Designing speech synthesizers.','Explaining consonant perception experiments.']::text[],'intermediate',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Formant Transition Cue');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1875','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1875') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1875');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1876','Forward-backward masking','The two forms of non-simultaneous masking, considered together: forward masking, in which a masker raises the threshold of a signal that follows it, and backward masking, in which a masker raises the threshold of a signal that precedes it. Forward masking decays over about 100 to 200 ms, whereas backward masking acts over a much shorter interval.','A loud sound can hide a quiet one that comes just before or just after it. Hiding a later sound is forward masking. Hiding an earlier sound is backward masking. Both fade as the time gap grows.','Together they define the temporal reach of masking, setting limits on the audibility of sounds near louder ones over time.','In perceptual coding a technician exploits forward masking to hide quantization noise for a short time after a loud transient, since forward masking lasts far longer than backward masking.','Auditory masking',ARRAY['Delayed masking','Masking','Gap detection threshold','Temporal resolution','Echo threshold']::text[],ARRAY['Assuming forward and backward masking are symmetric in strength and duration.','Believing masking requires temporal overlap of masker and signal.','Overestimating the duration of backward masking.']::text[],ARRAY['Placing coding noise around transients in codecs.','Measuring temporal masking functions.','Explaining audibility of brief sounds near loud events.']::text[],'intermediate',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Forward-backward masking');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1876','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1876') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1876');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1877','Gap detection threshold','The shortest silent interval within an otherwise continuous sound that a listener can just detect, used as a measure of the auditory system''s temporal resolution. For broadband stimuli at comfortable levels it is typically only a few milliseconds and increases with reduced level, narrow bandwidth, or hearing impairment.','A steady sound can have a tiny silent gap. The smallest gap a listener can notice is this threshold. For loud broadband noise it is only a few milliseconds. It shows how fast the ear tracks change.','It provides a simple index of temporal acuity, valuable for studying hearing loss, aging, and central auditory processing.','A technician testing temporal resolution inserts silent gaps of decreasing length into broadband noise; a young normal listener typically detects gaps down to about 2 to 3 ms.','Temporal resolution',ARRAY['Forward-backward masking','Delayed masking','Temporal resolution','Hearing threshold','Auditory processing']::text[],ARRAY['Assuming the threshold is the same at all levels and bandwidths.','Confusing gap detection with the overall duration threshold of a sound.','Ignoring that impaired hearing usually lengthens the detectable gap.']::text[],ARRAY['Assessing temporal processing in a hearing evaluation.','Studying age effects on temporal acuity.','Comparing temporal resolution across listeners.']::text[],'intermediate',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Gap detection threshold');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1877','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1877') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1877');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1878','Grouping cue','An acoustic feature that the auditory system uses to decide which sound components belong to the same source and should be perceptually grouped, as opposed to segregated into separate streams. Common grouping cues include common onset and offset, harmonicity, common amplitude and frequency modulation, spatial location, and proximity in frequency and time.','A mix of sounds reaches the ears at once. The brain must decide which parts go together. It uses clues like shared start times and shared pitch family. These clues are grouping cues. They build separate sound streams.','It underlies auditory scene analysis, letting a listener organize a complex mixture into distinct, meaningful sources such as separate voices or instruments.','A technician who wants a backing vocal to blend keeps its onsets, vibrato, and reverb aligned with the lead, supplying grouping cues that fuse the parts into one perceived voice.','Auditory scene analysis',ARRAY['Comodulation Masking Release','Cue integration','Cross-modal binding','Auditory streaming','Harmonicity']::text[],ARRAY['Assuming source separation depends only on frequency content, not on onset and modulation cues.','Ignoring that conflicting grouping cues can compete and shift the percept.','Confusing grouping (fusion) with stream segregation (splitting).']::text[],ARRAY['Blending or separating parts in a mix.','Explaining how listeners follow one voice in a crowd.','Designing source-separation and streaming experiments.']::text[],'intermediate',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Grouping cue');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1878','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1878') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1878');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1879','Head-related impulse response','The time-domain response, measured at a listener''s ear canal, to an impulsive sound from a specific direction, capturing how the head, torso, and pinna filter and delay the sound before it reaches the eardrum. It is the inverse Fourier transform of the head-related transfer function and is used to render directional sound over headphones.','Sound from a direction bounces off your head and outer ear before reaching the eardrum. Measure the ear''s response to a click from that direction. That response over time is the head-related impulse response. It carries the direction''s fingerprint.','It provides the directional filter needed to convincingly place virtual sound sources in space over headphones.','To place a sound to a listener''s left, a technician convolves the mono source with the left- and right-ear head-related impulse responses measured at that direction, recreating the natural interaural time and spectral differences.','Spatial hearing',ARRAY['Head-related transfer function','Cone of Confusion','Interaural time difference','Interaural level difference','Binaural rendering']::text[],ARRAY['Confusing the head-related impulse response (time domain) with the head-related transfer function (frequency domain).','Using a single non-individualized response and expecting perfect elevation and front-back accuracy.','Neglecting to keep the left and right responses paired for the correct direction.']::text[],ARRAY['Building headphone-based binaural renderers.','Creating virtual and augmented reality audio.','Auralizing directional sources from measured data.']::text[],'advanced',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Head-related impulse response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1879','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1879') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1879');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1880','Hearing level','The level of a test tone in an audiometric measurement expressed in decibels relative to standardized normal-hearing thresholds, written dB HL, so that 0 dB HL at each frequency corresponds to the median threshold of otologically normal young adults. It is obtained by referencing the sound pressure produced in a specified coupler to the reference equivalent threshold sound pressure levels for the transducer.','Audiograms use decibels called hearing level. Zero decibels hearing level is normal young-adult hearing at each pitch. A person''s threshold is how far above zero they sit. Higher numbers mean poorer hearing.','It puts thresholds at every frequency on a common, hearing-referenced scale so an audiogram reads flat for a normal ear regardless of the equipment''s frequency response.','If a listener''s 1 kHz threshold in a standard supra-aural earphone reads 27 dB SPL in the coupler and the reference level is 7 dB SPL, the hearing level is 27 minus 7, or 20 dB HL.','Audiometry',ARRAY['Audiometric zero','Bone-conduction threshold','Hearing threshold','Sound pressure level','Sensation level']::text[],ARRAY['Confusing dB HL with dB SPL; they differ by the frequency-dependent reference level.','Treating 0 dB HL as absolute silence rather than the normal-hearing reference threshold.','Mixing up hearing level with sensation level, which is referenced to the individual''s own threshold.']::text[],ARRAY['Reading and plotting an audiogram.','Calibrating an audiometer to the reference thresholds.','Reporting a hearing loss in dB HL.']::text[],'intermediate','L_HL = L_SPL(coupler) - RETSPL(f)','The hearing level in decibels equals the sound pressure level produced in the specified coupler minus the reference equivalent threshold sound pressure level for that transducer at that frequency.','4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hearing level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1880','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1880') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1880');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1881','Hearing threshold level','The hearing threshold level (HL) is the amount, in decibels, by which a listener''s pure-tone threshold at a given frequency exceeds the standardized reference threshold for otologically normal young adults. It is plotted on the audiogram in dB HL, where 0 dB HL corresponds to the reference equivalent threshold sound pressure level (RETSPL) defined for the transducer used.','This is how quiet a sound a person can just hear. It is measured against a normal-hearing reference. Zero decibels HL means average normal hearing. Higher numbers mean worse hearing at that pitch.','It expresses an individual''s hearing sensitivity on a common scale so results compare directly against normal hearing and across clinics.','If a listener first detects a 1 kHz tone at 30 dB HL, their threshold sits 30 dB above the normal reference; the audiologist marks 30 dB HL on the audiogram for that frequency.','Audiometry',ARRAY['Sensation level','Suprathreshold','Speech reception threshold','Isophonic contour']::text[],ARRAY['Confusing dB HL with dB SPL; HL is referenced to normal hearing, not to 20 micropascals.','Assuming 0 dB HL means no sound is present rather than the normal reference threshold.','Forgetting that RETSPL values differ by transducer, so HL depends on the earphone or bone vibrator used.']::text[],ARRAY['Recording pure-tone thresholds on a clinical audiogram.','Comparing a client''s hearing to normal reference values.','Fitting hearing aids based on measured HL across frequencies.']::text[],'intermediate','HL(dB) = L_threshold(dB SPL) - RETSPL(dB SPL)','Hearing threshold level equals the measured threshold sound pressure level minus the reference equivalent threshold sound pressure level for that frequency and transducer.','4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hearing threshold level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1881','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1881') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1881');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1882','Informational Masking','Informational masking is the reduction in detectability or identifiability of a target sound caused by uncertainty or similarity between the target and other sounds, beyond what peripheral overlap of energy predicts. It occurs at central, cognitive stages of hearing rather than from cochlear interaction alone.','Sometimes a sound is hard to hear even when it is loud enough. Other confusing sounds pull your attention away. Your brain, not just your ear, causes this. It happens most when sounds are similar or unpredictable.','It names the part of masking driven by perceptual confusion and attention, distinguishing it from purely energetic overlap in the cochlea.','A technician mixing dialogue against similar background chatter may find speech intelligible in meters yet hard to follow, so they separate voices by timbre, level, or panning to cut informational masking.','Masking',ARRAY['Energetic masking','Masking release','Spatial release from masking','Auditory scene analysis']::text[],ARRAY['Treating all masking as energetic overlap and ignoring cognitive confusion effects.','Assuming raising the target level always restores detection when uncertainty is the cause.','Confusing informational masking with simple loudness competition between sources.']::text[],ARRAY['Understanding why a talker is hard to follow among similar competing voices.','Designing intelligible multi-talker communication systems.','Explaining cocktail-party listening difficulty.']::text[],'advanced',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Informational Masking');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1882','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1882') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1882');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1883','Interaural cross-correlation coefficient','The interaural cross-correlation coefficient (IACC) is the maximum absolute value of the normalized cross-correlation between the sound pressure signals at a listener''s two ears, evaluated over interaural delays of plus or minus 1 millisecond. It quantifies the dissimilarity of the two ear signals and correlates with perceived spatial impression and listener envelopment.','This number compares the sound reaching your left and right ears. A value near one means both ears hear almost the same thing. A low value means the two signals differ. Lower values make a room feel more spacious.','It provides an objective measure of binaural dissimilarity used to rate the spaciousness and envelopment of concert halls.','Using a dummy head in a hall, an acoustician computes IACC from the two ear signals; a mid-frequency IACC around 0.3 indicates good spatial impression, while a value near 0.9 indicates a narrow, mono-like image.','Binaural acoustics',ARRAY['Interaural phase difference','Interaural intensity difference','Reverberation time','Isophonic contour']::text[],ARRAY['Reversing the interpretation: high IACC means similar ear signals and less spaciousness, not more.','Omitting the plus or minus 1 ms delay search window when computing the coefficient.','Reporting a single value without stating the frequency bands, which strongly affect IACC.']::text[],ARRAY['Rating concert-hall spaciousness from binaural room measurements.','Comparing spatial impression of different seating positions.','Evaluating envelopment in surround reproduction with a dummy head.']::text[],'advanced','IACC = max over |tau|<=1ms of | integral p_L(t) p_R(t+tau) dt / sqrt( integral p_L^2 dt * integral p_R^2 dt ) |','IACC is the largest magnitude, over interaural delays within plus or minus one millisecond, of the cross-correlation of the two ear-signal pressures divided by the square root of the product of their energies.','4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Interaural cross-correlation coefficient');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1883','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1883') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1883');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1884','Interaural intensity difference','The interaural intensity difference (IID), also called interaural level difference, is the difference in sound level between a listener''s two ears produced mainly by head shadowing of a source to one side. It is a dominant cue for horizontal localization at high frequencies, where the head casts an effective acoustic shadow.','A sound to your right reaches your right ear louder. Your head blocks some of it from the left ear. This loudness gap tells the brain the direction. It works best for high, short-wavelength sounds.','It supplies one of the two main binaural cues the brain uses to judge the left-right direction of a sound source.','A mixing engineer pans a hi-hat by creating a level difference between channels; a few decibels louder on the right shifts the image rightward, mimicking the natural interaural intensity difference.','Binaural acoustics',ARRAY['Interaural phase difference','Interaural cross-correlation coefficient','Spatial release from masking','Masking pattern']::text[],ARRAY['Assuming IID cues dominate at low frequencies, where the head casts little shadow.','Confusing level difference (IID) with time or phase difference cues.','Ignoring that IID magnitude grows with frequency for a given source angle.']::text[],ARRAY['Explaining stereo panning by level differences.','Modeling head-shadow effects in binaural rendering.','Diagnosing localization problems in listeners with asymmetric hearing loss.']::text[],'intermediate','IID(dB) = L_near(dB) - L_far(dB)','The interaural intensity difference is the sound level at the ear nearer the source minus the sound level at the far ear.','4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Interaural intensity difference');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1884','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1884') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1884');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1885','Interaural phase difference','The interaural phase difference (IPD) is the difference in phase of a periodic sound arriving at the two ears, arising from the interaural time difference and the source direction. For low-frequency tones it is an effective localization cue because the phase relation stays unambiguous while the wavelength exceeds the head width.','A sound off to one side reaches one ear slightly before the other. For low sounds this shows up as a phase gap between the ears. The brain reads this gap as direction. It only stays clear for low pitches.','It expresses the fine-timing binaural cue that lets the brain localize low-frequency sounds by the phase relation between the ears.','A binaural rendering engine delays one channel by a fraction of a millisecond; at 500 Hz a 0.5 ms delay creates a 90-degree interaural phase difference that steers the image to that side.','Binaural acoustics',ARRAY['Interaural intensity difference','Interaural cross-correlation coefficient','Spatial release from masking','Temporal masking']::text[],ARRAY['Relying on IPD cues at high frequencies, where phase becomes ambiguous as wavelength drops below head size.','Confusing interaural phase difference with interaural level difference.','Forgetting that IPD follows from the interaural time difference and frequency.']::text[],ARRAY['Modeling low-frequency localization in headphone virtualization.','Explaining why bass direction is judged by timing, not level.','Designing binaural test signals for localization experiments.']::text[],'advanced','IPD = 2 * pi * f * ITD','The interaural phase difference in radians equals two pi times the frequency times the interaural time difference.','4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Interaural phase difference');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1885','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1885') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1885');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1886','Internal noise of the auditory system','Internal noise of the auditory system is the intrinsic neural and physiological variability that sets a lower limit on detection independent of external stimuli. In signal-detection models it is treated as a random background against which a signal must be discriminated, and it helps explain absolute threshold and threshold variability.','Your hearing system makes its own faint background activity. This inner noise never fully stops. A sound must rise above it to be heard. It sets the quietest level you can detect.','It explains why absolute thresholds exist and why detection is probabilistic rather than a sharp all-or-nothing limit.','When modeling near-threshold detection, an engineer treats internal noise as a fixed variance, so a signal is detected reliably only when it raises the total above that internal floor.','Psychoacoustics',ARRAY['Hearing threshold level','Sensation level','Masking pattern','Suprathreshold']::text[],ARRAY['Assuming the auditory threshold is limited only by external ambient noise.','Treating detection as deterministic rather than statistical near threshold.','Confusing internal physiological noise with the electrical noise of test equipment.']::text[],ARRAY['Modeling absolute threshold in signal-detection experiments.','Explaining trial-to-trial variability in threshold measurement.','Setting realistic detection limits in perceptual coder design.']::text[],'advanced',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Internal noise of the auditory system');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1886','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1886') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1886');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1887','Ipsilateral masking','Ipsilateral masking is masking in which the masker and the signal are presented to the same ear. It is the ordinary monaural case in which one sound raises the detection threshold of another within the same cochlea.','One sound hides another in the same ear. Both the masker and the target reach that one ear. The masker makes the target harder to hear. This is the everyday same-ear case of masking.','It labels same-ear masking to distinguish it from contralateral or central masking, where the sounds go to different ears.','In an audiometric or perceptual test, a technician plays masker and probe into the same earphone to measure how much the masker lifts the probe''s threshold in that ear.','Masking',ARRAY['Masking pattern','Temporal masking','Successive masking','Post-masking']::text[],ARRAY['Confusing ipsilateral (same-ear) masking with contralateral masking across ears.','Assuming ipsilateral masking involves central rather than cochlear interaction.','Overlooking that clinical masking is applied to the non-test ear, unlike ipsilateral masking.']::text[],ARRAY['Describing same-ear masking in psychoacoustic experiments.','Explaining spectral masking in a single audio channel.','Distinguishing test conditions in binaural masking studies.']::text[],'intermediate',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ipsilateral masking');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1887','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1887') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1887');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1888','Isophonic contour','An isophonic contour, or equal-loudness contour, is a curve joining the sound pressure levels across frequency that a listener judges equally loud. Each contour is labeled by its loudness level in phons, defined so that the phon value equals the sound pressure level in decibels of an equally loud 1 kHz tone.','This curve shows sounds that all seem equally loud. It runs across different pitches. The ear needs more level for very low and very high sounds. Each curve is labeled in phons.','It maps how loudness perception varies with frequency, underpinning the phon scale and frequency weightings such as A-weighting.','Reading the standard contours, a technician sees that a 100 Hz tone must reach about 60 dB SPL to sound as loud as a 1 kHz tone at 50 dB SPL, explaining why bass seems weak at low listening levels.','Loudness',ARRAY['Sone','Sensation level','Hearing threshold level','Masking pattern']::text[],ARRAY['Assuming the contours are flat, ignoring the ear''s reduced low-frequency sensitivity.','Confusing phons (loudness level) with sones (loudness).','Treating one contour''s shape as valid at all listening levels.']::text[],ARRAY['Explaining loudness compensation and loudness-control switches.','Justifying A-weighting for noise measurement.','Setting monitoring levels so tonal balance stays consistent.']::text[],'intermediate',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Isophonic contour');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1888','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1888') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1888');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1889','Masking pattern','A masking pattern is the plot of the elevation in a signal''s detection threshold as a function of the signal''s frequency, produced by a fixed masker. It maps how far in frequency and by how much a masker raises thresholds, revealing the asymmetric spread of masking toward higher frequencies.','A masking pattern shows how one sound hides others across pitch. It marks how much harder each nearby tone becomes to hear. Masking spreads more upward in pitch than downward. The plot shows this lopsided shape.','It describes the frequency spread of masking around a masker, showing the upward spread that shapes audio coding and mixing decisions.','A perceptual audio coder computes a masking pattern for each frame, then hides quantization noise beneath the raised threshold so the noise stays inaudible.','Masking',ARRAY['Masking release','Temporal masking','Isophonic contour','Time-frequency masking']::text[],ARRAY['Assuming masking spreads symmetrically in frequency instead of more strongly upward.','Confusing the masking pattern (threshold vs frequency) with the temporal decay of masking.','Ignoring that the pattern broadens upward as masker level rises.']::text[],ARRAY['Designing psychoacoustic models in perceptual audio codecs.','Predicting when one instrument masks another in a mix.','Explaining upward spread of masking in hearing experiments.']::text[],'advanced',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Masking pattern');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1889','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1889') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1889');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1890','Masking release','Masking release is the improvement in detection or intelligibility of a target that occurs when the masker is changed so it interferes less, for example by fluctuating in level or by differing spatially or spectrally from the target. It reflects the auditory system exploiting gaps and dissimilarities to recover the target. The term is used interchangeably with ''release from masking'', which serves as the broader umbrella label for the same effect.','A target becomes easier to hear when the masker changes helpfully. A masker that dips in level leaves gaps to listen through. Separating the sounds in space or pitch also helps. This recovery is masking release.','It captures the ways listeners regain access to a target when maskers fluctuate or differ, key to understanding speech in noise.','A technician testing intelligibility finds speech scores rise when steady noise is replaced by fluctuating noise, because listeners glimpse the target in the dips, demonstrating masking release.','Masking',ARRAY['Release from masking','Spatial release from masking','Informational Masking','Masking pattern']::text[],ARRAY['Assuming louder targets are the only route to better detection in noise.','Confusing masking release with simply lowering the masker level.','Overlooking that steady maskers give less release than fluctuating ones.']::text[],ARRAY['Explaining better speech understanding in fluctuating versus steady noise.','Assessing hearing-aid benefit for speech in noise.','Designing speech-in-noise intelligibility tests.']::text[],'advanced',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Masking release');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1890','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1890') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1890');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1891','Modulation masking','Modulation masking is the reduction in the detectability of amplitude modulation at one modulation rate caused by the presence of modulation at another rate. It is interpreted through a modulation filterbank in which nearby modulation frequencies compete, analogous to spectral masking among audio frequencies.','Sounds can wobble in loudness over time. One wobble rate can hide another. The ear seems to sort wobble rates into channels. A strong wobble masks a similar one nearby.','It extends the masking concept to the modulation domain, supporting models of how the ear analyzes patterns of amplitude fluctuation over time.','When designing a model of temporal-envelope perception, an engineer treats modulation detection through tuned modulation filters, predicting that a target flutter is hidden by a similar-rate masker flutter.','Masking',ARRAY['Temporal masking','Masking pattern','Time-frequency masking','Informational Masking']::text[],ARRAY['Confusing modulation masking (rate domain) with ordinary spectral masking.','Assuming any modulation masks any other regardless of rate.','Ignoring the modulation-filterbank framing of the effect.']::text[],ARRAY['Modeling temporal-envelope processing in hearing research.','Predicting audibility of tremolo against fluctuating backgrounds.','Developing perceptual metrics for modulated signals.']::text[],'advanced',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Modulation masking');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1891','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1891') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1891');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1892','Multidimensional scaling of timbre','Multidimensional scaling of timbre is a statistical technique that turns listeners'' pairwise dissimilarity judgments of sounds into a low-dimensional spatial map. Distances in the map reflect perceived timbral difference, and the axes are commonly interpreted against acoustic features such as spectral centroid and attack time.','Listeners rate how different pairs of sounds feel. A method turns those ratings into a map. Sounds that seem alike sit close together. The map''s directions often match features like brightness and attack.','It provides a systematic way to represent and compare timbre perception, revealing the main perceptual dimensions that separate instrument sounds.','A researcher collects dissimilarity ratings for synthesized instruments, runs multidimensional scaling, and finds two axes tracking brightness and attack sharpness, guiding how a synth designer varies tone.','Timbre',ARRAY['Timbre space','Interaural cross-correlation coefficient','Masking pattern','Isophonic contour']::text[],ARRAY['Treating map axes as physical measurements rather than interpreted perceptual dimensions.','Assuming a fixed number of timbre dimensions across all sound sets.','Confusing the scaling method with the resulting timbre space it produces.']::text[],ARRAY['Analyzing perceptual differences among instrument tones.','Guiding sound-design parameters from perceptual data.','Comparing synthesized timbres in listening studies.']::text[],'advanced',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Multidimensional scaling of timbre');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1892','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1892') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1892');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1893','Noise gate threshold','The noise gate threshold is the input level setting at which a noise gate opens to pass signal and below which it attenuates or closes. Signals above the threshold pass, while quieter material such as background noise or leakage is reduced or muted.','A noise gate mutes quiet sounds and passes loud ones. The threshold is the level that decides which is which. Signals above it get through. Anything below it is turned down or shut off.','It sets the dividing line a gate uses to separate wanted signal from unwanted low-level noise or spill.','To silence hum between vocal phrases, an engineer sets the gate threshold just above the noise floor, say -45 dBFS, so the voice opens the gate while the hum stays muted.','Dynamics processing',ARRAY['Sensation level','Hearing threshold level','Reference listening level','Suprathreshold']::text[],ARRAY['Setting the threshold so high that quiet passages of the wanted signal are chopped off.','Confusing gate threshold with a compressor threshold, which acts on loud signals instead.','Ignoring attack, hold, and release so the gate chatters around the threshold.']::text[],ARRAY['Cleaning up drum-mic spill in a live mix.','Removing hum and hiss between spoken phrases.','Tightening a gated snare or tom sound.']::text[],'beginner',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noise gate threshold');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1893','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1893') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1893');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1894','Optimum reverberation time','Optimum reverberation time is the recommended mid-frequency reverberation time for a room given its use and volume, balancing clarity of speech or music against loudness and blend. Recommended values rise with room volume and are longer for music than for speech.','Every room has a best amount of echo for its job. Speech rooms need short reverberation for clarity. Music rooms need a bit more for warmth. Bigger rooms can take longer times.','It gives designers a target reverberation time so a space suits its intended speech or music use.','For a mid-size lecture hall an acoustician aims for roughly 0.8 to 1.0 s at mid frequencies, then adjusts absorption area using the Sabine relation to hit that optimum.','Room acoustics',ARRAY['Reverberation time','Reverberation radius','Isophonic contour','Speech reception threshold']::text[],ARRAY['Applying a single optimum value regardless of room volume.','Using music-length reverberation in a speech room, hurting intelligibility.','Treating the optimum as one number rather than a frequency-dependent target.']::text[],ARRAY['Specifying acoustic treatment for a lecture hall or worship space.','Balancing clarity and warmth in a concert venue.','Reviewing whether a multipurpose room suits both speech and music.']::text[],'intermediate',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Optimum reverberation time');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1894','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1894') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1894');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1895','Post-masking','Post-masking, or forward masking, is the elevation of a signal''s threshold when the signal follows shortly after a masker has ended. The effect is largest immediately after the masker and decays over roughly 100 to 200 milliseconds.','A loud sound can hide a quieter sound that comes just after it. The masker has already stopped, yet the ear still misses the target. The effect fades within a couple hundred milliseconds. This is post-masking.','It describes how a preceding sound continues to raise thresholds briefly after it stops, a key part of temporal masking.','A perceptual audio coder exploits post-masking by allowing brief coding noise just after a loud transient, where the raised threshold keeps that noise inaudible.','Masking',ARRAY['Pre-masking','Temporal masking','Successive masking','Time-frequency masking']::text[],ARRAY['Confusing post-masking (masker first) with pre-masking (signal first).','Assuming the effect lasts many seconds rather than a fraction of a second.','Treating forward masking as identical to simultaneous masking.']::text[],ARRAY['Placing coding noise after transients in audio codecs.','Explaining brief loss of detail after a loud sound.','Designing temporal-masking experiments.']::text[],'intermediate',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Post-masking');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1895','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1895') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1895');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1896','Pre-masking','Pre-masking, or backward masking, is the elevation of a signal''s threshold when the signal precedes the onset of a masker by a short interval. It acts over only a few to about 20 milliseconds and is generally weaker and more variable than forward masking.','A loud sound can hide a quieter sound that came just before it. The masker starts after the target, yet still hides it. This only works over a few milliseconds. It is weaker than forward masking.','It describes the brief masking that a later sound exerts on an earlier one, important for temporal resolution and transient coding.','In audio coding, pre-masking limits how far coding noise can spread before a transient, so coders keep the pre-echo window very short to stay under the threshold.','Masking',ARRAY['Post-masking','Temporal masking','Time-frequency masking','Successive masking']::text[],ARRAY['Confusing pre-masking (masker later) with post-masking (masker earlier).','Overstating its duration; it acts over only a few to about twenty milliseconds.','Assuming it is as strong and reliable as forward masking.']::text[],ARRAY['Controlling pre-echo artifacts in transform audio coders.','Explaining masking of a sound by a slightly later, louder sound.','Studying temporal resolution of hearing.']::text[],'intermediate',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pre-masking');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1896','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1896') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1896');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1897','Probe-tube microphone','A probe-tube microphone is a measurement microphone fitted with a thin flexible tube whose open end is placed deep in the ear canal near the eardrum. It lets a technician measure the real-ear sound pressure level with a hearing aid or earpiece in place, capturing the individual ear''s acoustic response.','This is a microphone with a slim soft tube. The tube tip sits in the ear canal near the eardrum. It measures the real sound level inside that ear. It is used to check hearing-aid fittings.','It enables real-ear measurement so clinicians verify the actual sound a hearing aid delivers in a patient''s own ear canal.','During a hearing-aid fitting, an audiologist inserts the probe tube past the aid, plays a calibrated signal, and compares the measured real-ear response to the prescription target.','Measurement',ARRAY['Hearing threshold level','Reference listening level','Sensation level','Suprathreshold']::text[],ARRAY['Placing the tube tip too shallow, giving errors from standing waves near the eardrum.','Assuming coupler (2 cc) measurements match the individual real-ear response.','Neglecting to calibrate the probe system before measurement.']::text[],ARRAY['Verifying hearing-aid output against prescription targets.','Measuring real-ear-to-coupler differences.','Checking in-ear response of custom earpieces.']::text[],'intermediate',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Probe-tube microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1897','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1897') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1897');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1898','Reference listening level','A reference listening level is a standardized monitoring sound pressure level tied to a defined electrical reference, so that program material is auditioned at a consistent, calibrated loudness. In multichannel film sound, each screen channel is aligned so that a defined pink-noise reference produces a specified sound pressure level at the listening position.','This is a fixed, agreed loudness for monitoring. A known test signal is set to produce a known level. Everyone then listens at the same calibrated volume. This keeps mixing decisions consistent.','It gives studios and cinemas a common calibrated monitoring level so mixes translate reliably between rooms.','A dubbing-stage technician feeds band-limited pink noise at the reference electrical level and adjusts each screen channel so it reads about 85 dB SPL, C-weighted, at the mix position.','Monitoring',ARRAY['Sensation level','Isophonic contour','Suprathreshold','Hearing threshold level']::text[],ARRAY['Confusing the electrical reference with the resulting acoustic sound pressure level.','Assuming every genre or room uses the same reference monitoring level.','UNSAFE: Monitoring far above the reference level for long sessions risks noise-induced hearing damage; observe safe exposure limits.']::text[],ARRAY['Calibrating a film dubbing stage to standard reference level.','Setting consistent monitor gain across mixing rooms.','Comparing mixes at a fixed, repeatable listening level.']::text[],'intermediate',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reference listening level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1898','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1898') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1898');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1899','Release from masking','Release from masking is the general term for any improvement in detection or intelligibility of a target that results when differences between target and masker are introduced or increased. Such differences may be spatial, temporal, spectral, or based on binaural cues.','A target gets easier to hear when it differs from the masker. The difference can be in place, timing, or pitch. Using two ears also helps. Any such gain is release from masking.','It is the umbrella concept covering the several mechanisms by which listeners recover a target from a masking background.','An engineer improves a talker''s audibility in noise by separating the talker and noise in space; the resulting intelligibility gain is a release from masking the technician can measure.','Masking',ARRAY['Masking release','Spatial release from masking','Informational Masking','Masking pattern']::text[],ARRAY['Treating release from masking as a single mechanism rather than a family of effects.','Assuming only louder targets, not target-masker differences, aid detection.','Confusing it with simply reducing the masker''s level.']::text[],ARRAY['Explaining benefits of spatial separation for speech in noise.','Assessing binaural hearing advantages.','Designing intelligibility improvements in communication systems.']::text[],'advanced',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Release from masking');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1899','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1899') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1900','Reverberation radius','The reverberation radius, or critical distance, is the distance from a sound source at which the direct sound level equals the reverberant sound level in a room. Beyond it the reverberant field dominates, and closer than it the direct sound dominates.','Move away from a loudspeaker in a room and echoes grow. At one distance direct sound and echo are equal. That distance is the reverberation radius. Past it the room sound takes over.','It marks where direct and reverberant energy are equal, guiding microphone and listener placement relative to a source.','In a 2000 cubic metre hall with a 1.5 s reverberation time, the reverberation radius is about 0.057 times the square root of 2000/1.5, roughly 2.1 m, so a close mic should sit well inside that radius.','Room acoustics',ARRAY['Reverberation time','Optimum reverberation time','Interaural cross-correlation coefficient','Reference listening level']::text[],ARRAY['Assuming the reverberation radius depends only on distance, not on room volume and reverberation time.','Ignoring source directivity, which extends the critical distance on axis.','Placing a distant microphone beyond the radius and then wondering why it sounds washy.']::text[],ARRAY['Choosing microphone distance for a desired direct-to-reverberant ratio.','Positioning loudspeakers and listeners in a room.','Estimating where reverberant field dominates for measurements.']::text[],'advanced','r_c = 0.057 * sqrt(V / RT60)   (Q = 1)','For an omnidirectional source the reverberation radius in metres is about 0.057 times the square root of room volume in cubic metres divided by reverberation time in seconds.','4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reverberation radius');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1900','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1900') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1900');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1901','Reverberation time','Reverberation time (RT60) is the time required for the sound pressure level in a room to decay by 60 decibels after the source stops. The Sabine equation relates it to room volume and total sound absorption.','Reverberation time measures how long echoes last. It is the time for sound to fall by sixty decibels. Big, hard rooms have long times. Soft, absorbent rooms have short times.','It is the primary single-number measure of a room''s liveness, used to specify and compare acoustic spaces.','For a 1000 cubic metre room with 200 metric sabins of absorption, the Sabine formula gives RT60 = 0.161 times 1000 divided by 200, about 0.8 s.','Room acoustics',ARRAY['Optimum reverberation time','Reverberation radius','Isophonic contour','Speech reception threshold']::text[],ARRAY['Assuming a single RT60 value describes the room at all frequencies.','Using the Sabine formula in very absorptive rooms, where it overestimates RT60.','Confusing the 60 dB decay definition with shorter early-decay measures.']::text[],ARRAY['Measuring and specifying room acoustics.','Comparing liveness of studios and halls.','Estimating absorption needed to reach a target reverberation time.']::text[],'intermediate','RT60 = 0.161 * V / A','The Sabine reverberation time in seconds equals 0.161 times the room volume in cubic metres divided by the total absorption in metric sabins.','4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reverberation time');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1901','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1901') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1901');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1902','Sensation level','Sensation level (SL) is the level of a sound in decibels above a listener''s own threshold for that sound. A tone presented at 40 dB SL is 40 dB above the level at which that individual just detects it.','Sensation level measures loudness above your own hearing threshold. Zero decibels SL is just barely audible for you. Forty decibels SL is forty above that point. It is personal to each listener.','It expresses stimulus level relative to an individual''s threshold, so tests deliver comparable audibility across listeners with different hearing.','If a listener''s threshold for a word list is 20 dB HL, presenting speech at 40 dB SL means 60 dB HL, ensuring the material sits a fixed amount above their threshold.','Audiometry',ARRAY['Hearing threshold level','Suprathreshold','Speech reception threshold','Isophonic contour']::text[],ARRAY['Confusing sensation level (above individual threshold) with hearing level (above normal reference).','Confusing dB SL with dB SPL.','Assuming the same dB SL gives the same absolute level for all listeners.']::text[],ARRAY['Presenting speech material at a fixed level above threshold.','Setting comfortable listening levels in clinical testing.','Comparing suprathreshold performance across listeners.']::text[],'intermediate','SL(dB) = L_stimulus(dB) - L_threshold(dB)','Sensation level equals the stimulus level minus the listener''s own detection threshold for that stimulus, in decibels.','4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sensation level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1902','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1902') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1902');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1903','Sone','The sone is the unit of loudness on a ratio scale, defined so that 1 sone equals the loudness of a 1 kHz tone at 40 dB SPL (a loudness level of 40 phons). The scale is built so that a doubling of the number of sones corresponds to a perceived doubling of loudness.','The sone measures how loud a sound seems. One sone is a soft reference tone. Two sones sound twice as loud. Ten sones sound ten times as loud.','It gives loudness a linear perceptual scale, so numbers add up the way perceived loudness does, unlike decibels or phons.','Using the standard relation, a sound at 60 phons is 2 to the power (60-40)/10 = 4 sones, meaning it sounds about four times as loud as the 40-phon, 1-sone reference.','Loudness',ARRAY['Isophonic contour','Sensation level','Hearing threshold level','Suprathreshold']::text[],ARRAY['Confusing sones (loudness) with phons (loudness level).','Assuming a 10 dB increase always doubles sones at every level; the doubling rule holds well above about 40 phons.','Treating the sone scale as identical to the decibel scale.']::text[],ARRAY['Reporting product loudness in sones, as for fans and appliances.','Comparing perceived loudness of sounds numerically.','Computing loudness in standardized loudness models.']::text[],'intermediate','N = 2 ^ ((L_N - 40) / 10)   for L_N >= 40 phon','Loudness in sones equals two raised to the power of the loudness level in phons minus forty, all divided by ten.','4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1903','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1903') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1903');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1904','Spatial release from masking','Spatial release from masking is the improvement in detection or intelligibility of a target that occurs when the target and masker are separated in space rather than co-located. Binaural processing exploits the resulting interaural differences and head-shadow level differences to segregate the target from the masker.','Speech in noise is easier when the noise comes from a different direction. Your two ears use the direction difference. This separates the voice from the noise. The gain is spatial release from masking.','It quantifies the benefit of spatial separation and binaural hearing for hearing a target in a noisy background.','Testing a listener with target ahead and masker moved to the side, an audiologist measures a several-decibel improvement in speech threshold, documenting spatial release from masking.','Masking',ARRAY['Release from masking','Masking release','Interaural intensity difference','Interaural phase difference']::text[],ARRAY['Assuming the benefit persists fully with one ear blocked; it depends on binaural cues.','Confusing it with simple head-shadow level gain only, ignoring binaural timing.','Expecting the same benefit when target and masker share the same location.']::text[],ARRAY['Measuring binaural benefit for speech in noise.','Evaluating bilateral hearing-aid or cochlear-implant fittings.','Explaining the cocktail-party advantage of two ears.']::text[],'advanced',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spatial release from masking');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1904','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1904') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1904');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1905','Speech reception threshold','The speech reception threshold (SRT), also called speech recognition threshold, is the lowest presentation level at which a listener correctly repeats about 50 percent of standardized two-syllable spondee words. It is expressed in dB HL and should agree closely with the average pure-tone thresholds.','This is the softest level at which speech is half understood. The listener repeats familiar two-part words. The level where half are correct is the speech reception threshold. It should match the pure-tone results.','It cross-checks the pure-tone audiogram and gives a functional measure of the softest speech a listener can just understand.','An audiologist presents spondees at decreasing levels; when the listener gets half correct at 25 dB HL, the SRT is 25 dB HL, which should agree with the pure-tone average within about 6 to 10 dB.','Speech audiometry',ARRAY['Hearing threshold level','Sensation level','Suprathreshold','Optimum reverberation time']::text[],ARRAY['Confusing SRT with word-recognition (discrimination) scores measured well above threshold.','Expecting SRT to differ greatly from the pure-tone average when reliability is good.','Using non-spondee or unfamiliar words, which invalidates the standard measure.']::text[],ARRAY['Cross-checking pure-tone thresholds during a hearing evaluation.','Establishing a reference level for suprathreshold speech testing.','Documenting functional hearing for speech.']::text[],'intermediate',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Speech reception threshold');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1905','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1905') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1905');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1906','Successive masking','Successive masking is masking between sounds that do not overlap in time, comprising forward masking when the masker precedes the signal and backward masking when it follows. It is the non-simultaneous, temporal form of masking.','Successive masking happens between sounds that do not overlap. One sound can still hide another nearby in time. It covers both before and after cases. It is the timing form of masking.','It groups the non-overlapping temporal masking effects under one heading, distinguishing them from simultaneous masking.','When analyzing whether a soft echo after a transient will be heard, an engineer applies successive masking data, since the transient can mask the later sound over a short interval.','Masking',ARRAY['Temporal masking','Post-masking','Pre-masking','Time-frequency masking']::text[],ARRAY['Confusing successive (non-overlapping) masking with simultaneous masking.','Assuming forward and backward masking are equally strong.','Treating successive masking as a purely spectral effect.']::text[],ARRAY['Analyzing masking of closely spaced transients.','Modeling temporal masking in perceptual coders.','Explaining audibility of echoes near a loud sound.']::text[],'intermediate',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Successive masking');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1906','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1906') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1906');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1907','Suprathreshold','Suprathreshold describes any stimulus or auditory measurement made at levels above the detection threshold. Suprathreshold tests, such as loudness growth, word recognition, or uncomfortable loudness level, probe how the auditory system processes clearly audible sounds.','Suprathreshold means above the just-hearable level. The sound is clearly audible, not faint. These tests study how loud and clear sounds are processed. They go beyond simple detection.','It labels measurements made at audible levels, complementing threshold tests by revealing how hearing handles everyday, clearly heard sounds.','After finding thresholds, an audiologist runs suprathreshold word recognition at 40 dB SL to assess how well a listener understands clearly audible speech.','Audiometry',ARRAY['Sensation level','Hearing threshold level','Speech reception threshold','Internal noise of the auditory system']::text[],ARRAY['Confusing suprathreshold (above threshold) with subthreshold (below threshold).','Assuming normal thresholds guarantee normal suprathreshold performance.','Treating suprathreshold level as a single fixed value rather than a range above threshold.']::text[],ARRAY['Running word-recognition testing above threshold.','Measuring loudness growth and discomfort levels.','Assessing supra-threshold deficits despite normal audiograms.']::text[],'beginner',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Suprathreshold');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1907','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1907') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1907');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1908','Temporal masking','Temporal masking is the raising of a signal''s threshold by a masker that is close in time but not simultaneous. It includes forward masking, decaying over about 100 to 200 milliseconds after the masker, and the briefer, weaker backward masking before it.','A loud sound can hide quieter sounds near it in time. This works both just before and just after. The after-effect lasts longer than the before-effect. Together this is temporal masking.','It captures how masking extends in time around a sound, essential to modeling temporal resolution and to audio compression.','A codec designer uses temporal masking to place brief quantization noise near a strong transient, where the raised threshold before and after it keeps the noise inaudible.','Masking',ARRAY['Pre-masking','Post-masking','Successive masking','Time-frequency masking']::text[],ARRAY['Assuming temporal masking is symmetric before and after the masker.','Confusing temporal masking with simultaneous spectral masking.','Overstating backward-masking duration, which is only a few milliseconds.']::text[],ARRAY['Controlling pre-echo and post-echo noise in audio codecs.','Explaining why detail is lost near loud transients.','Studying the temporal resolution of hearing.']::text[],'intermediate',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Temporal masking');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1908','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1908') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1908');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1909','Timbre space','A timbre space is a geometric representation, usually of two or three dimensions, in which sounds are positioned so that perceptual distances match listeners'' judged timbral dissimilarities. Its axes typically align with acoustic attributes such as spectral centroid (brightness) and attack time.','A timbre space is a map of sound colours. Sounds that seem alike sit close together. The map''s directions match features like brightness and attack. It comes from listeners'' dissimilarity ratings.','It gives a compact model of how instrument timbres relate perceptually, summarizing the main dimensions along which they differ.','A sound designer places target and existing patches in a timbre space and moves a synth''s brightness and attack controls to shift a patch toward the desired region.','Timbre',ARRAY['Multidimensional scaling of timbre','Interaural cross-correlation coefficient','Isophonic contour','Masking pattern']::text[],ARRAY['Treating the space''s axes as exact physical measures rather than interpreted dimensions.','Confusing the timbre space (the result) with multidimensional scaling (the method).','Assuming one universal timbre space applies to every set of sounds.']::text[],ARRAY['Guiding synthesizer patch design from perceptual dimensions.','Comparing instrument tones perceptually.','Interpreting results of timbre dissimilarity studies.']::text[],'advanced',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Timbre space');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1909','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1909') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1909');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1910','Time-frequency masking','Time-frequency masking is the combined description of how a masker raises detection thresholds jointly across both frequency and time. It merges spectral spread of masking with temporal (pre- and post-) masking into a single masking surface used in perceptual audio processing.','Masking spreads across both pitch and time at once. A loud sound hides nearby pitches and nearby moments. Combining both gives a masking map. Audio coders use this map to hide noise.','It provides a unified time-frequency model of masking that perceptual coders use to keep quantization noise inaudible.','An audio codec computes a time-frequency masking threshold for each block, then shapes quantization noise to stay beneath that surface in every frequency band and time frame.','Masking',ARRAY['Masking pattern','Temporal masking','Pre-masking','Post-masking']::text[],ARRAY['Treating spectral and temporal masking separately when they interact jointly.','Assuming the masking surface is symmetric in time or in frequency.','Ignoring pre-masking limits, causing audible pre-echo in codecs.']::text[],ARRAY['Building psychoacoustic models for perceptual audio codecs.','Shaping quantization noise below the masking threshold.','Analyzing audibility of coding artifacts across time and frequency.']::text[],'advanced',NULL,NULL,'4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Time-frequency masking');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1910','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1910') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1910');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1911','Tonality index','In a psychoacoustic model, the tonality index is a normalized value, typically bounded between 0 and 1, that grades how tone-like (versus noise-like) each spectral component of a signal is. It is commonly derived from an unpredictability (chaos) measure of the short-time spectrum, then used to set the required signal-to-mask offset, because a tonal masker and a noise masker of equal level do not mask other sounds equally.','This is a score for how much a sound acts like a pure tone. A score near one means a clear tone. A score near zero means it sounds like noise. Audio models use it to judge what other sounds a listener will miss.','It lets a masking model classify spectral energy as tonal or noise-like, since a steady tone and a noise band of equal level produce different masking thresholds.','In an MPEG-style encoder, a component''s unpredictability c sets the index t = -0.299 - 0.43 * ln(c); for c = 0.05 this gives t of about 0.99 (nearly a pure tone), so the model demands a larger masking margin than for a noise-like component near t = 0.','Masking',ARRAY['Masking pattern','Critical Bandwidth','Excitation pattern','Modulation masking']::text[],ARRAY['Confusing the tonality index with musical tonality, meaning keys and scales, which is a different idea.','Assuming a high tonality index means the component is loud; it only describes tone-like character, not level.','Treating tonal and noise maskers as equally effective, ignoring that masking is asymmetric.','Reading the index as an absolute measurement rather than a model-internal, normalized classifier.']::text[],ARRAY['Tuning a lossy audio encoder''s psychoacoustic model to allocate bits by tonal versus noise content.','Explaining why a steady sine tone is masked less effectively than a noise band of the same level.','Investigating why a tonal spectral peak in a device''s noise emission stands out to listeners.','Teaching how a coder decides which quiet spectral components can be discarded.']::text[],'advanced','t = -0.299 - 0.43 * ln(c),  clipped to 0 <= t <= 1','The tonality index equals minus zero point two nine nine, minus zero point four three times the natural logarithm of the unpredictability measure, with the result limited to the range zero to one.','4c9b890d-65de-45f0-805a-f38f9efbcd80' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tonality index');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1911','4c9b890d-65de-45f0-805a-f38f9efbcd80',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1911') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1911');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1912','Absorption loss','Absorption loss is the portion of sound energy that is converted to heat as a wave travels through a medium or interacts with a boundary, instead of being reflected or transmitted. It is described by an absorption (attenuation) coefficient and increases with propagation distance, so it is normally expressed in decibels per unit length or per interaction.','Sound loses energy as it moves through air, water, or materials. Some of that energy turns into a tiny bit of heat. This is called absorption loss. It grows with distance, so far-off sound is weaker and duller.','It explains why sound weakens with distance and why high frequencies fade first, which is central to predicting propagation and designing quiet spaces.','Using ISO 9613-1 atmospheric data, air absorbs roughly 5 dB per kilometre at 1 kHz in mild conditions, so a 500 m outdoor path adds about 2.5 dB of extra high-frequency loss on top of distance spreading.','Sound propagation',ARRAY['Acoustic Attenuation Constant','Atmospheric absorption','Absorption coefficient','Sound propagation','Transmission loss']::text[],ARRAY['Confusing absorption loss with distance (spreading) loss; they are separate mechanisms that add together.','Assuming absorption is equal at all frequencies, when high frequencies are absorbed far more strongly.','Treating a surface absorption coefficient as if it applied to the air path, or vice versa.']::text[],ARRAY['Predicting how far an outdoor concert carries at night.','Explaining why distant thunder sounds like a low rumble.','Modelling reverberation, where boundary absorption controls decay time.']::text[],'intermediate','p(d) = p_0 * e^(-alpha*d);  L_abs = alpha_dB * d','Sound pressure decays exponentially with distance at a rate set by the absorption coefficient; in decibels, the absorption loss equals the coefficient in decibels per metre times the path length in metres.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Absorption loss');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1912','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1912') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1912');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1914','Acoustic Attenuation Constant','The acoustic attenuation constant is the real part, alpha, of the complex propagation constant of a sound wave; it sets the exponential rate at which the wave''s pressure amplitude decreases per unit distance travelled. It combines viscous, thermal, and molecular-relaxation losses and is normally given in nepers per metre or decibels per metre.','A sound wave gets weaker as it travels. The attenuation constant is the number that says how fast. A bigger value means the sound dies away sooner. It rises with frequency, so treble fades before bass.','It packages every energy-loss mechanism into one distance-rate figure, letting engineers predict how far a signal survives in air, water, or tissue.','If alpha is 0.1 nepers per metre, after 10 m the pressure amplitude falls to e^(-1), about 37% of its start; multiply nepers/m by 8.686 to get roughly 0.87 dB/m.','Sound propagation',ARRAY['Absorption loss','Propagation constant','Attenuation coefficient','Acoustic impedance of water','Sound absorption']::text[],ARRAY['Mixing up nepers and decibels; 1 Np equals about 8.686 dB.','Forgetting the constant is strongly frequency dependent and rises roughly with frequency squared in air.','Confusing amplitude decay rate with intensity decay rate, which is twice as fast.']::text[],ARRAY['Estimating ultrasound penetration depth in tissue or water.','Calculating high-frequency loss over a long outdoor path.','Comparing the damping of different transmission media.']::text[],'advanced','p(x) = p_0 * e^(-alpha*x),  gamma = alpha + j*beta','Pressure amplitude falls exponentially with distance at the rate alpha, which is the real part of the complex propagation constant; the imaginary part beta is the phase constant.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic Attenuation Constant');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1914','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1914') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1914');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1915','Acoustic Black Hole','An acoustic black hole is a structural feature, typically a wedge or hole whose thickness tapers to near zero following a power law, in which the bending-wave speed slows and the wave energy concentrates without strong reflection. With a thin damping layer near the tip, incoming flexural (bending) waves are trapped and dissipated, giving lightweight vibration and noise control.','An acoustic black hole is a specially shaped taper in a plate or beam. As a bending wave enters, it slows down and bunches up near the thin tip. A small patch of damping there soaks up the energy. This cuts vibration and radiated noise cheaply.','It lets designers absorb structural vibration with very little added mass, replacing heavy damping treatments in panels and machinery.','A technician shapes a plate edge so its thickness follows h(x) = e*x^m with m at least 2, then bonds a thin viscoelastic film near the tip to turn the trapped bending waves into heat.','Vibration control',ARRAY['Flexural wave','Structural damping','Acoustic Attenuation Constant','Vibration isolation','Acoustic Dispersion']::text[],ARRAY['Thinking it absorbs airborne sound directly; it acts on bending waves in the structure.','Expecting perfect absorption; a real, non-zero tip thickness always reflects some energy.','Omitting the small damping layer, without which the effect largely fails.']::text[],ARRAY['Reducing panel vibration in aerospace or automotive structures.','Damping resonances in a machine housing without adding mass.','Research on lightweight noise-control metamaterials.']::text[],'advanced','h(x) = e * x^m,  m >= 2','The local thickness decreases toward the tip as a power law with exponent at least two, so the bending-wave speed falls toward zero and the wave slows to a near stop.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic Black Hole');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1915','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1915') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1915');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1916','Acoustic Bridge','In building acoustics an acoustic bridge, or sound bridge, is a rigid mechanical connection that spans an intended air gap or resilient break between two elements, forming a direct structure-borne path that short-circuits their sound isolation. The name is also used historically for Rayleigh''s balancing device for comparing acoustic impedances.','Two layers are meant to stay separate so sound cannot cross easily. An acoustic bridge is a hard link that accidentally joins them. Vibration then passes straight through and ruins the isolation. A screw touching both leaves is a common example.','Naming the bridge helps technicians find and remove the hidden rigid paths that let vibration bypass an otherwise well-isolated wall, floor, or float.','When a double-stud wall underperforms its rated sound transmission class, the technician hunts for acoustic bridges such as a mortar dropping, a shared fastener, or rigid conduit spanning the cavity.','Sound isolation',ARRAY['Flanking transmission','Sound transmission class','Vibration isolation','Acoustic boundary','Structure-borne sound']::text[],ARRAY['Assuming a thick wall cannot be bridged; one small rigid contact can dominate the leak.','Confusing an acoustic bridge with an airborne leak; a bridge carries structure-borne vibration.','Forgetting that mortar droppings in a cavity act as bridges between the leaves.']::text[],ARRAY['Diagnosing why a floated floor still transmits footfall.','Inspecting a party wall that fails its insulation target.','Detailing services so they do not rigidly link two leaves.']::text[],'intermediate',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic Bridge');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1916','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1916') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1916');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1917','Acoustic Dispersion','Acoustic dispersion is the dependence of the speed of sound on frequency, so that different frequency components of a wave travel at different phase velocities and a broadband pulse spreads out in time as it propagates. It arises from mechanisms such as molecular relaxation, boundary effects in ducts and plates, and bubbly or porous media.','Normally all pitches of sound travel at the same speed. In some media they do not. High and low tones then move at slightly different speeds. This is dispersion, and it smears a sharp click into a longer sound.','It tells engineers when wave shape and timing will distort during travel, which matters for pulses, sonar, and waves in pipes and plates.','A technician measuring flexural waves on a plate allows for dispersion because bending-wave speed rises with the square root of frequency, so higher components arrive first and stretch the recorded pulse.','Sound propagation',ARRAY['Phase velocity','Group velocity','Flexural wave','Acoustic Attenuation Constant','Acoustic Black Hole']::text[],ARRAY['Assuming air is strongly dispersive; over normal audio distances air is nearly non-dispersive.','Confusing dispersion (speed varies with frequency) with diffusion or scattering.','Ignoring that phase and group velocity differ when a medium is dispersive.']::text[],ARRAY['Interpreting stretched pulses in ultrasonic pipe testing.','Modelling bending waves on panels and rails.','Sonar in bubbly water where sound speed varies with frequency.']::text[],'advanced','c_p = omega / k;  dispersive if d(c_p)/d(omega) != 0','Phase velocity equals angular frequency divided by wavenumber; a medium is dispersive when this phase velocity changes with frequency.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic Dispersion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1917','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1917') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1917');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1918','Acoustic Encounter','In passive acoustic monitoring an acoustic encounter is a bounded period during which sounds from a particular source, most often a vocalizing animal, are detected at a sensor, used as the basic unit for counting and analysing acoustic presence. Consecutive detections are grouped into one encounter unless separated by a silence longer than a chosen gap time.','Underwater and field microphones listen for animals. When one starts calling and is heard, an encounter begins. It ends after a long enough silence. Scientists count encounters to study how often animals are present.','It turns a continuous recording into countable events, giving a practical unit for measuring occurrence and activity without having to identify individuals.','A technician sets a gap rule, say five minutes, so detections closer than that are merged into one acoustic encounter, then tallies encounters per day as an activity metric.','Acoustic monitoring',ARRAY['Passive acoustic monitoring','Detection','Acoustic source trajectory','Bioacoustics','Vocalization']::text[],ARRAY['Treating one encounter as one animal; several individuals may contribute.','Comparing encounter counts across studies that used different gap times.','Assuming no encounter means no animal, when it may just be silent.']::text[],ARRAY['Monitoring marine mammals with seafloor recorders.','Surveying bird or bat activity from field microphones.','Reporting seasonal presence from long-term acoustic data.']::text[],'intermediate',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic Encounter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1918','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1918') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1918');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1919','Acoustic Equivalent Volume','An acoustic equivalent volume is the volume of enclosed air whose acoustic compliance equals that of the device or cavity being characterised, converting a springiness into an easily compared air volume. In loudspeaker theory it is the Thiele-Small parameter Vas, the air volume with the same compliance as the driver suspension; in audiology it is the equivalent ear-canal volume read from tympanometry.','Air trapped in a box acts like a spring. Many acoustic parts also act springy. We describe their springiness as the volume of air that would feel the same. Speaker suspensions and eardrums are both measured this way.','It reduces a compliance to one intuitive number in litres or cubic centimetres, so parts, drivers, or ear canals can be compared and enclosures can be sized.','Reading a driver''s Vas of 50 litres, a technician sizing a sealed box of 25 litres adds about twice the driver''s own suspension stiffness (Vas/Vb = 2), which raises the system resonance to roughly 1.7 times the driver''s free-air value.','Acoustic compliance',ARRAY['Thiele-Small parameters','Acoustic compliance','Acoustic coupler','Acoustic transfer impedance','Sealed enclosure']::text[],ARRAY['Thinking Vas is the box volume; it is the equivalent volume of the suspension, not the cabinet.','Mixing units, since Vas is often in litres but coupler volumes are in cubic centimetres.','Assuming equivalent volume is fixed; it varies with the driver and with temperature.']::text[],ARRAY['Sizing a sealed loudspeaker enclosure from Thiele-Small data.','Reading equivalent ear-canal volume during a tympanometry test.','Calibrating probe microphones against a known coupler volume.']::text[],'advanced','V_as = rho * c^2 * C_MS * S_d^2','The equivalent volume equals air density times the square of the speed of sound times the suspension mechanical compliance times the square of the effective diaphragm area.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic Equivalent Volume');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1919','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1919') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1919');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1920','Acoustic Localization Error','Acoustic localization error is the discrepancy between the position or direction of a sound source estimated from acoustic measurements and its true position, usually reported as a distance, an angular error, or a root-mean-square value over many trials. It captures the combined effect of noise, reverberation, sensor geometry, and algorithm limits on a localization system.','A microphone array guesses where a sound comes from. The guess is rarely exact. Localization error is the gap between the guess and the truth. It can be given in metres or in degrees off target.','It provides the yardstick for judging and comparing source-localization systems and for deciding whether an application''s accuracy is good enough.','If an array estimates a talker at 32 degrees when the true bearing is 28 degrees, the angular localization error is 4 degrees; the technician averages many such trials into a root-mean-square figure.','Source localization',ARRAY['Microphone array','Direction of arrival','Acoustic multitarget tracking','Acoustic source trajectory','Time difference of arrival']::text[],ARRAY['Reporting a single trial instead of a statistic over many measurements.','Ignoring that reverberation and background noise inflate the error.','Confusing angular error with distance error; both must be stated clearly.']::text[],ARRAY['Testing a smart-speaker beamformer''s aiming accuracy.','Evaluating gunshot or drone acoustic locators.','Benchmarking direction-of-arrival algorithms.']::text[],'intermediate','e = || x_est - x_true ||;  RMSE = sqrt( mean(e^2) )','The error for one estimate is the distance between the estimated and true source positions; the root-mean-square error is the square root of the mean of the squared errors over all trials.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic Localization Error');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1920','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1920') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1920');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1921','Acoustic Radiation Force','Acoustic radiation force is the steady, time-averaged force exerted on an object or interface by a sound field, arising from the nonlinear transfer of wave momentum when sound is absorbed, reflected, or scattered. Its magnitude depends on the acoustic energy density and on the target''s size, impedance, and whether it absorbs or reflects the incident wave.','A strong sound field can push on objects steadily, not just make them vibrate. This steady push is the acoustic radiation force. It comes from the wave giving up its momentum. It can trap tiny particles or move droplets.','It underlies acoustic tweezers, particle trapping, and the radiation-force balances used to measure the output power of ultrasound sources.','On a perfectly absorbing target in a plane wave the force equals acoustic power divided by sound speed; a 1 W ultrasound beam in water (c about 1500 m/s) gives roughly 6.7x10^-4 N.','Nonlinear acoustics',ARRAY['Radiation pressure','Acoustic Streaming','Sound intensity','Ultrasound power measurement','Acoustic particle motion']::text[],ARRAY['Confusing the steady radiation force with the oscillating acoustic pressure.','Forgetting the force differs for absorbing versus reflecting targets; a reflector roughly doubles it.','Ignoring that it is a nonlinear, second-order effect, small at ordinary sound levels.']::text[],ARRAY['Measuring ultrasound power with a radiation-force balance.','Trapping and moving cells or droplets with acoustic tweezers.','Explaining particle patterns in a standing-wave field.']::text[],'advanced','F = P_ac / c   (absorbing target);  F ~ 2*P_ac/c  (reflector)','For a target that fully absorbs a normally incident beam, the radiation force equals the time-averaged acoustic power divided by the speed of sound; a perfect reflector experiences about twice this force.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic Radiation Force');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1921','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1921') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1921');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1922','Acoustic Streaming','Acoustic streaming is a steady, time-averaged fluid flow generated by a sound field, produced when the wave''s momentum is transferred to the fluid through viscous attenuation in the bulk (Eckart streaming) or in boundary layers near surfaces (Rayleigh and Schlichting streaming). It is a second-order, nonlinear effect whose speed grows with sound intensity.','A strong sound wave can set a fluid slowly circulating. This steady flow is acoustic streaming. It happens because the wave loses momentum to the fluid. Stronger sound makes faster streaming.','It explains slow flows and mixing driven by sound and is exploited in microfluidic pumping, mixing, and enhanced heat transfer.','Near an absorbing region the sound sets up a steady body force of about 2*alpha*I/c per unit volume that drives the flow; a technician raises drive amplitude to speed up ultrasonic mixing in a small chamber.','Nonlinear acoustics',ARRAY['Acoustic Radiation Force','Acoustic Attenuation Constant','Nonlinear acoustics','Microfluidics','Acoustic particle motion']::text[],ARRAY['Confusing the steady streaming flow with the oscillating particle motion of the wave itself.','Assuming it needs no losses; streaming requires attenuation to transfer momentum.','Treating it as linear, when its speed scales with intensity, a second-order quantity.']::text[],ARRAY['Mixing or pumping fluids in acoustofluidic devices.','Enhancing heat transfer with high-intensity sound.','Explaining slow circulation seen in ultrasonic cleaning baths.']::text[],'advanced','f_body = 2 * alpha * I / c','The steady body force per unit volume that drives Eckart streaming equals twice the absorption coefficient times the wave intensity, divided by the speed of sound.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic Streaming');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1922','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1922') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1922');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1923','Acoustic appropriateness','In soundscape assessment, acoustic appropriateness is a perceptual judgement of how well the sound environment of a place fits the activities and expectations for that place, rather than simply whether it is loud or quiet. It is one of the response attributes gathered in soundscape studies alongside overall sound quality.','A place can sound right or wrong for what it is for. A quiet library and a lively market each suit their setting. Acoustic appropriateness rates that fit. It is about suitability, not just loudness.','It lets planners judge sound environments by suitability to context, supporting the soundscape approach in which the right sound, not just less sound, is the goal.','Following the ISO 12913 soundscape method, a technician surveys visitors on whether the sound is appropriate to a park, then combines those answers with level measurements to guide design.','Soundscape',ARRAY['Soundscape','Acoustic privacy','Acoustic environment model','Environmental noise','Sound quality']::text[],ARRAY['Equating appropriateness with quietness; a suitable place can be lively and loud.','Judging it from measurements alone, when it is a perceptual, context-based response.','Assuming one rating fits all users of a space.']::text[],ARRAY['Designing an urban park''s soundscape.','Evaluating background-music suitability in a cafe.','Comparing the perceived fit of a plaza before and after redesign.']::text[],'intermediate',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic appropriateness');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1923','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1923') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1923');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1924','Acoustic boundary','An acoustic boundary is a surface at which the medium or its acoustic properties change, such as a room''s walls or the interface between two fluids, and at which the wave must satisfy conditions on pressure and particle velocity. The boundary''s specific acoustic impedance governs how much sound is reflected, absorbed, or transmitted there.','Sound changes behaviour where the material changes. A wall, a water surface, or a room edge is an acoustic boundary. At that surface some sound reflects and some passes through. The surface''s impedance decides how much of each.','Boundaries set the reflection, absorption, and transmission that shape reverberation, standing waves, and leakage, so defining them is essential to room and duct modelling.','Assigning each surface an impedance or absorption coefficient, a technician sets the acoustic boundary conditions in a room-acoustics simulation to predict reverberation time.','Boundary conditions',ARRAY['Acoustic impedance of water','Reflection coefficient','Absorption loss','Acoustic Bridge','Room modes']::text[],ARRAY['Assuming a rigid boundary absorbs sound, when a hard wall mostly reflects it.','Ignoring that boundary impedance is frequency dependent.','Forgetting that both pressure and velocity conditions must be met at the interface.']::text[],ARRAY['Setting wall properties in an acoustic finite-element model.','Explaining why a room has strong modes between hard walls.','Analysing reflection at a water-air interface in sonar.']::text[],'intermediate','Z_s = p / u_n','The specific acoustic impedance at a boundary is the sound pressure at the surface divided by the component of particle velocity normal to it.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic boundary');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1924','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1924') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1924');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1925','Acoustic coupler','An acoustic coupler is a cavity of precisely known volume and shape used to connect a sound source, such as an earphone, to a measurement microphone so that its output can be calibrated or measured under standardized conditions. Standard couplers, including the 2 cm^3 coupler and occluded-ear simulators, are specified in the IEC 60318 series.','To test an earphone you need a controlled little chamber. An acoustic coupler is that chamber, with a known air volume. It links the earphone to a measuring microphone. Standard shapes make results comparable between labs.','It provides a repeatable, standardized acoustic load so earphones, hearing aids, and audiometers can be calibrated consistently across laboratories.','Calibrating an audiometer, a technician seals the earphone onto a 2 cm^3 coupler (IEC 60318-3) and reads the resulting sound pressure level on the coupler microphone.','Calibration',ARRAY['Acoustic Equivalent Volume','Artificial ear','Sound level calibrator','Acoustic transfer impedance','Coupler microphone']::text[],ARRAY['Confusing a small hard-walled coupler with a full ear simulator, which mimics real ear impedance.','Using the wrong coupler type for the earphone under test.','Ignoring leaks, which change the effective cavity volume and the result.']::text[],ARRAY['Calibrating audiometer earphones before hearing tests.','Testing hearing-aid output on a standardized coupler.','Verifying earphone output level on a production line.']::text[],'intermediate',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic coupler');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1925','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1925') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1925');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1926','Acoustic diffraction','Acoustic diffraction is the bending and spreading of sound waves around obstacles and through openings, so that sound reaches regions that a straight-line ray picture would leave in shadow. It is most pronounced when the wavelength is comparable to, or larger than, the size of the obstacle or aperture.','Sound does not travel only in straight lines. It bends around edges and through gaps. This bending is diffraction. It is why you can hear someone around a corner, especially for low, long-wavelength notes.','It explains why barriers give limited low-frequency protection and why sound leaks around corners, guiding the design of noise barriers and loudspeaker directivity.','Estimating a noise barrier''s benefit, a technician computes the Fresnel number N = 2*delta/lambda from the extra path over the top; a larger N means less energy diffracts into the shadow and more attenuation.','Sound propagation',ARRAY['Acoustic obstruction','Noise barrier','Fresnel number','Wavelength','Acoustic ray']::text[],ARRAY['Assuming a barrier blocks all frequencies equally; low frequencies diffract around it easily.','Thinking sound casts sharp shadows like light; long wavelengths bend strongly.','Confusing diffraction (bending at edges) with refraction (bending from speed gradients).']::text[],ARRAY['Predicting how much a highway barrier quiets a home.','Explaining audible sound around a doorway or corner.','Understanding loudspeaker cabinet edge effects.']::text[],'intermediate','N = 2 * delta / lambda','The barrier Fresnel number equals twice the extra sound path over the obstacle divided by the wavelength; larger values mean stronger attenuation in the shadow.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic diffraction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1926','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1926') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1926');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1927','Acoustic energy map','An acoustic energy map is a spatial representation showing how sound energy, energy density, or level is distributed over a surface, region, or set of directions. Such maps are produced by acoustic cameras and beamforming arrays, by measurement grids, or by prediction models such as environmental noise maps.','An acoustic energy map is a picture of where sound is loud or soft. Colours show high and low energy across a space. Acoustic cameras and noise-mapping software make them. Engineers use them to spot the noisy places.','It makes an invisible sound field easy to see, helping locate noise sources and communicate exposure across a machine, room, or neighbourhood.','Pointing an acoustic camera at a machine, a technician overlays the beamforming energy map on a photo to find the loudest panel, then treats that spot first.','Acoustic imaging',ARRAY['Beamforming','Acoustic camera','Sound energy density','Noise mapping','Acoustic environment model']::text[],ARRAY['Reading beamforming colours as absolute level without checking the dynamic range and scale.','Trusting map detail below the array''s spatial-resolution limit.','Confusing an energy-density map with a directional (bearing) map.']::text[],ARRAY['Locating a rattle or leak on a running machine.','Producing a city environmental noise map.','Visualising level distribution across an open-plan office.']::text[],'intermediate','w = p_rms^2 / (rho * c^2)','The time-averaged acoustic energy density mapped for a plane progressive wave equals the mean-square sound pressure divided by the product of density and the square of the speed of sound.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic energy map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1927','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1927') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1927');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1928','Acoustic environment model','An acoustic environment model is a computational description of how sound behaves in a given space, combining geometry, surface absorption and scattering, sources, and medium so that pressures or impulse responses can be predicted or auralized. Such models range from simple statistical reverberation estimates through geometric ray tracing to full wave solvers used in virtual and augmented reality audio.','An acoustic environment model is a virtual copy of how a space sounds. It stores the shapes, materials, and sources. Software then predicts echoes and reverberation. Games and virtual reality use it to place sounds realistically.','It lets designers hear or predict a space before it exists and drives realistic spatial audio in games, virtual reality, and architectural simulation.','Building a room''s acoustic environment model, a technician assigns absorption coefficients to each surface, runs ray tracing to get an impulse response, then convolves it with dry audio to auralize the space.','Acoustic modelling',ARRAY['Auralization','Ray tracing','Acoustic boundary','Room impulse response','Acoustic energy map']::text[],ARRAY['Expecting accurate low-frequency results from geometric (ray) models, which ignore wave effects.','Using guessed absorption data, the largest source of model error.','Confusing a real-time game reverb model with a validated engineering prediction.']::text[],ARRAY['Auralizing a concert hall design before construction.','Rendering spatial audio in a virtual reality application.','Predicting reverberation in a proposed office.']::text[],'intermediate',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic environment model');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1928','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1928') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1928');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1929','Acoustic impedance of water','The acoustic impedance of water is its characteristic (specific) acoustic impedance, the product of density and sound speed, which governs how sound reflects and transmits at boundaries involving water. For fresh water near 20 degrees C it is about 1.48 megarayl (1.48x10^6 Pa*s/m), roughly 3,500 times that of air.','Every medium resists sound in its own way. For water this resistance is its acoustic impedance. Water''s value is far higher than air''s. That large mismatch is why most sound reflects at the water surface.','It sets how strongly sound reflects at water interfaces, which is fundamental to sonar, underwater communication, and medical ultrasound coupling.','Using Z = rho*c with rho about 998 kg/m^3 and c about 1481 m/s, water''s impedance is about 1.48x10^6 Pa*s/m; the huge air-water mismatch reflects roughly 99.9% of sound at the surface.','Acoustic impedance',ARRAY['Characteristic impedance','Acoustic Attenuation Constant','Reflection coefficient','Acoustic boundary','Impedance mismatch']::text[],ARRAY['Confusing characteristic impedance (rho*c) with the acoustic impedance ratio p/U at a point.','Forgetting the value shifts with temperature, salinity, and pressure through the sound speed.','Assuming sound passes easily from air into water, when most of it reflects.']::text[],ARRAY['Designing sonar and hydrophone couplings.','Explaining why shouting underwater is barely heard above the surface.','Selecting matching gel for medical ultrasound.']::text[],'intermediate','Z = rho * c','The characteristic acoustic impedance of water equals its density times its speed of sound.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic impedance of water');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1929','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1929') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1929');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1930','Acoustic multitarget tracking','Acoustic multitarget tracking is the estimation, over time, of the number and time-varying states (such as position and velocity) of several simultaneous sound sources from acoustic sensor data. It combines detection and localization with recursive filters that associate measurements to targets and maintain tracks despite noise, missed detections, and clutter.','Several things can make sound at once, and they move. Acoustic multitarget tracking follows all of them over time. Software links each new detection to the right source. It keeps a separate path for each one.','It provides continuous awareness of multiple moving sources, needed in surveillance, robotics, and wildlife monitoring where sources appear, move, and vanish.','Feeding array bearings into a tracking filter, a technician keeps separate tracks for two passing vehicles, letting the estimator handle moments when their sounds overlap.','Source tracking',ARRAY['Acoustic Localization Error','Acoustic source trajectory','Microphone array','Direction of arrival','Kalman filter']::text[],ARRAY['Assuming the number of sources is known; it must often be estimated too.','Ignoring data-association errors when tracks cross or overlap.','Confusing single-snapshot localization with tracking across time.']::text[],ARRAY['Following multiple talkers for a camera-steering system.','Tracking several vehicles from a ground sensor array.','Monitoring several calling animals at once.']::text[],'advanced',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic multitarget tracking');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1930','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1930') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1930');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1931','Acoustic obstruction','An acoustic obstruction is any object placed in a sound field that blocks, reflects, or scatters part of the wave, casting a partial acoustic shadow behind it. How much sound it stops depends on its size relative to the wavelength, since long wavelengths diffract around it while short ones are more effectively blocked.','Put something solid in the path of sound and it gets in the way. That object is an acoustic obstruction. It blocks high notes better than low ones. Low, long waves simply bend around it.','It is the basic idea behind noise barriers and screens, and it explains partial shadowing by walls, furniture, and terrain.','Choosing a screen to shield a workstation, a technician makes it large compared with the wavelengths of concern, because a small obstruction lets low frequencies diffract around it.','Sound propagation',ARRAY['Acoustic diffraction','Noise barrier','Acoustic opening','Scattering','Acoustic ray']::text[],ARRAY['Sizing a barrier for its height only, ignoring wavelength.','Expecting a small object to block low-frequency sound.','Confusing blocking (obstruction) with absorbing; a hard obstruction reflects sound elsewhere.']::text[],ARRAY['Placing a screen between a noisy machine and workers.','Explaining partial quiet behind a garden wall.','Modelling terrain shielding in outdoor noise prediction.']::text[],'beginner',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic obstruction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1931','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1931') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1931');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1932','Acoustic opening','An acoustic opening is an aperture, gap, or port that lets sound pass between two spaces or into and out of an enclosure. In building acoustics even small openings sharply reduce sound insulation, while in device acoustics deliberate openings such as vents and ports are used to tune a system''s response.','An acoustic opening is a hole or gap that sound can pass through. In a wall even a small gap lets a lot of noise leak. In a speaker box a tuned port is a wanted opening. Openings matter far more than their size suggests.','It captures how apertures dominate leakage in partitions and how intended ports shape the response of loudspeakers and mufflers.','Sealing a door undercut removes an acoustic opening; a gap of even 1% of a wall''s area can cap its effective sound reduction near 20 dB, however heavy the wall.','Sound isolation',ARRAY['Acoustic Bridge','Flanking transmission','Sound transmission class','Acoustic obstruction','Bass-reflex port']::text[],ARRAY['Underestimating leaks; a tiny gap can dominate a wall''s performance.','Assuming a heavier wall fixes a leak, when the opening sets the limit.','Confusing an unwanted gap with a deliberately tuned port.']::text[],ARRAY['Sealing gaps to meet a wall''s sound-insulation target.','Tuning a bass-reflex loudspeaker port.','Diagnosing noise leaking under a studio door.']::text[],'intermediate','TL_max ~ 10 * log10( S_total / S_open )','The best sound reduction a partition can reach is limited by its open area; it is about ten times the base-ten logarithm of the total area divided by the open area, in decibels.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic opening');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1932','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1932') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1932');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1933','Acoustic particle acceleration','Acoustic particle acceleration is the time rate of change of the acoustic particle velocity, describing how quickly a small element of the medium speeds up and slows down as a sound wave passes. For a sinusoidal field its amplitude equals the angular frequency times the particle-velocity amplitude.','As sound passes, tiny bits of air oscillate back and forth. How fast their speed changes is the particle acceleration. Higher frequencies mean sharper changes. So acceleration grows with pitch for the same motion.','It links the sound field to inertial forces on particles and sensors, and underlies particle-acceleration and vector sensors used in underwater acoustics.','For a plane wave with particle velocity 1 mm/s at 1 kHz, the acceleration amplitude is a = omega*u = 2*pi*1000*0.001, about 6.3 m/s^2.','Acoustic field quantities',ARRAY['Acoustic particle motion','Particle velocity','Acoustic Radiation Force','Vector sensor','Sound intensity']::text[],ARRAY['Confusing particle acceleration of the medium with the wave''s propagation speed.','Forgetting that acceleration leads velocity by 90 degrees in a sinusoidal field.','Mixing tiny particle motion up with bulk airflow.']::text[],ARRAY['Designing particle-motion (vector) hydrophones.','Relating pressure and motion in a sound field.','Analysing the response of accelerometer-based acoustic sensors.']::text[],'advanced','a = du/dt;  |a| = omega * |u|  (sinusoidal)','Particle acceleration is the time derivative of particle velocity; for a single-frequency field its amplitude equals the angular frequency times the particle-velocity amplitude.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic particle acceleration');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1933','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1933') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1933');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1934','Acoustic particle motion','Acoustic particle motion is the small oscillatory displacement and velocity of the fluid elements of a medium about their rest positions as a sound wave passes; it is a vector quantity with direction, unlike scalar sound pressure. For a plane progressive wave the particle-velocity amplitude equals the pressure amplitude divided by the characteristic impedance.','Sound is carried by tiny to-and-fro movements of the medium. Each little parcel of air or water shifts slightly, then returns. This is particle motion. It has a direction, which pressure alone does not.','It provides the directional side of the sound field, exploited by particle-velocity and vector sensors and essential to understanding intensity and energy flow.','For a plane wave in air at 1 Pa rms, particle velocity is u = p/(rho*c) = 1/415, about 2.4 mm/s; a vector sensor reads this motion to find the source direction.','Acoustic field quantities',ARRAY['Acoustic particle acceleration','Particle velocity','Sound intensity','Acoustic impedance of water','Acoustic Streaming']::text[],ARRAY['Thinking particles travel along with the wave; they only oscillate locally.','Assuming pressure and particle velocity are in phase everywhere; they are not in a reactive field.','Confusing tiny particle motion with steady acoustic streaming.']::text[],ARRAY['Measuring sound intensity from pressure and velocity.','Using vector sensors for underwater direction finding.','Explaining how particle motion, not net flow, carries sound.']::text[],'intermediate','u = p / (rho * c)   (plane progressive wave)','In a plane progressive wave the particle-velocity amplitude equals the sound-pressure amplitude divided by the characteristic acoustic impedance of the medium.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic particle motion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1934','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1934') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1934');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1936','Acoustic privacy','Acoustic privacy is the degree to which speech and other sounds produced in one space are prevented from being heard or understood in an adjacent space, so that conversations stay confidential and distraction is limited. It is quantified with speech-privacy metrics based on the transmitted speech level relative to background noise, as in ASTM speech-privacy standards.','Acoustic privacy means others cannot easily overhear you. Walls block some sound, and background noise masks the rest. Together they keep speech from being understood next door. Offices and clinics need this to protect conversations.','It sets a design goal for offices, clinics, and meeting rooms, balancing sound insulation and background masking so confidential speech is not intelligible elsewhere.','To raise acoustic privacy in an open office, a technician adds a sound-masking system so the background level covers intruding speech, improving the measured privacy rating toward confidential.','Speech privacy',ARRAY['Sound masking','Speech intelligibility','Acoustic appropriateness','Sound transmission class','Articulation index']::text[],ARRAY['Relying on wall insulation alone and ignoring background masking noise.','Confusing loudness reduction with privacy; privacy depends on intelligibility, not just level.','Assuming a quiet room is private, when low background can make speech more intelligible next door.']::text[],ARRAY['Designing confidential clinic or human-resources offices.','Adding sound masking to an open-plan office.','Assessing meeting-room speech confidentiality.']::text[],'intermediate',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic privacy');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1936','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1936') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1936');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1937','Acoustic ray','An acoustic ray is a line, drawn perpendicular to the wavefronts, that traces the local direction of sound-energy propagation in the high-frequency (geometrical) approximation. Ray methods treat sound as bundles of such rays that reflect, refract, and spread, while ignoring wave effects such as diffraction.','To picture where sound goes, we can draw arrows that follow it. Each arrow is an acoustic ray. Rays bounce off walls and bend in gradients. This simple picture works best for high frequencies.','Rays give an intuitive, computable way to trace reflections and refraction in rooms, oceans, and the atmosphere when wavelengths are small compared with the features involved.','In a room model, a technician launches many acoustic rays from a source and follows their reflections off surfaces to estimate early reflection paths and reverberation.','Geometrical acoustics',ARRAY['Acoustic ray path','Ray tracing','Acoustic diffraction','Wavefront','Reflection']::text[],ARRAY['Trusting ray results at low frequencies, where diffraction dominates.','Forgetting that rays carry energy but not phase in the simplest models.','Assuming rays are straight when speed gradients bend them.']::text[],ARRAY['Ray-tracing early reflections in a room design.','Modelling sound channels in the ocean.','Predicting atmospheric refraction of outdoor noise.']::text[],'intermediate',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic ray');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1937','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1937') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1937');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1938','Acoustic ray path','An acoustic ray path is the trajectory that a single acoustic ray follows through a medium; it is a straight line in a uniform medium but curves according to Snell''s law where the sound speed varies with position. The path bends by refraction toward regions of lower sound speed.','A ray path is the route one sound arrow actually takes. In steady conditions it runs straight. Where the speed of sound changes, the path bends. Sound curves toward slower regions.','Tracing ray paths shows exactly how sound bends and channels in the sea and atmosphere, explaining shadow zones, focusing, and long-range ducting.','Modelling a warm surface layer over cool water, a technician traces the ray path bending downward, which forms a surface sound channel that carries sonar signals farther.','Geometrical acoustics',ARRAY['Acoustic ray','Refraction','Snell''s law','Sound channel','Acoustic source trajectory']::text[],ARRAY['Assuming ray paths are always straight; speed gradients curve them.','Forgetting that paths bend toward slower sound-speed regions.','Ignoring shadow zones that ray bending creates.']::text[],ARRAY['Predicting sonar range in a layered ocean.','Explaining why sound carries far over water at night.','Modelling refraction in wind and temperature gradients.']::text[],'intermediate','sin(theta) / c = constant   (Snell''s law)','Along a ray path the ratio of the sine of the angle from the vertical to the local sound speed stays constant, so the ray bends toward slower regions.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic ray path');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1938','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1938') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1938');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1940','Acoustic source trajectory','An acoustic source trajectory is the path in space that a sound source follows as a function of time, describing how a moving source''s position, and often its velocity, evolves. It is the quantity that source-tracking systems estimate and that governs Doppler shift and time-varying arrival directions at a receiver.','When a sound source moves, it traces a path over time. That path is its trajectory. A passing siren follows one. Tracking systems try to work out this path from the sound.','It provides the time-position description needed to track moving sources, predict Doppler shifts, and steer cameras or beams toward them.','From a sequence of array bearings, a technician reconstructs a drone''s acoustic source trajectory over several seconds, then extrapolates it to predict its next position.','Source tracking',ARRAY['Acoustic multitarget tracking','Acoustic Localization Error','Doppler shift','Direction of arrival','Acoustic ray path']::text[],ARRAY['Confusing a single position estimate with the full time-varying trajectory.','Ignoring Doppler cues that help constrain a moving source''s path.','Assuming a smooth trajectory when detections are sparse or noisy.']::text[],ARRAY['Tracking a passing vehicle or drone by sound.','Predicting Doppler shift from a moving source.','Steering a camera to follow a moving talker.']::text[],'intermediate',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic source trajectory');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1940','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1940') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1940');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1941','Acoustic transfer impedance','Acoustic transfer impedance is the ratio of the sound pressure produced at one point to the volume velocity of a source acting at another point in an acoustic system, a cross-point measure rather than a local one. It characterises how strongly a source at one location drives the pressure at a separate location, and is used to specify couplers and calibrate transducers.','Push air in and out at one spot, and pressure rises somewhere else. Transfer impedance links those two points. It is the pressure at the second point divided by the flow at the first. Couplers and calibrators are described this way.','It defines the input-output relationship between separated points, letting engineers specify calibration couplers and predict how a source drives a distant pressure.','A standardized coupler is specified by its acoustic transfer impedance Z_T = p_out/U_in; a technician uses that known ratio to convert a source''s volume velocity into the expected coupler pressure.','Acoustic impedance',ARRAY['Acoustic coupler','Acoustic Equivalent Volume','Acoustic boundary','Volume velocity','Two-port network']::text[],ARRAY['Confusing transfer impedance (two separate points) with driving-point impedance (one point).','Forgetting it is complex and frequency dependent.','Mixing volume velocity (flow) up with particle velocity.']::text[],ARRAY['Specifying calibration couplers and artificial ears.','Characterising acoustic two-port networks such as mufflers.','Relating a source''s output to pressure at a remote sensor.']::text[],'advanced','Z_T = p_2 / U_1','Acoustic transfer impedance is the sound pressure at the observation point divided by the volume velocity of the source at the drive point.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic transfer impedance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1941','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1941') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1941');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1942','Acoustic transfer-function vector','A vector whose elements are the frequency-domain acoustic transfer functions from one sound source to each microphone in an array, capturing the source-to-array propagation including direct sound, room reflections and sensor response at a given frequency.','Sound travels from a source to each microphone in a set. Each path changes the sound a little. We store one number per microphone that describes its path. Stacked together, these numbers form a vector.','It compactly describes how a source couples into a whole microphone array, so beamformers and source-separation methods can steer toward or cancel that source.','In a 4-microphone array a technician measures each channel''s response to a loudspeaker, forming a 4-element complex vector at each frequency that the beamformer uses to align and sum the channels.','Array Processing',ARRAY['Relative transfer function','Beamforming','Room impulse response','Steering vector','Microphone array']::text[],ARRAY['Confusing it with a single-channel transfer function that ignores the array geometry.','Assuming it is frequency-independent when each frequency bin has its own vector.','Ignoring room reflections and treating it as a pure delay-and-gain model.']::text[],ARRAY['Designing a beamformer for a conference microphone array.','Estimating a talker''s direction from multichannel recordings.','Separating overlapping sources in a smart-speaker capture.']::text[],'advanced',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic transfer-function vector');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1942','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1942') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1942');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1943','Acoustic visibility','In geometrical acoustics, a test of whether an unobstructed sound-propagation path exists between two points, or between a source (or image source) and a receiver, used to decide if a direct sound or a reflection actually reaches the listener.','Sound needs a clear path to be heard. Acoustic visibility checks if anything blocks that path. If the path is open, the sound reaches the listener. If a wall blocks it, that reflection is dropped.','It lets ray-tracing and image-source room models keep only physically valid paths, so simulated reflections match how sound really travels around obstacles.','In an image-source auralization the technician runs a visibility check for each mirror source; a reflection off a wall hidden behind a pillar fails the test and is excluded from the response.','Geometric Acoustics',ARRAY['Image source method','Ray tracing','Auralization','Room impulse response','Diffraction']::text[],ARRAY['Treating acoustic visibility exactly like optical visibility and ignoring diffraction around edges.','Skipping the visibility test, which creates non-physical reflections in the model.','Assuming a valid image source always yields an audible reflection.']::text[],ARRAY['Building a geometrical acoustics model of a concert hall.','Validating reflection paths in a game-audio engine.','Debugging spurious early reflections in an auralization.']::text[],'advanced',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic visibility');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1943','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1943') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1943');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1944','Acoustic zone','A defined spatial region within which a particular acoustic condition is intended to hold, such as a target sound field, a controlled reverberation, or a listener area addressed by a personal-sound-zone or public-address system.','An acoustic zone is a chosen area with its own sound goal. One zone may get music while a nearby zone stays quiet. Systems aim sound to fill the right zone. This keeps areas from interfering.','It provides a spatial unit for designing and controlling sound coverage, so a system can deliver different or isolated acoustic conditions to different areas.','A technician configuring a car''s personal sound zones assigns the driver seat as one acoustic zone and the rear seats as another, then tunes the array so each zone hears different audio.','Spatial Audio',ARRAY['Personal sound zone','Sound reinforcement','Coverage','Beamforming','Zoned paging']::text[],ARRAY['Assuming zones are perfectly isolated when leakage between them is unavoidable.','Confusing an acoustic zone with a physical room boundary.','Ignoring frequency limits, since low frequencies are hard to confine to a zone.']::text[],ARRAY['Designing multi-room audio in a retail space.','Setting up personal sound zones in a vehicle cabin.','Zoning a public-address system in an airport terminal.']::text[],'intermediate',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic zone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1944','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1944') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1944');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1945','Acoustic-command injection','A class of attacks that feeds crafted audio, often inaudible ultrasonic or hidden signals, into a voice-controlled device so its speech recognizer executes unauthorized commands without the user''s knowledge.','Voice assistants listen for spoken commands. An attacker can send hidden or silent sounds instead. The device may obey these fake commands. The user often hears nothing at all.','The term names a security threat so engineers can test voice interfaces against it and design defenses such as ultrasonic filtering or liveness checks.','A security tester plays a modulated ultrasonic tone near a smart speaker; if the device silently ''hears'' a wake word and dials a number, the technician documents the vulnerability and adds input filtering.','Audio Security',ARRAY['Voice user interface','Ultrasound','Wake word','Adversarial example','Automatic speech recognition']::text[],ARRAY['Believing inaudible means harmless, since ultrasonic carriers can still trigger recognizers.','Assuming volume alone stops the attack rather than input-path filtering.','Confusing it with ordinary background-noise misrecognition.']::text[],ARRAY['Penetration-testing a smart-speaker product.','Reviewing microphone front-end filtering in a voice device.','Assessing risk of hidden commands in media playback.']::text[],'advanced',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic-command injection');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1945','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1945') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1945');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1946','Acoustic-environment recording','The capture of the sound of a place, either as a soundscape recording of the ambient acoustic scene or as a set of measured room responses, in order to document, analyze or reproduce that environment''s acoustic character.','This means recording how a place sounds. It can capture the general background scene. It can also capture how the room echoes. The result documents or recreates that space.','It preserves an environment''s acoustic identity for analysis, monitoring, or later reproduction in playback or virtual-reality systems.','A technician places a calibrated ambisonic microphone in a plaza and logs a timed recording, later using it for a soundscape study under ISO 12913 or to auralize the space.','Soundscape',ARRAY['Soundscape','Ambient sound','Room impulse response','Ambisonics','Field recording']::text[],ARRAY['Failing to calibrate the microphone, so absolute levels cannot be reported.','Confusing a soundscape scene recording with an impulse-response measurement.','Ignoring wind and handling noise that corrupt outdoor captures.']::text[],ARRAY['Documenting a park''s soundscape for an urban-noise study.','Capturing a venue''s ambience for a virtual-reality experience.','Building a reference archive of environmental sounds.']::text[],'intermediate',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic-environment recording');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1946','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1946') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1946');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1947','Acoustic-response parameterization','The reduction of a measured acoustic impulse response into a set of standardized single-number parameters, such as reverberation time, clarity and speech transmission index, that summarize the response for evaluation or reporting.','A room''s echo pattern holds a lot of detail. Parameterization turns it into a few clear numbers. These numbers include reverberation time and clarity. They make rooms easy to compare.','It converts complex response data into comparable metrics, so rooms can be judged against acoustic criteria and against one another.','From one impulse response a technician computes T30 and C50 per ISO 3382-1 and the STI per IEC 60268-16, reporting, for example, T30 of 0.9 s and C50 of 3 dB for a classroom.','Room Acoustics',ARRAY['Room impulse response','Reverberation time','Clarity index','Speech transmission index','Building acoustics descriptor']::text[],ARRAY['Reporting a single parameter as if it fully describes a room''s acoustics.','Using parameters outside the frequency bands where they are defined.','Ignoring measurement position, since parameters vary across a room.']::text[],ARRAY['Commissioning a classroom against speech-clarity targets.','Comparing candidate acoustic treatments from measurements.','Reporting hall acoustics to a design team.']::text[],'intermediate',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic-response parameterization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1947','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1947') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1947');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1948','Air-absorption model','A calculation method that predicts how much sound is absorbed by the atmosphere as it propagates, expressed as an attenuation coefficient that depends on frequency, temperature, humidity and static pressure, per ISO 9613-1.','Air itself soaks up some sound energy. It absorbs high frequencies much more than low ones. Warmth and humidity change how much is lost. A model predicts this loss over distance.','It supplies the atmospheric attenuation term needed in outdoor noise prediction and long-range propagation calculations, so high-frequency loss is accounted for correctly.','Using ISO 9613-1 for 20 C, 70% humidity and 4 kHz, a technician takes the coefficient near 0.03 dB/m and predicts about 3 dB of extra loss over 100 m of travel.','Outdoor Propagation',ARRAY['Attenuation coefficient','Attenuation due to geometrical divergence','Environmental noise','Sound propagation','Relative humidity']::text[],ARRAY['Ignoring air absorption because it is small at low frequencies.','Using a fixed coefficient and ignoring humidity and temperature dependence.','Confusing atmospheric absorption with geometric spreading loss.']::text[],ARRAY['Predicting long-range noise from an industrial plant.','Correcting outdoor measurements for weather conditions.','Modelling aircraft noise over distance.']::text[],'intermediate','A_atm = alpha * d / 1000','Atmospheric attenuation in decibels equals the attenuation coefficient in decibels per kilometre multiplied by the propagation distance in metres, divided by one thousand.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Air-absorption model');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1948','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1948') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1948');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1949','Airborne sound insulation','The reduction of airborne sound provided by a building element such as a wall, floor or window, quantified by the sound reduction index R, the level difference between source and receiving sides normalized for the specimen area and the receiving-room absorption.','Walls and floors block airborne sound like speech or music. Insulation measures how much they block. Higher numbers mean a quieter neighbour. It is tested by comparing loud and quiet sides.','It gives a standardized measure of how well a partition stops airborne noise, so designs can meet privacy and comfort requirements between spaces.','Under ISO 10140, a technician plays noise in the source room and measures L1 = 90 dB and L2 = 45 dB with S/A giving +2 dB, yielding a sound reduction index of about 47 dB in that band.','Sound Insulation',ARRAY['Sound reduction index','Apparent sound reduction index','Airborne sound insulation rating','Impact sound insulation','Flanking transmission']::text[],ARRAY['Confusing laboratory sound reduction index R with in-situ apparent R prime that includes flanking.','Forgetting the receiving-room absorption correction term.','Assuming a single number applies at all frequencies.']::text[],ARRAY['Testing a partition wall in an acoustic laboratory.','Specifying glazing to meet a facade insulation target.','Diagnosing speech privacy failures between offices.']::text[],'intermediate','R = L1 - L2 + 10*lg(S/A)','The sound reduction index equals the source-room level minus the receiving-room level, plus ten times the base-ten logarithm of the specimen area divided by the receiving-room equivalent absorption area.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Airborne sound insulation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1949','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1949') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1949');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1950','Airborne sound insulation rating','A single-number rating of a partition''s airborne sound insulation, derived by fitting a standard reference curve to the measured frequency-band values; examples are the weighted sound reduction index Rw (ISO 717-1) and the sound transmission class STC (ASTM E413).','A wall''s insulation changes with frequency. A rating turns the whole curve into one number. Higher numbers mean better sound blocking. Rw and STC are the common ratings.','It condenses a full frequency response into one comparable figure so specifications, regulations and product data sheets can state insulation simply.','A technician plots the measured R values, shifts the ISO 717-1 reference curve until the unfavourable deviations sum to just under 32 dB, and reads the value at 500 Hz as the Rw, for example 52 dB.','Sound Insulation',ARRAY['Sound reduction index','Airborne sound insulation','Building acoustics descriptor','Apparent sound reduction index','Spectrum adaptation term']::text[],ARRAY['Treating Rw and STC as identical, though their curves and rules differ slightly.','Ignoring spectrum adaptation terms C and Ctr for real noise sources.','Assuming a high rating guarantees low low-frequency transmission.']::text[],ARRAY['Comparing wall systems by their Rw or STC.','Meeting a building-code airborne insulation requirement.','Reading acoustic performance from a product data sheet.']::text[],'intermediate',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Airborne sound insulation rating');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1950','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1950') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1950');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1951','Ambient sound','The all-encompassing sound present in a given environment, usually a composite of many near and distant sources; in environmental noise work the residual sound remaining when the specific source under study is absent is closely related.','Ambient sound is the general background of a place. It comes from many sources mixed together. It is the sound you hear when nothing stands out. Engineers measure it to set a baseline.','It defines the baseline acoustic condition of a space, against which specific sources, intrusions or treatments are judged.','Before assessing a new fan, a technician measures the ambient level with the fan off, logging LAeq = 38 dB as the residual against which the fan''s contribution is compared.','Environmental Noise',ARRAY['Residual sound','Background noise level','Environmental noise','Anthropogenic sound','Assessment level']::text[],ARRAY['Confusing ambient sound with background level, since standards define these distinctly.','Measuring while the source under study is still running.','Assuming ambient sound is constant rather than time-varying.']::text[],ARRAY['Establishing a baseline before an industrial noise assessment.','Setting a recording location''s noise floor.','Judging whether a new source is audible above the background.']::text[],'beginner',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ambient sound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1951','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1951') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1951');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1952','Anthropogenic sound','Sound produced by human activity and technology, such as traffic, machinery, construction and speech; in soundscape studies it is distinguished from biophony (sound of living organisms) and geophony (natural non-biological sound).','Anthropogenic sound is sound made by people. It includes cars, machines, and building work. Soundscape science separates it from nature sounds. This helps study human impact on places.','It categorizes human-made sound as a distinct component of a soundscape, aiding analysis of noise impact on people and ecosystems.','In a soundscape survey a technician tags traffic and aircraft passes as anthropogenic sound, separating them from birdsong so the human contribution to the LAeq can be quantified.','Soundscape',ARRAY['Soundscape','Ambient sound','Environmental noise','Biophony','Geophony']::text[],ARRAY['Labelling all loud sound as anthropogenic without checking its source.','Confusing anthropogenic sound with natural wind or water noise.','Assuming anthropogenic sound is always unwanted noise.']::text[],ARRAY['Classifying sources in an urban soundscape study.','Assessing human noise impact in a protected natural area.','Separating human and natural sound in a field recording.']::text[],'beginner',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Anthropogenic sound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1952','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1952') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1952');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1953','Apparent sound reduction index','The sound reduction index measured between two rooms in a real building, denoted R prime, which unlike the laboratory index includes sound transmitted by flanking paths as well as through the separating element.','In a real building sound sneaks around a wall, not just through it. The apparent index measures the total that gets through. It is written R prime. It is usually lower than a lab result.','It quantifies the actual airborne insulation achieved on site, including flanking, so field performance can be checked against requirements.','Following ISO 16283-1, a technician measures L1 = 88 dB, L2 = 44 dB with a +1 dB area-to-absorption term, giving an apparent sound reduction index R prime of 45 dB for the field partition.','Sound Insulation',ARRAY['Sound reduction index','Airborne sound insulation','Flanking transmission','Standardized level difference','Airborne sound insulation rating']::text[],ARRAY['Comparing field R prime directly with laboratory R and expecting equal values.','Overlooking flanking paths when insulation falls short of the lab figure.','Confusing R prime with the standardized level difference DnT.']::text[],ARRAY['Verifying on-site insulation between finished apartments.','Diagnosing why field insulation misses the lab rating.','Reporting compliance in a building acoustics survey.']::text[],'advanced','R'' = L1 - L2 + 10*lg(S/A)','The apparent sound reduction index equals the source-room level minus the receiving-room level, plus ten times the base-ten logarithm of the separating-element area divided by the receiving-room equivalent absorption area, with flanking transmission included in the measured levels.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Apparent sound reduction index');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1953','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1953') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1953');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1954','Area source','In outdoor noise prediction, a spatially extended sound source represented as an emitting surface, such as a factory facade, car park or water body, often subdivided into smaller sources for calculation per ISO 9613-2.','Some noise comes from a whole surface, not one point. A factory wall or car park is an example. Models call this an area source. It is split into pieces to calculate.','It lets a large or distributed emitter be modelled realistically in propagation calculations, rather than being wrongly treated as a single point.','A technician models a 50 m by 20 m warehouse wall as an area source, dividing it into smaller equivalent point sources so ISO 9613-2 divergence and screening can be applied to each.','Outdoor Propagation',ARRAY['Point source','Line source','Attenuation due to geometrical divergence','Sound power level','Environmental noise']::text[],ARRAY['Modelling a large facade as a single point source, distorting near-field levels.','Ignoring that divergence behaves differently close to an extended source.','Double-counting energy when subdividing the source.']::text[],ARRAY['Predicting noise from an industrial building facade.','Modelling a car park or rail yard as a distributed source.','Assessing noise from a large ventilation louvre array.']::text[],'intermediate',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Area source');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1954','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1954') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1954');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1955','Assessment level','The rating level used to judge environmental noise against limits, formed from the measured or predicted equivalent continuous A-weighted level plus adjustments for tonal, impulsive or other character and for time of day, per ISO 1996.','Noise limits compare against an adjusted level, not the raw reading. The rating level adds penalties for annoying features. It also adjusts for night-time. This adjusted figure is checked against the limit.','It expresses how disturbing a noise is expected to be, so a fair comparison with regulatory limits can be made.','A technician measures LAeq = 47 dB, adds a +5 dB tonal penalty and a +5 dB night adjustment, giving a rating level of 57 dB to compare with the local night-time limit.','Environmental Noise',ARRAY['Rating level','Assessment period','Equivalent continuous sound level','Environmental noise','Ambient sound']::text[],ARRAY['Comparing the raw LAeq with a limit without adding the required adjustments.','Applying penalties twice or to the wrong assessment period.','Confusing the rating level with the measured ambient level.']::text[],ARRAY['Assessing a factory''s night-time noise against a planning limit.','Adding a tonal penalty for an audible whine in plant noise.','Reporting compliance in an environmental noise survey.']::text[],'intermediate',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Assessment level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1955','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1955') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1955');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1956','Assessment period','The specified interval of time over which environmental noise is evaluated for comparison with a limit, such as day, evening or night, chosen to represent the relevant exposure and used when computing time-averaged levels.','Noise is judged over a set stretch of time. This could be day, evening, or night. The chosen period matches when people are affected. Levels are averaged across it.','It fixes the time base for averaging and rating noise, so results are consistent and reflect the exposure that matters for a given limit.','For a night limit a technician sets the assessment period as 23:00 to 07:00 and computes the LAeq over those eight hours, then compares it with the night-time criterion.','Environmental Noise',ARRAY['Assessment level','Reference time interval','Equivalent continuous sound level','Day-evening-night level','Environmental noise']::text[],ARRAY['Averaging over the wrong period, which changes the LAeq result.','Confusing the assessment period with the shorter measurement time interval.','Ignoring that day, evening and night use different periods and penalties.']::text[],ARRAY['Choosing day and night periods for a noise survey.','Computing Lden across defined day, evening and night intervals.','Aligning a measurement schedule with regulatory periods.']::text[],'beginner',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Assessment period');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1956','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1956') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1956');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1957','Attenuation coefficient','A coefficient describing the rate at which sound pressure or intensity decreases with distance due to absorption in a medium, commonly the atmospheric attenuation coefficient expressed in decibels per kilometre or as a pressure decay in nepers per metre.','Sound loses energy as it passes through a medium. The attenuation coefficient sets how fast this loss happens. A bigger value means quicker fading. It rises steeply with frequency in air.','It quantifies absorption per unit distance, letting engineers predict how much level is lost over a propagation path.','With an atmospheric coefficient of 5 dB/km at 2 kHz, a technician predicts 2.5 dB of absorption loss over a 500 m outdoor path, adding it to geometric spreading loss.','Outdoor Propagation',ARRAY['Air-absorption model','Attenuation due to geometrical divergence','Sound propagation','Absorption coefficient','Decibel']::text[],ARRAY['Mixing decibel-per-metre with neper-per-metre units without converting.','Confusing the atmospheric attenuation coefficient with a surface absorption coefficient.','Applying a single value across all frequencies.']::text[],ARRAY['Estimating high-frequency loss over a long outdoor path.','Correcting field measurements for atmospheric absorption.','Modelling ultrasonic ranging attenuation in air.']::text[],'intermediate','L(d) = L0 - alpha*d','The level at distance d equals the reference level minus the attenuation coefficient multiplied by the distance, when the coefficient is expressed in decibels per unit distance.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Attenuation coefficient');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1957','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1957') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1957');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1958','Attenuation due to foliage','The excess attenuation of sound as it propagates through dense vegetation such as trees and shrubs, tabulated in ISO 9613-2 as octave-band values depending on the path length within the foliage.','Sound passing through thick trees loses extra energy. Leaves and branches scatter and absorb it. The effect is small and grows with distance in the foliage. Standards give values by frequency band.','It provides a defined excess-attenuation term so the modest screening effect of dense planting can be included in outdoor noise predictions.','For a path passing through 20 m of dense foliage, a technician reads the ISO 9613-2 octave-band values and adds a few decibels of extra attenuation, mainly at higher frequencies.','Outdoor Propagation',ARRAY['Attenuation due to geometrical divergence','Attenuation coefficient','Ground effect','Barrier attenuation','Environmental noise']::text[],ARRAY['Overestimating the effect, since sparse trees give little real attenuation.','Only counting the path length that actually lies within dense foliage.','Assuming foliage blocks low frequencies as well as high ones.']::text[],ARRAY['Assessing a tree belt as a noise screen.','Predicting road noise through a wooded buffer.','Modelling industrial noise across vegetated ground.']::text[],'intermediate',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Attenuation due to foliage');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1958','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1958') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1958');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1959','Attenuation due to geometrical divergence','The reduction in sound pressure level of a point source in free space caused by the spherical spreading of energy over an expanding wavefront, giving 6 dB of loss per doubling of distance, as defined in ISO 9613-2.','Sound from a point spreads out as it travels. The same energy covers a larger surface. So the level drops with distance. Each doubling of distance loses about 6 dB.','It captures the basic geometric spreading loss, the largest and most predictable attenuation term in outdoor propagation.','For a point source, a technician computes divergence at 100 m as 20 lg(100) + 11 = 51 dB, so a source of Lw = 110 dB gives about 59 dB before other losses.','Outdoor Propagation',ARRAY['Point source','Sound power level','Attenuation coefficient','Area source','Inverse square law']::text[],ARRAY['Forgetting the 11 dB constant that accounts for spherical spreading with a 1 m reference.','Applying the point-source 6 dB rule to a line source, which loses only 3 dB per doubling.','Using divergence in the near field of an extended source.']::text[],ARRAY['Predicting a plant''s noise level at a distant receiver.','Estimating loudspeaker level versus distance outdoors.','Setting up a noise-mapping calculation.']::text[],'intermediate','A_div = 20*lg(d/d0) + 11','The divergence attenuation in decibels equals twenty times the base-ten logarithm of the distance divided by the one-metre reference distance, plus eleven decibels.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Attenuation due to geometrical divergence');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1959','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1959') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1959');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1960','Attenuation due to housing','The excess attenuation of outdoor sound caused by propagation through a built-up area of houses, estimated in ISO 9613-2 from the housing density and the path length through the built-up area, subject to an upper limit.','Rows of houses partly block outdoor sound. The sound is reflected and scattered by buildings. This gives extra loss along the path. The effect is capped at a modest value.','It lets the screening effect of intervening housing be included in environmental noise predictions without modelling every building.','For a path crossing a built-up area, a technician applies ISO 9613-2 using the housing density and path length, then caps the housing attenuation at the standard''s limit of about 10 dB.','Outdoor Propagation',ARRAY['Attenuation due to geometrical divergence','Attenuation due to foliage','Attenuation due to industrial sites','Barrier attenuation','Environmental noise']::text[],ARRAY['Letting the housing attenuation exceed the standard''s cap.','Counting reflected energy that may raise levels at some receivers.','Applying housing attenuation where there is a clear line of sight over the roofs.']::text[],ARRAY['Predicting road noise reaching homes behind a first row of houses.','Noise-mapping a residential district.','Assessing industrial noise across a housing estate.']::text[],'advanced','A_hous = 0.1 * B * d_b   (capped at 10 dB)','The first housing-attenuation component in decibels equals zero point one times the housing density factor times the path length through the built-up area, limited to ten decibels; ISO 9613-2 adds a further contribution for well-defined rows of buildings.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Attenuation due to housing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1960','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1960') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1960');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1961','Attenuation due to industrial sites','The excess attenuation of sound propagating through an industrial site containing scattering objects such as pipework, tanks and installations, estimated in ISO 9613-2 as a site-specific value that increases with path length and frequency.','Industrial plant is full of pipes and tanks. These scatter and absorb passing sound. So sound crossing a plant loses extra energy. The amount depends on the specific site.','It accounts for the screening and scattering of dense plant equipment when predicting noise from or across an industrial site.','For a path through a congested process area, a technician applies the ISO 9613-2 site attenuation, typically a few decibels per hundred metres and limited by the standard, based on the equipment density.','Outdoor Propagation',ARRAY['Attenuation due to housing','Attenuation due to foliage','Attenuation due to geometrical divergence','Area source','Environmental noise']::text[],ARRAY['Assuming a fixed value rather than a site-specific estimate.','Ignoring that equipment can also reradiate and raise nearby levels.','Applying site attenuation over open ground with no scattering objects.']::text[],ARRAY['Predicting noise emitted from within a refinery.','Assessing a receiver located across a congested plant.','Noise-mapping a large industrial complex.']::text[],'advanced',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Attenuation due to industrial sites');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1961','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1961') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1961');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1962','Augmented-reality acoustic environment','An acoustic scene in which virtual sound sources are rendered so as to blend with a listener''s real surroundings, matching the room''s acoustics through spatialization, reverberation matching and head tracking so virtual and real sounds appear to share one space.','Augmented reality adds virtual sounds to the real world. The added sound must match the real room. It should echo and locate like a real source. Head tracking keeps it fixed in place.','It makes virtual audio convincing in a real space, so added sounds are localized and coloured consistently with the listener''s actual environment.','A technician measures the room''s reverberation and applies matching reverberation and binaural rendering to a virtual voice, so it sounds like it comes from a real point across the room.','Spatial Audio',ARRAY['Binaural rendering','Head-related transfer function','Room impulse response','Reverberation time','Auralization']::text[],ARRAY['Rendering virtual sound without matching the real room''s reverberation.','Omitting head tracking, so virtual sources drift with head movement.','Confusing augmented audio with fully virtual (replacement) audio.']::text[],ARRAY['Developing spatial audio for AR glasses.','Placing virtual guides in a museum audio tour.','Blending virtual instruments into a real practice room.']::text[],'advanced',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Augmented-reality acoustic environment');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1962','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1962') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1962');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1963','Axial Sensitivity','The sensitivity of a transducer measured along its principal (reference) axis, for a microphone the on-axis output per unit sound pressure at 0 degrees incidence, typically expressed in millivolts per pascal.','A microphone responds most to sound hitting it head-on. Axial sensitivity is that on-axis response. It is given as output volts per unit sound pressure. Off-axis sounds usually give less output.','It defines the reference output of a directional transducer for sound arriving on its main axis, the baseline for calibration and for directivity comparisons.','A technician reads a microphone''s axial sensitivity of 12.5 mV/Pa, so a 1 Pa (94 dB SPL) on-axis tone yields 12.5 mV, which sets the input gain for a known SPL.','Measurement Instrument',ARRAY['Sensitivity','Directivity','Free-field microphone','On-axis response','Polar pattern']::text[],ARRAY['Assuming axial sensitivity applies to sound arriving off-axis.','Confusing open-circuit sensitivity with the loaded output.','Mixing up sensitivity in mV/Pa with the dB re 1 V/Pa figure.']::text[],ARRAY['Calibrating a measurement microphone against a known SPL.','Comparing directional microphones by on-axis output.','Setting preamp gain from a microphone''s rated sensitivity.']::text[],'beginner','S = U / p   (on-axis, 0 degrees)','Axial sensitivity equals the transducer''s output voltage divided by the sound pressure, for sound incident along the reference axis.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Axial Sensitivity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1963','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1963') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1963');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1964','Building acoustics descriptor','A standardized single-number quantity that summarizes a building element''s or space''s acoustic performance, such as the weighted sound reduction index Rw, weighted standardized level difference DnT,w, weighted normalized impact sound level Ln,w, or reverberation time.','Building acoustics uses agreed single numbers to rate rooms and parts. Examples cover sound blocking and impact noise. These descriptors let designs be specified simply. They come from standard rating methods.','It gives designers, regulators and manufacturers a common shorthand for acoustic performance, enabling clear specification and compliance checking.','A technician states a party wall''s performance as DnT,w = 53 dB and a floor''s impact rating as L prime nT,w = 58 dB, drawn from ISO 717 ratings, to demonstrate code compliance.','Sound Insulation',ARRAY['Airborne sound insulation rating','Impact sound insulation','Standardized level difference','Reverberation time','Sound reduction index']::text[],ARRAY['Mixing descriptors from different standards without noting their definitions.','Reporting a descriptor without its subscript, so its basis is unclear.','Assuming one descriptor captures all aspects of acoustic performance.']::text[],ARRAY['Specifying acoustic performance in a building brief.','Checking compliance with a building code''s acoustic clauses.','Comparing products by their published descriptors.']::text[],'intermediate',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Building acoustics descriptor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1964','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1964') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1964');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1965','Clarity index','A room-acoustic parameter, defined in ISO 3382-1, that is the logarithmic ratio of the early to the late arriving sound energy in an impulse response; C80 (80 ms early limit) is used for music and C50 for speech.','Clarity compares early sound to later reverberation. Early sound helps you hear detail. Late sound blurs it. A higher clarity number means clearer, more distinct sound.','It rates how distinct music or speech will sound in a room by weighing useful early energy against blurring late energy.','From an impulse response a technician finds the early energy is twice the late energy, giving C80 = 10 lg(2) = +3 dB, indicating fairly clear conditions for music.','Room Acoustics',ARRAY['Reverberation time','Definition (D50)','Speech transmission index','Room impulse response','Acoustic-response parameterization']::text[],ARRAY['Using the 80 ms limit for speech, where the 50 ms C50 applies.','Reporting a single clarity value instead of frequency-band results.','Assuming high clarity always means good acoustics regardless of use.']::text[],ARRAY['Evaluating a concert hall''s clarity for orchestral music.','Checking a lecture room''s C50 for speech intelligibility.','Comparing clarity before and after acoustic treatment.']::text[],'advanced','C_te = 10*lg( INT_0^te p^2(t) dt / INT_te^inf p^2(t) dt )','The clarity index in decibels equals ten times the base-ten logarithm of the sound energy arriving before the early-time limit divided by the sound energy arriving after it, from the squared impulse response.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Clarity index');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1965','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1965') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1965');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1966','Class of a sound level meter','The performance grade of a sound level meter under IEC 61672-1, where Class 1 has tighter tolerance limits and a wider frequency range than Class 2; both classes share the same design goals but differ in permitted measurement uncertainty.','Sound level meters come in two accuracy grades. Class 1 is more precise than Class 2. Both aim to measure the same thing. Class 1 is used where accuracy matters most.','It tells users the accuracy grade of a meter, so the right instrument is chosen for a task and its uncertainty is known.','For a legal environmental noise assessment a technician selects a Class 1 meter, since regulations often require Class 1 tolerances, and uses a Class 2 meter only for indicative surveys.','Measurement Instrument',ARRAY['Sound level meter','Sound calibrator','A-weighting','Class of a sound calibrator','Measurement uncertainty']::text[],ARRAY['Assuming Class 1 and Class 2 give identical results within their tolerances.','Using a Class 2 meter where regulations require Class 1.','Confusing the old Type 0 to 3 grades with the current Class 1 and 2.']::text[],ARRAY['Choosing a meter for a regulatory noise survey.','Verifying an instrument''s class before a compliance measurement.','Deciding between Class 1 and Class 2 for a workplace check.']::text[],'beginner',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Class of a sound level meter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1966','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1966') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1966');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1967','Concert-hall acoustics','The branch of room acoustics concerned with the design and evaluation of halls for unamplified music, using measured parameters such as reverberation time, early decay time, clarity, strength and lateral energy fraction to relate a hall''s sound field to perceived quality.','This is the study of how concert halls sound. It looks at reverberation, clarity, and spaciousness. Designers use these measures to shape a hall. The aim is rich, clear music without amplification.','It links measurable acoustic parameters to the listening qualities that make a hall good for music, guiding both design and assessment.','A technician measures a hall and reports a mid-frequency reverberation time of 2.0 s, a G of +4 dB and a lateral fraction of 0.2, comparing them with values typical of highly rated halls.','Room Acoustics',ARRAY['Reverberation time','Clarity index','Early decay time','Sound strength (G)','Lateral energy fraction']::text[],ARRAY['Judging a hall on reverberation time alone, ignoring spatial parameters.','Assuming a longer reverberation time is always better.','Applying speech-optimized criteria to a music hall.']::text[],ARRAY['Assessing a new concert hall against reference values.','Diagnosing why a hall sounds muddy or dry.','Advising on variable acoustics for different repertoire.']::text[],'advanced',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Concert-hall acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1967','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1967') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1967');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1968','Contralateral routing of signals','A hearing-aid fitting, abbreviated CROS, in which a microphone on the poorer-hearing ear sends its signal to a receiver on the better-hearing ear, so sounds arriving at the impaired side become audible through the good ear.','Some people hear well in only one ear. A CROS aid uses contralateral routing of signals. It picks up sound at the weak ear. It sends that sound to the good ear. This lets them hear things on their poor side.','It restores awareness of sound arriving on a person''s unaidable side by rerouting it to their functioning ear, improving speech understanding in difficult listening.','An audiologist fits a CROS system for single-sided deafness, placing a microphone on the deaf ear that wirelessly feeds the aid on the hearing ear so the wearer catches speech from their deaf side.','Audiology',ARRAY['BiCROS','Single-sided deafness','Hearing aid','Bone conduction','Head shadow effect']::text[],ARRAY['Confusing CROS with BiCROS, which also amplifies a better ear with mild loss.','Expecting CROS to restore true directional hearing.','Assuming CROS treats hearing loss in the good ear.']::text[],ARRAY['Fitting a client with single-sided deafness.','Comparing CROS with a bone-conduction option.','Counselling a wearer on limits in noisy rooms.']::text[],'intermediate',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Contralateral routing of signals');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1968','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1968') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1968');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1969','Controlled acoustical environment','A space engineered to a known and stable acoustic condition for testing or listening, such as an anechoic chamber (near free-field), a reverberation room (near diffuse-field), or a treated listening room built to a defined standard.','Some rooms are built for precise sound work. An anechoic room removes almost all echoes. A reverberation room spreads sound evenly. Each gives a known, repeatable condition for tests.','It provides defined, repeatable acoustic conditions so measurements of sources, devices and materials are accurate and comparable.','To measure a loudspeaker''s frequency response free of reflections, a technician uses an anechoic chamber; to measure a material''s absorption, a reverberation room per ISO 354 is used.','Measurement Environment',ARRAY['Anechoic chamber','Reverberation room','Free field','Diffuse field','Sound power level']::text[],ARRAY['Assuming an anechoic chamber is anechoic below its cutoff frequency.','Confusing a reverberation room with an ordinary reverberant space.','Treating a merely quiet room as a controlled environment.']::text[],ARRAY['Measuring loudspeaker response in an anechoic chamber.','Determining absorption coefficients in a reverberation room.','Calibrating microphones under free-field conditions.']::text[],'intermediate',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Controlled acoustical environment');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1969','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1969') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1969');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1970','Decibel relative to sound power','The sound power level, a logarithmic measure of a source''s total acoustic power output expressed in decibels relative to the reference sound power of 1 picowatt (10^-12 W), determined by standards such as ISO 3741, 3744 and 3745.','Sound power is the total sound energy a source puts out per second. It is stated in decibels above a tiny reference power. This value describes the source itself. It does not depend on distance or room.','It characterizes a source''s inherent acoustic output independently of the listening position, enabling comparison of sources and prediction of levels at any distance.','For an acoustic power of 0.01 W a technician computes Lw = 10 lg(0.01 / 1e-12) = 100 dB re 1 pW, then uses it to predict sound pressure levels around the source.','Sound Power',ARRAY['Sound power level','Sound pressure level','Sound intensity level','Attenuation due to geometrical divergence','Controlled acoustical environment']::text[],ARRAY['Confusing sound power level with sound pressure level, which depends on distance.','Using the 20 micropascal pressure reference instead of the 1 pW power reference.','Assuming sound power level changes with the measurement room.']::text[],ARRAY['Rating a machine''s noise emission on its data sheet.','Predicting environmental levels from a source''s sound power.','Comparing appliances by declared sound power level.']::text[],'intermediate','L_W = 10*lg(P / P0),  P0 = 1e-12 W','The sound power level in decibels equals ten times the base-ten logarithm of the acoustic power divided by the reference power of one picowatt.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Decibel relative to sound power');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1970','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1970') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1970');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1971','Decision-directed estimation','A recursive method, introduced by Ephraim and Malah, for estimating the a priori signal-to-noise ratio in each frequency bin of a speech enhancement system by combining the previous frame''s estimated clean spectrum with the current frame''s measured ratio.','Noise reduction needs to know the true signal strength per band. Decision-directed estimation guesses it smoothly over time. It blends the last frame''s clean estimate with the current reading. This reduces annoying artifacts.','It yields a smooth, robust a priori SNR estimate that limits the musical-noise artifacts common in spectral noise-reduction algorithms.','In a spectral-subtraction denoiser a technician sets the smoothing factor near 0.98, so the decision-directed estimate leans on past frames and the residual noise sounds smoother.','Signal Processing',ARRAY['A priori SNR','Spectral subtraction','Speech enhancement','Wiener filter','Musical noise']::text[],ARRAY['Setting the smoothing factor too low, which reintroduces musical noise.','Confusing the a priori SNR with the directly measured a posteriori SNR.','Assuming it removes noise perfectly rather than trading off distortion.']::text[],ARRAY['Tuning a noise-reduction stage in a speech codec.','Reducing background noise in a hearing device.','Improving voice capture for a conferencing system.']::text[],'advanced','xi_hat(k,l) = alpha * |S_hat(k,l-1)|^2 / lambda_d(k,l-1) + (1-alpha) * max(gamma(k,l)-1, 0)','The estimated a priori signal-to-noise ratio in a frequency bin is a weighted sum: a smoothing factor times the previous frame''s estimated clean power over the noise power, plus one minus that factor times the current measured ratio minus one, floored at zero.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Decision-directed estimation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1971','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1971') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1971');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1972','Deterministic-plus-stochastic model','A signal model, central to spectral modelling synthesis, that splits a sound into a deterministic part made of slowly varying sinusoids and a stochastic (residual) part treated as filtered noise. The sinusoids capture stable, pitched partials while the residual captures breath, bow or transient noise left after the sinusoids are removed.','This method splits a sound into two parts. One part is clear, steady tones. The other part is the leftover noise, like breath or hiss. Storing them separately lets you reshape a sound cleanly.','It lets a system analyse, compress, and re-synthesise complex sounds by handling tonal and noisy energy with separate, efficient representations.','In an analysis, you track sinusoid amplitudes and frequencies, subtract them from the sound, then model whatever noise remains; for a flute note the partials become sinusoids and the airy hiss becomes the stochastic residual.','Signal modelling',ARRAY['Geometric acoustics','Perceptual noise substitution','Octave-band analysis','Envelopment']::text[],ARRAY['Assuming the residual is pure random noise rather than a shaped, time-varying spectrum.','Forgetting that poor sinusoid tracking leaves tonal energy in the noise part.','Believing the split is unique when it depends on analysis settings.']::text[],ARRAY['Building a flexible synthesiser that can stretch a sound without altering its pitch.','Separating pitched and noisy content for morphing between instruments.','Compressing a sustained instrument tone for a sampler.']::text[],'advanced','s(t) = Sum_r A_r(t) cos(theta_r(t)) + e(t)','The sound equals a sum of time-varying sinusoids plus a residual noise signal.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Deterministic-plus-stochastic model');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1972','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1972') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1972');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1973','Diagnostic Rhyme Test','A closed-response speech intelligibility test in which a listener hears one spoken word and chooses between two printed rhyming words that differ only in their initial consonant, such as ''veal'' versus ''feel''. The word pairs are arranged to probe specific distinctive phonetic features, and scores are corrected for guessing.','A listener hears one word through a system. They pick it from two look-alike words that start differently. The score shows how clearly speech comes through. It tests exact consonant sounds.','It gives a repeatable, feature-based score of how well a communication channel or codec preserves consonant information in speech.','You play the test list over the system under test, tally right and wrong picks, and correct for chance; with 30 correct and 6 wrong out of 36 the score is (30 - 6)/36 x 100, about 67 percent.','Speech intelligibility',ARRAY['Double-blind triple-stimulus test','Octave-band analysis','Weighting network']::text[],ARRAY['Reporting raw percent correct without the guessing correction.','Confusing it with open-response tests where listeners write any word.','Assuming a high score proves natural-sounding speech rather than just intelligible consonants.']::text[],ARRAY['Comparing low-bit-rate voice codecs for a radio system.','Checking intelligibility of a public-address system in noise.','Rating a speech-enhancement algorithm.']::text[],'intermediate','S = ((R - W) / N) x 100','The score is the number correct minus the number wrong, divided by the total items, as a percentage.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Diagnostic Rhyme Test');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1973','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1973') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1973');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1974','Diffuse-field sensitivity','The sensitivity of a measurement microphone to sound in a diffuse (random-incidence) field, where waves arrive with equal probability from all directions and random phase. It equals the pressure sensitivity multiplied by the microphone''s diffuse-field response, and is the relevant sensitivity when measuring reverberant or random-incidence sound.','This is how strongly a microphone responds to sound that comes from every direction at once. It matters in reverberant rooms. A microphone tuned this way stays flat for scattered sound. It differs from the on-axis rating.','It tells the technician the correct sensitivity to use when a microphone measures a sound field arriving from all directions rather than one axis.','When measuring sound in a reverberation room you apply the diffuse-field sensitivity; a microphone rated 50 mV/Pa with a small diffuse-field correction at high frequencies gives the true reverberant level.','Microphone metrology',ARRAY['Free-field sensitivity','Random-incidence response','Free-field correction','Equivalent sound absorption area']::text[],ARRAY['Using free-field sensitivity to measure diffuse reverberant sound.','Ignoring the frequency-dependent diffuse-field correction at high frequencies.','Assuming a free-field microphone is optimal for random-incidence work.']::text[],ARRAY['Measuring reverberation-room absorption per standard method.','Calibrating a microphone for building-acoustics field tests.','Selecting a random-incidence microphone for sound power work.']::text[],'advanced','M_d(f) = M_p(f) x H_d(f)','Diffuse-field sensitivity equals pressure sensitivity times the diffuse-field response of the microphone.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Diffuse-field sensitivity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1974','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1974') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1974');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1975','Distance attenuation model','An engineering model that predicts how outdoor sound level falls with distance from a source, summing geometrical divergence with added attenuation from air absorption, ground effect, barriers and meteorology. In ISO 9613-2 the receiver level equals the source sound power plus directivity minus the total attenuation.','This model predicts how quiet a source becomes far away outdoors. Sound spreads out and also loses energy to the air and ground. Adding these effects gives the level at a listener. It is used for noise maps.','It lets engineers estimate noise at homes or property lines from a plant, road or machine before it is built.','For a point source of 100 dB sound power at 100 m, geometrical divergence alone is 20 log(100) + 11 = 51 dB, giving about 49 dB before adding air and ground terms.','Environmental noise',ARRAY['Divergence loss','Excess attenuation','Distortion product otoacoustic emission','Weighting network']::text[],ARRAY['Using the 6 dB per doubling rule for line sources, which lose only 3 dB per doubling.','Ignoring ground and meteorological effects over long distances.','Confusing sound power level with sound pressure level at the source.']::text[],ARRAY['Predicting industrial noise at a nearby residence.','Producing a strategic noise map for a road scheme.','Checking whether a plant meets a night-time limit at the boundary.']::text[],'advanced','L_p = L_w + D_c - A ,  A_div = 20 log10(d/d0) + 11','Receiver level equals source power level plus directivity minus total attenuation, where the divergence term is twenty log of distance over one metre plus eleven decibels.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Distance attenuation model');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1975','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1975') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1975');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1976','Distortion product otoacoustic emission','A low-level sound generated by the healthy cochlea''s outer hair cells when the ear is stimulated by two simultaneous pure tones of frequencies f1 and f2, producing measurable emissions at intermodulation frequencies. The most prominent product occurs at 2f1 minus f2 and is recorded with a sensitive probe in the ear canal.','The inner ear can make its own faint sounds. Play two tones into a healthy ear and it produces extra tones. A tiny microphone in the ear canal picks them up. Their presence shows the hair cells work.','It provides an objective, frequency-specific check of outer hair cell function used in hearing screening and diagnosis.','A technician presents f1 and f2 with a fixed ratio near 1.22 and looks for a response at 2f1 minus f2; with f1 = 2000 Hz and f2 = 2400 Hz the emission appears at 1600 Hz.','Audiology',ARRAY['Otoacoustic emission','Distance attenuation model','Diffuse-field sensitivity']::text[],ARRAY['Treating a present emission as a full hearing test rather than a hair-cell check.','Confusing the 2f1 minus f2 product with the simple difference tone f2 minus f1.','Ignoring noisy probe fit that hides the small response.']::text[],ARRAY['Newborn hearing screening in a clinic.','Monitoring for early noise or drug damage to the cochlea.','Cross-checking a suspected non-organic hearing loss.']::text[],'advanced','f_dp = 2 f1 - f2','The main distortion product frequency equals twice the lower tone minus the higher tone.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Distortion product otoacoustic emission');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1976','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1976') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1976');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1977','Divergence loss','The reduction in sound pressure level caused purely by the geometric spreading of a wavefront over an expanding area as it travels from the source. For a point source radiating spherically in a free field, the level drops by about 6 dB for each doubling of distance.','As sound travels out, it spreads over a bigger area. That spreading alone makes it quieter. For a small source, doubling the distance drops the level by six decibels. This happens before any absorption.','It quantifies the unavoidable level drop from spreading, forming the baseline of any outdoor or free-field propagation estimate.','Moving from 2 m to 8 m from a small source is two doublings, so divergence loss is 20 log(8/2) = 12 dB; a 94 dB level at 2 m becomes about 82 dB at 8 m.','Sound propagation',ARRAY['Distance attenuation model','Excess attenuation','Loudspeaker sensitivity']::text[],ARRAY['Applying the 6 dB rule to line sources, which spread cylindrically at 3 dB per doubling.','Adding divergence loss twice when a level is already referenced to a distance.','Assuming it applies inside a reverberant room''s diffuse field.']::text[],ARRAY['Estimating level drop between two positions in a field.','Setting reference distances for loudspeaker sensitivity ratings.','Sanity-checking a propagation calculation.']::text[],'beginner','Delta L = 20 log10(r2 / r1)','The divergence loss equals twenty times the log of the far distance divided by the near distance.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Divergence loss');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1977','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1977') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1977');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1978','Double-blind triple-stimulus test','A subjective listening method for assessing small impairments in audio, standardised in ITU-R BS.1116, in which the listener is presented three stimuli: an open reference ''A'' and two hidden versions ''B'' and ''C'', one of which is the reference and one the system under test. Neither listener nor operator knows the coding, and impairments are graded on a five-grade continuous impairment scale.','A listener hears three clips. The first is the known original. One of the other two is the original again, hidden. The listener must find the changed one and rate how bad the change is. Nobody in the room knows which is which.','It gives statistically robust, bias-free ratings of very small audio quality differences, such as those from high-quality codecs.','The listener grades the impaired stimulus from 5.0 (imperceptible) down to 1.0 (very annoying); scoring the hidden reference lower than the test signal flags an unreliable listener whose data may be excluded.','Listening test',ARRAY['Diagnostic Rhyme Test','Perceptual noise substitution','Envelopment']::text[],ARRAY['Confusing it with MUSHRA, which targets larger impairments with an anchor.','Skipping the hidden-reference check used to screen unreliable listeners.','Letting the operator see the labels, breaking the double-blind condition.']::text[],ARRAY['Evaluating a new perceptual audio codec near transparency.','Certifying a broadcast processing chain for small artefacts.','Comparing loudspeaker or headphone rendering of fine detail.']::text[],'advanced','SDG = Grade_test - Grade_reference','The subjective difference grade equals the grade given to the test signal minus the grade given to the hidden reference.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Double-blind triple-stimulus test');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1978','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1978') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1978');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1979','Envelopment','The listener''s perception of being surrounded or immersed in reverberant sound, a spatial attribute of concert-hall acoustics distinct from the perceived width of the source. It is associated in ISO 3382-1 with strong late-arriving sound energy reaching the listener from lateral directions.','This is the feeling of being wrapped in sound. In a good hall, reverberation seems to come from all around you. It is separate from how wide the stage sounds. Late side reflections create it.','It captures a key quality that makes a concert hall feel spacious and immersive, guiding acoustic design and evaluation.','To increase envelopment a designer boosts late lateral reflections, for example with side-wall geometry; measured late lateral sound level correlates with how enveloping listeners judge the seat.','Room acoustics',ARRAY['Late lateral energy','Lateral gain','Lateral energy fraction','Lateralization']::text[],ARRAY['Confusing envelopment with apparent source width, which comes from early lateral energy.','Assuming loud overall reverberation guarantees good envelopment regardless of direction.','Ignoring that mainly late, not early, lateral energy drives it.']::text[],ARRAY['Judging the immersive quality of a concert-hall seat.','Designing side-wall reflections to improve spaciousness.','Evaluating a surround-sound reproduction''s sense of space.']::text[],'intermediate',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Envelopment');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1979','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1979') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1979');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1980','Equivalent sound absorption area','The area of a perfectly absorbing surface that would remove the same amount of sound energy as all the absorption present in a room, expressed in square metres and often called simply the room''s absorption ''A''. It equals the sum over all surfaces of area times absorption coefficient, and can be found from the measured reverberation time.','This is the total soaking power of a room, given as an area. It combines every surface and object that absorbs sound. A bigger value means a deader room. You can get it from the reverberation time.','It provides a single figure for a room''s total absorption, used in reverberation, sound insulation and sound power calculations.','For a 300 cubic metre room with a measured reverberation time of 0.8 s, the absorption is A = 0.161 x 300 / 0.8, about 60 square metres of equivalent absorption.','Room acoustics',ARRAY['Sabine absorption','Sound reduction index','Diffuse-field sensitivity','Schroeder integration']::text[],ARRAY['Confusing the absorption area in square metres with a plain absorption coefficient.','Forgetting to include air absorption and audience or furnishings.','Mixing metric 0.161 with the imperial 0.049 constant.']::text[],ARRAY['Sizing absorption to hit a target reverberation time.','Correcting a reverberation-room absorption measurement.','Computing the receiving-room term in a sound insulation test.']::text[],'intermediate','A = Sum_i S_i alpha_i = 0.161 V / T','The equivalent absorption area is the sum of each surface area times its absorption coefficient, and equals 0.161 times room volume divided by reverberation time.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Equivalent sound absorption area');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1980','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1980') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1980');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1981','Excess attenuation','The extra loss of outdoor sound, beyond simple geometrical spreading, caused by air absorption, ground reflection, barriers, foliage and weather. In propagation models it is the sum of all attenuation terms that remain after the divergence term is removed.','Sound outdoors loses energy for reasons beyond just spreading out. Air, ground, walls and wind all take extra energy. That extra loss is the excess attenuation. It changes with weather and terrain.','It accounts for the real-world propagation effects that make outdoor noise predictions differ from ideal free-field spreading.','If total measured loss to a receiver is 60 dB and geometrical divergence accounts for 51 dB, the excess attenuation from air, ground and barriers is 9 dB.','Environmental noise',ARRAY['Distance attenuation model','Divergence loss','Sound reduction index']::text[],ARRAY['Assuming excess attenuation is constant when it varies with wind and temperature gradients.','Double-counting ground effect and barrier loss when both act on the same path.','Neglecting that downwind conditions can turn attenuation into slight enhancement.']::text[],ARRAY['Refining a noise prediction over soft ground.','Assessing a barrier''s real benefit in wind.','Explaining why a distant source sounds louder at night.']::text[],'advanced','A_e = A_atm + A_gr + A_bar + A_misc = A_total - A_div','Excess attenuation is the sum of the air, ground, barrier and miscellaneous terms, equal to total attenuation minus geometrical divergence.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Excess attenuation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1981','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1981') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1981');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1982','Finite-difference time-domain acoustics','A wave-based numerical method that simulates sound by discretising the acoustic wave equation onto a spatial grid and stepping the pressure and velocity fields forward in small time increments. It models diffraction and interference directly, but stability requires the time step to satisfy a Courant condition tied to the grid spacing and sound speed.','This computer method solves the wave equation on a grid of points. It updates the sound field one tiny time step at a time. It captures bending and interference of waves. The time step must be small enough or the maths blows up.','It predicts detailed low-frequency room and device behaviour where wave effects like modes and diffraction dominate and ray methods fail.','You pick a grid fine enough for the highest frequency, then set the time step below the Courant limit; in three dimensions with 1 cm spacing and c = 343 m/s the step must be under about 0.01/(343 x sqrt(3)) = 17 microseconds.','Computational acoustics',ARRAY['Geometric acoustics','Deterministic-plus-stochastic model','Sabine absorption']::text[],ARRAY['Choosing too large a time step and violating the stability condition.','Using too coarse a grid, which causes numerical dispersion errors at high frequency.','Applying it to whole large halls where ray methods are far cheaper.']::text[],ARRAY['Modelling low-frequency modes in a control room.','Simulating diffraction around a barrier or loudspeaker cabinet.','Auralising a small, acoustically complex space.']::text[],'advanced','Delta t <= Delta x / (c sqrt(D))','The time step must be at most the grid spacing divided by the sound speed times the square root of the number of dimensions.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Finite-difference time-domain acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1982','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1982') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1982');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1983','Free-field correction','A frequency-dependent adjustment applied to a measurement microphone or sound level meter so that its indicated level equals the free-field sound pressure that existed before the instrument was introduced. It compensates for the pressure build-up and diffraction the microphone body itself causes, mainly at high frequencies.','A microphone changes the sound field around it. This correction cancels that effect. It makes the reading match the true undisturbed sound. It mostly matters at high frequencies where the body reflects sound.','It ensures a microphone reports the real free-field level rather than the disturbed level at its own diaphragm.','A pressure microphone facing a source may read a few decibels high at 10 kHz; applying the manufacturer''s free-field correction, for example minus 2 dB there, restores the true level.','Microphone metrology',ARRAY['Free-field sensitivity','Diffuse-field sensitivity','Random-incidence response','Weighting network']::text[],ARRAY['Omitting the correction and reporting a high-frequency level that is too high.','Applying a free-field correction to a diffuse-field measurement.','Assuming the correction is negligible for all microphone sizes.']::text[],ARRAY['Calibrating a class 1 sound level meter for free-field use.','Correcting loudspeaker response measured with a pressure microphone.','Meeting the free-field response tolerances of an instrument standard.']::text[],'advanced','L_free = L_ind + C_f(f)','The free-field level equals the indicated level plus the frequency-dependent free-field correction.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Free-field correction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1983','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1983') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1983');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1984','Free-field sensitivity','The output voltage a microphone produces per unit of free-field sound pressure for a plane wave arriving from a specified direction, usually head-on, expressed in millivolts per pascal or in decibels relative to 1 V/Pa. It refers to the undisturbed sound pressure that existed before the microphone was placed in the field.','This is how much voltage a microphone gives for a set sound pressure in open air. The sound arrives as a flat wave from the front. It is quoted in millivolts per pascal. It assumes no reflecting surfaces nearby.','It defines a microphone''s calibrated output for open-air, on-axis measurements, the basis for turning voltage back into sound level.','A microphone rated 50 mV/Pa in a 1 Pa (94 dB) free field outputs 50 mV; reading 5 mV therefore corresponds to 0.1 Pa, or 74 dB SPL.','Microphone metrology',ARRAY['Free-field correction','Diffuse-field sensitivity','Random-incidence response','Loudspeaker sensitivity']::text[],ARRAY['Confusing free-field sensitivity with pressure sensitivity at a boundary.','Ignoring the stated reference direction, usually zero degrees.','Mixing mV/Pa values with dB re 1 V/Pa without converting.']::text[],ARRAY['Converting a measured voltage to sound pressure level.','Selecting a microphone for anechoic loudspeaker tests.','Comparing microphone models on a data sheet.']::text[],'intermediate','M_f = U / p ;  L_M = 20 log10(M_f / M_ref)','Free-field sensitivity is the output voltage divided by the free-field sound pressure, and its level is twenty log of that value over the one-volt-per-pascal reference.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Free-field sensitivity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1984','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1984') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1984');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1985','Geometric acoustics','A high-frequency approximation that treats sound as rays travelling in straight lines, reflecting off surfaces like light, and ignoring wave effects such as diffraction. It underlies image-source and ray-tracing room models and is valid when wavelengths are small compared with room and surface dimensions.','This treats sound like beams of light. Rays bounce off walls in straight lines. It ignores how waves bend around edges. It works best for high frequencies in large rooms.','It provides a fast, intuitive way to model reflections and reverberation in rooms large relative to the wavelength.','In an auralisation you trace rays from a source, count reflections and their delays, and build an impulse response; it stays accurate above the Schroeder frequency but fails for low-frequency modes.','Computational acoustics',ARRAY['Finite-difference time-domain acoustics','Sabine absorption','Late lateral energy','Deterministic-plus-stochastic model']::text[],ARRAY['Applying it at low frequencies where diffraction and modes dominate.','Forgetting that it omits edge diffraction unless added separately.','Assuming ray counts alone give accurate absorption without proper coefficients.']::text[],ARRAY['Predicting reverberation and reflections in a concert hall model.','Designing early-reflection control in a studio.','Auralising a large sports venue.']::text[],'intermediate',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Geometric acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1985','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1985') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1985');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1986','Late lateral energy','The portion of a room impulse response arriving from lateral (sideways) directions later than about 80 ms after the direct sound, captured with a figure-of-eight microphone oriented so its null faces the source. In ISO 3382-1 it is the physical basis of listener envelopment and is quantified by the late lateral sound level.','This is the late sound that reaches you from the sides. It comes after the first strong echoes. A side-facing mic picks it up. Strong late side sound makes a room feel wrapped around you.','It provides the measurable acoustic quantity that predicts how enveloping and spacious a room feels to a listener.','You integrate the squared lateral impulse response from 80 ms onward and reference it to the free-field level at 10 m to get the late lateral sound level; higher values mean stronger envelopment.','Room acoustics',ARRAY['Lateral gain','Lateral energy fraction','Envelopment','Schroeder integration']::text[],ARRAY['Confusing late lateral energy with early lateral energy, which sets source width.','Aligning the figure-of-eight microphone incorrectly relative to the source.','Using an omnidirectional microphone, which cannot separate lateral direction.']::text[],ARRAY['Measuring envelopment in a concert hall.','Comparing seats for spatial impression.','Validating a room model''s late spatial response.']::text[],'advanced','L_J = 10 log10( Integral_{80ms}^{inf} p_L^2(t) dt / Integral p_10^2(t) dt )','The late lateral sound level is ten log of the late lateral squared pressure integrated from 80 milliseconds, divided by the free-field squared pressure at 10 metres.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Late lateral energy');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1986','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1986') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1986');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1987','Lateral energy fraction','An ISO 3382-1 spatial parameter equal to the ratio of early laterally arriving sound energy to the total early sound energy, both measured within the first 80 ms of the room impulse response. The lateral energy is captured with a figure-of-eight microphone (5 to 80 ms) and the total with an omnidirectional microphone (0 to 80 ms), and it predicts apparent source width.','This compares early side reflections with all early sound. A figure-of-eight microphone catches the side energy. An omni microphone catches the total. A higher fraction makes the sound source seem wider.','It gives a single measurable number for how much early lateral reflection a seat receives, linked to the perceived broadening of the source.','If the early lateral energy is 0.2 and the total early energy is 0.8 in consistent units, the lateral energy fraction is 0.25, a value typical of a good wide-sounding hall seat.','Room acoustics',ARRAY['Late lateral energy','Lateral gain','Envelopment','Schroeder integration']::text[],ARRAY['Confusing it with late lateral energy, which drives envelopment not width.','Starting the lateral integration at 0 ms instead of 5 ms.','Using the wrong microphone pattern for either the lateral or total term.']::text[],ARRAY['Rating apparent source width across concert-hall seats.','Tuning early side-wall reflections in a hall design.','Benchmarking a measured hall against ISO target ranges.']::text[],'advanced','J_LF = Integral_{5ms}^{80ms} p_L^2(t) dt / Integral_{0}^{80ms} p^2(t) dt','The lateral energy fraction is the lateral squared pressure from 5 to 80 milliseconds divided by the total squared pressure from 0 to 80 milliseconds.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Lateral energy fraction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1987','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1987') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1987');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1988','Lateral gain','A strength-type room-acoustic measure, also called the late lateral sound level, giving the level of late laterally arriving sound relative to the free-field level of the same source at 10 m. It rises with stronger late side energy and serves as an objective predictor of listener envelopment.','This measures how loud the late side reflections are in a room. It compares them to the source heard at ten metres in open air. A higher value means a more enveloping seat. It focuses on late, side-arriving sound.','It turns late lateral energy into a calibrated level in decibels that can be compared between seats and halls.','If the late lateral energy integrates to 15 dB below the 10 m free-field reference, the lateral gain is minus 15 dB; comparing seats, the higher (less negative) value is the more enveloping one.','Room acoustics',ARRAY['Late lateral energy','Envelopment','Lateral energy fraction','Equivalent sound absorption area']::text[],ARRAY['Treating it as identical to the unitless lateral energy fraction.','Forgetting the 10 m free-field reference that calibrates the level.','Assuming louder overall sound raises lateral gain regardless of direction.']::text[],ARRAY['Ranking concert-hall seats by envelopment.','Quantifying the effect of adding side reflectors.','Reporting spatial results alongside reverberation time.']::text[],'advanced','G_LL = 10 log10( Integral_{80ms}^{inf} p_L^2(t) dt / Integral p_10^2(t) dt )','The lateral gain is ten log of the late lateral squared pressure from 80 milliseconds onward divided by the free-field squared pressure at 10 metres.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Lateral gain');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1988','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1988') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1988');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1989','Lateralization','In psychoacoustics, the perception of a sound image''s position along the interaural axis inside the head, produced when sound is delivered by headphones. It is governed mainly by interaural time and level differences, and is distinguished from localization, which places sound at an external point in space.','With headphones, a sound can seem to sit inside your head. Its left-right position is called lateralization. Timing and loudness differences between the ears move it. It differs from hearing a sound out in the room.','It describes and quantifies where a headphone-delivered sound image appears between the ears, a core tool for studying binaural hearing.','Delaying the signal to one ear by a few hundred microseconds shifts the image toward the leading ear; about 0.6 ms of interaural delay pulls the image fully to that side.','Binaural hearing',ARRAY['Envelopment','Late lateral energy','Stimulus-onset asynchrony']::text[],ARRAY['Using lateralization and localization interchangeably.','Assuming level differences alone control the image, ignoring timing.','Expecting headphone images to appear outside the head without special processing.']::text[],ARRAY['Measuring interaural time-difference sensitivity in a lab.','Panning a mono source in headphone monitoring.','Studying binaural cues for hearing research.']::text[],'intermediate',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Lateralization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1989','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1989') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1989');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1990','Loudspeaker sensitivity','A rating of how loud a loudspeaker plays for a given electrical input, stated as the sound pressure level measured on-axis at 1 m for a standard drive, commonly 2.83 V or 1 W. It is expressed in decibels SPL and lets a technician predict output level and required amplifier power.','This tells how loud a speaker gets for a set input. It is measured one metre in front for a standard signal. A higher number means more volume per watt. It helps size the amplifier.','It allows comparison of loudspeaker efficiency and calculation of the amplifier power needed for a target level.','A speaker rated 88 dB at 2.83 V/1 m gains 3 dB per doubling of power, so 10 W (about 10 dB up) gives roughly 98 dB at 1 m, before adding distance losses.','Loudspeaker specifications',ARRAY['Free-field sensitivity','Divergence loss','Weighting network']::text[],ARRAY['Comparing a 2.83 V rating to a 1 W rating without noting the impedance.','Ignoring the measurement bandwidth and averaging method behind the figure.','Assuming a higher sensitivity always means better sound quality.']::text[],ARRAY['Choosing an amplifier to hit a target level at a distance.','Comparing two loudspeakers for a fixed install.','Estimating maximum SPL from sensitivity and power handling.']::text[],'intermediate','L_p(P) = L_sens + 10 log10(P / P_ref)','The on-axis level at one metre equals the rated sensitivity plus ten log of the applied power over the reference power.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Loudspeaker sensitivity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1990','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1990') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1990');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1991','Octave-band analysis','A method of frequency analysis that divides the audio spectrum into contiguous bands each one octave wide, or a fraction such as one-third octave, with standardised centre frequencies. Per IEC 61260 the upper edge of each octave band is twice the lower edge, and the centre is their geometric mean.','This splits sound into frequency bands. Each octave band is twice as wide as the one below in frequency. The bands have fixed standard centres like 1 kHz. It shows how energy spreads across pitch.','It gives a compact, standardised picture of how sound energy is distributed with frequency, matching how hearing groups pitch.','Measuring room noise you read the level in each octave band; the 1000 Hz octave spans about 707 to 1414 Hz, since the edges are 1000 divided and multiplied by the square root of two.','Signal analysis',ARRAY['Weighting network','Free-field correction','Sabine absorption','Sound reduction index']::text[],ARRAY['Confusing octave bands with equal-width linear bands.','Mixing one-octave and one-third-octave results on the same chart.','Assuming band levels can be added arithmetically instead of on an energy basis.']::text[],ARRAY['Assessing room noise against a noise-rating curve.','Setting a graphic equaliser by band.','Reporting absorption or transmission per frequency band.']::text[],'beginner','f_u = 2 f_l ,  f_c = sqrt(f_l f_u)','The upper band edge is twice the lower edge, and the centre frequency is the square root of the product of the two edges.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Octave-band analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1991','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1991') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1991');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1992','Open-plan office acoustics','The study and measurement of speech propagation and privacy in offices without full-height partitions, standardised in ISO 3382-3. Key single-number descriptors include the spatial decay rate of speech D2,S, the A-weighted speech level at 4 m, and the distraction distance where speech intelligibility falls to a set threshold.','This covers how speech travels across an open office. It measures how fast talk fades with distance. It also finds how far away a voice stops being distracting. Good design lowers speech that carries.','It provides objective metrics to judge whether an open office controls distracting speech and offers acceptable speech privacy.','You measure speech level versus distance and fit the spatial decay rate D2,S in dB per distance doubling; the distraction distance rD is where the speech transmission index drops to 0.50, and larger D2,S with smaller rD is better.','Building acoustics',ARRAY['Sound reduction index','Equivalent sound absorption area','Diagnostic Rhyme Test','Octave-band analysis']::text[],ARRAY['Assuming a quiet room automatically means good speech privacy.','Reporting only overall level and skipping the spatial decay rate.','Confusing distraction distance with privacy distance thresholds.']::text[],ARRAY['Assessing speech privacy in a new open-plan fit-out.','Specifying screens and sound masking to raise the decay rate.','Comparing two office layouts against ISO 3382-3 metrics.']::text[],'advanced','D2,S = slope of L_p,A,S versus log2(r)','The spatial decay rate of speech is the drop in A-weighted speech level per doubling of distance from the speaker.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Open-plan office acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1992','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1992') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1992');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1993','Otoacoustic emission','A faint sound generated within the cochlea by the active motion of the outer hair cells and measurable with a sensitive microphone sealed in the ear canal. Emissions may be spontaneous or evoked by clicks or tone pairs, and their presence indicates functioning cochlear amplification.','The inner ear can produce its own quiet sounds. A sealed probe in the ear canal records them. They may appear on their own or after a test sound. Their presence shows the hair cells are working.','It offers a quick, objective, non-invasive way to check cochlear outer hair cell function, widely used for hearing screening.','In newborn screening a probe plays clicks and records the transient emission; a clear response passes the ear, while no response flags it for full diagnostic follow-up.','Audiology',ARRAY['Distortion product otoacoustic emission','Diffuse-field sensitivity','Free-field sensitivity']::text[],ARRAY['Treating a pass as a complete measure of hearing thresholds.','Blaming a genuine absent emission on probe noise without rechecking fit.','Confusing evoked emissions with spontaneous ones.']::text[],ARRAY['Universal newborn hearing screening.','Monitoring cochlear health during ototoxic drug therapy.','Screening workers for early noise damage.']::text[],'intermediate',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Otoacoustic emission');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1993','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1993') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1993');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1994','Perceptual noise substitution','A coding tool in MPEG-4 Advanced Audio Coding that identifies spectral regions perceived as noise and, instead of transmitting their detailed coefficients, sends only the band''s total energy so the decoder regenerates equivalent random noise. Standardised in ISO/IEC 14496-3, it saves bits on noise-like content while preserving the perceived sound.','In audio compression, some sounds are just noise-like. Coding every detail of that noise wastes data. Instead the coder sends only how loud the noise band is. The player then makes fresh noise at that level.','It cuts the bit rate needed for noise-like signal parts by replacing exact data with a parametric noise description.','For a cymbal wash the encoder flags a high band as noise and sends its energy; the decoder fills that band with matched random noise, using far fewer bits than coding the spectrum directly.','Audio coding',ARRAY['Deterministic-plus-stochastic model','Double-blind triple-stimulus test','Octave-band analysis']::text[],ARRAY['Assuming the original noise waveform is reproduced rather than a statistical match.','Applying it to tonal content, which would sound wrong.','Confusing it with spectral band replication, a different high-frequency tool.']::text[],ARRAY['Encoding music at low bit rates with AAC.','Explaining why noisy passages compress efficiently.','Debugging odd texture on noise-like sounds after coding.']::text[],'advanced',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Perceptual noise substitution');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1994','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1994') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1994');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1995','Random-incidence response','The frequency response of a microphone to sound arriving simultaneously from all directions with random phase, as in a diffuse field. A random-incidence microphone is designed so this response stays flat, making it suited to measuring reverberant sound and community or environmental noise.','This describes how a microphone reacts to sound coming from every direction at once. A random-incidence type stays flat under those conditions. It suits reverberant rooms and outdoor noise. It differs from a front-facing rating.','It characterises how a microphone performs in a diffuse sound field, guiding correct microphone choice for reverberant and environmental measurements.','For a community noise survey where sound reflects from many surfaces, you pick a random-incidence microphone so the reading does not depend on which way the meter points.','Microphone metrology',ARRAY['Diffuse-field sensitivity','Free-field correction','Free-field sensitivity','Weighting network']::text[],ARRAY['Using a free-field microphone for diffuse-field measurements and reading high at treble.','Assuming the pattern matters little because levels are averaged.','Confusing random-incidence with a simple omnidirectional pattern at low frequency.']::text[],ARRAY['Measuring reverberant room sound levels.','Conducting a community or environmental noise survey.','Selecting a microphone corrector for a class 1 meter.']::text[],'advanced',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Random-incidence response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1995','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1995') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1995');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1996','Sabine absorption','The absorption of a room as described by Sabine''s reverberation formula, which relates reverberation time to room volume and total equivalent absorption area assuming a perfectly diffuse field. The Sabine absorption coefficient is the value derived by measuring reverberation time in a reverberation room.','This links how long sound lingers to how much a room soaks up. Bigger rooms echo longer. More absorption makes them echo less. Sabine''s equation ties these together. Measuring the echo time gives the absorption.','It provides the classic relationship used to predict reverberation time and to rate materials for their sound-absorbing power.','For a 500 cubic metre studio with 80 square metres of equivalent absorption, Sabine''s formula gives T = 0.161 x 500 / 80, about 1.0 s reverberation time.','Room acoustics',ARRAY['Equivalent sound absorption area','Schroeder integration','Geometric acoustics','Sound reduction index']::text[],ARRAY['Using Sabine at high absorption, where Eyring''s formula is more accurate.','Assuming a perfectly diffuse field in a very absorptive or oddly shaped room.','Reporting Sabine coefficients above 1.0 as errors when edge effects can cause them.']::text[],ARRAY['Predicting reverberation time from planned absorption.','Rating an absorber in a reverberation room test.','Estimating how much treatment a room needs.']::text[],'intermediate','T = 0.161 V / A','The reverberation time equals 0.161 times the room volume divided by the total equivalent absorption area.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sabine absorption');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1996','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1996') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1996');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1997','Schroeder integration','A method of obtaining a smooth energy decay curve from a single room impulse response by integrating the squared impulse response backward in time from its end. Introduced by Schroeder, it removes the fluctuations of raw squared responses and is the basis for estimating reverberation time in ISO 3382.','This turns one recorded impulse into a smooth decay curve. It adds up the sound energy from the end backward. The result is clean enough to measure how fast the room fades. It avoids the noisy wiggles of a raw trace.','It yields a repeatable, low-noise decay curve so reverberation time and related decay measures can be read reliably from a single measurement.','You square the impulse response, integrate from the tail toward the start, plot the curve in decibels, and fit a straight line over the decay range, for example minus 5 to minus 35 dB, to get T30.','Room acoustics',ARRAY['Sabine absorption','Equivalent sound absorption area','Late lateral energy','Lateral energy fraction']::text[],ARRAY['Integrating from the start forward instead of backward from the end.','Including too much background noise in the tail, which curves the decay.','Fitting the reverberation slope over the wrong decibel range.']::text[],ARRAY['Deriving reverberation time from an impulse-response measurement.','Cleaning up decay curves in room-acoustics software.','Estimating early decay time and clarity from one measurement.']::text[],'advanced','E(t) = Integral_{t}^{inf} p^2(tau) d tau','The decay energy at a time is the integral of the squared impulse response from that time to the end.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Schroeder integration');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1997','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1997') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1997');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1998','Sound reduction index','A laboratory measure of the airborne sound insulation of a building element, equal to ten times the log of the ratio of incident to transmitted sound power. It is determined from the level difference between source and receiving rooms with a correction for the receiving room''s absorption and the specimen area, per ISO 10140-2.','This rates how well a wall or floor blocks airborne sound. A higher number blocks more. It comes from comparing loud and quiet room levels. A room-absorption correction keeps it fair.','It quantifies a partition''s ability to stop airborne sound so designs can meet building sound-insulation requirements.','With a source-receiver level difference of 45 dB, a specimen area of 10 square metres and receiving-room absorption of 10 square metres, R = 45 + 10 log(10/10) = 45 dB.','Building acoustics',ARRAY['Equivalent sound absorption area','Excess attenuation','Octave-band analysis','Sabine absorption']::text[],ARRAY['Confusing the lab index R with the field index R'', which includes flanking paths.','Omitting the receiving-room absorption and area correction.','Mixing the single-number rating Rw with the frequency-band values.']::text[],ARRAY['Testing a partition in a transmission-loss laboratory.','Specifying a wall to meet a required sound-insulation class.','Comparing glazing options for airborne insulation.']::text[],'advanced','R = L1 - L2 + 10 log10(S / A)','The sound reduction index is the source-room level minus the receiving-room level plus ten log of the specimen area over the receiving-room absorption.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound reduction index');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1998','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1998') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1998');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1999','Stimulus-onset asynchrony','The time interval between the onset of one stimulus and the onset of a following stimulus in a sequence, regardless of either stimulus''s duration. In auditory experiments it controls the timing between events such as a masker and a target, and differs from the inter-stimulus interval, which is the gap between offset and next onset.','This is the time from the start of one sound to the start of the next. It counts from beginning to beginning. It is not the silent gap between them. Researchers use it to time masking and priming tests.','It defines the precise timing between successive events in perception experiments, essential for studying masking, priming and temporal processing.','If a masker starts at 0 ms and a target tone starts at 120 ms, the stimulus-onset asynchrony is 120 ms, even if the masker itself lasts only 50 ms.','Psychoacoustics',ARRAY['Lateralization','Diagnostic Rhyme Test','Double-blind triple-stimulus test']::text[],ARRAY['Confusing stimulus-onset asynchrony with the inter-stimulus interval.','Measuring from stimulus offset instead of onset.','Assuming it equals the first stimulus''s duration.']::text[],ARRAY['Designing a forward-masking experiment.','Timing prime and target in an auditory priming study.','Setting event spacing in a temporal-resolution test.']::text[],'intermediate','SOA = t_onset2 - t_onset1','The stimulus-onset asynchrony equals the onset time of the second stimulus minus the onset time of the first.','aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Stimulus-onset asynchrony');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1999','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1999') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1999');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2000','Weighting network','A standardised frequency-weighting filter built into sound level meters that shapes the measured spectrum to approximate human loudness perception or a defined flat response. IEC 61672-1 specifies A-weighting, which de-emphasises low and very high frequencies, C-weighting, which is nearly flat across the audio band, and Z (zero) weighting, which is flat by definition.','This is a filter inside a sound meter. It adjusts different pitches before the level is read. A-weighting follows how the ear judges loudness. C and Z weightings are much flatter. The chosen weighting is shown as a letter.','It makes a meter''s single number reflect either perceived loudness or a defined reference response, so measurements are consistent and comparable.','Measuring workplace noise you select A-weighting and report dB(A); at 1000 Hz the A-weighting adjustment is 0 dB by definition, while at 100 Hz it subtracts about 19 dB.','Sound measurement',ARRAY['Octave-band analysis','Free-field correction','Random-incidence response','Loudspeaker sensitivity']::text[],ARRAY['UNSAFE: Treating a low dB(A) reading as proof of safe exposure without checking level, duration and peak C-weighted values.','Comparing dB(A) and dB(C) values as if they were on the same scale.','Assuming A-weighting is accurate for loud sounds, where it underweights low frequencies.','Forgetting to state the weighting used with a reported level.']::text[],ARRAY['Measuring occupational noise for a hearing-conservation program.','Reporting environmental noise as dB(A).','Checking low-frequency content with C-weighting.']::text[],'beginner',NULL,NULL,'aa98040e-7646-4a7c-a922-37a36646ba4b' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Weighting network');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2000','aa98040e-7646-4a7c-a922-37a36646ba4b',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2000') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2000');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2001','Acoustic camera','An acoustic camera is a measurement instrument that pairs a microphone array with beamforming processing and an optical camera to produce a color-mapped image showing where sound sources are and how strong they are, overlaid on the visual scene.','An acoustic camera shows where sound comes from. It uses many microphones plus a normal camera. Software finds the loud spots. It draws them as bright colors over the picture.','It lets engineers pinpoint and rank noise or sound sources in space quickly, without probing each point by hand.','A technician aims the array at a panel, records briefly, and reads the color map to find the exact spot radiating the most noise.','Acoustic imaging',ARRAY['Acoustic imaging','Array microphone','Beamforming','Acoustic localization','Acoustic zoom']::text[],ARRAY['Reading the color map as absolute SPL rather than a relative source-strength map at the array''s focus.','Expecting fine resolution at low frequencies; angular resolution falls as frequency drops.','Confusing an acoustic camera image with a true acoustic hologram.']::text[],ARRAY['Locating a rattle or air leak on a vehicle body.','Finding the dominant noise source on a machine.','Mapping a source during a product noise investigation.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic camera');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2001','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2001') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2001');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2002','Acoustic focus','Acoustic focus is the concentration of sound energy toward, or reception from, a specific point in space, achieved by a curved reflector, an acoustic lens, or by delay-and-sum focusing of a microphone or loudspeaker array on a chosen focal point.','Acoustic focus means aiming sound at one exact spot. A curved dish or lens can do this. A set of microphones can also do it with timing tricks. Focusing boosts sound from one place.','It raises the signal from a chosen location while suppressing sound from other directions, improving pickup or delivery at that point.','In near-field array focusing, a technician sets the array''s focal distance to the target so signals from that point add in phase and stand out.','Array processing',ARRAY['Acoustic reflector','Array microphone','Acoustic zoom','Beamforming','Acoustic camera']::text[],ARRAY['Confusing focus (a point in space) with steering (a direction only).','Assuming tight focus at all frequencies; long wavelengths blur the focal spot.','Ignoring that reflector focus depends on geometry and source distance.']::text[],ARRAY['Setting the focal range on a beamforming array.','Aiming a parabolic reflector at a distant talker.','Concentrating ultrasound with an acoustic lens.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic focus');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2002','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2002') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2002');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2003','Acoustic gain','Acoustic gain is the increase in sound pressure level at a listener produced by a sound system, expressed in decibels as the difference between the level with the system on and the level with it off for the same source.','Acoustic gain is how much louder a sound system makes a source. Measure the level at the seat with the system off. Then measure it with the system on. The difference, in decibels, is the acoustic gain.','It quantifies how much reinforcement a system delivers to a listener, and helps predict feedback limits before ringing.','If a talker gives 60 dB at a seat with the system off and 72 dB with it on, the acoustic gain is 12 dB.','Sound reinforcement',ARRAY['Acoustic surveillance','Array microphone','Audio monitoring','Signal-to-noise ratio','Feedback']::text[],ARRAY['Confusing acoustic gain with the electrical gain set on the amplifier.','Ignoring that room feedback caps the achievable (potential) acoustic gain.','Forgetting the value is tied to a specific listener position.']::text[],ARRAY['Estimating usable gain before feedback in a room.','Comparing microphone placement for more gain-before-feedback.','Assessing whether a listening post gets enough level.']::text[],'intermediate','AG = L_on - L_off','Acoustic gain equals the sound level at the listener with the system on minus the level at the same listener with the system off, in decibels.','bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic gain');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2003','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2003') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2003');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2004','Acoustic imaging','Acoustic imaging is the family of techniques that map the spatial distribution of sound sources or acoustic reflectivity, using arrays and methods such as beamforming, near-field acoustical holography, or inverse methods to render sound as a spatial image.','Acoustic imaging turns sound into a picture. It uses many sensors to find where sound comes from. The result is a map of loud and quiet areas. It works a bit like a heat map for sound.','It reveals where sound is generated or reflected, supporting noise diagnosis, source localization, and non-destructive testing.','An engineer records a machine with an array and applies beamforming to produce an image that ranks its noisiest parts.','Acoustic imaging',ARRAY['Acoustic camera','Array microphone','Acoustic localization','Acoustic focus','Beamforming']::text[],ARRAY['Treating near-field holography and far-field beamforming as interchangeable; they suit different distances.','Expecting fine spatial detail at low frequencies from a small array.','Reading the image as calibrated SPL instead of relative source strength.']::text[],ARRAY['Noise-source mapping on machinery.','Underwater or medical acoustic imaging.','Locating leaks or partial discharge by sound.']::text[],'advanced',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic imaging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2004','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2004') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2004');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2005','Acoustic intelligence (ACINT)','Acoustic intelligence (ACINT) is a category of technical intelligence derived from collecting and analyzing acoustic phenomena, especially underwater and platform-radiated sound; it is treated as a subdiscipline of measurement and signature intelligence (MASINT).','Acoustic intelligence means learning from sound. It often uses underwater sensors and sonar. Experts study the sounds ships or engines make. This helps find and track them.','It supports detection, classification, and tracking of vehicles and platforms by their acoustic signatures.','An analyst compares a recorded underwater signature against a reference library to identify a vessel class.','Intelligence discipline',ARRAY['Acoustic surveillance','Acoustic localization','Audio intelligence','Sonar','Acoustic signature']::text[],ARRAY['Confusing ACINT (a MASINT subdiscipline) with communications intercept under SIGINT.','Assuming ACINT is only military; it also covers seismic and infrasonic sensing.','Equating a raw recording with finished intelligence.']::text[],ARRAY['Classifying a vessel from its underwater sound.','Monitoring an area with a fixed hydrophone array.','Identifying a vehicle by engine and drivetrain noise.']::text[],'advanced',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic intelligence (ACINT)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2005','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2005') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2005');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2006','Acoustic localization','Acoustic localization is the estimation of a sound source''s position or direction from signals captured at spatially separated sensors, typically using time-difference-of-arrival (TDOA), level differences, or beamforming across a microphone array.','Acoustic localization finds where a sound came from. It uses several microphones in different spots. The sound reaches each mic at a slightly different time. Software uses those tiny delays to locate the source.','It converts multi-sensor recordings into a source direction or coordinate, enabling tracking, mapping, and forensic reconstruction.','With two microphones and a 5 ms arrival delay, the path-length difference is about 1.7 m (0.005 s x 343 m/s), which constrains the source to one hyperbola.','Source localization',ARRAY['Acoustic imaging','Array microphone','Acoustic camera','Acoustic surveillance','Time difference of arrival']::text[],ARRAY['Forgetting one TDOA fixes a hyperbola, not a point; several sensors are needed for a fix.','Using a wrong speed of sound; c changes with temperature.','Ignoring reflections, which create false arrival times.']::text[],ARRAY['Gunshot location from distributed sensors.','Steering a camera toward an active talker.','Mapping wildlife calls with a sensor array.']::text[],'advanced','d_ij = c * (t_i - t_j)','The difference in distance from a source to two sensors equals the speed of sound times the difference in their arrival times.','bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic localization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2006','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2006') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2006');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2007','Acoustic reflector','An acoustic reflector is a rigid surface, often curved such as a parabolic dish, that redirects or concentrates sound waves; a parabolic reflector focuses distant on-axis sound onto a microphone placed at its focal point.','An acoustic reflector is a hard surface that bounces sound. A curved dish can gather faint distant sound. It focuses that sound onto a microphone at its focal point. This boosts sound from straight ahead.','It raises the level and directivity of captured sound from a target direction, aiding long-range and directional pickup.','A technician mounts a microphone at a parabolic dish''s focus to record a distant bird or talker with higher on-axis gain.','Directional pickup',ARRAY['Acoustic focus','Parabolic microphone','Acoustic surveillance','Array microphone','Acoustic shadow']::text[],ARRAY['Assuming useful gain at low frequencies; a dish helps only when its diameter is comparable to or larger than the wavelength.','Misplacing the microphone off the focal point, losing gain.','UNSAFE: using a parabolic microphone to record others may be restricted by consent and wiretap laws (jurisdiction-dependent); this is not legal advice.']::text[],ARRAY['Wildlife or sports-sideline recording with a parabolic dish.','Long-range pickup of a distant talker.','Concentrating sound onto a sensor in a test rig.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic reflector');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2007','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2007') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2007');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2008','Acoustic shadow','An acoustic shadow is a region of reduced sound level behind an obstacle or beyond a refracting boundary, where the object''s size relative to the wavelength limits diffraction into the zone; high frequencies are attenuated more than low frequencies.','An acoustic shadow is a quiet zone behind a barrier. The barrier blocks some sound. Low sounds bend around it easily. High sounds bend less, so they drop off more.','It describes how obstacles and the atmosphere block or bend sound, affecting where a source can be heard or recorded.','Placing a recorder in a wall''s acoustic shadow reduces high-frequency pickup of a source on the far side, muffling speech.','Sound propagation',ARRAY['Diffraction','Acoustic reflector','Acoustic focus','Sound propagation','Acoustic surveillance']::text[],ARRAY['Assuming a barrier blocks all frequencies equally; low frequencies diffract around it.','Confusing an acoustic shadow with simple distance loss.','Ignoring temperature or wind refraction, which also creates shadow zones.']::text[],ARRAY['Barrier placement to shield a microphone from noise.','Explaining why distant sounds fade over a hill or in wind.','Assessing coverage gaps for a listening post.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic shadow');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2008','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2008') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2008');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2009','Acoustic surveillance','Acoustic surveillance is the monitoring of an environment by capturing sound, typically speech or activity, using microphones and directional or concealed sensors with recorders, for security, investigative, or intelligence purposes.','Acoustic surveillance means watching a place by listening. It uses microphones to capture sound and speech. Recorders or transmitters store or send the audio. People use it for security or investigations.','It gathers audio evidence or situational awareness about people and activity in a target area.','Acting under lawful authority, an investigator places an approved microphone to record conversations relevant to a case.','Surveillance',ARRAY['Audio surveillance','Audio bug','Audio interception','Acoustic reflector','Acoustic gain']::text[],ARRAY['Assuming any recording is admissible; evidence needs proven integrity and lawful capture.','UNSAFE: recording others'' conversations is subject to consent and wiretap laws that vary by jurisdiction; this is not legal advice.','Confusing surveillance capture with finished forensic analysis.']::text[],ARRAY['Lawful monitoring during a criminal investigation.','Perimeter audio sensing for site security.','Warranted covert audio capture.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic surveillance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2009','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2009') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2009');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2010','Acoustic zoom','Acoustic zoom, also called audio zoom, is a processing technique that narrows a capture system''s effective directional focus toward a chosen source or distance using beamforming across a microphone array, so the recorded balance emphasizes that source as if moving closer.','Acoustic zoom makes a far sound seem closer. It uses several microphones and software. The system focuses on one direction. Sound from there gets louder, and other sound is pushed back.','It lets a recordist emphasize a distant or specific source without moving, improving that source''s relative level and clarity.','On a multi-mic device, selecting audio zoom steers the beam toward a talker so their voice rises above room noise in the recording.','Array processing',ARRAY['Acoustic focus','Array microphone','Beamforming','Acoustic camera','Acoustic gain']::text[],ARRAY['Expecting true optical-style zoom; it changes balance, not real distance.','Assuming it removes reverberation; early reflections often remain.','Over-narrowing the beam so a moving source drops out.']::text[],ARRAY['Emphasizing a speaker on a smartphone or camcorder.','Focusing a conferencing array on the active talker.','Lifting a distant source above background noise.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic zoom');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2010','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2010') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2010');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2011','Active monitoring','Active monitoring is the real-time, attended observation of an audio feed by an operator who listens as events occur, in contrast to passive or unattended recording that is reviewed later.','Active monitoring means someone listens live. An operator hears the audio as it happens. They can react right away to what they hear. This differs from just recording and checking later.','It enables immediate response, targeting decisions, and note-taking while events unfold, rather than only after the fact.','An operator actively monitors a lawful intercept, flagging relevant passages in real time for later review.','Monitoring',ARRAY['Audio monitoring','Acoustic surveillance','Audio surveillance','Ambient recording','Audio interception']::text[],ARRAY['Confusing this with ''active monitors'', which are powered loudspeakers.','Assuming live listening removes the need for a recording and log.','Underestimating operator fatigue during long active sessions.']::text[],ARRAY['Live listening on an authorized wiretap.','Real-time monitoring of a security post''s microphones.','Attended monitoring during a controlled operation.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Active monitoring');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2011','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2011') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2011');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2012','Adaptive filtering','Adaptive filtering is a signal-processing method in which a digital filter continuously adjusts its coefficients from the incoming signal and an error measure to minimize that error; the least-mean-squares (LMS) algorithm is a common update rule.','An adaptive filter tunes itself as it runs. It compares its output to a target. Then it changes its settings to shrink the error. Engineers use it to cancel changing noise or echo.','It tracks changing signals or noise to perform tasks like noise cancellation, echo removal, and interference suppression without fixed, hand-set coefficients.','In forensic denoising, an adaptive filter uses a noise reference to subtract steady hum or background from a voice recording.','Signal processing',ARRAY['Audio forensics','Ambient recording','Adaptive noise cancellation','Noise reduction','Signal processing']::text[],ARRAY['Choosing too large a step size, which makes the filter diverge.','Assuming adaptive noise cancellation needs no clean noise reference; it usually does.','Expecting it to remove noise that overlaps the speech spectrum without artifacts.']::text[],ARRAY['Removing steady hum from an evidential recording.','Echo cancellation on a communications link.','Suppressing periodic interference before transcription.']::text[],'advanced','w(n+1) = w(n) + mu * e(n) * x(n)','The new filter weight vector equals the old weights plus a step size times the error times the input sample vector.','bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Adaptive filtering');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2012','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2012') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2012');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2013','Ambient recording','Ambient recording is the deliberate capture of the background sound of a location, including its room tone, environmental noise, and reverberation, either as context or as a reference sample for later analysis.','Ambient recording captures the background sound of a place. This includes room tone, hum, and general noise. It does not focus on one talker. Analysts use it as context or a reference.','It documents a location''s acoustic background, supporting authentication, noise modeling, and realistic context for other recordings.','An examiner records several seconds of room tone at a scene to characterize the noise floor for later comparison or denoising.','Recording technique',ARRAY['Audio forensics','Adaptive filtering','Acoustic surveillance','Room tone','Audio authentication']::text[],ARRAY['Confusing ambient recording with a film ''wild track'' used only for editing.','Skipping a background reference, which weakens later noise analysis.','Assuming background is constant; it changes with time and conditions.']::text[],ARRAY['Capturing scene room tone for forensic comparison.','Recording environmental context during surveillance.','Sampling noise for denoising a target recording.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ambient recording');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2013','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2013') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2013');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2014','Analog transmitter','An analog transmitter is a device that impresses an audio signal directly onto a radio-frequency carrier using analog modulation, typically frequency modulation, and radiates it, as in traditional wireless microphones and body-worn transmitters.','An analog transmitter sends audio over radio waves. It changes a radio carrier to match the sound, usually with FM. There is no digital coding step. Wireless microphones and body packs often work this way.','It carries audio wirelessly from a source to a receiver without a cable, using continuous (analog) modulation.','A technician sets an FM body-pack transmitter and its receiver to the same licensed frequency to pass a lavalier microphone''s audio.','Wireless transmission',ARRAY['Audio transmitter','Audio uplink','Audio link','Companding','Audio bug']::text[],ARRAY['Assuming analog FM is encrypted; the audio is generally open to any matching receiver.','Ignoring companding, which analog wireless uses to fight noise.','UNSAFE: transmitting requires legal frequencies and power; unlicensed use may violate radio regulations.']::text[],ARRAY['Setting up a wireless lavalier for field recording.','Comparing analog and digital wireless for latency and range.','Understanding legacy body-worn transmitters.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Analog transmitter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2014','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2014') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2014');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2015','Array microphone','An array microphone is an assembly of multiple microphone elements at known positions whose signals are combined by beamforming to achieve directional pickup, source localization, or steerable focus not available from a single capsule.','An array microphone uses many small mics at once. It knows where each mic sits. Software blends the signals with careful timing. This lets it aim pickup at one spot.','It provides electronically steerable directivity and spatial information, enabling focus, localization, and imaging.','A conferencing array steers its beam to the active talker, raising that voice over room noise without a handheld microphone.','Microphone array',ARRAY['Acoustic camera','Acoustic imaging','Acoustic localization','Acoustic zoom','Beamforming']::text[],ARRAY['Assuming more elements always means better low-frequency resolution; aperture size matters most.','Ignoring element spacing, which causes spatial aliasing above a limit frequency.','Treating an array like a single directional mic with a fixed pattern.']::text[],ARRAY['Steerable pickup in conference rooms.','Beamforming for noise-source mapping.','Direction finding in acoustic surveillance.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Array microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2015','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2015') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2015');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2016','Articulation index','The articulation index (AI) is a calculated, weighted measure of speech intelligibility that divides the speech spectrum into frequency bands, scores each band by its effective speech-to-noise ratio over a limited dynamic range, and sums the weighted contributions to a value between 0 and 1.','The articulation index rates how well speech can be understood. It splits speech into frequency bands. Each band gets a score from its signal-to-noise ratio. The scores add up to a number from 0 to 1.','It predicts intelligibility from measurable signal and noise levels, guiding communication-system and room design.','Using 20 equally weighted bands, each contributes up to 0.05; a path with full audibility in 14 bands yields AI of about 0.70, indicating good intelligibility.','Speech intelligibility',ARRAY['Speech intelligibility index','Speech transmission index','Signal-to-noise ratio','Intelligibility','Audio forensics']::text[],ARRAY['Confusing the older AI with its successor, the Speech Intelligibility Index (SII).','Assuming AI accounts for reverberation; the STI handles echo and modulation loss better.','Reading AI as a percentage of words correct rather than an index.']::text[],ARRAY['Estimating intelligibility of a communications channel.','Assessing whether an enhanced recording is intelligible.','Designing announcement systems for clarity.']::text[],'advanced','AI = sum_k ( W_k * A_k )','The articulation index is the sum over frequency bands of each band''s weight times its audibility fraction, where each band''s speech-to-noise ratio is clamped to a fixed dynamic range.','bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Articulation index');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2016','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2016') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2016');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2017','Audio authentication','Audio authentication is the forensic process of determining whether a recording is original and unaltered and whether it was produced consistently with its purported history, using analyses such as edit and splice detection, format and metadata checks, and electric network frequency (ENF) comparison.','Audio authentication checks if a recording is genuine. Examiners look for cuts, edits, or added parts. They check the file format and hidden data. They may match the mains-hum frequency to a database.','It establishes whether audio evidence can be trusted as an accurate, complete, and original record.','An examiner compares the recording''s embedded ENF trace against a reference power-grid log to test the stated time and continuity.','Forensic authentication',ARRAY['Audio forensics','Audio integrity','Electric network frequency','Butt splice','Edit detection']::text[],ARRAY['Assuming a clean-sounding file is authentic; edits can be inaudible.','Treating a copy as an original; authentication favors first-generation media.','Believing ENF works everywhere; it needs the hum captured and a reference database.']::text[],ARRAY['Testing a disputed recording offered as evidence.','Verifying continuity of a body-worn recording.','Checking whether a file was re-encoded or edited.']::text[],'advanced',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio authentication');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2017','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2017') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2017');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2018','Audio bug','An audio bug is a covert listening device consisting of a concealed microphone with a recorder or radio transmitter, hidden in an environment or object to capture conversations without the knowledge of those present.','An audio bug is a hidden listening device. It has a small microphone plus a recorder or radio sender. Someone conceals it in a room or object. It captures talk without people knowing.','It enables covert capture of speech in a target space for surveillance or intelligence.','A technical surveillance countermeasures (TSCM) sweep searches a room for bugs by detecting their radio emissions or physical presence.','Covert device',ARRAY['Audio surveillance','Audio transmitter','RF bug','Acoustic surveillance','Audio interception']::text[],ARRAY['Assuming all bugs transmit; some only record for later recovery.','UNSAFE: planting a listening device to capture others is illegal in most jurisdictions absent authority; this is not legal advice.','Thinking a powered-off or ''silent'' device cannot act as a bug.']::text[],ARRAY['Technical surveillance countermeasures (bug sweeps).','Lawful, warranted covert audio capture.','Understanding threats in executive protection.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio bug');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2018','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2018') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2018');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2019','Audio downlink','An audio downlink is the transmission path that carries audio from a remote or elevated platform, such as a satellite, aircraft, or repeater, down to a receiving station on the ground.','An audio downlink sends audio down to a base. The source is a satellite, aircraft, or relay. The ground station receives the signal. ''Down'' means from the high platform to the ground.','It delivers audio from an airborne or orbital relay to operators, completing a remote link''s return path.','A ground receiver tunes the downlink frequency of a relay to hear audio forwarded from a distant transmitter.','RF transmission',ARRAY['Audio uplink','Audio relay','Audio link','Audio transmitter','Analog transmitter']::text[],ARRAY['Swapping uplink and downlink; downlink is toward the ground station.','Assuming downlink and uplink share one frequency; they usually differ.','Ignoring propagation delay on long relay paths.']::text[],ARRAY['Receiving audio relayed by a satellite.','Downlinking audio from an aircraft or drone.','Planning frequencies for a two-way relay.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio downlink');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2019','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2019') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2019');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2020','Audio forensics','Audio forensics is the scientific discipline concerned with the acquisition, authentication, enhancement, and interpretation of audio evidence for legal, investigative, or official proceedings, following documented methods and chain-of-custody practices.','Audio forensics is the science of examining sound evidence. Experts recover, verify, and clean up recordings. They may also identify voices or events. Their work must follow strict, documented steps.','It produces reliable, defensible findings from audio evidence so courts and investigators can rely on them.','A forensic examiner authenticates a recording, enhances a passage for intelligibility, and documents each step for disclosure.','Forensic discipline',ARRAY['Audio authentication','Audio integrity','Adaptive filtering','Speaker recognition','Audio enhancement']::text[],ARRAY['Assuming enhancement can always make speech intelligible; some audio is unrecoverable.','Editing the original file instead of working on a verified copy.','Overstating certainty; forensic conclusions carry stated limits.']::text[],ARRAY['Preparing audio evidence for a trial.','Enhancing an emergency call for review.','Authenticating a disputed recording.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio forensics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2020','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2020') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2020');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2021','Audio integrity','Audio integrity is the property that a recording is complete and unaltered from its original captured state, preserved and demonstrable through hashing, write-protected copies, and a documented chain of custody.','Audio integrity means a recording has not changed. It is complete and unedited since capture. Experts protect it with copies and hash checks. A clear record of custody proves it stayed intact.','It ensures that audio evidence can be shown to be trustworthy and untampered when relied upon.','On intake, an examiner computes a cryptographic hash of the file, works only on verified copies, and re-checks the hash to prove no change.','Evidence handling',ARRAY['Audio authentication','Chain of custody','Audio forensics','Hash value','Write blocker']::text[],ARRAY['Confusing integrity (unaltered) with authentication (original and genuine).','Working on the sole original instead of a protected copy.','Skipping hash documentation, which weakens the integrity claim.']::text[],ARRAY['Intake and preservation of seized recordings.','Proving a file was unchanged during analysis.','Maintaining chain of custody for court.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio integrity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2021','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2021') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2021');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2022','Audio intelligence','Audio intelligence is information of intelligence value derived from the collection and analysis of sound, including intercepted speech and non-speech acoustic signatures; it overlaps signals intelligence for communications and acoustic intelligence for signatures.','Audio intelligence is useful facts drawn from sound. It can come from tapped talk or machine noises. Experts study the audio to find meaning. It overlaps signals and acoustic work.','It turns collected sound into actionable information for investigations or operations.','An analyst reviews intercepted audio, transcribes key passages, and reports the intelligence with source and reliability noted.','Intelligence discipline',ARRAY['Acoustic intelligence (ACINT)','Audio surveillance','Audio interception','Acoustic surveillance','Speaker recognition']::text[],ARRAY['Using ''audio intelligence'' and ACINT as exact synonyms; ACINT centers on signatures.','Treating raw intercept as finished intelligence without analysis.','Ignoring collection legality and provenance.']::text[],ARRAY['Analyzing intercepted communications.','Deriving cues from environmental sound.','Reporting findings from monitored audio.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio intelligence');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2022','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2022') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2022');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2023','Audio interception','Audio interception is the capture of audio, especially communications, while it is being conveyed or spoken, by a party who is not an intended recipient, using microphones, taps, or radio receivers.','Audio interception means grabbing audio in transit. Someone who is not meant to hear it captures it. They may use a tap, microphone, or radio receiver. Wiretapping is a common example.','It obtains communications or conversations for surveillance, investigation, or intelligence, typically without the speakers'' knowledge.','Under a lawful warrant, investigators intercept a target''s calls at the carrier and record them for evidence.','Interception',ARRAY['Audio surveillance','Audio bug','Acoustic surveillance','Audio intelligence','Wiretap']::text[],ARRAY['UNSAFE: intercepting communications is heavily regulated; unauthorized interception violates wiretap laws (jurisdiction-dependent); this is not legal advice.','Assuming one-party consent applies everywhere; rules vary widely.','Confusing lawful, warranted interception with illegal eavesdropping.']::text[],ARRAY['Court-authorized wiretap in an investigation.','Radio interception of an unencrypted link.','Understanding threats to confidential meetings.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio interception');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2023','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2023') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2023');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2024','Audio link','An audio link is a communication path, wired or wireless, that carries an audio signal between two points, characterized by its bandwidth, latency, noise performance, and, for radio links, carrier frequency and modulation.','An audio link is a path that carries sound between two points. It can be a cable or a radio connection. It is judged by clarity, delay, and noise. Both ends must match its settings.','It moves audio reliably from a source to a destination, forming the backbone of remote monitoring and communication systems.','A technician verifies a wireless audio link by confirming a matched frequency, adequate signal strength, and acceptable latency before use.','Signal transmission',ARRAY['Audio uplink','Audio downlink','Audio relay','Audio transmitter','Analog transmitter']::text[],ARRAY['Confusing the link (the path) with the transmitter (one endpoint device).','Ignoring latency, which matters for live monitoring.','Assuming a strong signal guarantees clean audio; interference still degrades it.']::text[],ARRAY['Establishing a wireless feed to a monitoring post.','Connecting a remote microphone to a base.','Planning bandwidth and delay for a live feed.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio link');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2024','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2024') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2024');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2025','Audio monitoring','Audio monitoring is the act of listening to or metering an audio signal to check its content, level, and quality, in real time or from a recording, often through headphones, monitor loudspeakers, or level meters.','Audio monitoring means checking an audio signal. You listen through headphones or speakers. You may also watch level meters. This confirms the sound is present, clean, and at a safe level.','It verifies that audio is captured or transmitted correctly and lets an operator catch problems and important content.','An operator monitors a recording chain on headphones and meters, adjusting gain to avoid clipping while confirming intelligible speech.','Monitoring',ARRAY['Active monitoring','Acoustic surveillance','Audio surveillance','Ambient recording','Audio link']::text[],ARRAY['UNSAFE: prolonged high-level headphone monitoring can damage hearing; keep levels moderate.','Trusting meters alone without listening for distortion or dropouts.','Assuming a monitoring path adds no latency of its own.']::text[],ARRAY['Checking a live surveillance feed.','Quality-checking a recording during capture.','Metering levels to prevent clipping.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio monitoring');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2025','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2025') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2025');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2026','Audio relay','An audio relay is a device or station that receives an audio-bearing signal and retransmits it to extend range or bridge otherwise-unreachable paths, as in a repeater placed between a remote transmitter and a distant receiver.','An audio relay passes audio along to reach farther. It receives a signal, then sends it out again. This bridges gaps a single link cannot cross. A repeater is a common example.','It extends the reach of an audio link past the range or line-of-sight limits of a single hop.','A technician places a repeater on high ground so a body-worn transmitter''s audio reaches a base beyond direct range.','RF transmission',ARRAY['Audio uplink','Audio downlink','Audio link','Audio transmitter','Analog transmitter']::text[],ARRAY['Assuming a relay adds no delay or noise; each hop adds both.','Placing the relay without line-of-sight to both ends.','Confusing a relay (retransmits) with a simple splitter.']::text[],ARRAY['Extending range of a covert transmitter.','Repeating a feed over hilly terrain.','Bridging a signal to a distant monitoring post.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio relay');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2026','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2026') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2026');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2027','Audio surveillance','Audio surveillance is the systematic electronic monitoring and recording of speech and sound in a target area or over a communication channel, using microphones, transmitters, and recorders for security, investigative, or intelligence purposes.','Audio surveillance is watching a target by capturing sound. It uses microphones, transmitters, and recorders. It can cover a room or a phone line. People use it for security or investigations.','It gathers spoken content and activity as evidence or intelligence about people in a target area or channel.','Under lawful authority, an investigator records a target''s conversations and preserves the files with documented integrity.','Surveillance',ARRAY['Acoustic surveillance','Audio bug','Audio interception','Audio surveillance network','Audio monitoring']::text[],ARRAY['UNSAFE: audio surveillance of others is governed by consent and wiretap laws that vary by jurisdiction; this is not legal advice.','Assuming captured audio is automatically admissible; integrity and legality matter.','Confusing surveillance capture with forensic analysis of the result.']::text[],ARRAY['Warranted covert recording in an investigation.','Monitoring a secured facility for security.','Preserving intercepted audio as evidence.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio surveillance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2027','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2027') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2027');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2028','Audio surveillance network','An audio surveillance network is a distributed system of networked acoustic sensors and processing nodes that continuously monitor an area, sharing data to detect, classify, and localize sounds such as gunshots across the covered region.','An audio surveillance network links many sound sensors together. They cover a wide area at once. The system shares data to spot and locate sounds. Gunshot detection systems work this way.','It provides wide-area, real-time detection and location of acoustic events by combining many sensors.','A gunshot-detection network times a shot''s arrival at several sensors and computes its location by time-difference-of-arrival.','Sensor network',ARRAY['Acoustic localization','Audio surveillance','Gunshot detection','Array microphone','Acoustic surveillance']::text[],ARRAY['Assuming detections are always correct; systems can mislabel fireworks or a backfire.','Ignoring that localization accuracy depends on sensor density and timing sync.','Treating an alert as proof without human and forensic review.']::text[],ARRAY['City-wide gunshot detection and location.','Perimeter acoustic monitoring of a large site.','Wide-area wildlife or event monitoring.']::text[],'advanced',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio surveillance network');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2028','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2028') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2028');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2029','Audio transmitter','An audio transmitter is a device that converts an audio signal into a modulated radio-frequency signal and radiates it via an antenna for reception elsewhere; it may use analog (FM) or digital modulation.','An audio transmitter turns sound into a radio signal. It puts the audio onto a carrier wave. An antenna then sends it out. A receiver picks it up somewhere else.','It sends audio wirelessly from a source to one or more receivers without a physical cable.','A technician pairs a body-worn audio transmitter with a receiver on the same frequency to pass a microphone''s signal.','Wireless transmission',ARRAY['Analog transmitter','Audio uplink','Audio link','Audio relay','Audio bug']::text[],ARRAY['Confusing the transmitter (converts and sends) with the antenna alone.','Assuming higher power always helps; regulations cap power and channel use.','UNSAFE: transmitting must use legal frequencies and power; unlicensed operation may break radio regulations.']::text[],ARRAY['Wireless microphone and body-pack setups.','Covert audio links under lawful authority.','Choosing analog versus digital wireless.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio transmitter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2029','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2029') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2029');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2030','Audio uplink','An audio uplink is the transmission path that carries audio from a ground station up to a remote or elevated platform, such as a satellite, aircraft, or repeater, for relay or distribution.','An audio uplink sends audio up to a platform. The source is a ground station. The platform is a satellite, aircraft, or relay. ''Up'' means from the ground to the high platform.','It delivers audio from the ground to an airborne or orbital relay, forming the outbound leg of a remote link.','A ground station transmits on the uplink frequency to a satellite, which relays the audio to distant receivers on a different downlink frequency.','RF transmission',ARRAY['Audio downlink','Audio relay','Audio link','Audio transmitter','Analog transmitter']::text[],ARRAY['Swapping uplink and downlink; uplink goes up to the platform.','Assuming uplink and downlink use the same frequency; they normally differ.','Ignoring rain fade and delay on satellite uplinks.']::text[],ARRAY['Feeding a satellite relay from the ground.','Uplinking audio to an aircraft repeater.','Planning paired uplink and downlink frequencies.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio uplink');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2030','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2030') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2030');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2031','Base station','A base station is a fixed transceiver or receiving unit that anchors a wireless link, receiving signals from portable transmitters such as body-worn wires or wireless microphones and passing the audio to monitoring or recording equipment. In cellular networks the term denotes the fixed radio node that connects mobile devices to the network.','A base station is a fixed radio unit. It stays in one place and listens for signals. Small transmitters, like a hidden wire, send audio to it. It then feeds that audio to a recorder or monitor.','It provides the stationary end of a wireless link, letting mobile or concealed transmitters reach recording and monitoring gear reliably.','A surveillance technician places the base station within radio range of a body-worn transmitter, then routes its line output to a logging recorder.','Surveillance hardware',ARRAY['Body wire microphone','Digital transmitter','Cellular audio transmitter','Continuous recorder','Channel synchronization']::text[],ARRAY['Assuming a base station captures sound itself; it only receives and relays a transmitter''s signal.','Confusing a wireless-microphone base/receiver with a cellular network base station; the term spans both.','Ignoring range and line-of-sight limits, so the transmitter drops out at distance.']::text[],ARRAY['Setting up a fixed receiver for a body-worn wire during an operation.','A cellular tower node linking mobile phones to the network.','A wireless microphone receiver feeding a recording console.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Base station');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2031','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2031') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2031');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2032','Beam steering','Beam steering is the electronic aiming of an array''s main sensitivity (or radiation) lobe toward a chosen direction by applying controlled time delays or phase shifts across the array elements, without physically moving the array. For a uniform linear array steered to angle theta, adjacent elements are delayed by d*sin(theta)/c, where d is the element spacing and c is the speed of sound.','Beam steering points a microphone array at a target using math, not motion. The array delays each microphone''s signal by a small amount. These delays line up sound from one direction. That direction becomes the array''s focus.','It lets one fixed array focus on different sources on demand, improving pickup of a target while rejecting other directions.','With 5 cm element spacing steered to 30 degrees, the technician sets about a 73 microsecond delay between adjacent mics (0.05*sin30/343), favouring that bearing.','Array processing',ARRAY['Beamforming array','Beamforming microphone','Directional pickup','Channel synchronization','Base station']::text[],ARRAY['Thinking the array physically rotates; steering is done with delays or phase, not motion.','Forgetting that spacing wider than half a wavelength causes grating lobes and false directions.','Assuming perfect rejection; sidelobes still admit sound from other angles.']::text[],ARRAY['Aiming a conference array at whoever is speaking.','Focusing a surveillance array on one window across a street.','Tracking a moving talker by updating the steering angle.']::text[],'advanced','tau_n = n*d*sin(theta)/c ;  delta_phi = 2*pi*d*sin(theta)/lambda','The steering delay for element n equals n times the spacing times the sine of the steering angle, divided by the speed of sound; the equivalent phase shift between adjacent elements equals two pi times spacing times the sine of the angle, divided by wavelength.','bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Beam steering');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2032','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2032') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2032');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2033','Beamforming array','A beamforming array is a set of two or more microphones (or antennas) whose signals are combined with element-specific delays, phases, and weights to form a directional response that reinforces sound from a chosen direction and suppresses it from others. In the simplest delay-and-sum form, array gain against uncorrelated noise rises by about 10*log10(N) dB for N elements.','A beamforming array is a group of microphones working together. Their signals are delayed and added in a smart way. Sound from the target direction adds up strongly. Sound from other directions partly cancels. More microphones give more focus.','It creates a steerable, high-directivity pickup from small elements, improving the signal-to-noise ratio for a target source in noisy or reverberant spaces.','An eight-element delay-and-sum array gives about 9 dB of gain over a single mic against diffuse noise, since 10*log10(8) is approximately 9 dB.','Array processing',ARRAY['Beamforming microphone','Beam steering','Directional pickup','Channel synchronization','Base station']::text[],ARRAY['Assuming more mics always help; benefit against uncorrelated noise grows only as 10*log10(N).','Ignoring element spacing, which sets both aliasing (grating lobes) and low-frequency directivity limits.','Expecting equal performance at all frequencies; a fixed array''s beamwidth changes with frequency.']::text[],ARRAY['Picking a talker out of a noisy room.','Building a directional pickup from small MEMS microphones.','A phased antenna array steering a radio beam.']::text[],'advanced','y(t) = sum_{n=1}^{N} w_n * x_n(t - tau_n) ;  AG = 10*log10(N)','The array output is the sum over all elements of each element''s weight times its delayed signal; the delay-and-sum array gain against uncorrelated noise equals ten times the base-ten logarithm of the number of elements.','bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Beamforming array');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2033','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2033') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2033');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2034','Beamforming microphone','A beamforming microphone is a single product integrating a fixed or adaptive microphone array with onboard beamforming processing, presenting one or more steerable directional pickup beams from a compact housing. It is common in conferencing (ceiling and table array microphones) and in surveillance pickups that must focus on a target while rejecting ambient noise.','A beamforming microphone puts a whole array in one unit. Inside, many tiny mics feed a processor. The processor forms a focused pickup beam. It can aim at a talker and ignore other noise.','It packages microphone-array directivity into a plug-and-play device, so users get steerable, noise-rejecting pickup without wiring separate elements.','A technician mounts a ceiling beamforming microphone with four or more capsules; its array gain of roughly 10*log10(N) dB raises speech level over room noise.','Surveillance hardware',ARRAY['Beamforming array','Beam steering','Directional pickup','Concealed microphone','Base station']::text[],ARRAY['Treating it as a plain directional mic; its beam is formed by processing, not just capsule shape.','Assuming it removes all room noise; it improves, not perfects, the signal-to-noise ratio.','Overlooking that very low frequencies are hard to focus in a small array.']::text[],ARRAY['Ceiling array microphone in a meeting room.','Compact directional pickup for covert monitoring.','Voice capture for a smart speaker or kiosk.']::text[],'intermediate','AG = 10*log10(N)','The array gain against uncorrelated noise equals ten times the base-ten logarithm of the number of microphone elements.','bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Beamforming microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2034','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2034') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2034');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2035','Bluetooth audio','Bluetooth audio is the transport of audio over the Bluetooth short-range radio standard maintained by the Bluetooth SIG, operating in the 2.4 to 2.4835 GHz ISM band using adaptive frequency-hopping spread spectrum. Classic Bluetooth carries media through media profiles such as A2DP and voice through voice profiles such as HFP and HSP, while Bluetooth LE Audio uses the LC3 codec.','Bluetooth audio sends sound over a short-range radio link. It uses the 2.4 GHz band shared by Wi-Fi. The radio hops between channels to fight interference. Phones, earbuds, and speakers use it. Range is usually a few metres to tens of metres.','It provides a wireless, standardized way to stream music and voice between nearby devices without cables.','A technician pairing a recorder to a Bluetooth source notes that lossy codecs and channel hopping can add latency and artefacts unwanted in forensic capture.','Wireless audio',ARRAY['Digital transmitter','Cellular audio transmitter','Base station','Carrier detection','Bug']::text[],ARRAY['Assuming Bluetooth audio is lossless; classic profiles use lossy codecs such as SBC or AAC.','Confusing Bluetooth''s 2.4 GHz band with Wi-Fi''s; they share the band but use different protocols.','Ignoring pairing and encryption, so a link is assumed private when it may not be.']::text[],ARRAY['Streaming to wireless earbuds or a speaker.','A covert transmitter disguised as a Bluetooth accessory.','Assessing whether a Bluetooth recording is court-suitable.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bluetooth audio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2035','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2035') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2035');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2036','Body recorder','A body recorder is a concealed or worn audio recording device carried on a person to capture nearby conversation locally to internal storage, as distinct from a body wire that transmits to a remote receiver. It is widely used in law-enforcement consensual monitoring and in investigative or workplace recording.','A body recorder is a small recorder worn on the body. It saves sound to its own memory. It does not send a radio signal out. A person wears it to capture nearby talk. Investigators often use one.','It captures first-hand audio at the scene without a radio link that could be detected or fail, keeping the recording self-contained.','An investigator clips a body recorder under clothing, checks battery and storage, then later copies the file and computes a verified hash for chain of custody.','Covert recording',ARRAY['Body wire microphone','Digital voice recorder','Covert recording','Concealed microphone','Continuous recorder']::text[],ARRAY['Confusing a body recorder, which stores locally, with a body wire, which transmits live.','Recording without confirming consent laws for the jurisdiction (one-party versus all-party consent).','Failing to hash and verify the file, which weakens admissibility and chain of custody.']::text[],ARRAY['Consensual monitoring in an undercover operation.','An employee documenting a meeting where lawful.','A journalistic source recording where permitted.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Body recorder');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2036','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2036') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2036');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2037','Body wire microphone','A body wire microphone is a concealed microphone worn on a person and connected to a body-worn transmitter, sending captured audio in real time by radio to a nearby receiver or recorder. Unlike a body recorder, it depends on a live radio link and a remote base station.','A body wire is a hidden mic worn on a person. It connects to a small radio transmitter. The mic''s sound goes out live by radio. A nearby receiver catches and records it. This differs from a recorder that stores sound itself.','It lets a remote team hear and record a wearer''s conversation live, which supports real-time monitoring and safety oversight.','A technician tapes the microphone high on the chest, routes it to the transmitter, and confirms clear reception at the base station before deployment.','Covert recording',ARRAY['Body recorder','Digital transmitter','Concealed microphone','Base station','Covert microphone']::text[],ARRAY['Thinking a body wire stores audio; it usually transmits and relies on a receiver to record.','Placing the mic where clothing rustle masks speech.','Ignoring jurisdiction-specific consent and wiretap law before recording a conversation.']::text[],ARRAY['A live-monitored undercover meeting.','Officer-safety oversight during a controlled buy.','Feeding a base station recorder from a wearer.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Body wire microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2037','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2037') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2037');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2038','Broadband detector','A broadband detector is a counter-surveillance instrument that measures total radio-frequency energy across a wide band to reveal nearby transmitters such as covert bugs, regardless of exact frequency. Because it responds to summed field strength rather than tuned channels, it is strongest close to a transmitter and cannot by itself identify the emitter.','A broadband detector measures radio energy over a wide range at once. It does not tune to one station. It shows when strong radio energy is near. Bug sweepers use it to find hidden transmitters. It works best up close.','It gives a fast, frequency-agnostic way to sense the presence of an active radio transmitter during a bug sweep.','A sweeper watches the detector''s level rise near a wall, then narrows the source with a tuned receiver or spectrum analyzer.','Counter-surveillance',ARRAY['Bug sweep','Carrier detection','Counter-surveillance','Electronic countermeasures','Bug']::text[],ARRAY['Expecting it to name a frequency; it only senses total energy, not which channel.','Missing bursty or very low-power bugs that emit only briefly or weakly.','Being fooled by legitimate nearby radios such as phones and Wi-Fi that also raise the reading.']::text[],ARRAY['Initial walkthrough of a room for hidden transmitters.','Locating a bug by rising field strength.','Screening a vehicle before a sensitive meeting.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Broadband detector');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2038','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2038') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2038');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2039','Buffered recording','Buffered recording, also called pre-record or pre-trigger buffering, continuously holds the most recent audio in a rolling memory buffer so that, when recording is triggered, the saved file begins from a moment before the trigger. It ensures the onset of an event is captured even though an operator or trigger reacts after it starts.','Buffered recording keeps the last few seconds of sound in memory all the time. When you hit record, it also saves what came just before. So you do not lose the start of an event. Many recorders and dashcams use this.','It prevents losing the beginning of a sound event by preserving audio from before the record trigger fires.','With a 10-second pre-buffer, a technician arming capture after a gunshot still retains the shot and the seconds leading up to it.','Recording practice',ARRAY['Continuous recorder','Continuous monitoring','Digital voice recorder','Body recorder','Channel synchronization']::text[],ARRAY['Assuming pre-buffer audio is unlimited; only the buffer length is retained.','Forgetting that a missed trigger means only buffered audio, not the whole event, is kept.','Overlooking that buffer contents are lost on power failure before a save.']::text[],ARRAY['Capturing the onset of a gunshot with pre-trigger memory.','A dashcam saving seconds before an impact.','A voice-activated recorder keeping speech from before it triggered.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Buffered recording');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2039','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2039') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2039');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2040','Bug','A bug is a concealed electronic device that captures audio (and sometimes video) and either transmits it by radio or another channel to a remote listener or stores it locally, used for covert eavesdropping. Bugs range from RF transmitters and telephone taps to devices that exploit a room''s own wiring or a nearby phone.','A bug is a hidden listening device. It picks up sound in a room. It may send that sound out by radio. It may also just store it. People use bugs to eavesdrop in secret.','It exists to secretly capture private conversation or sound and deliver it to someone who is not present.','A counter-surveillance technician hunts a bug by combining RF detection, physical search, and inspection of phone lines and fixtures.','Covert device',ARRAY['Bugging','Bug sweep','Covert microphone','Digital transmitter','Electronic eavesdropping']::text[],ARRAY['Assuming all bugs transmit; some only record locally and emit no radio signal.','Believing a bug must sit near the talker; some tap wiring or use existing devices.','Placing or using a bug without regard to wiretap and consent law, which is often criminal.']::text[],ARRAY['A suspected hidden transmitter in an office.','A counter-surveillance sweep before a sensitive meeting.','Forensic exam of a seized listening device.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bug');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2040','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2040') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2040');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2041','Bug sweep','A bug sweep, part of technical surveillance countermeasures (TSCM), is a systematic search of a room, vehicle, or device for hidden eavesdropping equipment, combining physical inspection, RF spectrum analysis, and examination of wiring, phones, and electronics. Its goal is to detect, locate, and neutralize covert audio or video devices.','A bug sweep is a careful search for hidden listening devices. Experts look by hand and with radio tools. They check walls, phones, and wiring. The aim is to find and remove any bug. It is also called technical surveillance countermeasures, or TSCM.','It protects privacy and sensitive information by finding and removing covert surveillance devices.','A TSCM team scans the RF spectrum, uses a nonlinear junction detector for dormant electronics, and physically inspects fixtures and furniture.','Counter-surveillance',ARRAY['Counter-surveillance','Electronic countermeasures','Broadband detector','Carrier detection','Bug']::text[],ARRAY['Relying only on RF detection, which misses wired or powered-off devices.','Sweeping once and assuming lasting safety; devices can be planted later.','Sweeping openly, which can prompt an adversary to disable a bug temporarily.']::text[],ARRAY['Pre-meeting inspection of a boardroom.','A vehicle check for a tracking or audio device.','A residential sweep after a suspected intrusion.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bug sweep');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2041','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2041') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2041');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2042','Bugging','Bugging is the act of placing and operating concealed listening devices to covertly capture private conversation or sound. As a practice it spans device concealment, signal transmission or storage, and later retrieval, and it is restricted by wiretap and privacy law in most jurisdictions.','Bugging means secretly planting listening devices. Someone hides a bug to hear private talk. The device sends or stores the sound. The listener collects it later. Most places have strict laws against it.','Defined neutrally here, it names the practice of secret device-based eavesdropping, which technicians must recognize in order to counter it.','Understanding how bugging is done helps a counter-surveillance technician anticipate where and how devices are hidden during a sweep.','Covert practice',ARRAY['Bug','Bug sweep','Electronic eavesdropping','Covert listening','Counter-surveillance']::text[],ARRAY['Equating bugging only with RF transmitters, ignoring recorders and wired taps.','Assuming property-owner consent makes it legal; wiretap law may still forbid it.','Confusing bugging, which plants devices, with lawful, consented recording.']::text[],ARRAY['Investigating suspected bugging of an office.','Training staff to recognize bugging risks.','Assessing a threat model before a sensitive negotiation.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bugging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2042','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2042') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2042');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2043','Burst transmitter','A burst transmitter is a covert or low-probability-of-intercept transmitter that stores captured audio and sends it in brief, compressed high-speed bursts rather than continuously, reducing its on-air time and the chance of detection. The short transmission duty cycle makes it harder for broadband detectors and sweepers to catch it while it is emitting.','A burst transmitter saves sound, then sends it in quick bursts. It stays silent most of the time. Short bursts are hard to catch. This helps a bug avoid detection. Sweepers may miss it between bursts.','It minimizes detectable on-air time so a covert link is harder to find and intercept.','A sweeper counters burst devices by logging the spectrum over time, since a momentary spike may be the only clue.','Covert device',ARRAY['Digital transmitter','Bug','Carrier detection','Broadband detector','Cellular audio transmitter']::text[],ARRAY['Assuming continuous monitoring will catch it; bursts are brief and intermittent.','Ignoring the need for long-duration spectral logging to detect it.','Confusing burst transmission with ordinary packetized digital radio.']::text[],ARRAY['A low-probability-of-intercept bug in a monitored area.','Spectrum logging to catch intermittent emissions.','Analyzing a seized device''s transmission pattern.']::text[],'advanced',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Burst transmitter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2043','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2043') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2043');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2044','Carrier detection','Carrier detection is the sensing of a radio-frequency carrier wave to confirm that a transmitter is active on a given frequency, used both in normal receivers (carrier-sense) and in counter-surveillance to locate covert transmitters. It typically relies on measuring energy or a stable spectral line at the carrier frequency.','Carrier detection means sensing a radio signal''s carrier wave. A carrier shows a transmitter is on the air. Receivers use it to know a channel is busy. Sweepers use it to find hidden bugs. It looks for steady energy at a frequency.','It confirms the presence and frequency of an active transmitter, whether to manage channel access or to hunt covert emitters.','A technician sweeping a spectrum analyzer flags a steady carrier at 433 MHz as a candidate covert transmitter for closer inspection.','Counter-surveillance',ARRAY['Broadband detector','Bug sweep','Burst transmitter','Digital transmitter','Continuous monitoring']::text[],ARRAY['Assuming any carrier is a bug; many are licensed, legitimate signals.','Missing spread-spectrum or burst signals that lack a steady, narrow carrier.','Confusing carrier presence with successful demodulation of its content.']::text[],ARRAY['A spectrum sweep flagging an unknown steady carrier.','Carrier-sense in a receiver before it transmits.','Confirming a suspected bug''s operating frequency.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Carrier detection');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2044','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2044') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2044');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2045','Cellular audio transmitter','A cellular audio transmitter is a device that captures audio and relays it over a cellular (mobile) network to a remote listener, using a SIM and the carrier''s data or voice channels rather than a local RF link. Because it rides the public network, its effective range is limited only by coverage and it emits no distinctive local surveillance carrier.','A cellular audio transmitter sends captured sound over the mobile phone network. It uses a SIM card like a phone. The listener can be anywhere with coverage. It has no short local radio link to find. That makes it hard to detect by normal sweeps.','It provides long-range, network-based audio relay without a dedicated local transmitter that a nearby sweep could easily detect.','A sweeper checks for unexpected cellular emissions and inspects devices for hidden SIMs, since a broadband RF sweep alone may miss network traffic.','Covert device',ARRAY['Digital transmitter','Bluetooth audio','Base station','Bug','Burst transmitter']::text[],ARRAY['Assuming a standard bug sweep detects it; it blends into normal cellular traffic.','Believing its range is limited; it works anywhere with network coverage.','Overlooking a hidden SIM or data module during a physical search.']::text[],ARRAY['A covert device relaying audio over 4G or 5G.','Sweeping for unexpected cellular activity in a room.','Forensic exam of a seized cellular listening device.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cellular audio transmitter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2045','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2045') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2045');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2046','Channel synchronization','Channel synchronization is the alignment in time, and often in sample clock, of two or more audio channels or streams so that their samples correspond to the same instants, essential for multichannel recording, array processing, and comparing evidential recordings. Misalignment of even a few samples degrades beamforming, stereo imaging, and time-difference analysis.','Channel synchronization keeps multiple audio channels lined up in time. Each channel''s samples must match the same moments. If they drift apart, arrays and stereo break down. Forensic time comparisons also fail. So recorders share a clock or reference.','It guarantees that multichannel audio shares a common time base, which array processing and time-of-arrival analysis depend on.','A technician locks multiple recorders to one word clock or timecode so a later time-difference-of-arrival calculation stays valid.','Signal handling',ARRAY['Beamforming array','Beam steering','Continuous recorder','Base station','Directional pickup']::text[],ARRAY['Assuming separate recorders stay in sync; free-running clocks drift over time.','Ignoring sample-level offsets that ruin beamforming and time-difference-of-arrival estimates.','Confusing a loose start together with true sample-clock synchronization.']::text[],ARRAY['Locking a mic array to one sample clock.','Aligning body-wire and fixed recordings for analysis.','Time-difference-of-arrival source location from synced channels.']::text[],'advanced',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Channel synchronization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2046','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2046') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2046');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2047','Communications intelligence (COMINT)','Communications intelligence (COMINT) is intelligence derived from intercepting and analyzing foreign communications by parties other than the intended recipients, and is a subdiscipline of signals intelligence (SIGINT). It covers both the content and the externals (traffic metadata) of voice, text, and data communications.','COMINT means learning secrets from other people''s messages. Someone reads or hears talk not meant for them. It covers phone calls, texts, and data. It is one kind of spy work on signals. Nations use it to learn about rivals.','It exists to gather intelligence from foreign or adversary communications, informing security and military decisions.','In this glossary it frames why interception and countermeasures matter; a technician meets COMINT concepts when handling intercepted-audio evidence or protective sweeps.','Intelligence discipline',ARRAY['Electronic eavesdropping','Covert listening','Bug','Counter-surveillance','Electronic countermeasures']::text[],ARRAY['Confusing COMINT (communications) with ELINT (non-communications emissions); both are branches of SIGINT.','Assuming COMINT is only message content; it also includes traffic metadata.','Treating lawful investigative interception and foreign COMINT as the same legal regime.']::text[],ARRAY['Intercepting foreign radio or phone traffic.','Distinguishing COMINT from ELINT in a SIGINT briefing.','Handling intercepted-communication evidence.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Communications intelligence (COMINT)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2047','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2047') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2047');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2048','Concealed microphone','A concealed microphone is a microphone hidden from view, built into an object, clothing, or fixture, so that sound can be captured without the source being aware of the device. Concealment constrains placement, so such microphones often trade fidelity for invisibility and are prone to muffling and handling noise.','A concealed microphone is a hidden mic. It is built into an object or clothing. People nearby do not see it. It captures their sound without notice. Hiding it can hurt sound quality.','It enables discreet audio capture where a visible microphone would be noticed or unwanted.','An investigator hides a lavalier-style microphone in a bag, accepts some muffling, and later notes the concealment when assessing recording quality.','Covert device',ARRAY['Covert microphone','Body wire microphone','Body recorder','Bug','Directional pickup']::text[],ARRAY['Assuming concealment does not affect sound; hiding a mic usually muffles and colors it.','Ignoring handling and fabric noise from clothing concealment.','Recording covertly without checking consent and wiretap law for the jurisdiction.']::text[],ARRAY['A mic hidden in a bag or clothing for an interview.','A fixture-mounted mic for discreet room capture.','Assessing muffling when analyzing a covert recording.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Concealed microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2048','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2048') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2048');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2049','Continuous monitoring','Continuous monitoring is the uninterrupted, real-time listening to or observation of an audio channel or environment, by a person or automated system, as opposed to intermittent or triggered checks. In surveillance it supports live oversight, and in counter-surveillance it means a persistent watch of the RF spectrum or environment.','Continuous monitoring means listening or watching without breaks. A person or system stays on the channel the whole time. It catches events as they happen. This differs from checking now and then. It needs steady staffing or automation.','It ensures events are caught live and in full, supporting real-time response and complete coverage.','A monitoring team keeps a live feed from a body wire, with an operator listening throughout, ready to act on developments.','Surveillance practice',ARRAY['Continuous recorder','Buffered recording','Carrier detection','Covert listening','Base station']::text[],ARRAY['Confusing monitoring (listening) with recording (storing); one may occur without the other.','Assuming automated monitoring never misses events; detectors have gaps and false alarms.','Underestimating the staffing needed to truly monitor without breaks.']::text[],ARRAY['Live oversight of an undercover meeting.','A continuous RF watch during a high-risk event.','Automated alerting on a monitored channel.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Continuous monitoring');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2049','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2049') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2049');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2050','Continuous recorder','A continuous recorder captures audio without interruption over long periods, storing everything on a channel rather than only triggered segments, common in dispatch, call-center, and surveillance logging systems. It contrasts with voice-activated or buffered recorders that store only selected audio.','A continuous recorder saves sound all the time. It does not wait for a trigger. It keeps a full, unbroken record. Emergency dispatch and call centers use these. They capture everything on the channel.','It provides a complete, gap-free record of a channel for later review, evidence, or compliance.','A technician verifies a dispatch continuous recorder''s storage capacity and time stamping so a full shift can be retrieved and authenticated later.','Recording hardware',ARRAY['Continuous monitoring','Buffered recording','Digital voice recorder','Body recorder','Channel synchronization']::text[],ARRAY['Assuming it never overwrites; storage limits force a retention window.','Confusing continuous recording with voice-activated capture.','Overlooking accurate time stamps needed for evidential use.']::text[],ARRAY['Emergency dispatch call logging.','Call-center compliance recording.','Long-duration surveillance channel logging.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Continuous recorder');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2050','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2050') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2050');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2051','Counter-surveillance','Counter-surveillance comprises the measures taken to detect, prevent, and defeat surveillance, including technical surveillance countermeasures (bug sweeps), physical and procedural security, and watching for signs of being observed or bugged. It aims to protect people, spaces, and information from covert observation.','Counter-surveillance means stopping others from spying on you. It includes searching for hidden bugs. It also includes physical and procedural security. People use it to protect private talk. It is the defensive side of surveillance.','It protects privacy and sensitive information by finding and blocking covert observation and eavesdropping.','A counter-surveillance plan combines regular bug sweeps, controlled room access, and staff awareness before sensitive meetings.','Counter-surveillance',ARRAY['Bug sweep','Electronic countermeasures','Broadband detector','Bug','Bugging']::text[],ARRAY['Equating counter-surveillance only with bug sweeps, ignoring procedures and physical security.','Treating one sweep as permanent protection.','Publicizing measures, which tells an adversary how to adapt.']::text[],ARRAY['Protecting a boardroom before merger talks.','Securing a residence after a suspected intrusion.','An ongoing program for a high-risk executive.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Counter-surveillance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2051','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2051') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2051');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2052','Covert audio','Covert audio refers to the secret capture, transmission, or recording of sound without the knowledge of those being recorded, and encompasses the devices, links, and practices involved. It is defined here neutrally; lawful use depends on jurisdiction-specific consent and wiretap requirements.','Covert audio means capturing sound in secret. The people recorded do not know. It covers hidden mics, bugs, and recorders. Whether it is legal depends on local law. Consent rules vary by place.','The term groups the tools and methods for secret sound capture, which technicians must understand to use lawfully or to counter.','A technician evaluating a covert-audio recording assesses device type, capture quality, and whether consent and wiretap requirements were met.','Covert audio',ARRAY['Covert recording','Covert listening','Covert microphone','Bug','Concealed microphone']::text[],ARRAY['Assuming covert audio is always illegal or always legal; it depends on jurisdiction and consent.','Confusing covert (secret) capture with merely discreet, consented recording.','Underrating the quality problems caused by concealment and hidden placement.']::text[],ARRAY['Assessing a covert recording offered as evidence.','Advising on lawful consensual monitoring.','Countering covert audio through a sweep.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Covert audio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2052','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2052') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2052');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2053','Covert listening','Covert listening is the secret, real-time interception of conversation or sound without the participants'' knowledge, whether by ear, a live radio link from a bug, or a remote monitor. It is the live-monitoring aspect of eavesdropping, distinct from merely recording for later review.','Covert listening means secretly hearing talk as it happens. The people do not know they are heard. It may use a hidden mic and radio link. A listener follows in real time. It differs from just recording for later.','It provides real-time awareness of private conversation, for intelligence, investigation, or (unlawfully) intrusion.','A monitoring officer covertly listens to a live body-wire feed, ready to respond, while a separate recorder preserves the audio.','Covert practice',ARRAY['Covert audio','Covert recording','Electronic eavesdropping','Continuous monitoring','Bug']::text[],ARRAY['Confusing covert listening (live) with covert recording (stored for later).','Assuming it always leaves a recording; live listening may not.','Ignoring the consent and wiretap law that governs live interception.']::text[],ARRAY['Live monitoring of a body-wire feed.','Real-time interception during an operation.','Distinguishing live listening from later playback.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Covert listening');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2053','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2053') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2053');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2054','Covert microphone','A covert microphone is a microphone deployed secretly to capture sound without the awareness of those nearby, whether concealed in an object, worn on a body, or built into a bug. As with any hidden mic, concealment constrains placement and can reduce fidelity.','A covert microphone is a mic used in secret. People nearby do not know it is there. It may be hidden in an object or worn. It captures their sound quietly. Hiding it can lower quality.','It enables secret sound capture where any visible microphone would defeat the purpose.','A technician selects a small, sensitive covert microphone and positions it to minimize muffling while staying hidden.','Covert device',ARRAY['Concealed microphone','Body wire microphone','Covert recording','Bug','Covert audio']::text[],ARRAY['Treating covert and concealed as different technologies; the mic is ordinary, the use is secret.','Assuming hidden placement keeps fidelity; muffling and noise usually rise.','Deploying one without regard to consent and wiretap law.']::text[],ARRAY['A hidden mic feeding a bug or recorder.','Body-worn covert capture in an operation.','Assessing a covert mic''s quality in evidence.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Covert microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2054','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2054') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2054');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2055','Covert recording','Covert recording is the secret storage of audio (or audiovisual) capture without the knowledge or consent of those recorded, for later review or as potential evidence. Its admissibility and legality depend on jurisdiction-specific consent (one-party versus all-party) and wiretap statutes.','Covert recording means secretly saving sound for later. The people recorded do not know. It is stored, not just heard live. Laws on it differ by place. Some require everyone''s consent; some need only one person''s.','It preserves a secret record of events for evidence, investigation, or documentation.','Before relying on a covert recording, a technician documents the device, verifies the file with a hash, and confirms the governing consent law.','Covert practice',ARRAY['Covert audio','Covert listening','Body recorder','Digital voice recorder','Covert microphone']::text[],ARRAY['Assuming a covert recording is automatically admissible; law and authentication both matter.','Confusing one-party and all-party consent rules across jurisdictions.','Failing to hash and document the file, which weakens chain of custody.']::text[],ARRAY['Secretly recording a meeting for evidence.','Assessing a covert file''s admissibility.','Authenticating a covert recording in the lab.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Covert recording');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2055','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2055') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2055');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2056','Digital transmitter','A digital transmitter sends audio as an encoded, and often encrypted, digital bitstream over a radio link rather than as an analog-modulated signal, giving better noise immunity, optional encryption, and resistance to casual interception. In surveillance it may use spread-spectrum or packetized formats that are harder to detect and demodulate than analog FM.','A digital transmitter sends sound as data over radio. It turns audio into bits first. This resists noise and can be encrypted. Casual listeners cannot easily decode it. Many modern wireless mics and bugs use it.','It delivers cleaner, more secure wireless audio and can evade simple analog interception.','A technician chooses a digital transmitter with encryption so a body-wire feed cannot be casually monitored by a scanner.','Wireless audio',ARRAY['Cellular audio transmitter','Burst transmitter','Bluetooth audio','Body wire microphone','Carrier detection']::text[],ARRAY['Assuming digital always means encrypted; encoding and encryption are separate features.','Expecting a simple analog scanner to demodulate a digital link.','Ignoring the added latency that digital encoding brings to live monitoring.']::text[],ARRAY['An encrypted digital body-wire link.','A spread-spectrum wireless mic system.','Analyzing a digital covert transmitter.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Digital transmitter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2056','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2056') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2056');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2057','Digital voice recorder','A digital voice recorder is a compact device that captures speech and stores it as digital audio files, often compressed formats such as MP3 or WMA, on internal or removable memory, widely used for notes, interviews, dictation, and covert recording. Compression and automatic gain control can introduce artefacts that matter in forensic analysis.','A digital voice recorder is a small device that records speech to memory. It saves sound as digital files. Many use compression like MP3. People use them for notes and interviews. They are also used to record secretly.','It provides an easy, portable way to record and store voice for later playback or documentation.','A forensic examiner notes the recorder''s file format and compression, since MP3 and automatic gain control can affect authentication and enhancement.','Recording hardware',ARRAY['Body recorder','Continuous recorder','Covert recording','Buffered recording','Digital transmitter']::text[],ARRAY['Assuming files are uncompressed; many recorders use lossy formats by default.','Overlooking automatic gain control, which alters levels and complicates analysis.','Editing the original file instead of working on a verified copy.']::text[],ARRAY['Interview and dictation capture.','Covert speech recording.','Forensic exam of a recorder''s files.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Digital voice recorder');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2057','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2057') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2057');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2058','Directional pickup','Directional pickup is the property of a microphone or array by which sensitivity varies with the direction of arriving sound, favouring a target direction and rejecting others, quantified by the polar pattern and the directivity index (DI). A higher DI means stronger rejection of off-axis sound and better reach toward a distant source in noise.','Directional pickup means a mic hears best from one direction. Sound from the front is favoured. Sound from the sides and back is reduced. This helps capture a target in noise. Shotgun mics and arrays do this strongly.','It improves capture of a wanted source over background noise and reverberation by rejecting off-axis sound.','A hypercardioid microphone has a directivity factor of about 4, giving a directivity index near 6 dB, since 10*log10(4) is about 6 dB of on-axis advantage over an omni.','Microphone directivity',ARRAY['Beamforming microphone','Beamforming array','Beam steering','Concealed microphone','Covert microphone']::text[],ARRAY['Assuming a directional mic ignores all off-axis sound; it only attenuates it.','Confusing the polar pattern with the frequency response; both matter.','Expecting the same directivity at all frequencies; patterns broaden at low frequencies.']::text[],ARRAY['A shotgun mic capturing a distant talker.','Choosing a polar pattern to reject room noise.','Comparing the DI of a cardioid versus a hypercardioid.']::text[],'intermediate','DI = 10*log10(Q)','The directivity index in decibels equals ten times the base-ten logarithm of the directivity factor, which is the ratio of on-axis intensity to the average intensity over all directions for the same total response.','bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Directional pickup');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2058','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2058') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2058');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2059','Electronic countermeasures','Electronic countermeasures (ECM) are actions taken to prevent or degrade an adversary''s effective use of the electromagnetic spectrum, classically a division of electronic warfare covering jamming, deception, and denial (now often termed electronic attack in current U.S. joint doctrine). In the surveillance and TSCM context the term is also used loosely for measures that defeat eavesdropping devices, such as audio masking or transmitter jamming.','Electronic countermeasures block or spoil an enemy''s use of radio. They include jamming and deception. This is part of electronic warfare. In bug work, the term also means defeating listening devices. Examples are jamming a bug or masking speech.','It denies an adversary reliable use of the spectrum, whether to protect forces in electronic warfare or to defeat covert eavesdropping.','To protect a meeting, a team might use audio masking to cover speech and, only where lawful, jam a suspected transmitter''s frequency.','Counter-surveillance',ARRAY['Counter-surveillance','Bug sweep','Broadband detector','Carrier detection','Electronic eavesdropping']::text[],ARRAY['Confusing the strict military ECM meaning (electronic warfare) with the loose TSCM usage.','Assuming jamming is lawful; deliberate RF jamming is illegal in most jurisdictions.','Believing masking removes a bug; it only obscures the audio, not the device.']::text[],ARRAY['Jamming or deceiving enemy radar or comms in electronic warfare.','Audio masking to protect a sensitive meeting.','Neutralizing a detected transmitter.']::text[],'advanced',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Electronic countermeasures');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2059','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2059') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2059');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2060','Electronic eavesdropping','Electronic eavesdropping is the use of electronic devices such as microphones, bugs, wiretaps, or interceptors to secretly listen to or record private communication without consent. It is the technologically assisted form of eavesdropping and is restricted by wiretap and privacy law in most jurisdictions.','Electronic eavesdropping means secretly listening with devices. It uses bugs, mics, or wiretaps. The target does not consent. It captures private talk. Most places have strict laws against it.','Described neutrally, it names secret device-based interception of communication, which technicians must recognize and counter.','A counter-surveillance technician maps likely device types, entry points, and transmission paths, then sweeps to detect electronic eavesdropping.','Covert practice',ARRAY['Covert listening','Bug','Bugging','Electronic countermeasures','Counter-surveillance']::text[],ARRAY['Confusing electronic eavesdropping (devices) with ordinary overhearing.','Assuming one party''s consent always makes it legal; laws vary widely.','Believing only RF bugs count, ignoring wiretaps and software interception.']::text[],ARRAY['A wiretap or bug intercepting private calls.','Assessing eavesdropping threats before a sweep.','Forensic review of an intercepted conversation.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Electronic eavesdropping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2060','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2060') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2060');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2061','Electronic surveillance','The monitoring or interception of communications and ambient sound using electronic devices such as microphones, radio bugs, wiretaps, or receivers, together with any recording of the intercepted signals. It spans lawful, authorized operations and unlawful eavesdropping.','Electronic surveillance means using devices to listen in on people. It can catch phone calls, room sound, or radio signals. Recordings are often kept for later. Laws control when it is allowed.','It exists to gather audio or communications intelligence for law enforcement, national security, or investigation, subject to legal authorization.','A technician installs and maintains approved recording gear on a monitored line, keeping the captured audio clear, time-stamped, and preserved for possible evidence.','Surveillance concept',ARRAY['Audio surveillance','Electronic eavesdropping','Audio interception','Listening device','Technical surveillance']::text[],ARRAY['Assuming recording others is always legal; consent and wiretap rules differ by jurisdiction.','Confusing lawful, authorized surveillance with illegal eavesdropping.','Thinking surveillance means only wiretapping, not room audio or radio interception.']::text[],ARRAY['A court-authorized wiretap on a suspect''s phone line.','A workplace monitored with the owner''s lawful consent.','An intelligence unit intercepting radio communications.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Electronic surveillance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2061','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2061') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2061');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2062','Electronic surveillance countermeasures (ESCM)','The techniques and equipment used to detect, locate, and neutralize unauthorized electronic surveillance devices such as hidden microphones, radio transmitters, and wiretaps. The discipline overlaps heavily with technical surveillance counter-measures (TSCM).','These are methods to find hidden bugs and taps. Experts search a room for secret microphones and transmitters. They use radio detectors and physical checks. The goal is to protect private talks.','It exists to safeguard privacy and sensitive information by finding and removing covert listening devices.','A technician runs a physical and radio-frequency sweep of a room, using an RF detector and a nonlinear junction detector to reveal concealed electronics.','Counter-surveillance',ARRAY['Technical surveillance counter-measures (TSCM)','Bug sweep','Nonlinear junction detector (NLJD)','RF detector','Counter-surveillance']::text[],ARRAY['Confusing ESCM (defensive detection) with offensive electronic countermeasures like jamming.','Assuming one radio sweep finds every device; passive or wired bugs emit no signal.','Believing consumer ''bug detector'' apps reliably find professional devices.']::text[],ARRAY['Sweeping a boardroom before a confidential meeting.','Checking a hotel room used for sensitive negotiations.','A counter-intelligence team clearing a secure facility.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Electronic surveillance countermeasures (ESCM)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2062','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2062') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2062');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2063','Electronic sweep','A systematic inspection of a room, vehicle, or object to detect covert electronic surveillance equipment, combining physical search with radio-frequency and other electronic detection methods. It is a core activity of technical surveillance counter-measures.','A sweep is a careful search for hidden bugs. A technician checks a space with radio detectors and by eye. They look for secret microphones and transmitters. It helps keep meetings private.','It exists to confirm whether a space is free of eavesdropping devices before sensitive conversations occur.','The technician scans the radio spectrum for suspicious signals, inspects furniture and fixtures, and uses a nonlinear junction detector to reveal hidden circuits.','Counter-surveillance',ARRAY['Bug sweep','Technical surveillance counter-measures (TSCM)','RF spectrum analyzer','Nonlinear junction detector (NLJD)','Electronic surveillance countermeasures (ESCM)']::text[],ARRAY['Relying only on a radio sweep, missing wired or recording-only devices.','Sweeping once and assuming the area stays clean afterward.','Overlooking everyday objects that can hide a device.']::text[],ARRAY['Clearing a conference room before a merger discussion.','Checking a rental car used by an executive.','Routine sweeps of a secure government office.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Electronic sweep');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2063','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2063') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2063');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2064','Encrypted transmitter','A covert or communications audio transmitter that digitizes and encrypts its signal before radio transmission, so intercepted audio cannot be understood without the decryption key. Encryption commonly applies a standardized cipher such as AES to the digitized audio stream.','This transmitter scrambles sound before sending it by radio. Only a receiver with the right key can unscramble it. That stops others from hearing the audio. It protects the link from eavesdroppers.','It exists to keep a wireless audio link private, preventing interception from recovering intelligible speech.','A technician pairs transmitter and receiver with a shared key, then checks that the recovered audio is clear while a nearby scanner captures only noise.','Covert device',ARRAY['Digital transmitter','RF transmitter','Audio transmitter','Frequency hopping','Spread spectrum']::text[],ARRAY['Assuming any digital transmitter is encrypted; digital and encrypted are different.','Thinking encryption hides the transmission itself — the radio signal is still detectable.','Forgetting that a lost or weak key defeats the protection.']::text[],ARRAY['A body-worn wire that must resist interception during an operation.','Secure two-way audio between a surveillance team and a base.','Protecting a wireless microphone feed from casual scanning.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Encrypted transmitter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2064','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2064') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2064');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2065','Event-triggered recorder','A recorder that starts capturing only when a defined event occurs — such as sound above a threshold, a keyword, motion, or an external signal — rather than recording continuously. Voice-activated recording (VOX) is a common example.','This recorder stays idle until something happens. A loud sound or a voice can start it. That saves storage and battery. It skips long silent periods.','It exists to conserve storage and power and to capture only relevant activity, easing later review.','A technician sets the trigger so normal speech starts recording but background hum does not, then checks that no important audio is cut at the start.','Recording device',ARRAY['Voice-activated recorder (VOX)','Buffered recording','Continuous recorder','Miniature recorder','Digital voice recorder']::text[],ARRAY['Setting the threshold so high that quiet speech is missed.','Forgetting pre-trigger buffering, so the first word is cut off.','Assuming a triggered gap proves nothing was said, when for evidence continuous recording is preferred.']::text[],ARRAY['A long unattended stakeout with limited storage.','Capturing only spoken activity in a monitored room.','Battery-limited covert recording over many hours.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Event-triggered recorder');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2065','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2065') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2065');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2066','Evidence recorder','A recording device used to capture audio intended as legal evidence, built to preserve the original signal with reliable time-stamping and secure storage and to support later authentication and chain of custody. It prioritizes integrity over convenience features.','This is a recorder made for legal use. It saves the original sound without changes. It adds accurate time stamps and secure storage. That helps prove the audio is genuine in court.','It exists to produce recordings that can be trusted as authentic and unaltered when presented as evidence.','An investigator records an interview, stores the original file read-only, and logs who handled it, following forensic best practice for chain of custody.','Recording device',ARRAY['Evidence recording','Time-stamped recording','Audio authentication','Recording continuity','Digital voice recorder']::text[],ARRAY['Editing or converting the original file instead of working on a copy.','Assuming the built-in clock is accurate without checking it.','Believing any recorder''s output is automatically admissible.']::text[],ARRAY['Recording a custodial interview for later court use.','Capturing a controlled undercover meeting.','Documenting an emergency call.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Evidence recorder');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2066','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2066') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2066');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2067','Evidence recording','An audio recording made and handled so it can be admitted as legal evidence, meaning its origin, integrity, and continuity of custody can be demonstrated. Forensic guidelines require working from preserved originals and documenting every processing step.','This is a recording used to prove facts in court. Its source and history must be clear. The original is kept safe and unchanged. Any cleanup is done on copies and written down.','It exists to give courts audio they can rely on as authentic and traceable.','A technician preserves the original file, makes a verified copy for enhancement, and records each step so the work can be repeated and defended.','Forensic concept',ARRAY['Evidence recorder','Audio authentication','Audio integrity','Recording continuity','Recording authentication']::text[],ARRAY['Enhancing the only copy and losing the original.','Skipping documentation of the processing chain.','Assuming louder or clearer automatically means more credible in court.']::text[],ARRAY['Preparing a covert recording for trial.','Authenticating a recording challenged as edited.','Enhancing a threatening voicemail for a jury.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Evidence recording');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2067','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2067') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2067');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2068','Far-field microphone','A microphone used to capture sound at a distance from the source, in the acoustic far field where the wavefront is effectively planar and, in free field, sound pressure falls about 6 dB per doubling of distance. Far-field capture typically gives lower level and worse signal-to-noise ratio than close miking.','This microphone picks up sound from far away. In the far field, sound spreads out evenly. Doubling the distance cuts the level about six decibels. So distant capture is quieter and noisier.','It exists to capture sound when the microphone cannot be placed near the source, as in covert or ambient recording.','Moving a mic from 1 m to 2 m from a talker drops the direct level about 6 dB (20·log10(2)), so the technician expects a weaker, noisier signal and plans for enhancement.','Microphone type',ARRAY['Near-field microphone','Ambient recording','Long-range pickup','Parabolic reflector','Directional pickup']::text[],ARRAY['Expecting far-field audio to be as clean as close miking.','Ignoring that room reverberation dominates at large distances.','Confusing the source near/far-field boundary with an array''s near/far-field boundary.']::text[],ARRAY['Recording a conversation across a large room.','Covertly capturing speech from a concealed position.','Ambient monitoring of an open area.']::text[],'intermediate','ΔL = 20·log10(r2 / r1)','The free-field level change equals twenty times the base-ten log of the ratio of the two distances.','bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Far-field microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2068','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2068') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2068');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2069','Fiber optic microphone','A microphone that senses sound with light rather than electrical transduction, typically by detecting sound-induced movement of a reflective diaphragm through changes in reflected or interferometric light carried on optical fiber. Because the sensing element carries no current and little metal, it is immune to electromagnetic interference and hard to detect electronically.','This microphone uses light instead of electricity to sense sound. Sound moves a tiny reflector, and the light change is read out. It ignores electrical interference. It also has no radio signal to detect.','It exists for sensing in strong electromagnetic fields, MRI rooms, or settings where a powered, metal microphone is unsuitable or detectable.','A technician runs the optical fiber to a remote opto-electronic unit, leaving only the small passive optical sensor near the sound source.','Microphone type',ARRAY['Laser Doppler microphone','Concealed microphone','Near-field microphone','MEMS microphone array']::text[],ARRAY['Confusing a fiber optic microphone with a laser listening device aimed at a window.','Assuming it needs no electronics — the readout unit is electronic.','Thinking optical sensing lets it hear through walls.']::text[],ARRAY['Audio capture inside an MRI scanner room.','High-voltage or industrial sites with strong interference.','Placement where an RF or metal detector would find a normal mic.']::text[],'advanced',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Fiber optic microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2069','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2069') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2069');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2070','Flash recorder','An audio recorder that stores captured audio on solid-state flash memory rather than tape or disk, giving small size, no moving parts, and rugged storage. Nearly all modern covert and evidence recorders are flash-based solid-state devices.','This recorder saves sound onto flash memory chips. It has no moving parts. That makes it small, quiet, and rugged. Most small modern recorders work this way.','It exists to store audio compactly and reliably, which suits covert, field, and evidence recording.','A technician picks a card of adequate size and speed, records in an uncompressed format for evidence, and copies files off before reusing the card.','Recording device',ARRAY['Solid-state recorder','Miniature recorder','Digital voice recorder','Pocket recorder','Multi-channel recorder']::text[],ARRAY['Assuming deleted or overwritten flash data is always unrecoverable.','Using heavily compressed formats for evidence audio.','Reusing a card without securely archiving prior recordings.']::text[],ARRAY['Body-worn covert recording during a meeting.','Field capture of an interview for later analysis.','Long unattended recording on a large memory card.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Flash recorder');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2070','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2070') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2070');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2071','Forensic acoustics','The scientific analysis of acoustic events in recordings or environments for legal purposes — determining sound sources, timing, positions, and propagation, such as analyzing gunshots, background sounds, or scene acoustics. It is the branch of forensic audio focused on the physical behavior of sound rather than speech content.','This is the study of sounds for legal cases. Experts work out what made a sound and when. They may study gunshots or background noises. The physics of sound helps rebuild events.','It exists to reconstruct events and test claims using the physical evidence carried in recorded or measured sound.','An analyst measures the time between a gunshot''s muzzle blast and its echoes on a recording to estimate the shooter''s distance or position.','Forensic concept',ARRAY['Forensic audio','Audio forensics','Acoustic localization','Sound source localization','Audio authentication']::text[],ARRAY['Confusing forensic acoustics (sound events and physics) with speech-focused forensic audio.','Treating recorded levels as calibrated absolute sound pressure.','Ignoring how recording gear and codecs distort acoustic cues.']::text[],ARRAY['Estimating gunshot distance from an emergency-call recording.','Testing whether two shots came from the same weapon or place.','Analyzing background sounds to check where a recording was made.']::text[],'advanced',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Forensic acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2071','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2071') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2071');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2072','Forensic audio','The scientific field concerned with the acquisition, authentication, enhancement, and analysis of audio recordings for legal or investigative use, covering both speech and non-speech content. Core tasks include verifying integrity, improving intelligibility, transcribing speech, and comparing speakers.','This field handles audio used in legal cases. Experts check if a recording is genuine. They clean it up to hear speech better. They may also compare voices or make transcripts.','It exists to turn imperfect recordings into reliable, defensible evidence and analysis for courts and investigations.','An examiner authenticates a recording, enhances speech buried in noise, and prepares a documented transcript for use at trial.','Forensic concept',ARRAY['Audio forensics','Forensic acoustics','Audio authentication','Speaker recognition','Voice enhancement']::text[],ARRAY['Assuming enhancement can add detail that was never captured.','Editing the original instead of a working copy.','Believing screen-style ''cleanup'' can always recover intelligible speech.']::text[],ARRAY['Enhancing a noisy covert recording for a jury.','Authenticating a recording challenged as edited.','Comparing a suspect''s voice to a recorded threat.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Forensic audio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2072','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2072') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2072');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2073','Formant analysis','The measurement of formants — the resonant frequency peaks of the vocal tract that shape speech, especially vowels — used in phonetics and forensic speaker comparison. The lowest formants (F1, F2, F3) largely determine vowel identity and carry speaker-dependent information.','Formants are the strong frequency bands in a voice. They come from resonances in the throat and mouth. They shape vowel sounds. Experts measure them to compare speakers.','It exists to characterize vowels and speaker-specific vocal-tract properties for phonetic and forensic analysis.','An examiner measures F1 and F2 of a suspect''s vowels on a spectrogram and compares them with the questioned recording; a neutral tract of length 0.17 m gives F1 ≈ 350/(4·0.17) ≈ 515 Hz.','Speech analysis',ARRAY['Harmonic analysis','Phonetic analysis','Spectral comparison','Voiceprint','Speaker recognition']::text[],ARRAY['Confusing formants (vocal-tract resonances) with harmonics (source frequencies).','Comparing formants across different phone or codec conditions without caution.','Treating formants alone as a unique ''voiceprint'' identity.']::text[],ARRAY['Forensic speaker comparison between two recordings.','Vowel analysis in a phonetics study.','Checking disguise or accent in a questioned voice.']::text[],'advanced','F_n = (2n − 1)·c / (4·L)','For a uniform tube closed at one end, the nth formant equals an odd multiple of the sound speed divided by four tube lengths.','bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Formant analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2073','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2073') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2073');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2074','Frequency hopping','A spread-spectrum transmission method in which the carrier frequency rapidly changes among many channels in a pseudo-random sequence known to both transmitter and receiver. It resists interception, jamming, and interference because energy at any single frequency appears only briefly.','This method keeps changing the radio frequency very fast. Both ends follow the same secret pattern. A listener on one channel hears only short bursts. That makes the signal hard to catch or jam.','It exists to make a radio link robust and hard to intercept or jam by spreading it across many frequencies over time.','A technician confirms transmitter and receiver share the same hop set and timing, then checks that a fixed-tuned scanner catches only brief, intermittent energy.','RF technique',ARRAY['Spread spectrum','Encrypted transmitter','Burst transmitter','Carrier detection','Narrowband transmission']::text[],ARRAY['Assuming hopping alone encrypts the audio; it protects more than it hides content.','Confusing frequency hopping with direct-sequence spread spectrum.','Thinking a slow radio sweep will always catch it.']::text[],ARRAY['A covert transmitter designed to evade a countersurveillance scan.','Bluetooth links, which hop across the 2.4 GHz band.','Military and secure two-way radios.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Frequency hopping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2074','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2074') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2074');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2075','GSM audio transmitter','A covert audio device that relays captured audio over the GSM cellular network — effectively a hidden phone that auto-answers or calls out, sending room audio to a remote listener. It exploits standard 2G/GSM digital cellular infrastructure rather than a dedicated short-range radio link.','This is a hidden bug that works like a cell phone. It uses the mobile network to send room sound far away. A listener calls in or receives audio from anywhere. It needs a SIM card and cell coverage.','It exists to relay audio over unlimited distance using existing cellular networks instead of a short-range radio link.','During a sweep, a technician watches for a device that periodically registers with or transmits to a cell tower, since it emits characteristic GSM bursts.','Covert device',ARRAY['Cellular audio transmitter','LTE transmitter','Audio transmitter','RF transmitter','Listening device']::text[],ARRAY['Assuming it emits a constant signal; it may transmit only during a call.','Thinking it needs local range — it works anywhere with coverage.','Overlooking its distinctive cellular bursts during a sweep.']::text[],ARRAY['A concealed bug relaying a boardroom to a distant listener.','Countersurveillance detecting unexpected cellular emissions.','Investigating audio leakage from a compromised office.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='GSM audio transmitter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2075','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2075') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2075');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2076','Harmonic analysis','The examination of a signal''s harmonic content — components at integer multiples of a fundamental frequency — used to study periodic sounds such as voiced speech, hums, and machinery. In forensic audio it helps identify sources like electrical hum, estimate pitch, or reveal tampering artifacts.','Voiced sounds and hums contain a base tone plus overtones. The overtones sit at whole-number multiples of the base. Harmonic analysis measures these parts. It helps find pitch, hum, or edits.','It exists to characterize periodic signals by their fundamental and overtones for identification and diagnostics.','Spotting a 60 Hz mains hum with harmonics at 120 and 180 Hz lets an analyst identify and notch out the electrical interference.','Signal analysis',ARRAY['Formant analysis','Pitch analysis','Spectral comparison','Waveform comparison','Adaptive filtering']::text[],ARRAY['Confusing harmonics (integer multiples) with formants (tract resonances).','Assuming all overtones are perfectly harmonic; real sounds can be inharmonic.','Mistaking mains-harmonic hum for part of the voice.']::text[],ARRAY['Removing electrical hum and its harmonics from a recording.','Analyzing machinery or engine sound on a recording.','Detecting periodic artifacts that suggest editing.']::text[],'intermediate','f_n = n·f_0','The frequency of the nth harmonic equals n times the fundamental frequency.','bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Harmonic analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2076','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2076') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2076');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2077','Hidden microphone detection','The process of locating concealed microphones — wired, recording-only, or part of a transmitter — using physical search, radio-frequency detection, nonlinear junction detection, and inspection for wiring or acoustic leakage. Passive wired and recording-only microphones emit no radio signal and require non-RF methods.','This means finding secret microphones in a space. Some bugs send a radio signal you can detect. Others only record and give off no signal. Finding those needs a physical search and special detectors.','It exists to protect privacy by revealing concealed audio pickups before or after sensitive conversations.','A technician uses a nonlinear junction detector to reveal electronics inside walls or objects, since it responds even to powered-off or non-transmitting devices.','Counter-surveillance',ARRAY['Hidden transmitter detection','Nonlinear junction detector (NLJD)','Bug sweep','Concealed microphone','Technical surveillance counter-measures (TSCM)']::text[],ARRAY['Relying on radio detection alone, which misses wired and recording-only mics.','Assuming a powered-off device cannot be found.','Overlooking microphones hidden in everyday objects.']::text[],ARRAY['Sweeping an office suspected of being bugged.','Checking a vehicle for concealed audio devices.','Inspecting a hotel room before a private meeting.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hidden microphone detection');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2077','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2077') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2077');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2078','Hidden transmitter detection','The process of locating covert radio transmitters (bugs) by detecting their emissions, using broadband RF detectors, spectrum analyzers, and receivers to find unexpected signals in a protected area. It is complicated by low-power, burst, frequency-hopping, and encrypted devices that minimize their radio footprint.','This means finding hidden radio bugs by their signals. Detectors scan the airwaves for strange transmissions. Some bugs are easy to spot. Others send weak or brief bursts that are hard to catch.','It exists to reveal transmitting eavesdropping devices so they can be located and removed.','A technician watches a spectrum analyzer while moving through a room, looking for a signal that strengthens near a suspected device.','Counter-surveillance',ARRAY['Hidden microphone detection','RF detector','RF spectrum analyzer','Broadband detector','Burst transmitter']::text[],ARRAY['Assuming a bug always transmits continuously.','Missing burst or frequency-hopping devices with a slow sweep.','Ignoring that everyday Wi-Fi and cellular traffic clutter the spectrum.']::text[],ARRAY['Locating a transmitting bug during a room sweep.','Tracking a signal that appears only intermittently.','Distinguishing a covert transmitter from normal wireless traffic.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hidden transmitter detection');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2078','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2078') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2078');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2079','ISM-band transmitter','A transmitter operating in an Industrial, Scientific, and Medical (ISM) radio band — such as 433 MHz (ITU Region 1), 902–928 MHz, 2.4 GHz, or 5.8 GHz — which are allocated for low-power unlicensed use. Many covert and consumer audio devices use ISM bands because they need no license and blend with common wireless traffic.','This transmitter uses shared radio bands open to everyone. Common ones are 433 MHz, 915 MHz, and 2.4 GHz. No license is needed at low power. Its signal blends in with Wi-Fi and other gadgets.','It exists to send audio on license-free bands, keeping devices legal, cheap, and easy to hide among ordinary wireless signals.','During a sweep, a technician pays close attention to busy ISM bands, since a covert transmitter can hide amid Wi-Fi, Bluetooth, and remote-control traffic.','Covert device',ARRAY['Low-power transmitter','RF transmitter','Frequency hopping','Wi-Fi audio transmission','Bluetooth audio']::text[],ARRAY['Assuming ISM devices are always tiny; power and range vary.','Thinking license-free bands make the captured audio legal to use.','Overlooking a bug because its band is crowded with normal traffic.']::text[],ARRAY['A 2.4 GHz covert transmitter hidden among Wi-Fi devices.','Consumer wireless microphones on ISM bands.','Countersurveillance scanning crowded ISM frequencies.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='ISM-band transmitter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2079','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2079') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2079');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2080','LTE transmitter','A covert audio device that relays captured audio over a 4G LTE cellular data network, streaming or uploading audio to a remote listener rather than using a dedicated short-range radio link. It is a newer counterpart to the GSM audio transmitter, using packet data instead of a 2G voice call.','This bug sends room sound over a 4G data network. It works like a tiny data modem with a microphone. A listener can receive the audio anywhere with coverage. It replaces older 2G phone-based bugs.','It exists to relay audio over long distances using modern cellular data, with better quality and coverage than older 2G devices.','A technician sweeping for it looks for unexpected LTE data activity from a device that should not be transmitting.','Covert device',ARRAY['GSM audio transmitter','Cellular audio transmitter','Encrypted transmitter','Audio uplink','Listening device']::text[],ARRAY['Assuming 2G detection methods fully cover LTE devices.','Thinking data traffic is harmless — it can carry live audio.','Expecting steady emissions when it may stream in bursts.']::text[],ARRAY['A modern cellular bug streaming audio from an office.','Countersurveillance checking for rogue LTE emissions.','Investigating audio leakage over a data connection.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='LTE transmitter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2080','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2080') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2080');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2081','Laser Doppler microphone','A device that recovers sound remotely by aiming a laser at a surface such as a window and measuring the tiny sound-induced vibrations of that surface through the Doppler shift or phase change of the reflected light. It is a covert, non-contact listening technique whose performance depends on surface reflectivity and stability.','This device listens using a laser beam. It aims at a window that vibrates with room sound. The reflected light shifts slightly with each vibration. That shift is turned back into audio.','It exists to capture speech from a distance without placing any device in the target space.','An analyst reflects the beam off a smooth window and reads the vibration velocity; a 1 mm/s surface motion at a 633 nm wavelength gives about a 3.2 kHz Doppler shift to demodulate.','Covert device',ARRAY['Laser vibrometer','Fiber optic microphone','Long-range pickup','Through-wall microphone','Listening device']::text[],ARRAY['Assuming it works on any surface; rough or moving surfaces defeat it.','Confusing it with a fiber optic microphone placed at the source.','Assuming such interception is lawful; it is heavily restricted by wiretap and privacy law.']::text[],ARRAY['Covertly recovering speech via a window''s vibration.','Research demonstrations of optical eavesdropping.','Countersurveillance assessing optical threats to a room.']::text[],'advanced','f_D = 2·v / λ','The Doppler frequency shift equals twice the surface velocity divided by the laser wavelength.','bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Laser Doppler microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2081','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2081') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2081');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2082','Laser vibrometer','A laboratory instrument that measures the velocity and displacement of a vibrating surface without contact, using laser interferometry and the Doppler shift of reflected light. Though designed for vibration measurement, the same principle underlies laser-based acoustic eavesdropping.','This tool measures how a surface vibrates using a laser. It never touches the surface. It reads motion from the shift in the reflected light. Engineers use it to study vibration and sound.','It exists for precise, non-contact vibration and acoustic measurement in engineering, research, and testing.','An engineer points the vibrometer at a loudspeaker cone to map its motion, using the Doppler relation to convert the measured light shift into surface velocity.','Measurement instrument',ARRAY['Laser Doppler microphone','Fiber optic microphone','Harmonic analysis','Waveform comparison','Long-range pickup']::text[],ARRAY['Confusing a metrology vibrometer with a covert laser microphone.','Assuming dull surfaces need no reflective treatment.','Ignoring how bulk motion and speckle noise corrupt readings.']::text[],ARRAY['Measuring loudspeaker cone or panel vibration.','Non-contact modal testing of structures.','Research into surface-vibration audio recovery.']::text[],'advanced','f_D = 2·v / λ','The Doppler frequency shift equals twice the surface velocity divided by the laser wavelength.','bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Laser vibrometer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2082','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2082') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2082');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2083','Listening device','A general term for any device used to overhear or capture audio, especially covertly — including microphones, radio bugs, wiretaps, and recorders. In legal contexts it often specifically means a concealed device used for eavesdropping.','A listening device is any tool used to overhear people. It can be a hidden microphone, a radio bug, or a tap on a line. Often it is concealed. Laws limit its use.','It exists to capture speech or sound for surveillance, evidence, or intelligence, whether openly or covertly.','An investigator selects a device suited to the setting — a body-worn wire, a room bug, or a line tap — within legal limits.','Surveillance concept',ARRAY['Audio bug','Bug','Covert microphone','Concealed microphone','Remote listening device']::text[],ARRAY['Assuming all listening devices transmit; many only record.','Thinking any use is legal; consent and wiretap laws apply.','Equating ''listening device'' only with radio bugs.']::text[],ARRAY['A concealed bug in a room under surveillance.','A body-worn wire during an undercover meeting.','A tap placed on a telephone line.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Listening device');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2083','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2083') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2083');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2084','Listening post','A staffed or automated location where intercepted audio is received, monitored, and recorded, usually remote from the surveillance site and linked to it by radio, wire, or network. It is the receiving end of an audio surveillance system.','A listening post is where the captured audio is received. It sits away from the bugged place. A person or system there monitors and records it. It is the far end of the surveillance link.','It exists to receive, monitor, and record surveillance audio safely away from the target location.','A technician sets up a receiver, recorder, and antenna at the listening post, confirming a clean link before an operation begins.','Surveillance concept',ARRAY['Monitoring station','Base station','Listening device','Live monitoring','Relay station']::text[],ARRAY['Confusing the listening post (receiving end) with the device planted at the target.','Assuming any location works, ignoring radio range and line of sight.','Forgetting the post also needs secure, logged recording.']::text[],ARRAY['A van parked near a surveillance target.','A remote office receiving a relayed audio feed.','A base monitoring several body wires at once.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Listening post');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2084','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2084') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2084');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2085','Live monitoring','The real-time listening to surveillance or recorded audio as it is captured, letting an operator respond immediately, direct an operation, or confirm the recording is working. It contrasts with reviewing recordings after the fact.','Live monitoring means listening as sound is captured, in real time. An operator hears events as they happen. That allows quick decisions. It also confirms the recording is working.','It exists to give operators immediate awareness so they can react during an event and verify capture quality.','An operator wears headphones on the live feed during an undercover meeting, ready to signal the team while a separate recorder preserves the audio.','Monitoring',ARRAY['Active monitoring','Continuous monitoring','Audio monitoring','Listening post','Remote monitoring']::text[],ARRAY['Relying on live monitoring instead of a reliable recording.','Assuming what is heard live is automatically saved as evidence.','Letting live listening distract from safety or the operation.']::text[],ARRAY['Monitoring a wire during an undercover buy.','Watching an audio feed to trigger a response.','Confirming a covert recorder is capturing clearly.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Live monitoring');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2085','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2085') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2085');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2086','Long-range pickup','The capture of sound from a considerable distance using directional or focusing techniques such as parabolic reflectors, shotgun microphones, or large arrays to raise the level and directivity of a distant source. Performance is limited by the inverse-square loss of level with distance and by intervening noise.','This means picking up sound from far away. Dishes, shotgun mics, and arrays focus on the source. They lift the wanted sound above the distance loss. Even so, range is limited by noise.','It exists to capture distant speech or sound when close placement is impossible, as in surveillance or field recording.','Moving from 2 m to 20 m loses about 20 dB (20·log10(10)), so a technician uses a parabolic dish or shotgun mic to recover directivity and level.','Microphone technique',ARRAY['Parabolic reflector','Far-field microphone','Directional pickup','Array microphone','Acoustic zoom']::text[],ARRAY['Expecting clear speech at long range despite heavy background noise.','Assuming a bigger dish always helps at low frequencies — it does not.','Ignoring wind and handling noise that dominate distant capture.']::text[],ARRAY['Capturing a conversation across a field with a parabolic mic.','Wildlife or sports recording at a distance.','Covert pickup from a fixed remote position.']::text[],'intermediate','ΔL = 20·log10(r2 / r1)','The free-field level change equals twenty times the base-ten log of the ratio of the two distances.','bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Long-range pickup');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2086','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2086') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2086');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2087','Low-power transmitter','A radio transmitter operating at very low output power, used in covert audio devices to limit range and reduce the chance of detection while still reaching a nearby receiver. Low power also allows small size and long battery life but restricts range and robustness.','This transmitter sends a weak radio signal on purpose. Low power keeps it small and long-lasting. It only reaches a nearby receiver. A weak signal is also harder to detect.','It exists to relay audio a short distance discreetly, trading range for small size, battery life, and lower detectability.','A technician places the receiver close enough for a reliable link, knowing the weak signal fades quickly with distance and obstacles.','Covert device',ARRAY['ISM-band transmitter','RF transmitter','Audio transmitter','Hidden transmitter detection','Miniature recorder']::text[],ARRAY['Placing the receiver too far, so the weak link drops out.','Assuming low power makes it undetectable, not just harder to find.','Ignoring how walls and bodies further cut the short range.']::text[],ARRAY['A short-range body wire to a nearby van.','A room bug reaching a receiver in the next room.','Countersurveillance searching close-in for a faint signal.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Low-power transmitter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2087','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2087') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2087');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2088','MEMS microphone array','An array of micro-electro-mechanical-system (MEMS) microphones — tiny silicon-chip microphones — arranged with known spacing so their signals can be combined by beamforming to enhance sound from a chosen direction and suppress noise. Their small size, close matching, and low cost make them common in phones, smart speakers, and compact surveillance devices.','This is a group of tiny chip microphones set at known spacing. Combining their signals focuses on one direction. It boosts wanted sound and cuts noise. Phones and smart speakers use these arrays.','It exists to capture directional, cleaner audio from small, cheap, well-matched microphones using beamforming.','Combining four matched MEMS mics can add about 6 dB (10·log10(4)) of signal-to-noise ratio against diffuse noise, plus directional focus from beamforming.','Microphone array',ARRAY['Beamforming array','Array microphone','Beamforming microphone','Sound source localization','Near-field microphone']::text[],ARRAY['Assuming more microphones always help regardless of spacing.','Expecting ideal array gain when mics are mismatched or noise is correlated.','Confusing beamforming direction with physically moving the array.']::text[],ARRAY['A smart speaker isolating a talker across a room.','A compact device focusing on one speaker in a group.','Localizing a sound source with a small array.']::text[],'advanced','G = 10·log10(N)','For spatially white (uncorrelated) noise, the array gain in decibels equals ten times the base-ten log of the number of microphones.','bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='MEMS microphone array');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2088','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2088') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2088');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2089','Miniature recorder','A very small audio recorder designed for concealment or portability, typically solid-state, battery-powered, and capable of long unattended recording. It is a common covert and field recording tool.','This is a very small sound recorder. It runs on battery and stores audio on chips. Its size makes it easy to hide or carry. It can record for a long time unattended.','It exists to capture audio discreetly where a larger recorder would be impractical or noticeable.','An investigator conceals a miniature recorder for a meeting, choosing an uncompressed format and confirming the battery lasts the full session.','Recording device',ARRAY['Pocket recorder','Flash recorder','Solid-state recorder','Digital voice recorder','Body recorder']::text[],ARRAY['Assuming small size means low quality — many record well.','Running out of battery or storage during a long session.','Using heavy compression that harms later forensic analysis.']::text[],ARRAY['A concealed recorder carried to a meeting.','Discreet field capture of an interview.','Long unattended recording in a small space.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Miniature recorder');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2089','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2089') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2089');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2090','Monitoring station','A fixed or mobile facility equipped to receive, monitor, record, and manage one or more surveillance audio feeds, often serving as the central hub of an audio surveillance network. It combines receivers, recorders, and operator positions.','A monitoring station is a base that handles surveillance audio. It receives and records one or more feeds. Operators listen and manage the system there. It is the hub of the network.','It exists to centralize the reception, monitoring, recording, and management of surveillance audio.','A technician configures the station''s receivers and recorders, verifies each feed''s quality and time sync, and logs recordings for later use.','Monitoring',ARRAY['Listening post','Base station','Audio surveillance network','Live monitoring','Relay station']::text[],ARRAY['Confusing a monitoring station (the hub) with a single planted device.','Neglecting time synchronization across multiple feeds.','Assuming monitoring replaces properly preserved recordings.']::text[],ARRAY['A central room managing several building audio feeds.','A mobile unit coordinating an operation''s audio.','A network hub logging multiple surveillance channels.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Monitoring station');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2090','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2090') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2090');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2091','Multi-channel recorder','A multi-channel recorder captures two or more audio inputs at the same time, storing each on its own separate track. The channels share a common clock so they stay time-aligned for later comparison, mixing, or analysis.','This device records several sound sources at once. Each source gets its own track. All tracks start and stop together. This keeps them lined up in time.','It preserves multiple simultaneous sources separately so each can be reviewed, enhanced, or isolated without losing the timing relationship between them.','An investigator feeds several concealed microphones or an array into one multi-channel recorder, then later solos a single track to follow one talker in a crowded room.','Recording device',ARRAY['Solid-state recorder','Continuous recorder','Channel synchronization','Array microphone','Evidence recorder']::text[],ARRAY['Assuming all channels are automatically phase- or sample-aligned when using separate unsynchronized recorders.','Confusing channel count with track count when a device downmixes inputs.','Overlooking that gain must be set per channel to avoid clipping one source.']::text[],ARRAY['Recording a microphone array for later beamforming.','Capturing several room mics as legal evidence.','Documenting a multi-party conversation on separate tracks.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Multi-channel recorder');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2091','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2091') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2091');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2092','Narrowband transmission','Narrowband transmission sends a signal using only a small slice of radio-frequency bandwidth, typically just wide enough to carry speech. Restricting bandwidth concentrates the transmitted power, which extends range and improves spectral efficiency at the cost of audio bandwidth.','This sends a radio signal in a very thin frequency band. The band is just wide enough for speech. Using less bandwidth focuses the power. This helps the signal travel farther.','It lets a low-power voice link reach farther and share crowded spectrum with other users, since each channel occupies little bandwidth.','A surveillance transmitter set to narrowband voice fits in a few kilohertz, so a technician can pack more channels into a band and still get usable range.','RF transmission',ARRAY['RF transmitter','RF link','Spread spectrum','Low-power transmitter','VHF transmitter']::text[],ARRAY['Assuming narrowband always means better audio - it trades fidelity for range and channel count.','Confusing narrowband with low power; they are independent choices.','Ignoring that too-narrow filtering distorts speech and reduces intelligibility.']::text[],ARRAY['Choosing a voice-only link to maximize range.','Fitting many channels into limited spectrum.','Comparing narrowband against wideband or spread-spectrum links.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Narrowband transmission');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2092','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2092') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2092');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2093','Near-field microphone','A near-field microphone is placed close to a sound source, well within its acoustic near field, so that direct sound strongly dominates over room reflections and background noise. The short source distance yields a high direct-to-reverberant ratio, though directional types also show a proximity bass boost.','This microphone sits very close to what it records. Being close, it hears mostly the direct sound. Room echoes and noise stay weaker. Directional close mics also add extra bass.','Close placement maximizes the wanted signal against noise and reverberation, giving cleaner capture of speech or a single source.','To catch one talker in a noisy room, a technician places the mic near the mouth; halving the distance to the source raises the direct level by about 6 dB.','Microphone',ARRAY['Far-field microphone','Omnidirectional pickup','Directional pickup','Concealed microphone','Pin microphone']::text[],ARRAY['Forgetting proximity effect boosts low frequencies on directional mics placed very close.','Assuming a close mic removes all room sound - it only reduces it.','Overloading the capsule by placing a sensitive mic too close to a loud source.']::text[],ARRAY['Capturing a single talker in a reverberant room.','Improving speech clarity for later transcription.','Reducing pickup of nearby machinery noise.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Near-field microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2093','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2093') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2093');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2094','Nonlinear junction detector (NLJD)','A nonlinear junction detector transmits a microwave probe signal and listens for harmonic energy re-radiated by the semiconductor junctions inside electronic circuits. Because diodes and transistors respond nonlinearly, they return second-harmonic energy even when the device is switched off, letting a sweep locate hidden electronics.','This tool sends out a radio beam and listens for echoes. Electronic parts send back a special harmonic tone. This works even if the device is turned off. So it can find hidden bugs and recorders.','It helps a counter-surveillance technician find concealed electronics, such as bugs or recorders, that may be powered down and invisible to a radio-signal detector.','During a sweep the operator scans walls and furniture; a strong second-harmonic return flags a real semiconductor, while a dominant third harmonic usually means a corroded metal joint, not a device.','Countermeasure',ARRAY['Bug sweep','Counter-surveillance','TSCM','RF detector','Electronic countermeasures']::text[],ARRAY['Reading every response as a bug - corrosion and metal-to-metal contacts give false ''rusty bolt'' returns.','Assuming a powered-off device is undetectable; its junctions still re-radiate.','Confusing an NLJD with an RF detector, which only finds active transmitters.']::text[],ARRAY['Sweeping a room for switched-off recorders.','Locating electronics hidden inside walls or objects.','Confirming a suspect device found by other means.']::text[],'advanced',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Nonlinear junction detector (NLJD)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2094','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2094') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2094');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2095','Omnidirectional pickup','Omnidirectional pickup describes a microphone response that is essentially equal for sound arriving from every direction. Such a pressure-operated capsule has a polar pattern that is nearly a circle, so it does not favor any bearing.','This microphone hears sound equally from all sides. It does not point in one direction. It picks up the whole room. Front and back sound the same.','It captures the full ambient scene and stays consistent regardless of talker position, which suits room capture and small concealed mics.','A technician uses an omni lavalier so a moving talker stays at a constant level, accepting that room noise and reverberation are also captured.','Microphone',ARRAY['Directional pickup','Near-field microphone','Ambient recording','Pin microphone','Concealed microphone']::text[],ARRAY['Expecting an omni to reject off-axis noise the way a cardioid does.','Assuming omnis have proximity effect - true pressure omnis do not.','Using an omni where directional rejection of a noise source is actually needed.']::text[],ARRAY['Recording overall room ambience.','Concealing a small mic where orientation cannot be controlled.','Keeping level constant for a moving talker.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Omnidirectional pickup');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2095','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2095') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2095');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2096','Parabolic reflector','A parabolic reflector is a concave paraboloidal dish that focuses incoming parallel sound waves onto its focal point, where a microphone is mounted. It provides directional gain for distant sources, working best at frequencies whose wavelength is small compared with the dish diameter.','This is a curved dish with a microphone at its focus point. It gathers sound from far away and concentrates it. This makes faraway sounds louder and more directional. It works best for higher-pitched sounds.','It boosts a distant sound and narrows the pickup angle, letting an operator capture a far-off talker or event without moving closer.','For a 0.5 m dish at 4 kHz (wavelength about 0.086 m), the ideal aperture gain (pi*D/lambda)^2 is roughly 336, about 25 dB; real dishes give less and lose low frequencies.','Directional pickup',ARRAY['Acoustic reflector','Long-range pickup','Directional pickup','Far-field microphone','Acoustic focus']::text[],ARRAY['Expecting strong low-frequency gain - the dish only helps where its size exceeds the wavelength.','Placing the mic off the focal point, which blurs and weakens the focus.','Assuming the ideal gain is reached in practice; real efficiency is well below it.']::text[],ARRAY['Recording a distant talker outdoors.','Capturing wildlife or field sound at range.','Sideline sound pickup at sporting events.']::text[],'intermediate','G = (pi * D / lambda)^2','The ideal on-axis power gain of a parabolic reflector equals pi times the dish diameter divided by the wavelength, all squared.','bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Parabolic reflector');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2096','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2096') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2096');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2097','Passive monitoring','Passive monitoring means listening to or receiving audio or signals without transmitting any energy of the monitor''s own. Because it only receives, it emits nothing that a radio-frequency detector or nonlinear junction detector can readily find.','This means listening without sending out any signal. The listener only receives. It gives off almost nothing to detect. This makes the listening hard to find.','It allows covert reception that leaves little emission to betray the monitor, in contrast to active methods that radiate a probe or carrier.','A technician records audio from an existing wired feed or simply receives a distant signal, avoiding any transmitter that a sweep could pick up.','Monitoring',ARRAY['Active monitoring','Remote monitoring','Continuous monitoring','Listening post','Signal detector']::text[],ARRAY['Assuming passive means undetectable - a receiver''s local-oscillator leakage can still radiate.','Confusing passive monitoring with passive electronics generally.','Believing that no transmitter means no legal limits - consent and wiretap laws still apply.']::text[],ARRAY['Receiving a signal without revealing a listening post.','Monitoring an existing feed to avoid emissions.','Comparing detectability of active versus passive methods.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Passive monitoring');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2097','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2097') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2097');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2098','Phonetic analysis','Phonetic analysis is the auditory and acoustic examination of the speech sounds in a recording, describing features such as articulation, accent, voice quality, and pronunciation patterns. In forensic speaker comparison it supports the auditory-phonetic side of the work, usually combined with acoustic measurements.','This studies the actual speech sounds in a recording. An expert listens for accent, voice quality, and how words are said. It helps describe and compare speakers. It is often paired with acoustic measurements.','It characterizes how a person speaks so two samples can be compared or a talker profiled, using trained listening alongside measured speech features.','A forensic phonetician transcribes and annotates disputed speech, noting distinctive vowels or a lisp, then compares those features against a reference recording.','Forensic analysis',ARRAY['Formant analysis','Pitch analysis','Speaker recognition','Forensic audio','Voice signature']::text[],ARRAY['Treating auditory impressions as proof without acoustic support or a stated uncertainty.','Ignoring that recording quality and channel effects change how sounds appear.','Assuming a single unusual feature identifies a speaker on its own.']::text[],ARRAY['Comparing a suspect''s voice to an intercepted call.','Profiling an unknown talker''s accent or background.','Supporting a forensic voice-comparison report.']::text[],'advanced',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phonetic analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2098','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2098') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2098');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2099','Pin microphone','A pin microphone is a very small microphone that clips or pins to clothing near the chest, a compact form of the lavalier microphone. Its tiny capsule and body make it easy to conceal while keeping the mouth at a fairly constant distance.','This is a tiny clip-on microphone. It pins to a shirt near the chest. Its small size makes it easy to hide. It keeps a steady distance from the mouth.','It provides hands-free, discreet speech pickup that stays with a moving talker, which suits both broadcast and covert body-worn use.','A technician clips a pin mic under a lapel; an omni capsule keeps the level steady as the wearer turns, while careful placement limits clothing rustle.','Microphone',ARRAY['Concealed microphone','Body wire microphone','Omnidirectional pickup','Near-field microphone','Covert microphone']::text[],ARRAY['Mounting it where fabric rubs the capsule and adds rustle.','Assuming small size means low quality - capsule and placement matter more.','Forgetting that recording others may require consent under local law.']::text[],ARRAY['Body-worn speech capture on a moving talker.','Discreet interview or broadcast miking.','Hands-free recording where a boom is impractical.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pin microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2099','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2099') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2099');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2100','Pitch analysis','Pitch analysis measures the fundamental frequency (f0) of a voice - the rate of vocal-fold vibration - and how it varies over time. Its average value and range are partly speaker-dependent features used in forensic and phonetic voice work.','This measures how high or low a voice is. It tracks the base frequency of the voice. This is set by how fast the vocal folds vibrate. The average and range help describe a speaker.','It quantifies a fairly stable, partly speaker-specific trait so voices can be compared or characterized, though pitch alone is not a unique identifier.','If a voiced segment repeats every 8 ms, f0 = 1/T = 1/0.008 = 125 Hz, a typical adult-male value the analyst logs across the sample.','Forensic analysis',ARRAY['Formant analysis','Phonetic analysis','Speaker recognition','Harmonic analysis','Voice signature']::text[],ARRAY['Confusing fundamental frequency (f0) with formants, which come from the vocal tract.','Treating pitch as a unique fingerprint; many people share a similar f0.','Ignoring that emotion, health, and effort shift a person''s pitch.']::text[],ARRAY['Characterizing an unknown talker''s voice.','Comparing pitch statistics between two recordings.','Tracking intonation for phonetic analysis.']::text[],'intermediate','f0 = 1 / T0','The fundamental frequency equals one divided by the period of a single vocal-fold vibration cycle.','bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pitch analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2100','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2100') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2100');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2101','Pocket recorder','A pocket recorder is a small, self-contained handheld audio recorder sized to be carried discreetly. It combines a microphone, battery, and solid-state storage in one body for quick, portable capture.','This is a small handheld recorder. It fits in a pocket. It has a microphone, battery, and memory built in. It is used for quick, easy recording.','It offers fast, unobtrusive recording without external gear, useful for interviews, field notes, and discreet capture.','An investigator carries a pocket recorder to capture a conversation, checking battery and free memory beforehand and confirming consent rules for the location.','Recording device',ARRAY['Solid-state recorder','Digital voice recorder','Miniature recorder','Wearable recorder','Body recorder']::text[],ARRAY['Running out of battery or storage mid-recording by not checking first.','Assuming pocket size means poor audio - mic placement dominates quality.','Recording people without meeting local consent or wiretap laws.']::text[],ARRAY['Capturing an interview on the move.','Discreet field recording.','Keeping a personal record of a conversation.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pocket recorder');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2101','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2101') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2101');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2102','RF detector','An RF detector is a broadband receiver that senses the presence and relative strength of radio-frequency energy nearby. In counter-surveillance it is used to find active transmitters, such as radio bugs, by their emissions.','This tool senses nearby radio signals. It shows how strong they are. Sweep teams use it to find hidden radio bugs. It only finds devices that are transmitting.','It gives a quick, portable way to locate radiating transmitters during a sweep, guiding the operator toward the source of a signal.','A technician walks a room watching the meter rise near a wall, then narrows in on a concealed transmitter; a device that is off or wired will not show up.','Countermeasure',ARRAY['RF spectrum analyzer','Bug sweep','Nonlinear junction detector (NLJD)','Signal detector','Carrier detection']::text[],ARRAY['Expecting it to find powered-off or wired devices - it only sees active RF.','Chasing legitimate signals like Wi-Fi and cellular as if they were bugs.','Confusing a simple field-strength detector with a full spectrum analyzer.']::text[],ARRAY['Initial quick sweep for active bugs.','Locating a known transmitter by field strength.','Screening a room before a sensitive meeting.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='RF detector');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2102','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2102') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2102');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2103','RF leakage','RF leakage is the unintended escape of radio-frequency energy from a device, cable, or enclosure through gaps, poor shielding, or imperfect grounding. It is both an electromagnetic-compatibility concern and a stray signal that can reveal the presence or operation of hidden electronics.','This is radio energy that escapes a device by accident. It leaks through gaps or weak shielding. It can cause interference. It can also give away hidden electronics.','Understanding leakage helps a technician control interference and, in sweeps, use stray emissions as a clue to concealed devices.','A sweep operator may detect faint stray emissions from a recorder''s clock or switching supply, using that leakage to locate a device that has no intentional transmitter.','RF / EMC',ARRAY['RF detector','RF spectrum analyzer','Electronic countermeasures','Carrier detection','Bug sweep']::text[],ARRAY['Confusing unintended leakage with an intentional transmitter carrier.','Assuming good shielding is perfect; seams and cables still leak.','Overlooking leakage as a detection clue during sweeps.']::text[],ARRAY['Tracing interference to a leaking enclosure.','Detecting a non-transmitting device by its stray emissions.','Assessing the shielding integrity of equipment.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='RF leakage');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2103','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2103') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2103');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2104','RF link','An RF link is the radio path that carries a signal between a transmitter and a receiver. Its usable range is set by transmitted power, antenna gains, receiver sensitivity, and path loss, which in open space rises with both distance and frequency.','This is the radio path between a sender and a receiver. Its range depends on power and antennas. Signals fade over distance. Higher frequencies fade faster in open space.','It defines how a wireless microphone, bug, or transmitter reaches its receiver, and a link budget predicts whether the signal will arrive strong enough.','In free space a 433 MHz link over 1 km loses about 20*log10(1) + 20*log10(433) + 32.44 = 85 dB, which the transmitter power and antennas must overcome.','RF transmission',ARRAY['RF transmitter','Remote receiver','Relay station','Narrowband transmission','Audio link']::text[],ARRAY['Assuming range is fixed - walls, bodies, and terrain add loss beyond the free-space figure.','Forgetting that higher carrier frequencies increase free-space path loss.','Ignoring receiver sensitivity and noise when estimating the link budget.']::text[],ARRAY['Estimating range for a body-worn transmitter.','Planning a relay to cover a long path.','Comparing bands for a covert link.']::text[],'intermediate','FSPL(dB) = 20*log10(d) + 20*log10(f) + 32.44','Free-space path loss in decibels is twenty times the log of distance in kilometers, plus twenty times the log of frequency in megahertz, plus the constant 32.44.','bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='RF link');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2104','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2104') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2104');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2105','RF spectrum analyzer','An RF spectrum analyzer is an instrument that displays signal amplitude against frequency across a chosen radio band. It reveals the frequency, strength, and shape of individual signals, letting an operator identify and characterize transmitters.','This instrument shows radio signals on a graph. The graph plots strength against frequency. It reveals each signal''s frequency and power. Sweep teams use it to identify transmitters.','It gives detailed insight into which signals are present and their characteristics, going well beyond a simple detector''s presence indication.','During a sweep the operator scans a band, spots an unexpected narrow carrier among the known signals, notes its frequency, and traces it to a hidden transmitter.','Test equipment',ARRAY['RF detector','RF transmitter','Carrier detection','Bug sweep','Signal detector']::text[],ARRAY['Setting the resolution bandwidth too wide to see weak narrowband signals.','Mistaking normal broadcast, Wi-Fi, or cellular signals for threats.','Assuming one snapshot catches bursts; intermittent transmitters need longer captures.']::text[],ARRAY['Detailed spectral sweep of a room.','Identifying a transmitter''s exact frequency.','Distinguishing a bug from legitimate signals.']::text[],'advanced',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='RF spectrum analyzer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2105','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2105') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2105');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2106','RF transmitter','An RF transmitter generates a radio-frequency carrier, modulates it with an audio signal, and radiates it from an antenna to a receiver. In covert audio it is the radiating element of a wireless bug or body-worn wire.','This device creates a radio signal. It adds audio onto the signal. Then it sends it out through an antenna. A receiver picks it up elsewhere.','It moves captured audio wirelessly to a remote receiver, removing the need for a wired connection to the listening point.','A technician sets a wireless microphone transmitter to a clear frequency, pairs it with its receiver, and checks range and battery life before use.','RF transmission',ARRAY['RF link','Remote receiver','RF detector','Narrowband transmission','Audio transmitter']::text[],ARRAY['Choosing an occupied frequency, causing interference or dropouts.','Assuming more power is always better - it also raises detectability and drains batteries.','Transmitting on bands or at powers not allowed by local radio regulations.']::text[],ARRAY['Wireless microphone links.','Body-worn covert audio (subject to law).','Relaying audio to a remote listening post.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='RF transmitter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2106','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2106') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2106');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2107','Recording authentication','Recording authentication is the forensic process of determining whether an audio recording is an original, genuine, and unaltered representation of the events it purports to capture. Examiners assess integrity using methods such as electrical-network-frequency (ENF) analysis, waveform and spectral inspection, and examination of file structure and metadata.','This checks if a recording is real and unchanged. Experts look for signs of editing. One method matches the recording to the power grid''s frequency. Others inspect the sound and the file''s data.','It establishes trust in a recording offered as evidence, showing whether it was edited, copied, or manufactured.','An examiner compares the faint mains hum in a file against a database of grid frequency over time; a break or mismatch in that ENF pattern flags a possible edit.','Authentication',ARRAY['Recording continuity','Tamper detection','Audio integrity','Audio authentication','Forensic audio']::text[],ARRAY['Assuming a clean-sounding file is authentic; skilled edits can be inaudible.','Treating file metadata as proof; it is easily altered.','Skipping documentation, which itself can undermine an authentication claim.']::text[],ARRAY['Verifying a recording before it is used as evidence.','Detecting whether a call was edited.','Confirming a file is an original, not a re-recording.']::text[],'advanced',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Recording authentication');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2107','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2107') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2107');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2108','Recording continuity','Recording continuity is the property that a recording runs unbroken from start to finish, with no stops, gaps, insertions, or deletions in the captured stream. Establishing continuity is a key part of authentication and of chain-of-custody documentation.','This means a recording plays without breaks. Nothing was cut, added, or paused. The sound flows from start to end. Proving this supports the recording as evidence.','It shows the recording was not stopped or edited, supporting its reliability and its admissibility as evidence.','An examiner looks for abrupt changes in background noise, level, or the ENF trace that would reveal a stop or splice breaking the continuity.','Authentication',ARRAY['Recording authentication','Tamper detection','Audio integrity','Time-stamped recording','Evidence recording']::text[],ARRAY['Confusing a continuous file with a continuous recording; files can be assembled from clips.','Assuming pauses leave no trace - background sound and ENF often reveal them.','Overlooking that copying can break the original''s continuity record.']::text[],ARRAY['Checking an interview recording for edits.','Documenting an unbroken evidence recording.','Investigating a suspected gap in a call.']::text[],'advanced',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Recording continuity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2108','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2108') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2108');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2109','Relay station','A relay station is an intermediate point that receives a signal and retransmits it, extending the reach of a link beyond what a single hop allows. In audio surveillance it forwards a transmitter''s signal onward to a distant receiver or listening post.','This is a middle point that passes a signal along. It receives the signal, then sends it again. This extends the range. It links a distant sender to a far receiver.','It overcomes distance and obstacles by breaking a long path into shorter hops, keeping the signal strong enough to reach the endpoint.','When a body-worn transmitter cannot reach a base station directly, a hidden relay near the scene picks up the weak signal and forwards it to the distant receiver.','RF transmission',ARRAY['RF link','Remote receiver','Base station','Audio relay','RF transmitter']::text[],ARRAY['Assuming a relay improves audio quality; it mainly extends range and can add noise.','Placing the relay where it cannot hear the source cleanly.','Forgetting that each hop adds delay and another point of failure.']::text[],ARRAY['Extending range past an obstruction.','Linking a scene transmitter to a distant post.','Covering a large area with several hops.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Relay station');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2109','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2109') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2109');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2110','Remote audio monitoring','Remote audio monitoring is the practice of listening to audio from a location the monitor is not physically present in, using a link that carries the sound to a distant point. The link may be radio, wired, cellular, or network-based.','This means listening to a place from far away. The sound travels over a link to the listener. The link can be radio, wire, cellular, or internet. The listener never has to be there.','It lets an operator hear events at a site without being present, over any medium that can carry the audio.','A technician routes a microphone''s audio over a network so a listener at another site can monitor a room in real time, subject to consent and wiretap law.','Monitoring',ARRAY['Remote monitoring','Remote listening device','Room monitoring','Audio monitoring','Listening post']::text[],ARRAY['Assuming remote monitoring is private - links can be intercepted.','Ignoring latency and dropouts on long or wireless links.','Recording or listening without the consent required by local law.']::text[],ARRAY['Listening to a site from a distant post.','Live monitoring over a network link.','Cellular relay of room audio.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Remote audio monitoring');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2110','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2110') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2110');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2111','Remote listening device','A remote listening device is any apparatus that captures sound at one location and makes it audible at another, such as a radio bug, a wired microphone feed, or a networked audio sensor. It is the general term for the hardware behind remote or covert audio monitoring.','This is any device that lets someone hear a place from afar. It picks up sound in one spot. Then it sends that sound to a listener elsewhere. A radio bug is one example.','It provides the pickup-and-link hardware needed to hear a distant location, whether openly or covertly.','A sweep team searches for remote listening devices by combining RF detection, nonlinear junction detection, and physical inspection, since a device may be wireless, wired, or off.','Covert device',ARRAY['Listening device','Audio bug','Bug','Covert microphone','Remote monitoring']::text[],ARRAY['Assuming all such devices transmit RF; many are wired or store audio locally.','Believing a powered-off device is undetectable.','Deploying one without meeting consent and wiretap laws, which vary by place.']::text[],ARRAY['Sweeping a room for hidden bugs.','Classifying a found device by how it links.','Assessing threats before a sensitive meeting.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Remote listening device');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2111','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2111') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2111');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2112','Remote monitoring','Remote monitoring is the general practice of observing something - here, audio or signals - from a distance rather than on site. In surveillance it covers receiving and following audio via any link without being present at the source.','This means watching or listening from far away. The person is not on site. Signals travel to them over a link. It covers many kinds of remote checking.','It lets an operator keep watch over a location or signal continuously from a safe or hidden distance.','An operator at a listening post follows several remote feeds at once, logging events without approaching any of the monitored sites.','Monitoring',ARRAY['Remote audio monitoring','Room monitoring','Passive monitoring','Continuous monitoring','Listening post']::text[],ARRAY['Using it interchangeably with recording; monitoring may leave no stored copy.','Assuming links are secure; remote feeds can be intercepted.','Overlooking that consent and privacy law still apply from a distance.']::text[],ARRAY['Watching multiple sites from one post.','Continuous remote surveillance of a location.','Real-time oversight without being present.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Remote monitoring');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2112','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2112') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2112');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2113','Remote receiver','A remote receiver is a receiver placed away from the operator''s position that captures a transmitted signal and passes it on to a recorder or listening post. Locating the receiver near the source improves signal quality on weak links.','This is a receiver placed away from the operator. It catches the sent signal. Then it feeds it to a recorder or post. Putting it near the source helps weak signals.','It captures a transmission close to its source, then relays the audio onward, improving reliability when the operator is far away.','A technician hides a remote receiver near a transmitter and runs its output over a separate secure link back to the distant listening post.','RF transmission',ARRAY['Relay station','RF link','RF transmitter','Base station','Listening post']::text[],ARRAY['Confusing a remote receiver with a relay; a receiver need not retransmit by radio.','Placing it too far from the source on a weak link.','Forgetting to secure the onward link from the receiver.']::text[],ARRAY['Capturing a weak transmitter near its source.','Feeding audio to a distant post.','Improving reception on a long link.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Remote receiver');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2113','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2113') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2113');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2114','Room monitoring','Room monitoring is the listening to or recording of the sounds within a specific enclosed space, typically to capture conversations or activity there. It may use a concealed microphone, a room bug, or an existing audio device in the space.','This means listening to the sounds inside one room. The goal is to hear talk or activity there. It can use a hidden microphone or bug. The listener often stays outside the room.','It captures what happens acoustically in a defined space, for security, evidence, or intelligence purposes.','An investigator places a concealed microphone to monitor a room, first confirming that consent and wiretap laws in that jurisdiction permit it.','Monitoring',ARRAY['Remote monitoring','Concealed microphone','Ambient recording','Audio surveillance','Remote listening device']::text[],ARRAY['Placing the mic where room reverberation and noise bury speech.','Assuming one mic covers a large or divided room.','Monitoring a room without the consent that local law may require.']::text[],ARRAY['Capturing conversation in a target room.','Security monitoring of a space.','Gathering evidence from within a room.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Room monitoring');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2114','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2114') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2114');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2115','Signal detector','A signal detector is a device or circuit that indicates when a signal of interest - audio, radio, or other - is present above a set threshold. In surveillance and counter-surveillance it flags activity such as a transmitter switching on or a sound exceeding a trigger level.','This tool shows when a signal is present. It reacts when the signal passes a set level. It can watch for radio or sound. It warns the operator that something is active.','It provides a simple present-or-absent indication, often to trigger recording or to alert an operator to activity.','A voice-triggered recorder uses an audio signal detector so it starts capturing only when sound rises above the threshold, saving storage and battery.','Detection',ARRAY['RF detector','Carrier detection','Voice-activated recorder (VOX)','Signals intelligence (SIGINT)','Broadband detector']::text[],ARRAY['Setting the threshold so low that noise triggers false detections.','Setting it so high that weak but real signals are missed.','Confusing mere detection with identification of the signal''s source.']::text[],ARRAY['Triggering a recorder on sound or RF.','Alerting to a transmitter turning on.','Screening for activity before detailed analysis.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Signal detector');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2115','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2115') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2115');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2116','Signals intelligence (SIGINT)','Signals intelligence is intelligence produced by intercepting and analyzing electronic signals and communications. It is conventionally divided into communications intelligence (COMINT), drawn from messages, and electronic intelligence (ELINT), drawn from non-communication emissions such as radar.','This is information taken from signals. Spies listen in on radio and phone links. They also study other signals like radar. They learn facts from what they hear.','It lets agencies gather information from a target''s electronic emissions without direct access to the source.','An analyst intercepts a radio link, identifies its type and content category, and reports the resulting communications intelligence to decision-makers.','Intelligence discipline',ARRAY['Communications intelligence (COMINT)','Acoustic intelligence (ACINT)','Audio interception','Electronic surveillance','Audio intelligence']::text[],ARRAY['Equating SIGINT only with wiretaps; it also covers non-communication emissions.','Confusing COMINT and ELINT, which target different signal types.','Assuming interception is always lawful; it is tightly regulated.']::text[],ARRAY['Intercepting communications for intelligence.','Classifying an emitter from its signal.','Framing audio interception within a wider SIGINT effort.']::text[],'advanced',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Signals intelligence (SIGINT)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2116','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2116') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2116');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2117','Solid-state recorder','A solid-state recorder stores audio in semiconductor flash memory rather than on tape or a spinning disk, so it has no moving parts. This gives it low power use, resistance to shock, silent operation, and a small size well suited to concealment.','This recorder saves sound to flash memory chips. It has no moving parts. That makes it quiet, small, and tough. It also uses little power.','It provides reliable, compact, silent recording, which suits portable, wearable, and covert use.','A technician chooses a solid-state recorder for a body-worn task because it runs silently, survives movement, and fits in a small concealed space.','Recording device',ARRAY['Multi-channel recorder','Digital voice recorder','Pocket recorder','Miniature recorder','Flash recorder']::text[],ARRAY['Assuming flash storage never fails; cells wear out and files can corrupt.','Forgetting that solid-state size and silence do not guarantee good audio.','Neglecting backups of critical evidence files.']::text[],ARRAY['Silent body-worn recording.','Shock-prone field capture.','Long unattended recording on low power.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Solid-state recorder');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2117','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2117') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2117');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2118','Sound source localization','Sound source localization is the estimation of the direction or position of a sound source from measurements made at two or more spaced microphones. A common method uses the time difference of arrival (TDOA) between microphones to compute the source bearing.','This finds where a sound comes from. It uses two or more spaced microphones. The sound reaches them at slightly different times. That timing gives the direction.','It lets a system point at, track, or map sound sources, supporting arrays, gunshot location, and the steering of directional pickup.','With mics 0.30 m apart and a 0.50 ms delay, theta = arcsin(c*dt/d) = arcsin(343*0.0005/0.30) = about 35 degrees off broadside.','Localization',ARRAY['Acoustic localization','Beamforming array','Array microphone','Acoustic camera','Beam steering']::text[],ARRAY['Ignoring that a two-mic pair leaves a front-back and cone ambiguity.','Assuming perfect timing; noise and reverberation blur the TDOA estimate.','Forgetting that using the wrong speed of sound biases the result.']::text[],ARRAY['Steering an array toward a talker.','Locating a gunshot or impulsive event.','Mapping sources with an acoustic camera.']::text[],'advanced','theta = arcsin( c * dt / d )','The source bearing from broadside equals the inverse sine of the speed of sound times the arrival-time difference, divided by the microphone spacing.','bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound source localization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2118','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2118') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2118');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2119','Speaker recognition','Speaker recognition is the automatic or expert task of determining who is speaking from voice characteristics, covering verification (is this the claimed person?) and identification (which of several people is it?). In forensic voice comparison the strength of the evidence is expressed as a likelihood ratio comparing the same-speaker and different-speaker hypotheses.','This works out who is speaking from their voice. One task confirms a claimed identity. Another picks the talker from a group. In court, results are given as a likelihood ratio.','It links a voice to a person for access control, intelligence, or forensic comparison, while expressing the uncertainty honestly.','If the measured speech features are 100 times more probable under the same-speaker hypothesis than the different-speaker one, the likelihood ratio is 100 - moderately strong support for a common source.','Forensic analysis',ARRAY['Voiceprint','Voice signature','Spectral comparison','Formant analysis','Phonetic analysis']::text[],ARRAY['Treating a voice as a unique ''fingerprint''; recognition is probabilistic, not certain.','Reporting a decision instead of a likelihood ratio with its uncertainty.','Ignoring channel, health, and emotion, which change how a voice sounds.']::text[],ARRAY['Comparing a suspect''s voice to an intercept.','Verifying identity for phone access.','Reporting evidence strength in court.']::text[],'advanced','LR = p(E | Hp) / p(E | Hd)','The likelihood ratio is the probability of the evidence assuming the same-speaker hypothesis, divided by its probability assuming the different-speaker hypothesis.','bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Speaker recognition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2119','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2119') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2119');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2120','Spectral comparison','Spectral comparison is the examination of the frequency content of two audio samples side by side - often via spectrograms - to judge similarity or difference. It supports tasks such as forensic voice comparison, authentication, and matching a sound to a suspected source.','This compares the sound content of two clips. Experts look at pitch and tone maps. Matching shapes point to a likely match. Different shapes point to different sources.','It provides a visual and quantitative way to assess whether two sounds share spectral features, aiding comparison and authentication.','An examiner lines up spectrograms of two recordings, comparing formant positions and noise patterns, while treating visual similarity as support rather than proof.','Forensic analysis',ARRAY['Waveform comparison','Formant analysis','Speaker recognition','Harmonic analysis','Forensic audio']::text[],ARRAY['Treating similar spectrograms as proof of identity; they show similarity, not certainty.','Comparing samples recorded on very different channels without accounting for it.','The discredited belief that a ''voiceprint'' matches like a fingerprint.']::text[],ARRAY['Comparing two voices in a case.','Checking a file for spectral edit traces.','Matching a sound to a candidate source.']::text[],'advanced',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spectral comparison');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2120','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2120') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2120');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2121','Speech extraction','In forensic and surveillance audio, the process of recovering a target talker''s speech from a recording degraded by background noise, reverberation, or competing voices. It combines filtering, source separation, and enhancement to make the wanted speech more usable for listening, transcription, or analysis.','This means pulling wanted speech out of a messy recording. The clip may hold noise, echo, or other voices. Tools reduce those problems so the target talk stands out. It recovers what was captured; it cannot add missing words.','It exists to make otherwise unusable spoken evidence audible and analyzable, so investigators can hear and document what was actually said.','A technician may apply adaptive noise reduction, band-limited filtering, and dereverberation to a covert clip, checking that processing improves clarity without introducing artefacts that distort the words.','Audio enhancement',ARRAY['Voice enhancement','Voice isolation','Target isolation','Target voice enhancement','Wind filtering']::text[],ARRAY['Believing extraction can add information that was never captured in the recording.','Over-filtering until the speech itself is thinned or slurred.','Confusing speech extraction with transcription of the words.']::text[],ARRAY['Recovering a quiet talker on a noisy covert body recording.','Cleaning a 911 call for review by an investigator.','Isolating one speaker from a crowded room recording.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Speech extraction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2121','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2121') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2121');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2122','Speech intelligence','Intelligence information derived from the analysis of intercepted spoken communications, covering what is said, who is speaking, and in what language. It is a component of communications intelligence (COMINT) within signals intelligence.','This is useful knowledge gained from listening to captured talk. It covers the words, the speaker, and the language. Analysts turn recorded speech into reports. It is one part of wider signals intelligence work.','It exists to turn raw intercepted speech into actionable knowledge for security, law-enforcement, or military decision-making.','An analyst reviews intercepted audio, identifies talkers and topics, and summarizes content, always within the legal authority governing the collection.','Intelligence discipline',ARRAY['Voice interception','Voice collection','Technical surveillance','Voice signature','Speech extraction']::text[],ARRAY['Confusing speech intelligence with speech intelligibility, which measures how clearly words are understood.','Assuming any interception is lawful regardless of jurisdiction or authorization.','Treating a rough transcript as verified fact without corroboration.']::text[],ARRAY['Summarizing intercepted communications under a lawful warrant.','Language and topic analysis of collected voice traffic.','Linking a talker across several intercepted calls.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Speech intelligence');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2122','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2122') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2122');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2123','Spread spectrum','A modulation family in which a signal is deliberately spread over a bandwidth much wider than its information rate, typically by direct-sequence coding (DSSS) or frequency hopping (FHSS). Spreading yields processing gain, resistance to narrowband interference and jamming, and low probability of interception.','This spreads a signal across a wide band of frequencies. It can jump between channels or use a special code. Doing this makes the signal hard to jam or find. Wireless microphones and secure links use it.','It exists to make radio links robust against interference and eavesdropping and to let many users share a band without heavy mutual interference.','For a link spreading a 2 kHz message across 2 MHz, processing gain is 10*log10(2,000,000 / 2,000) = 10*log10(1000) = 30 dB of interference rejection.','RF modulation',ARRAY['UHF transmitter','VHF transmitter','Technical surveillance','Wi-Fi audio transmission','Technical surveillance counter-measures (TSCM)']::text[],ARRAY['Thinking a wider band always means better audio quality rather than more interference resistance.','Confusing direct-sequence with frequency-hopping methods.','Assuming spread spectrum alone provides message secrecy without encryption.']::text[],ARRAY['Choosing a hop-based wireless microphone for a congested RF site.','Understanding why a covert link resists narrowband jamming.','Explaining how many devices coexist in an unlicensed band.']::text[],'advanced','G_p = 10 * log10( W_ss / R_info )','Processing gain in decibels equals ten times the base-ten logarithm of the spread bandwidth divided by the information rate.','bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spread spectrum');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2123','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2123') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2123');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2124','TSCM','TSCM stands for Technical Surveillance Counter-Measures: the systematic detection, location, and neutralization of covert eavesdropping and monitoring devices. A sweep combines physical search, radio-frequency spectrum analysis, and inspection of wiring and structures.','TSCM means checking a place for hidden bugs. Experts look for secret microphones and cameras. They search by hand and scan radio signals. The goal is to find and remove listening devices.','It exists to protect private conversations and sensitive spaces from technical eavesdropping.','A sweep team scans the RF spectrum, uses a non-linear junction detector to find hidden electronics, and physically inspects furniture, walls, and wall plates.','Countermeasures',ARRAY['Bug sweep','Technical surveillance','RF transmitter','Spread spectrum','UHF transmitter']::text[],ARRAY['Assuming a single RF scan finds every device, including wired or recording-only bugs.','Confusing TSCM (defensive) with technical surveillance (the collection itself).','Believing consumer ''bug detector'' apps match professional sweep equipment.']::text[],ARRAY['Sweeping a boardroom before confidential negotiations.','Checking an executive vehicle for a tracking or audio device.','Inspecting a room after suspected unauthorized entry.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='TSCM');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2124','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2124') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2124');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2125','Tamper detection','In audio authentication, the examination of a recording for signs of alteration such as insertions, deletions, or re-recording. Analysts look for waveform and spectral discontinuities, inconsistent background noise, and irregularities in the embedded electric network frequency (ENF).','This checks whether a recording was changed. Experts look for edits, cuts, or added parts. Odd breaks in sound or hum can reveal tampering. A clean, continuous file supports that it is original.','It exists to test whether a recording is an unaltered original before it is relied on as evidence.','An examiner inspects the waveform and spectrogram for abrupt joins and compares the mains-hum ENF pattern against a reference database to check for gaps or splices.','Authentication',ARRAY['Time-stamped recording','Waveform comparison','Voiceprint','Time synchronization','Technical surveillance counter-measures (TSCM)']::text[],ARRAY['Assuming a file is authentic simply because it plays without obvious glitches.','Treating any editing artefact as proof of malicious tampering rather than format processing.','Relying on ENF analysis when no mains hum was captured.']::text[],ARRAY['Authenticating a submitted recording before a hearing.','Checking a covert file for hidden edits.','Using ENF to verify a claimed recording date and time.']::text[],'advanced',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tamper detection');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2125','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2125') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2125');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2126','Target isolation','The separation of a desired sound source, such as one talker, from other sources and noise in a recording or live capture. Techniques include microphone-array beamforming, blind or model-based source separation, and spatial or spectral filtering.','This means picking out one wanted sound source. It could be a single voice in a busy room. Tools focus on that source and push others down. The aim is a cleaner capture of the target.','It exists to concentrate on one source of interest so it can be heard and analyzed apart from competing sound.','A technician steers a microphone-array beam toward the target speaker''s direction, attenuating off-axis voices and reflections before further enhancement.','Audio enhancement',ARRAY['Target voice enhancement','Voice isolation','Speech extraction','Voice enhancement','Wind filtering']::text[],ARRAY['Expecting perfect separation when sources overlap heavily in time and frequency.','Assuming a single microphone can beamform without an array.','Confusing isolation with simple volume boosting of the whole mix.']::text[],ARRAY['Focusing on one speaker at a crowded meeting.','Separating a target voice from music in a bar recording.','Steering an array toward a known source position.']::text[],'advanced',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Target isolation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2126','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2126') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2126');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2127','Target voice enhancement','Processing aimed at improving the clarity and intelligibility of one specific talker in a recording. It combines isolation of that voice with noise reduction, equalization, and level control tuned to that speaker.','This makes one chosen voice easier to hear. First the voice is isolated from noise. Then filters and level changes sharpen it. The focus stays on that single speaker.','It exists to render a particular person''s speech clearer for review, transcription, or presentation.','A technician isolates the target talker, then applies gentle equalization around speech formants and adaptive noise reduction, verifying the words remain natural.','Audio enhancement',ARRAY['Target isolation','Voice enhancement','Voice isolation','Speech extraction','Voice collection']::text[],ARRAY['Pushing enhancement so far that the voice sounds processed and unnatural.','Enhancing the whole mix instead of the target talker.','Assuming enhancement can reveal words that were never captured.']::text[],ARRAY['Clarifying a suspect''s speech in a covert recording.','Preparing a specific caller''s audio for a jury.','Improving one talker on a multi-party call.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Target voice enhancement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2127','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2127') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2127');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2128','Technical surveillance','The covert use of technical or electronic devices, such as microphones, transmitters, and cameras, to collect audio, video, or data without the subject''s knowledge. It is the collection activity that technical surveillance counter-measures are designed to detect and defeat.','This is spying with electronic devices. Hidden microphones, bugs, or cameras gather information. The target does not know it is happening. Laws control when and how it may be done.','It exists as a covert collection method for lawful investigations and intelligence work, subject to legal authorization.','In a lawful operation under warrant, agents may deploy concealed microphones or transmitters, while ensuring collection stays within the terms of the authorization.','Surveillance method',ARRAY['Technical surveillance counter-measures (TSCM)','Voice interception','Voice collection','UHF transmitter','Wearable recorder']::text[],ARRAY['Assuming any covert recording is legal without checking consent and wiretap law.','Confusing technical surveillance (collection) with TSCM (detection).','Believing surveillance audio is always high quality and easy to analyze.']::text[],ARRAY['Deploying concealed audio under a lawful warrant.','Understanding threats a TSCM sweep must counter.','Studying how covert devices capture conversation.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Technical surveillance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2128','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2128') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2128');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2129','Technical surveillance counter-measures (TSCM)','The professional discipline of detecting, locating, and neutralizing covert surveillance devices and vulnerabilities. A full survey integrates physical inspection, radio-frequency and spectrum analysis, non-linear junction detection, and review of telephone and network infrastructure.','This is the full practice of bug sweeping. Experts hunt for hidden listening and recording devices. They search physically and scan radio signals. They also check phones, wiring, and networks for weaknesses.','It exists to safeguard sensitive conversations and facilities against technical eavesdropping and information leakage.','A survey team baselines the RF environment, sweeps with a spectrum analyzer and non-linear junction detector, and physically inspects rooms, furniture, and cabling for concealed devices.','Countermeasures',ARRAY['Bug sweep','Technical surveillance','Spread spectrum','RF transmitter','UHF transmitter']::text[],ARRAY['Assuming an RF sweep alone catches wired, optical, or recording-only devices.','Skipping a physical inspection because the spectrum looked clean.','Treating one sweep as permanent protection rather than a point-in-time check.']::text[],ARRAY['Full survey of a corporate headquarters before a merger.','Recurring sweeps of a secure conference facility.','Post-incident inspection after a suspected breach.']::text[],'advanced',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Technical surveillance counter-measures (TSCM)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2129','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2129') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2129');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2130','Through-wall microphone','A listening device that senses sound in an adjacent space by coupling to a shared structure rather than to open air. Contact or spike (probe) microphones and accelerometers pick up the vibration a wall, pipe, or door transmits from voices on the other side.','This device listens through a wall. It does not use open air like a normal microphone. Instead it senses tiny wall vibrations from voices next door. A contact sensor or probe picks up that shaking.','It exists to monitor sound in a space that cannot be entered, using the building structure as the sound path.','An operator couples a contact microphone to a shared wall or pipe; performance depends on wall stiffness and mass, and it is defeated by decoupled or heavy construction.','Covert device',ARRAY['Technical surveillance','Voice interception','Technical surveillance counter-measures (TSCM)','Voice collection','Wearable recorder']::text[],ARRAY['Assuming it hears clearly through any wall regardless of construction.','Confusing a structure-borne contact sensor with an air microphone.','Ignoring that use is restricted by wiretap and privacy law.']::text[],ARRAY['Understanding a threat a TSCM survey must consider.','Explaining structure-borne versus airborne sound pickup.','Assessing why heavy, decoupled walls resist eavesdropping.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Through-wall microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2130','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2130') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2130');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2131','Time synchronization','Aligning the clocks or timebases of separate recording devices or systems so their timestamps and samples correspond to a common reference. Common references include GPS time, Network Time Protocol (NTP), Precision Time Protocol (IEEE 1588), and SMPTE timecode.','This lines up the clocks of different devices. Then their recordings share one common time. Sources like GPS or a time server set the reference. It lets you match events across separate files.','It exists so that recordings from multiple sources can be aligned, compared, and trusted for their timing.','Before a multi-device operation, a technician syncs recorders to a common GPS or NTP reference so that later, files can be aligned to a shared timeline.','Timing',ARRAY['Time-stamped recording','Waveform comparison','Tamper detection','Voice collection','Wi-Fi audio transmission']::text[],ARRAY['Assuming device clocks stay aligned without a shared reference (they drift).','Confusing timestamp accuracy with audio sample-clock accuracy.','Ignoring time-zone and daylight-saving offsets in logged times.']::text[],ARRAY['Aligning several recorders on one operation to a common time.','Matching a call log timestamp to a recording.','Preparing multi-source audio for synchronized review.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Time synchronization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2131','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2131') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2131');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2132','Time-stamped recording','A recording that carries embedded or logged time information marking when it was captured, supporting chain of custody and evidentiary review. Timestamps may be stored in file metadata, as an audio or timecode track, or in a device log.','This is a recording tagged with the time it was made. The time may sit in the file details or a log. It helps prove when the audio was captured. That supports its use as evidence.','It exists to document when audio was captured, strengthening its reliability and traceability as evidence.','An examiner reads the file''s embedded timestamps and device log, checking them for consistency with a synchronized reference and for signs of alteration.','Evidence handling',ARRAY['Time synchronization','Tamper detection','Waveform comparison','Voice collection','Voiceprint']::text[],ARRAY['Trusting a timestamp without checking the device clock was correct.','Assuming metadata times cannot be edited or forged.','Confusing file-created time with the actual recording time.']::text[],ARRAY['Establishing when a covert recording was made.','Building a chain of custody for submitted audio.','Cross-checking a timestamp against an ENF date estimate.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Time-stamped recording');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2132','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2132') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2132');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2133','UHF transmitter','A radio transmitter operating in the ultra-high-frequency band, defined by the ITU as 300 MHz to 3 GHz. In audio work, UHF wireless microphones and body transmitters exploit this band for compact antennas and, in many regions, portions of the former television spectrum.','This transmitter sends radio in the UHF band. UHF covers 300 megahertz up to 3 gigahertz. Wireless microphones and body packs often use it. Its short waves allow small antennas.','It exists to carry audio wirelessly over a band that supports small antennas and, in some regions, many usable channels.','At 600 MHz the wavelength is lambda = c/f = (3e8 m/s)/(600e6 Hz) = 0.5 m, so a quarter-wave whip antenna is about 0.125 m long.','RF device',ARRAY['VHF transmitter','Spread spectrum','Technical surveillance','Wi-Fi audio transmission','RF transmitter']::text[],ARRAY['Assuming UHF wireless bands are unregulated (many require license or fall under wireless-mic rules).','Confusing the UHF band (300 MHz to 3 GHz) with VHF (30 to 300 MHz).','Ignoring that some former TV frequencies are now reallocated and off-limits.']::text[],ARRAY['Selecting a UHF wireless microphone channel free of interference.','Understanding a covert body transmitter''s band.','Explaining why UHF antennas are physically short.']::text[],'intermediate','lambda = c / f','Wavelength equals the speed of light divided by the frequency.','bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='UHF transmitter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2133','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2133') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2133');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2134','VHF transmitter','A radio transmitter operating in the very-high-frequency band, defined by the ITU as 30 MHz to 300 MHz. Legacy and budget wireless microphones use VHF, which offers good propagation but longer antennas and, today, a more congested and lower-capacity spectrum than UHF.','This transmitter sends radio in the VHF band. VHF covers 30 megahertz up to 300 megahertz. Older wireless microphones often use it. Its longer waves need longer antennas.','It exists to carry audio wirelessly over a band with good range, at the cost of larger antennas and fewer clear channels.','At 150 MHz the wavelength is lambda = c/f = (3e8 m/s)/(150e6 Hz) = 2 m, so a quarter-wave antenna is about 0.5 m long.','RF device',ARRAY['UHF transmitter','Spread spectrum','Technical surveillance','RF transmitter','Wi-Fi audio transmission']::text[],ARRAY['Confusing VHF (30 to 300 MHz) with UHF (300 MHz to 3 GHz).','Expecting as many clear channels on VHF as on UHF.','Overlooking that VHF antennas are physically longer for a given design.']::text[],ARRAY['Identifying an older VHF wireless microphone system.','Explaining why VHF antennas are longer than UHF ones.','Assessing VHF congestion at a busy site.']::text[],'intermediate','lambda = c / f','Wavelength equals the speed of light divided by the frequency.','bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='VHF transmitter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2134','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2134') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2134');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2135','Voice collection','The gathering of voice recordings or samples for later analysis, such as speaker comparison, transcription, or enrollment in a recognition system. Collection covers how, where, and under what authority the audio is captured and preserved.','This is gathering voice recordings for later study. The audio may be used to compare or identify speakers. How and where it is captured matters. So does keeping it safe and unaltered.','It exists to obtain and preserve voice material suitable for reliable analysis and, where needed, evidentiary use.','An examiner documents the source, device, and settings of collected audio, and captures a controlled reference sample under similar conditions for speaker comparison.','Collection',ARRAY['Voice interception','Voice signature','Voiceprint','Time-stamped recording','Speech intelligence']::text[],ARRAY['Comparing samples recorded under very different channels without noting the mismatch.','Failing to document how and when audio was collected.','Assuming a short, poor sample is enough for reliable comparison.']::text[],ARRAY['Capturing a controlled reference sample for comparison.','Preserving intercepted audio for later analysis.','Enrolling voices into a recognition database.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Voice collection');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2135','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2135') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2135');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2136','Voice enhancement','Signal processing applied to make recorded speech clearer and more intelligible, typically through noise reduction, filtering, equalization, and level normalization. In forensic work it aims to improve audibility without adding, removing, or distorting spoken content.','This makes recorded speech easier to hear. It cuts noise and shapes the sound. It also evens out loud and quiet parts. It must not change the actual words.','It exists to improve the audibility of speech so listeners can better understand what was recorded.','A technician applies broadband noise reduction and a speech-band filter, then compares before and after to confirm intelligibility improved and no words were altered.','Audio enhancement',ARRAY['Target voice enhancement','Voice isolation','Speech extraction','Wind filtering','Target isolation']::text[],ARRAY['Over-processing until artefacts make the speech sound robotic.','Assuming enhancement can create words that were never captured.','Enhancing a working copy without preserving the untouched original.']::text[],ARRAY['Improving a noisy interview recording for review.','Preparing audio for courtroom playback.','Making a faint conversation more audible.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Voice enhancement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2136','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2136') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2136');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2137','Voice interception','The capture of voice communications, typically without the participants'' knowledge, for surveillance or investigation. In most jurisdictions it is tightly regulated by wiretap and privacy statutes requiring consent or judicial authorization.','This is capturing people''s spoken communication in secret. It is used in surveillance and investigations. Strict laws control it. Often a warrant or consent is required.','It exists as a lawful collection method, under authorization, for investigations and intelligence.','Under a lawful wiretap order, communications are captured and preserved, with careful logging so the audio remains reliable and admissible.','Surveillance method',ARRAY['Voice collection','Technical surveillance','Speech intelligence','Voice signature','Wearable recorder']::text[],ARRAY['Assuming interception is legal without a warrant or the required consent.','Confusing one-party and all-party consent rules across jurisdictions.','Treating intercepted audio as automatically admissible in court.']::text[],ARRAY['Capturing calls under a lawful wiretap order.','Understanding consent rules before any recording.','Preserving intercepted audio for later analysis.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Voice interception');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2137','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2137') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2137');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2138','Voice isolation','The separation of a voice signal from background noise, music, or other talkers in a recording. It draws on spectral and spatial filtering and, increasingly, machine-learning source separation trained to model speech.','This pulls a voice apart from other sounds. The mix may hold noise, music, or extra talkers. Filters and models focus on the speech. The result is a cleaner voice track.','It exists to obtain a cleaner voice signal for listening, transcription, or speaker analysis.','A technician runs a speech-separation model on a noisy clip, then checks that the isolated voice keeps natural timbre and no words were dropped.','Audio enhancement',ARRAY['Target isolation','Voice enhancement','Speech extraction','Target voice enhancement','Wind filtering']::text[],ARRAY['Expecting perfect isolation when voice and noise share the same frequencies.','Assuming isolation and enhancement are identical steps.','Ignoring artefacts that separation can introduce into the voice.']::text[],ARRAY['Separating a voice from loud music in a recording.','Cleaning a voice buried in traffic noise.','Preparing an isolated voice for speaker comparison.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Voice isolation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2138','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2138') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2139','Voice signature','The set of measurable acoustic characteristics, such as fundamental frequency, formant patterns, and speaking style, that tend to distinguish one speaker''s voice. It underpins speaker comparison, though no single feature uniquely identifies a person the way a fingerprint can.','This is the mix of features that make a voice distinctive. Pitch, tone shape, and speaking style all count. Experts use them to compare speakers. No one feature alone proves identity.','It exists as the descriptive basis for comparing voices and estimating whether two samples share a speaker.','In speaker comparison, an examiner measures pitch and formant patterns across matched sounds in two recordings and expresses the result as a likelihood, not a certainty.','Speaker characterization',ARRAY['Voiceprint','Voice collection','Waveform comparison','Speech intelligence','Voice isolation']::text[],ARRAY['Treating a voice signature as unique and infallible like a fingerprint.','Ignoring how illness, emotion, or channel change a voice.','Confusing casual listening with validated speaker comparison methods.']::text[],ARRAY['Comparing a suspect sample to a questioned recording.','Describing features that vary between talkers.','Explaining why voice comparison yields likelihoods, not certainty.']::text[],'advanced',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Voice signature');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2139','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2139') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2139');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2140','Voice-activated recorder (VOX)','A recorder that starts capturing only when input sound exceeds a set threshold and pauses during silence, a mode called VOX (voice-operated exchange). It conserves storage and battery but can clip word onsets and drop quiet speech below the threshold.','This recorder only runs when it hears sound. Quiet gaps are skipped to save space and battery. The mode is called VOX, for voice-operated exchange. It can miss the start of soft speech.','It exists to save storage and power by recording only during sound activity rather than continuously.','A technician sets the VOX threshold above the noise floor but low enough to catch speech, accepting that very quiet talk or word onsets may be missed.','Recording device',ARRAY['Wearable recorder','Time-stamped recording','Voice collection','Voice interception','Wind filtering']::text[],ARRAY['Setting the threshold so high that soft speech is never recorded.','Assuming VOX captures continuously without gaps.','Forgetting that dropped silence can weaken a chain-of-custody timeline.']::text[],ARRAY['Configuring a covert recorder to save battery.','Reviewing a VOX file with gaps between utterances.','Explaining missing onsets in a submitted recording.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Voice-activated recorder (VOX)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2140','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2140') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2140');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2141','Voiceprint','A popular term for a spectrogram used to compare voices, historically promoted for speaker identification. The scientific community has long cautioned that spectrographic ''voiceprints'' are not uniquely identifying like fingerprints, and reliability depends heavily on method and conditions.','A voiceprint is a picture of a voice''s frequencies over time. People once claimed it could identify a speaker for sure. Scientists warn it is not that reliable. It is not like a fingerprint.','The concept exists as a visual aid for voice comparison, but its evidentiary weight is limited and contested.','An examiner may view spectrograms to compare speakers, but reports conclusions as likelihoods using validated methods, not as certain ''voiceprint'' matches.','Speaker identification',ARRAY['Voice signature','Waveform comparison','Voice collection','Tamper detection','Speech intelligence']::text[],ARRAY['Believing a voiceprint identifies a speaker with fingerprint-like certainty.','Assuming visual spectrogram matching is a validated, error-free method.','Confusing the popular term ''voiceprint'' with modern automatic speaker recognition.']::text[],ARRAY['Explaining why spectrographic voice matching is contested.','Discussing admissibility of voice comparison under Daubert.','Comparing legacy voiceprint claims to modern methods.']::text[],'advanced',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Voiceprint');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2141','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2141') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2141');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2142','Waveform comparison','The side-by-side or quantitative comparison of two audio signals in the time domain to assess similarity, alignment, or alteration. Cross-correlation gives a numerical measure, peaking when the waveforms are aligned and most similar.','This compares two recordings by their wave shapes. It can show if they match or line up in time. A math tool called cross-correlation gives a score. A high score means the shapes are very similar.','It exists to measure how alike or aligned two signals are, aiding authentication, synchronization, and duplicate detection.','For x = [1,2,3] and y = [2,4,6], the normalized cross-correlation is r = 4 / sqrt(2*8) = 4/4 = 1.0, showing identical waveform shape.','Analysis method',ARRAY['Tamper detection','Time synchronization','Voiceprint','Voice signature','Time-stamped recording']::text[],ARRAY['Assuming a high correlation proves the recordings share one source rather than one shape.','Comparing waveforms without first aligning them in time.','Ignoring that gain or filtering changes a waveform without changing content.']::text[],ARRAY['Detecting a spliced segment against a reference.','Aligning two recordings of the same event.','Checking whether two files are duplicates.']::text[],'intermediate','r = Sum[(x_i - x_bar)(y_i - y_bar)] / sqrt( Sum(x_i - x_bar)^2 * Sum(y_i - y_bar)^2 )','The correlation equals the summed product of the two signals'' deviations from their means, divided by the square root of the product of their summed squared deviations.','bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Waveform comparison');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2142','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2142') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2142');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2143','Wearable recorder','A small audio recorder carried or worn on the body to capture conversation, often covertly (a ''wire''). Modern units combine a concealed microphone, solid-state storage, and sometimes a transmitter, and their use is governed by wiretap and consent law.','This is a small recorder worn on the body. It captures nearby talk, sometimes in secret. People often call it a wire. Laws control when it may be used.','It exists to record conversations discreetly during investigations or personal documentation, subject to legal limits.','In a lawful operation, an agent wears a concealed recorder with a body-mounted microphone, and the file is later preserved and enhanced for review.','Covert device',ARRAY['Voice-activated recorder (VOX)','Technical surveillance','Voice interception','Time-stamped recording','Voice collection']::text[],ARRAY['Assuming body-worn recording is always legal regardless of consent rules.','Expecting studio-quality audio from a concealed body microphone.','Overlooking clothing rustle and body contact noise on the recording.']::text[],ARRAY['Recording a meeting during a lawful investigation.','Reviewing muffled audio from a concealed microphone.','Understanding a threat a TSCM sweep must address.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wearable recorder');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2143','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2143') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2143');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2144','Wi-Fi audio transmission','The streaming of audio over a wireless local-area network using the IEEE 802.11 (Wi-Fi) family of standards, in the 2.4 GHz, 5 GHz, and 6 GHz bands. It carries digital, usually packetized and often encrypted audio, and is subject to network latency and congestion.','This sends audio over a Wi-Fi network. It uses the same standards as home wireless internet. The audio travels as digital data packets. Network delay and traffic can affect it.','It exists to move audio wirelessly over standard network infrastructure, often with encryption and flexible routing.','A technician streams audio over an 802.11 link, managing latency and packet loss with buffering, and relies on network encryption such as WPA to protect the stream.','Transmission',ARRAY['Spread spectrum','UHF transmitter','Time synchronization','Technical surveillance','RF transmitter']::text[],ARRAY['Assuming Wi-Fi audio is inherently low latency like a wired link.','Believing the stream is private without network encryption enabled.','Ignoring how congestion and range cause dropouts.']::text[],ARRAY['Streaming audio from a networked sensor.','Assessing latency for a Wi-Fi monitoring link.','Understanding encryption on a wireless audio stream.']::text[],'intermediate',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wi-Fi audio transmission');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2144','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2144') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2144');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2145','Wind filtering','The reduction of low-frequency wind noise in a recording, using mechanical windscreens at capture and high-pass (low-cut) filtering or adaptive processing afterward. Wind energy is concentrated at low frequencies, so filtering there removes rumble while preserving most speech.','This cuts wind noise from a recording. Foam or fur covers help at the microphone. A low-cut filter removes the low rumble later. Speech mostly sits above the wind, so it survives.','It exists to suppress wind-induced low-frequency noise so that speech and other wanted sound remain clear.','A technician sets a high-pass filter around 80 to 120 Hz to remove wind rumble, checking that speech warmth and fullness are not overly thinned.','Noise reduction',ARRAY['Voice enhancement','Speech extraction','Voice isolation','Target voice enhancement','Target isolation']::text[],ARRAY['Setting the low-cut filter so high that voices sound thin.','Relying on filtering alone when a windscreen would prevent the noise.','Confusing steady wind rumble with wind gust distortion, which filters poorly.']::text[],ARRAY['Cleaning an outdoor recording with wind rumble.','Choosing a low-cut frequency for a windy interview.','Deciding between a windscreen and post filtering.']::text[],'beginner',NULL,NULL,'bb5e290a-c651-4b6e-b139-4e54a2f32944' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wind filtering');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2145','bb5e290a-c651-4b6e-b139-4e54a2f32944',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2145') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2145');
